(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("josephus-war-2-e", [{"sp": "HDR", "t": "Ἱστορία Ἰουδαϊκοῦ πολέμου πρὸς Ῥωμαίους"}, {"sp": "HDR", "t": "Βιβλίον Γʹ", "st": "3"}, {"sp": "N", "t": "Νέρωνι δ’ ὡς ἠγγέλη τὰ κατὰ τὴν Ἰουδαίαν πταίσματα, λεληθυῖα μὲν ὡς εἰκὸς ἔκπληξις ἐμπίπτει καὶ δέος, φανερῶς δὲ ὑπερηφάνει καὶ προσωργίζετο, στρατηγῶν μὲν ῥᾳστώνῃ μᾶλλον ἢ ταῖς τῶν πολεμίων ἀρεταῖς γεγονέναι τὰ συμβάντα λέγων, πρέπειν δ’ ἡγούμενος ἑαυτῷ διὰ τὸν ὄγκον τῆς ἡγεμονίας κατασοβαρεύεσθαι τῶν σκυθρωπῶν καὶ δοκεῖν δεινοῦ παντὸς ἐπάνω τὴν ψυχὴν ἔχειν.", "st": "3.1.1"}, {"sp": "N", "t": "διηλέγχετό γε μὴν ὁ τῆς ψυχῆς θόρυβος ὑπὸ τῶν φροντίδων σκεπτομένου τίνι πιστεύσει κινουμένην τὴν ἀνατολήν, ὃς τιμωρήσεται μὲν τὴν τῶν Ἰουδαίων ἐπανάστασιν, προκαταλήψεται δ’ αὐτοῖς ἤδη καὶ τὰ πέριξ ἔθνη συννοσοῦντα. μόνον εὑρίσκει Οὐεσπασιανὸν ταῖς χρείαις ἀναλογοῦντα καὶ τηλικούτου πολέμου μέγεθος ἀναδέξασθαι δυνάμενον, ἄνδρα ταῖς ἀπὸ νεότητος στρατείαις ἐγγεγηρακότα καὶ προειρηνεύσαντα μὲν πάλαι Ῥωμαίοις τὴν ἑσπέραν ὑπὸ Γερμανῶν ταρασσομένην, προσκτησάμενον δὲ τοῖς ὅπλοις Βρεττανίαν τέως λανθάνουσαν, ὅθεν αὐτοῦ καὶ τῷ πατρὶ Κλαυδίῳ παρέσχε χωρὶς ἱδρῶτος ἰδίου θρίαμβον καταγαγεῖν.", "st": "3.1.2"}, {"sp": "N", "t": "Ταῦτά τε δὴ προκλῃδονιζόμενος καὶ σταθερὰν μετ’ ἐμπειρίας τὴν ἡλικίαν ὁρῶν, μέγα δὲ πίστεως αὐτοῦ τοὺς υἱοὺς ὅμηρον καὶ τὰς τούτων ἀκμὰς χεῖρα τῆς πατρῴας συνέσεως, τάχα τι καὶ περὶ τῶν ὅλων ἤδη τοῦ θεοῦ προοικονομουμένου, πέμπει τὸν ἄνδρα ληψόμενον τὴν ἡγεμονίαν τῶν ἐπὶ Συρίας στρατευμάτων, πολλὰ πρὸς τὸ ἐπεῖγον οἷα κελεύουσιν αἱ ἀνάγκαι μειλιξάμενός τε καὶ προθεραπεύσας. ὁ δ’ ἀπὸ τῆς Ἀχαΐας, ἔνθα συνῆν τῷ Νέρωνι, τὸν μὲν υἱὸν Τίτον ἀπέστειλεν ἐπ’ Ἀλεξανδρείας τὸ πέμπτον καὶ δέκατον ἐκεῖθεν ἀναστήσοντα τάγμα, περάσας δ’ αὐτὸς τὸν Ἑλλήσποντον πεζὸς εἰς Συρίαν ἀφικνεῖται κἀκεῖ τάς τε Ῥωμαϊκὰς δυνάμεις συνήγαγε καὶ συχνοὺς παρὰ τῶν γειτνιώντων βασιλέων συμμάχους.", "st": "3.1.3"}, {"sp": "N", "t": "Ἰουδαῖοι δὲ μετὰ τὴν Κεστίου πληγὴν ἐπηρμένοι ταῖς ἀδοκήτοις εὐπραγίαις ἀκρατεῖς ἦσαν ὁρμῆς καὶ ὥσπερ ἐκριπιζόμενοι τῇ τύχῃ προσωτέρω τὸν πόλεμον ἐξῆγον· πᾶν γοῦν εὐθέως ὅσον ἦν μαχιμώτατον αὐτοῖς ἀθροισθέντες ὥρμησαν ἐπ’ Ἀσκάλωνα. πόλις ἐστὶν ἀρχαία τῶν Ἱεροσολύμων εἴκοσι πρὸς τοῖς πεντακοσίοις ἀπέχουσα σταδίους ἀεὶ διὰ μίσους Ἰουδαίοις γεγενημένη, διὸ καὶ τότε ταῖς πρώταις ὁρμαῖς ἐγγίων ἔδοξεν. ἐξηγοῦντο δὲ τῆς καταδρομῆς τρεῖς ἄνδρες ἀλκήν τε κορυφαῖοι καὶ συνέσει, Νίγερ τε ὁ Περαΐτης καὶ ὁ Βαβυλώνιος Σίλας, πρὸς οἷς Ἰωάννης ὁ Ἐσσαῖος. ἡ δὲ Ἀσκάλων ἐτετείχιστο μὲν καρτερῶς, βοηθείας δὲ ἦν σχεδὸν ἔρημος· ἐφρουρεῖτο γὰρ ὑπό τε σπείρας πεζῶν καὶ ὑπὸ μιᾶς ἴλης ἱππέων, ἧς ἐπῆρχεν Ἀντώνιος.", "st": "3.2.1"}, {"sp": "N", "t": "Οἱ μὲν οὖν πολὺ ταῖς ὁρμαῖς συντονώτερον ὁδεύσαντες ὡς ἐγγύθεν ὡρμημένοι καὶ δὴ παρῆσαν· ὁ δὲ Ἀντώνιος, οὐ γὰρ ἠγνόει μέλλουσαν ἔτι τὴν ἔφοδον αὐτῶν, προεξήγαγε τοὺς ἱππεῖς καὶ οὐδὲν οὔτε πρὸς τὸ πλῆθος οὔτε τὴν τόλμαν ὑποδείσας τῶν πολεμίων καρτερῶς τὰς πρώτας ὁρμὰς ἀνεδέξατο καὶ τοὺς ἐπὶ τὸ τεῖχος ὠθουμένους ἀνέστειλεν. οἱ δὲ πρὸς ἐμπείρους πολέμων ἄπειροι καὶ πεζοὶ πρὸς ἱππεῖς, ἀσύντακτοί τε πρὸς ἡνωμένους καὶ πρὸς ὁπλίτας ἐξηρτυμένους εἰκαιότερον ὡπλισμένοι, θυμῷ τε πλέον ἢ βουλῇ στρατηγούμενοι πρὸς εὐπειθεῖς καὶ νεύματι πάντα πράττοντας ἀντιτασσόμενοι πονοῦσιν ῥᾳδίως· ὡς γὰρ αὐτῶν ἅπαξ ἤδη συνεταράχθησαν αἱ πρῶται φάλαγγες, ὑπὸ τῆς ἵππου τρέπονται, καὶ τοῖς κατόπιν αὐτῶν ἐπὶ τὸ τεῖχος βιαζομένοις περιπίπτοντες ἀλλήλων ἦσαν πολέμιοι, μέχρι πάντες ταῖς τῶν ἱππέων ἐμβολαῖς εἴξαντες ἐσκεδάσθησαν ἀνὰ πᾶν τὸ πεδίον· τὸ δὲ ἦν πολὺ καὶ πᾶν ἱππάσιμον. ὃ δὴ καὶ τοῖς Ῥωμαίοις συνεργῆσαν πλεῖστον εἰργάσατο τῶν Ἰουδαίων φόνον· τούς τε γὰρ φεύγοντας αὐτῶν φθάνοντες ἐπέστρεφον καὶ τῶν ὑπὸ τοῦ δρόμου συνειλουμένων διεκπαίοντες ἀπείρους ἀνῄρουν, ἄλλοι δὲ ἄλλους ὅπῃ τρέποιντο κυκλούμενοι καὶ περιελαύνοντες κατηκόντιζον ῥᾳδίως. καὶ τοῖς μὲν Ἰουδαίοις τὸ ἴδιον πλῆθος ἐρημία παρὰ τὰς ἀμηχανίας κατεφαίνετο, Ῥωμαῖοι δὲ ἐν ταῖς εὐπραγίαις καίπερ ὄντες ὀλίγοι τῷ πολέμῳ καὶ περισσεύειν σφᾶς αὐτοὺς ὑπελάμβανον. καὶ τῶν μὲν προσφιλονεικούντων τοῖς πταίσμασιν αἰδοῖ τε φυγῆς ταχείας καὶ μεταβολῆς ἐλπίδι, τῶν δὲ μὴ κοπιώντων ἐν οἷς εὐτύχουν, παρέτεινεν ἡ μάχη μέχρι δείλης, ἕως ἀνῃρέθησαν μὲν μύριοι τῶν Ἰουδαίων τὸν ἀριθμὸν ἄνδρες καὶ δύο τῶν ἡγεμόνων, Ἰωάννης τε καὶ Σίλας· οἱ λοιποὶ δὲ τραυματίαι τὸ πλέον σὺν τῷ περιλειπομένῳ τῶν ἡγεμόνων Νίγερι τῆς Ἰδουμαίας εἰς πολίχνην τινά, Χάαλλις καλεῖται, συνέφυγον. ὀλίγοι δέ τινες καὶ τῶν Ῥωμαίων ἐπὶ τῆσδε τῆς παρατάξεως ἐτρώθησαν.", "st": "3.2.2"}, {"sp": "N", "t": "Οὐ μὴν οἱ Ἰουδαῖοι τηλικαύτῃ συμφορᾷ κατεστάλησαν τὰ φρονήματα, μᾶλλον δ’ αὐτῶν τὸ πάθος ἤγειρε τὰς τόλμας, ὑπερορῶντές τε τοὺς ἐν ποσὶ νεκροὺς ἐδελεάζοντο τοῖς προτέροις κατορθώμασιν ἐπὶ πληγὴν δευτέραν. διαλιπόντες γοῦν οὐδ’ ὅσον ἰάσασθαι τὰ τραύματα καὶ τὴν δύναμιν πᾶσαν ἐπισυλλέξαντες ὀργιλώτερον καὶ πολλῷ πλείους ἐπαλινδρόμουν ἐπὶ τὴν Ἀσκάλωνα. παρείπετο δ’ αὐτοῖς μετά τε τῆς ἀπειρίας καὶ τῶν ἄλλων πρὸς πόλεμον ἐλασσωμάτων ἡ προτέρα τύχη· τοῦ γὰρ Ἀντωνίου τὰς παρόδους προλοχίσαντος ἀδόκητοι ταῖς ἐνέδραις ἐμπεσόντες καὶ ὑπὸ τῶν ἱππέων πρὶν εἰς μάχην συντάξασθαι κυκλωθέντες, πάλιν πίπτουσι μὲν ὑπὲρ ὀκτακισχιλίους, οἱ λοιποὶ δὲ πάντες ἔφυγον, σὺν οἷς καὶ Νίγερ, πολλὰ κατὰ τὴν φυγὴν εὐτολμίας ἐπιδειξάμενος ἔργα, συνελαύνονταί τε προσκειμένων τῶν πολεμίων εἴς τινα πύργον ὀχυρὸν κώμης Βελζεδὲκ καλουμένης. οἱ δὲ περὶ τὸν Ἀντώνιον ὡς μήτε τρίβοιντο περὶ τὸν πύργον ὄντα δυσάλωτον μήτε ζῶντα τὸν ἡγεμόνα καὶ γενναιότατον τῶν πολεμίων περιίδοιεν, ὑποπιμπρᾶσι τὸ τεῖχος. φλεγομένου δὲ τοῦ πύργου Ῥωμαῖοι μὲν ἀναχωροῦσι γεγηθότες ὡς διεφθαρμένου καὶ Νίγερος, ὁ δὲ εἰς τὸ μυχαίτατον τοῦ φρουρίου σπήλαιον καταπηδήσας ἐκ τοῦ πύργου διασώζεται, καὶ μεθ’ ἡμέρας τρεῖς τοῖς μετ’ ὀλοφυρμοῦ πρὸς κηδείαν αὐτὸν ἐρευνῶσιν ὑποφθέγγεται. προελθὼν δὲ χαρᾶς ἀνελπίστου πάντας ἐπλήρωσεν Ἰουδαίους ὡς προνοίᾳ θεοῦ σωθεὶς αὐτοῖς στρατηγὸς εἰς τὰ μέλλοντα.", "st": "3.2.3"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ τὰς δυνάμεις ἀναλαβὼν ἐκ τῆς Ἀντιοχείας, ἣ μητρόπολίς ἐστι τῆς Συρίας, μεγέθους τε ἕνεκα καὶ τῆς ἄλλης εὐδαιμονίας τρίτον ἀδηρίτως ἐπὶ τῆς ὑπὸ Ῥωμαίοις οἰκουμένης ἔχουσα τόπον, ἔνθα μετὰ πάσης τῆς ἰδίας ἰσχύος ἐκδεχόμενον αὐτοῦ τὴν ἄφιξιν καὶ Ἀγρίππαν τὸν βασιλέα κατειλήφει, ἐπὶ Πτολεμαΐδος ἠπείγετο. καὶ κατὰ ταύτην ὑπαντῶσιν αὐτῷ τὴν πόλιν οἱ τῆς Γαλιλαίας Σέπφωριν νεμόμενοι πόλιν, μόνοι τῶν τῇδε εἰρηνικὰ φρονοῦντες· οἳ καὶ τῆς ἑαυτῶν σωτηρίας καὶ τῆς Ῥωμαίων ἰσχύος οὐκ ἀπρονόητοι πρὶν ἀφικέσθαι Οὐεσπασιανὸν Καισεννίῳ Γάλλῳ πίστεις τε ἔδοσαν καὶ δεξιὰς ἔλαβον καὶ παρεδέξαντο φρουράν. τότε γε μὴν φιλοφρόνως ἐκδεξάμενοι τὸν ἡγεμόνα προθύμως σφᾶς αὐτοὺς ὑπέσχοντο κατὰ τῶν ὁμοφύλων συμμάχους· οἷς ὁ στρατηγὸς ἀξιώσασι τέως πρὸς ἀσφάλειαν ἱππεῖς τε καὶ πεζοὺς παραδίδωσιν ὅσους ἀνθέξειν ταῖς καταδρομαῖς, εἴ τι Ἰουδαῖοι παρακινοῖεν, ὑπελάμβανον· καὶ γὰρ οὐ μικρὸν ἐδόκει τὸ κινδύνευμα πρὸς τὸν μέλλοντα πόλεμον ἀφαιρεθῆναι τὴν Σέπφωριν, μεγίστην μὲν οὖσαν τῆς Γαλιλαίας πόλιν, ἐρυμνοτάτῳ δ’ ἐπιτετειχισμένην χωρίῳ καὶ φρουρὰν ὅλου τοῦ ἔθνους ἐσομένην.", "st": "3.2.4"}, {"sp": "N", "t": "Δύο δ’ οὔσας τὰς Γαλιλαίας, τήν τε ἄνω καὶ τὴν κάτω προσαγορευομένην, περιίσχει μὲν ἡ Φοινίκη τε καὶ Συρία, διορίζει δὲ ἀπὸ μὲν δύσεως ἡλίου Πτολεμαῒς τοῖς τῆς χώρας τέρμασι καὶ Κάρμηλος, τὸ πάλαι μὲν Γαλιλαίων, νῦν δὲ Τυρίων ὄρος· ᾧ προσίσχει Γαβαά, πόλις ἱππέων, οὕτω προσαγορευομένη διὰ τὸ τοὺς ὑφ’ Ἡρώδου βασιλέως ἀπολυομένους ἱππεῖς ἐν αὐτῇ κατοικεῖν· ἀπὸ δὲ μεσημβρίας Σαμαρεῖτίς τε καὶ Σκυθόπολις μέχρι τῶν Ἰορδάνου ναμάτων. πρὸς ἕω δὲ Ἱππηνῇ τε καὶ Γαδάροις ἀποτέμνεται καὶ τῇ Γαυλωνίτιδι· ταύτῃ καὶ τῆς Ἀγρίππα βασιλείας ὅροι. τὰ προσάρκτια δ’ αὐτῆς Τύρῳ τε καὶ τῇ Τυρίων χώρᾳ περατοῦται. καὶ τῆς μὲν κάτω καλουμένης Γαλιλαίας ἀπὸ Τιβεριάδος μέχρι Χαβουλών, ἧς ἐν τοῖς παραλίοις Πτολεμαῒς γείτων, τὸ μῆκος ἐκτείνεται. πλατύνεται δ’ ἀπὸ τῆς ἐν τῷ μεγάλῳ πεδίῳ κειμένης κώμης, Ἐξαλὼθ καλεῖται, μέχρι Βηρσάβης, ἣ καὶ τῆς ἄνω Γαλιλαίας εἰς εὖρος ἀρχὴ μέχρι Βακὰ κώμης· αὕτη δὲ τὴν Τυρίων γῆν ὁρίζει. μηκύνεται δὲ μέχρι Μηρὼθ ἀπὸ Θελλᾶ κώμης Ἰορδάνου γείτονος.", "st": "3.3.1"}, {"sp": "N", "t": "Τηλικαῦται δ’ οὖσαι τὸ μέγεθος καὶ τοσούτοις ἔθνεσιν ἀλλοφύλοις κεκυκλωμέναι πρὸς πᾶσαν ἀεὶ πολέμου πεῖραν ἀντέσχον· μάχιμοί τε γὰρ ἐκ νηπίων καὶ πολλοὶ Γαλιλαῖοι πάντοτε, καὶ οὔτε δειλία ποτὲ τοὺς ἄνδρας οὔτε λιπανδρία τὴν χώραν κατέσχεν, ἐπειδὴ πίων τε πᾶσα καὶ εὔβοτος καὶ δένδρεσι παντοίοις κατάφυτος, ὡς ὑπὸ τῆς εὐπετείας προκαλέσασθαι καὶ τὸν ἥκιστα γῆς φιλόπονον. προσησκήθη γοῦν ὑπὸ τῶν οἰκητόρων πᾶσα, καὶ μέρος αὐτῆς ἀργὸν οὐδέν, ἀλλὰ καὶ πόλεις πυκναὶ καὶ τὸ τῶν κωμῶν πλῆθος πανταχοῦ πολυάνθρωπον διὰ τὴν εὐθηνίαν, ὡς τὴν ἐλαχίστην ὑπὲρ πεντακισχιλίους πρὸς τοῖς μυρίοις ἔχειν οἰκήτορας.", "st": "3.3.2"}, {"sp": "N", "t": "Καθόλου δέ, εἰ καὶ τῷ μεγέθει τις ἐλαττώσειε τῆς Περαίας τὴν Γαλιλαίαν, προέλοιτο δ’ ἂν τῇ δυνάμει· ἡ μὲν γὰρ ἐνεργὸς ὅλη καὶ συνεχής ἐστιν καρποφόρος, ἡ Περαία δὲ πολὺ μὲν μείζων, ἔρημος δὲ καὶ τραχεῖα τὸ πλέον πρός τε καρπῶν ἡμέρων αὔξησιν ἀγριωτέρα, τό γε μὴν μαλθακὸν αὐτῆς καὶ πάμφορον, καὶ τὰ πεδία δένδρεσι ποικίλοις κατάφυτα τὸ πλεῖστόν τε ἐλαίαν [τε] καὶ ἄμπελον καὶ φοινικῶνας ἤσκηται, διαρδομένη χειμάρροις τε τοῖς ἀπὸ τῶν ὀρῶν καὶ πηγαῖς ἀεννάοις ἅλις, εἴ ποτ’ ἐκεῖνοι σειρίῳ φθίνοιεν. μῆκος μὲν [οὖν] αὐτῆς ἀπὸ Μαχαιροῦντος εἰς Πέλλαν, εὖρος δ’ ἀπὸ Φιλαδελφείας μέχρι Ἰορδάνου. καὶ Πέλλῃ μέν, ἣν προειρήκαμεν, τὰ πρὸς ἄρκτον ὁρίζεται, πρὸς ἑσπέραν δὲ Ἰορδάνῃ· μεσημβρινὸν δ’ αὐτῆς πέρας ἡ Μωαβῖτις, καὶ πρὸς ἀνατολὴν Ἀραβίᾳ τε καὶ Σιλωνίτιδι, πρὸς δὲ Φιλαδελφηνῇ καὶ Γεράσοις ἀποτέμνεται.", "st": "3.3.3"}, {"sp": "N", "t": "Ἡ δὲ Σαμαρεῖτις χώρα μέση μὲν τῆς Γαλιλαίας ἐστὶ καὶ τῆς Ἰουδαίας· ἀρχομένη γὰρ ἀπὸ τῆς ἐν τῷ πεδίῳ κειμένης Γηνεὼς ὄνομα κώμης ἐπιλήγει τῆς Ἀκραβετηνῶν τοπαρχίας· φύσιν δὲ τῆς Ἰουδαίας κατ’ οὐδὲν διάφορος. ἀμφότεραι γὰρ ὀρειναὶ καὶ πεδιάδες, εἴς τε γεωργίαν μαλθακαὶ καὶ πολύφοροι κατάδενδροί τε καὶ ὀπώρας ὀρεινῆς καὶ ἡμέρου μεσταί, παρ’ ὅσον οὐδαμοῦ φύσει διψάδες, ὕονται δὲ τὸ πλέον· γλυκὺ δὲ νᾶμα πᾶν διαφόρως ἐν αὐταῖς, καὶ διὰ πλῆθος πόας ἀγαθῆς τὰ κτήνη πλέον ἢ παρ’ ἄλλοις γαλακτοφόρα. μέγιστόν γε μὴν τεκμήριον ἀρετῆς καὶ εὐθηνίας τὸ πληθύειν ἀνδρῶν ἑκατέραν.", "st": "3.3.4"}, {"sp": "N", "t": "Μεθόριος δ’ αὐτῶν ἡ Ἀνουάθου Βόρκαιος προσαγορευομένη κώμη· πέρας αὕτη τῆς Ἰουδαίας τὰ πρὸς βορέαν, τὰ νότια δ’ αὐτῆς ἐπὶ μῆκος μετρουμένης ὁρίζει προσκυροῦσα τοῖς Ἀράβων ὅροις κώμη, καλοῦσι δ’ αὐτὴν Ἰορδὰν οἱ τῇδε Ἰουδαῖοι. εὖρός γε μὴν ἀπὸ Ἰορδάνου ποταμοῦ μέχρις Ἰόππης ἀναπέπταται. μεσαιτάτη δ’ αὐτῆς πόλις τὰ Ἱεροσόλυμα κεῖται, παρ’ ὃ καί τινες οὐκ ἀσκόπως ὀμφαλὸν τὸ ἄστυ τῆς χώρας ἐκάλεσαν. ἀφῄρηται δ’ οὐδὲ τῶν ἐκ θαλάσσης τερπνῶν ἡ Ἰουδαία τοῖς παραλίοις κατατείνουσα μέχρι Πτολεμαΐδος. μερίζεται δ’ εἰς ἕνδεκα κληρουχίας, ὧν ἄρχει μὲν βασίλειον τὰ Ἱεροσόλυμα προανίσχουσα τῆς περιοίκου πάσης ὥσπερ ἡ κεφαλὴ σώματος· αἱ λοιπαὶ δὲ μετ’ αὐτὴν διῄρηνται τὰς τοπαρχίας. Γοφνὰ δευτέρα καὶ μετὰ ταύτην Ἀκραβετά, Θαμνὰ πρὸς ταύταις καὶ Λύδδα, Ἀμμαοῦς καὶ Πέλλη καὶ Ἰδουμαία καὶ Ἐνγαδδαὶ καὶ Ἡρώδειον καὶ Ἱεριχοῦς, μεθ’ ἃς Ἰάμνεια καὶ Ἰόππη τῶν περιοίκων ἀφηγοῦνται, κἀπὶ ταύταις ἥ τε Γαμαλιτικὴ καὶ Γαυλανῖτις Βαταναία τε καὶ Τραχωνῖτις, αἳ καὶ τῆς Ἀγρίππα βασιλείας εἰσὶ μοῖραι. ἀρχομένη δὲ ἀπὸ Λιβάνου ὄρους καὶ τῶν Ἰορδάνου πηγῶν ἡ χώρα μέχρι τῆς πρὸς Τιβεριάδα λίμνης εὐρύνεται, ἀπὸ δὲ κώμης καλουμένης Ἀρφᾶς μέχρις Ἰουλιάδος ἐκτείνεται τὸ μῆκος. οἰκοῦσι δ’ αὐτὴν μιγάδες Ἰουδαῖοί τε καὶ Σύροι. τὰ μὲν δὴ περὶ τῆς Ἰουδαίων τε καὶ πέριξ χώρας ὡς ἐνῆν μάλιστα συντόμως ἀπηγγέλκαμεν.", "st": "3.3.5"}, {"sp": "N", "t": "Ἡ δ’ ὑπὸ Οὐεσπασιανοῦ πεμφθεῖσα Σεπφωρίταις βοήθεια, χίλιοι μὲν ἱππεῖς ἑξακισχίλιοι δὲ πεζοί, Πλακίδου χιλιαρχοῦντος αὐτῶν ἐν τῷ μεγάλῳ πεδίῳ στρατοπεδευσάμενοι διαιροῦνται, καὶ τὸ μὲν πεζὸν ἐν τῇ πόλει πρὸς φυλακὴν αὐτῆς, τὸ δ’ ἱππικὸν ἐπὶ τῆς παρεμβολῆς αὐλίζεται. προϊόντες δὲ ἑκατέρωθεν συνεχῶς καὶ τὰ πέριξ τῆς χώρας κατατρέχοντες μεγάλα τοὺς περὶ τὸν Ἰώσηπον ἐκάκουν ἀτρεμοῦντα τάς τε πόλεις ἔξωθεν λῃζόμενοι καὶ προθέοντας ὁπότε θαρρήσειαν ἀνακόπτοντες. ὥρμησέ γε μὴν Ἰώσηπος ἐπὶ τὴν πόλιν αἱρήσειν ἐλπίσας, ἣν αὐτὸς πρὶν ἀποστῆναι Γαλιλαίων ἐτείχισεν ὡς καὶ Ῥωμαίοις δυσάλωτον εἶναι· διὸ καὶ τῆς ἐλπίδος ἀφήμαρτεν τοῦ τε βιάζεσθαι καὶ τοῦ μεταπείθειν Σεπφωρίτας ἀσθενέστερος εὑρεθείς. παρώξυνεν δὲ μᾶλλον τὸν πόλεμον ἐπὶ τὴν χώραν, καὶ οὔτε νύκτωρ οὔτε μεθ’ ἡμέραν ὀργῇ τῆς ἐπιβολῆς οἱ Ῥωμαῖοι διέλιπον δῃοῦντες αὐτῶν τὰ πεδία καὶ διαρπάζοντες τὰ ἐπὶ τῆς χώρας κτήματα, καὶ κτείνοντες μὲν ἀεὶ τὸ μάχιμον, ἀνδραποδιζόμενοι δὲ τοὺς ἀσθενεῖς. πυρὶ δὲ ἡ Γαλιλαία καὶ αἵματι πεπλήρωτο πᾶσα πάθους τε οὐδενὸς ἢ συμφορᾶς ἀπείρατος ἦν· μία γὰρ καταφυγὴ διωκομένοις αἱ ὑπὸ τοῦ Ἰωσήπου τειχισθεῖσαι πόλεις ἦσαν.", "st": "3.4.1"}, {"sp": "N", "t": "Ὁ δὲ Τίτος περαιωθεὶς ἀπὸ τῆς Ἀχαΐας εἰς τὴν Ἀλεξάνδρειαν ὠκύτερον ἢ κατὰ χειμῶνος ὥραν, παραλαμβάνει μὲν ἐφ’ ἣν ἔσταλτο δύναμιν, συντόνῳ δὲ χρώμενος πορείᾳ διὰ τάχους εἰς Πτολεμαΐδα ἀφικνεῖται. κἀκεῖ καταλαβὼν τὸν πατέρα δυσὶ τοῖς ἅμα αὐτῷ τάγμασιν, ἦν δὲ τὰ ἐπισημότατα τὸ πέμπτον καὶ τὸ δέκατον, ζεύγνυσι τὸ ἀχθὲν ὑπ’ αὐτοῦ πεντεκαιδέκατον. τούτοις εἵποντο ὀκτωκαίδεκα σπεῖραι· προσεγένοντο δὲ καὶ ἀπὸ Καισαρείας πέντε καὶ ἱππέων ἴλη μία, πέντε δ’ ἕτεραι τῶν ἀπὸ Συρίας ἱππέων. τῶν δὲ σπειρῶν αἱ δέκα μὲν εἶχον ἀνὰ χιλίους πεζούς, αἱ δὲ λοιπαὶ δεκατρεῖς ἀνὰ ἑξακοσίους μὲν πεζούς, ἱππεῖς δὲ ἑκατὸν εἴκοσιν. συχνὸν δὲ καὶ παρὰ τῶν βασιλέων συνήχθη συμμαχικόν, Ἀντιόχου μὲν καὶ Ἀγρίππα καὶ Σοαίμου παρασχομένων ἀνὰ δισχιλίους πεζοὺς τοξότας καὶ χιλίους ἱππεῖς, τοῦ δὲ Ἄραβος Μάλχου χιλίους πέμψαντος ἱππεῖς ἐπὶ πεζοῖς πεντακισχιλίοις, ὧν τὸ πλέον ἦσαν τοξόται, ὡς τὴν πᾶσαν δύναμιν συνεξαριθμουμένων τῶν βασιλικῶν ἱππέας τε καὶ πεζοὺς εἰς ἓξ ἀθροίζεσθαι μυριάδας δίχα θεραπόντων, οἳ παμπληθεῖς μὲν εἵποντο, διὰ δὲ συνάσκησιν πολεμικὴν οὐκ ἂν ἀποτάσσοιντο τοῦ μαχίμου, κατὰ μὲν εἰρήνην ἐν ταῖς μελέταις τῶν δεσποτῶν ἀεὶ στρεφόμενοι, συγκινδυνεύοντες δ’ ἐν πολέμοις, ὡς μήτ’ ἐμπειρίᾳ μήτ’ ἀλκῇ τινος πλὴν τῶν δεσποτῶν ἐλαττοῦσθαι.", "st": "3.4.2"}, {"sp": "N", "t": "Κἀν τούτῳ μὲν οὖν θαυμάσαι τις ἂν Ῥωμαίων τὸ προμηθὲς κατασκευαζομένων ἑαυτοῖς τὸ οἰκετικὸν οὐ μόνον εἰς τὰς τοῦ βίου διακονίας ἀλλὰ καὶ πρὸς τοὺς πολέμους χρήσιμον. εἰ δέ τις αὐτῶν καὶ εἰς τὴν ἄλλην σύνταξιν τῆς στρατιᾶς ἀπίδοι, γνώσεται τὴν τοσήνδε ἡγεμονίαν αὐτοὺς ἀρετῆς κτῆμα ἔχοντας, οὐ δῶρον τύχης. οὐ γὰρ αὐτοῖς ἀρχὴ τῶν ὅπλων πόλεμος, οὐδ’ ἐπὶ μόνας τὰς χρείας τὼ χεῖρε κινοῦσιν ἐν εἰρήνῃ προηργηκότες, ἀλλ’ ὥσπερ συμπεφυκότες τοῖς ὅπλοις οὐδέποτε τῆς ἀσκήσεως λαμβάνουσιν ἐκεχειρίαν οὐδὲ ἀναμένουσιν τοὺς καιρούς. αἱ μελέται δ’ αὐτοῖς οὐδὲν τῆς κατὰ ἀλήθειαν εὐτονίας ἀποδέουσιν, ἀλλ’ ἕκαστος ὁσημέραι στρατιώτης πάσῃ προθυμίᾳ καθάπερ ἐν πολέμῳ γυμνάζεται. διὸ κουφότατα τὰς μάχας διαφέρουσιν· οὔτε γὰρ ἀταξία διασκίδνησιν αὐτοὺς ἀπὸ τῆς ἐν ἔθει συντάξεως οὔτε δέος ἐξίστησιν οὔτε δαπανᾷ πόνος, ἕπεται δὲ τὸ κρατεῖν ἀεὶ κατὰ τῶν οὐχ ὁμοίων βέβαιον. καὶ οὐκ ἂν ἁμάρτοι τις εἰπὼν τὰς μὲν μελέτας αὐτῶν χωρὶς αἵματος παρατάξεις, τὰς παρατάξεις δὲ μεθ’ αἵματος μελέτας. οὐδὲ γὰρ ἐξ ἐπιδρομῆς εὐάλωτοι πολεμίοις· ὅπῃ δ’ ἂν ἐμβάλωσιν εἰς ἐχθρῶν γῆν, οὐ πρὶν ἅπτονται μάχης ἢ τειχίσαι στρατόπεδον. τὸ δὲ οὐκ εἰκαῖον οὐδὲ ἀνώμαλον ἐγείρουσιν οὐδὲ πάντες ἢ ἀτάκτως διαλαβόντες, ἀλλ’ εἰ μὲν ἀνώμαλος ὢν τύχοι χῶρος, ἐξομαλίζεται· διαμετρεῖται δὲ παρεμβολὴ τετράγωνος αὐτοῖς. καὶ τεκτόνων πλῆθος ἕπεται τῶν τε πρὸς τὴν δόμησιν ἐργαλείων.", "st": "3.5.1"}, {"sp": "N", "t": "Καὶ τὸ μὲν ἔνδον εἰς σκηνὰς διαλαμβάνουσιν, ἔξωθεν δ’ ὁ κύκλος τείχους ὄψιν ἐπίχει πύργοις ἐξ ἴσου διαστήματος κεκοσμημένος. ἐπὶ δὲ τῶν μεταπυργίων τούς τε ὀξυβελεῖς καὶ καταπέλτας καὶ λιθοβόλα καὶ πᾶν ἀφετήριον ὄργανον τιθέασιν, πάντα πρὸς τὰς βολὰς ἕτοιμα. πύλαι δὲ ἐνοικοδομοῦνται τέσσαρες καθ’ ἕκαστον τοῦ περιβόλου κλίμα, πρός τε εἰσόδους τῶν ὑποζυγίων εὐμαρεῖς καὶ πρὸς τὰς ἐκδρομὰς αὐτῶν, εἰ κατεπείγοι, πλατεῖαι. ῥυμοτομοῦσι δ’ εὐδιαθέτως εἴσω τὸ στρατόπεδον, καὶ μέσας μὲν τὰς τῶν ἡγεμόνων σκηνὰς τίθενται, μεσαίτατον δὲ τούτων τὸ στρατήγιον ναῷ παραπλήσιον· ὥσπερ δὲ ἐν σχεδίῳ πόλις καὶ ἀγορά τις ἀποδείκνυται καὶ χειροτέχναις χωρίον θῶκοί τε λοχαγοῖς καὶ ταξιάρχοις, ὅπῃ δικάζοιεν, εἴ τινες διαφέροιντο. τειχίζεται δὲ ὁ περίβολος καὶ τὰ ἐν αὐτῷ πάντα θᾶττον ἐπινοίας πλήθει καὶ ἐπιστήμῃ τῶν πονούντων· εἰ δ’ ἐπείγοι, καὶ τάφρος ἔξωθεν περιβάλλεται βάθος τετράπηχυς καὶ εὖρος ἴση.", "st": "3.5.2"}, {"sp": "N", "t": "Φραξάμενοι δ’ αὐλίζονται κατὰ συντάξεις ἕκαστοι μεθ’ ἡσυχίας τε καὶ κόσμου. πάντα δ’ αὐτοῖς καὶ τὰ ἄλλα μετ’ εὐταξίας ἀνύεται καὶ ἀσφαλείας, ξυλεία τε καὶ ἐπισιτισμός, εἰ δέοιντο, καὶ ὑδρεία κατὰ συντάξεις ἑκάστοις. οὐδὲ γὰρ δεῖπνον ἢ ἄριστον ὁπότε θελήσειαν αὐτεξούσιον ἑκάστῳ, πᾶσιν δ’ ὁμοῦ, τούς τε ὕπνους αὐτοῖς καὶ τὰς φυλακὰς καὶ τὰς ἐξεγέρσεις σάλπιγγες προσημαίνουσιν, οὐδ’ ἔστιν ὅ τι γίνεται δίχα παραγγέλματος. ὑπὸ δὲ τὴν ἕω τὸ στρατιωτικὸν μὲν ἐπὶ τοὺς ἑκατοντάρχας ἕκαστοι, πρὸς δὲ τοὺς χιλιάρχους οὗτοι συνίασιν ἀσπασόμενοι, μεθ’ ὧν πρὸς τὸν ἡγεμόνα τῶν ὅλων οἱ ταξίαρχοι πάντες. ὁ δ’ αὐτοῖς τό τε ἐξ ἔθους σημεῖον καὶ τἆλλα παραγγέλματα δίδωσιν διαφέρειν εἰς τοὺς ὑποτεταγμένους· ὃ δὴ κἀπὶ παρατάξεως πράττοντες ἐπιστρέφονταί τε ταχέως, ἵνα δέοι, καὶ πρὸς τὰς ἐφόδους αὐτοῖς καὶ πρὸς τὰς ἀνακλήσεις ὑποχωροῦσιν ἀθρόοι.", "st": "3.5.3"}, {"sp": "N", "t": "Ἐξιέναι δὲ τοῦ στρατοπέδου δέον ὑποσημαίνει μὲν ἡ σάλπιγξ, ἠρεμεῖ δ’ οὐδείς, ἀλλ’ ἅμα νεύματι τὰς μὲν σκηνὰς ἀναιροῦσιν, πάντα δ’ ἐξαρτύονται πρὸς τὴν ἔξοδον. καὶ πάλιν αἱ σάλπιγγες ὑποσημαίνουσιν παρεσκευάσθαι. οἱ δ’ ἐν τάχει τοῖς τε ὀρεῦσιν καὶ τοῖς ὑποζυγίοις ἐπιθέντες τὴν ἀποσκευὴν ἑστᾶσιν ὥσπερ ἐφ’ ὕσπληγος ἐξορμᾶν ἕτοιμοι, ὑποπιμπρᾶσίν τε ἤδη τὴν παρεμβολὴν ὡς αὐτοῖς μὲν ὂν ῥᾴδιον ἐκεῖ πάλιν τειχίσασθαι, μὴ γένοιτο δ’ ἐκεῖνό ποτε τοῖς πολεμίοις χρήσιμον. καὶ τρίτον δ’ ὅμως αἱ σάλπιγγες προσημαίνουσιν τὴν ἔξοδον ἐπισπέρχουσαι τοὺς δι’ αἰτίαν τινὰ βραδύναντας, ὡς μή τις ἀπολειφθείη τάξεως. ὅ τε κῆρυξ δεξιὸς τῷ πολεμάρχῳ παραστάς, εἰ πρὸς πόλεμόν εἰσιν ἕτοιμοι, τῇ πατρίῳ γλώσσῃ τρὶς ἀναπυνθάνεται. κἀκεῖνοι τοσαυτάκις ἀντιβοῶσιν μέγα τι καὶ πρόθυμον ἕτοιμοι λέγοντες εἶναι, φθάνουσιν δὲ τὸν ἐπερωτῶντα, καί τινος ἀρηΐου πνεύματος ὑποπιμπλάμενοι τῇ βοῇ συνεξαίρουσιν τὰς δεξιάς.", "st": "3.5.4"}, {"sp": "N", "t": "Ἔπειτα προϊόντες ὁδεύουσιν ἡσυχῇ καὶ μετὰ κόσμου πάντες, ὥσπερ ἐν πολέμῳ τὴν ἰδίαν τάξιν ἕκαστος φυλάσσων, οἱ μὲν πεζοὶ θώραξιν πεφραγμένοι καὶ κράνεσιν καὶ μαχαιροφοροῦντες ἀμφοτέρωθεν. μακρότερον δ’ αὐτῶν τὸ λαιὸν ξίφος πολλῷ· τὸ γὰρ κατὰ τὸ δεξιὸν σπιθαμῆς οὐ πλέον ἔχει τὸ μῆκος. φέρουσι δ’ οἱ μὲν περὶ τὸν στρατηγὸν ἐπίλεκτοι πεζοὶ λόγχην καὶ ἀσπίδα, ἡ δὲ λοιπὴ φάλαγξ ξυστόν τε καὶ θυρεὸν ἐπιμήκη, πρὸς οἷς πρίονα καὶ κόφινον ἄμην τε καὶ πέλεκυν, πρὸς δὲ ἱμάντα καὶ δρέπανον καὶ ἅλυσιν, ἡμερῶν τε τριῶν ἐφόδιον· ὡς ὀλίγον ἀποδεῖν τῶν ἀχθοφορούντων ὀρέων τὸν πεζόν. τοῖς δὲ ἱππεῦσιν μάχαιρα μὲν ἐκ δεξιῶν μακρὰ καὶ κοντὸς ἐπιμήκης ἐν χειρί, θυρεὸς δὲ παρὰ πλευρὸν ἵππου πλάγιος, καὶ κατὰ γωρυτοῦ παρήρτηνται τρεῖς ἢ πλείους ἄκοντες, πλατεῖς μὲν αἰχμάς, οὐκ ἀποδέοντες δὲ δοράτων μέγεθος· κράνη δὲ καὶ θώρακες ὁμοίως τοῖς πεζοῖς ἅπασιν. οὐδενὶ δὲ ὅπλων διαλλάττουσιν οἱ περὶ τὸν στρατηγὸν ἔκκριτοι τῶν ἐν ταῖς ἴλαις ἱππέων. κλήρῳ δὲ τῶν ταγμάτων ἀεὶ τὸ λαχὸν ἡγεῖται.", "st": "3.5.5"}, {"sp": "N", "t": "Τοιαῦται μὲν οὖν αἱ Ῥωμαίων πορεῖαί τε καὶ καταλύσεις, πρὸς δὲ ὅπλων διαφοραί, οὐδὲν δὲ ἀπροβούλευτον ἐν ταῖς μάχαις οὐδὲ αὐτοσχέδιον, ἀλλὰ γνώμη μὲν ἀεὶ παντὸς ἔργου προάγει, τοῖς δοχθεῖσι δὲ ἕπεται τὰ ἔργα· παρ’ ὃ καὶ σφάλλονται μὲν ἥκιστα, κἂν πταίσωσι δέ, ῥᾳδίως ἀναλαμβάνουσι τὰ σφάλματα. ἡγοῦνταί τε τῶν ἀπὸ τύχης ἐπιτευγμάτων ἀμείνους τὰς ἐπὶ τοῖς προβουλευθεῖσιν διαμαρτίας, ὡς τοῦ μὲν αὐτομάτου καλοῦ δελεάζοντος εἰς ἀπρομήθειαν, τῆς σκέψεως δέ, κἂν ἀτυχήσῃ ποτέ, πρὸς τὸ μὴ αὖθις καλὴν ἐχούσης μελέτην· καὶ τῶν μὲν αὐτομάτων ἀγαθῶν οὐ τὸν λαβόντα αἴτιον εἶναι, τῶν δὲ παρὰ γνώμην προσπεσόντων σκυθρωπῶν παραμυθίαν τό γε προσηκόντως βεβουλεῦσθαι.", "st": "3.5.6"}, {"sp": "N", "t": "Παρασκευάζουσι μὲν οὖν ἐν ταῖς μελέταις τῶν ὅπλων οὐ τὰ σώματα μόνον ἀλλὰ καὶ τὰς ψυχὰς ἀλκίμους, προσασκοῦνται δὲ καὶ τῷ φόβῳ. οἵ τε γὰρ νόμοι παρ’ αὐτοῖς οὐ λιποταξίου μόνον ἀλλὰ καὶ ῥᾳστώνης ὀλίγης θανατικοὶ οἵ τε στρατηγοὶ τῶν νόμων φοβερώτεροι· ταῖς γὰρ πρὸς τοὺς ἀγαθοὺς τιμαῖς ῥύονται τὸ δοκεῖν ὠμοὶ πρὸς τοὺς κολαζομένους. τοσοῦτον δ’ αὐτῶν τὸ πρὸς τοὺς ἡγεμόνας πειθήνιον, ὡς ἔν τε εἰρήνῃ κόσμον εἶναι καὶ ἐπὶ παρατάξεως ἓν σῶμα τὴν ὅλην στρατιάν. οὕτως αὐτῶν ἀσφαλεῖς μὲν αἱ τάξεις, εὔστροφοι δ’ εἰσὶν αἱ περιαγωγαί, ὀξεῖαι δ’ ἀκοαὶ μὲν παραγγέλμασιν, ὄψεις δὲ σημείοις, ἔργοις δὲ χεῖρες. ὅθεν δρᾶσαι μὲν ἀεὶ ταχεῖς, βραδύτατοι δὲ παθεῖν εἰσιν, οὐδ’ ἔστιν ὅπου σταθέντες ἢ πλήθους ἡσσήθησαν ἢ στρατηγημάτων ἢ δυσχωρίας, ἀλλ’ οὐδὲ τύχης· καὶ γὰρ ταύτης αὐτοῖς τὸ κρατεῖν βεβαιότερον. οἷς οὖν βουλὴ μὲν ἄρχει παρατάξεως, ἕπεται δὲ τοῖς βεβουλευμένοις στρατὸς οὕτω δραστήριος, τί θαυμαστόν, εἰ πρὸς ἕω μὲν Εὐφράτης, ὠκεανὸς δὲ πρὸς ἑσπέραν, μεσημβρινὸν δὲ Λιβύης τὸ πιότατον καὶ πρὸς ἄρκτον Ἴστρος τε καὶ Ῥῆνος τῆς ἡγεμονίας ὅροι; δεόντως γὰρ ἄν τις εἴποι τὸ κτῆμα τῶν κτησαμένων ἔλασσον.", "st": "3.5.7"}, {"sp": "N", "t": "Ταῦτα μὲν οὖν διεξῆλθον οὐ Ῥωμαίους ἐπαινέσαι προαιρούμενος τοσοῦτον, ὅσον εἴς τε παραμυθίαν τῶν κεχειρωμένων καὶ εἰς ἀποτροπὴν τῶν νεωτεριζόντων· εἴη δ’ ἂν τοῖς ἀγνοοῦσιν τῶν φιλοκαλούντων καὶ πρὸς ἐμπειρίας ἡ ἀγωγὴ τῆς Ῥωμαίων στρατιᾶς. ἐπάνειμι δ’ ὅθεν ἐπὶ ταῦτ’ ἐξέβην.", "st": "3.5.8"}, {"sp": "N", "t": "Οὐεσπασιανὸς μὲν ἅμα τῷ παιδὶ Τίτῳ διατρίβων τέως ἐν τῇ Πτολεμαΐδι συνέτασσεν τὰς δυνάμεις, ὁ δὲ τὴν Γαλιλαίαν κατατρέχων Πλάκιδος ἐπεὶ πολὺ μὲν πλῆθος ἀνῃρήκει τῶν καταλαμβανομένων, τοῦτο δ’ ἦν τὸ ἀσθενέστερον Γαλιλαίων καὶ ταῖς φυγαῖς ἐναποκάμνον, ὁρῶν δὲ συμφεῦγον ἀεὶ τὸ μάχιμον εἰς τὰς ὑπὸ τοῦ Ἰωσήπου τειχισθείσας πόλεις ὥρμησεν ἐπὶ τὴν ὀχυρωτάτην αὐτῶν Ἰωταπάταν, οἰόμενος ἐξ ἐφόδου μὲν αἱρήσειν ῥᾳδίως, μέγα δὲ κλέος αὐτῷ παρὰ τοῖς ἡγεμόσιν κἀκείνοις ὄφελος εἰς τὰ λοιπὰ παρέξειν· προσχωρήσειν γὰρ δέει τὰς ἄλλας πόλεις τῆς καρτερωτάτης ἐχομένης. πολύ γε μὴν διήμαρτεν τῆς ἐλπίδος· ἐπιόντα γὰρ αὐτὸν οἱ Ἰωταπατηνοὶ προαισθόμενοι πρὸ τῆς πόλεως ἐκδέχονται, καὶ τοῖς Ῥωμαίοις συρραγέντες ἀδοκήτοις πολλοὶ καὶ πρὸς μάχην ἕτοιμοι πρόθυμοί τε ὡς ἂν ὑπὲρ κινδυνευούσης πατρίδος καὶ γυναικῶν καὶ τέκνων, τρέπονται ταχέως. καὶ πολλοὺς μὲν τιτρώσκουσι τῶν Ῥωμαίων, ἑπτὰ δὲ ἀναιροῦσιν διὰ τὸ μήτε ἄτακτον αὐτῶν τὴν ὑποχώρησιν γενέσθαι καὶ τὰς πληγὰς ἐπιπολαίους πεφραγμένων πάντοθεν τῶν σωμάτων, τούς τε Ἰουδαίους πόρρωθεν βάλλειν πλέον ἢ συμπλέκεσθαι θαρρεῖν γυμνῆτας ὁπλίταις. ἔπεσον δὲ καὶ τῶν Ἰουδαίων τρεῖς ἄνδρες καὶ ἐτρώθησαν ὀλίγοι. Πλάκιδος μὲν οὖν τῆς ἐπὶ τὴν πόλιν ὁρμῆς ἀτονώτερος εὑρεθεὶς φεύγει.", "st": "3.6.1"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ ὡρμημένος αὐτὸς ἐμβαλεῖν εἰς τὴν Γαλιλαίαν ἐξελαύνει τῆς Πτολεμαΐδος διατάξας τὴν στρατιὰν ὁδεύειν καθὰ Ῥωμαίοις ἔθος. τοὺς μέν γε ψιλοὺς τῶν ἐπικούρων καὶ τοξότας προάγειν ἐκέλευσεν, ὡς ἀνακόπτοιεν τὰς ἐξαπιναίους τῶν πολεμίων ἐπιδρομὰς καὶ διερευνῷεν τὰς ὑπόπτους καὶ λοχᾶσθαι δυναμένας ὕλας, οἷς εἵπετο καὶ Ῥωμαίων ὁπλιτικὴ μοῖρα πεζοί τε καὶ ἱππεῖς. τούτοις ἀφ’ ἑκάστης ἑκατονταρχίας ἠκολούθουν δέκα τήν τε ἑαυτῶν σκευὴν καὶ τὰ μέτρα τῆς παρεμβολῆς φέροντες, καὶ μετ’ αὐτοὺς ὁδοποιοί, τά τε σκολιὰ τῆς λεωφόρου κατευθύνειν καὶ χθαμαλοῦν τὰ δύσβατα καὶ τὰς ἐμποδίους ὕλας προανακόπτειν, ὡς μὴ ταλαιπωροῖτο δυσποροῦν τὸ στράτευμα. κατόπιν δὲ τούτων τάς τε ἰδίας καὶ τὰς τῶν ὑπ’ αὐτὸν ἡγεμόνων ἔταξεν ἀποσκευὰς καὶ συχνοὺς ἐπὶ τούτοις πρὸς ἀσφάλειαν τῶν ἱππέων. μεθ’ οὓς αὐτὸς ἐξήλαυνεν τούς τε ἐπιλέκτους τῶν πεζῶν καὶ ἱππέων καὶ τοὺς λογχοφόρους ἔχων. εἵπετο δ’ αὐτῷ τὸ ἴδιον τοῦ τάγματος ἱππικόν· ἴδιοι γὰρ ἑκάστου τάγματος εἴκοσι πρὸς τοῖς ἑκατὸν ἱππεῖς. τούτοις δ’ ἠκολούθουν οἱ τὰς ἑλεπόλεις φέροντες ὀρεῖς καὶ τὰ λοιπὰ μηχανήματα. μετὰ τούτους ἡγεμόνες τε καὶ σπειρῶν ἔπαρχοι σὺν χιλιάρχοις, ἐπιλέκτους περὶ σφᾶς στρατιώτας ἔχοντες· ἔπειτα αἱ σημαῖαι περιίσχουσαι τὸν ἀετόν, ὃς παντὸς ἄρχει Ῥωμαίοις τάγματος, βασιλεύς τε οἰωνῶν ἁπάντων καὶ ἀλκιμώτατος ὤν· ὃ δὴ καὶ τῆς ἡγεμονίας τεκμήριον αὐτοῖς καὶ κλῃδών, ἐφ’ οὓς ἂν ἴωσιν, τοῦ κρατήσειν δοκεῖ. τοῖς δὲ ἱεροῖς ἠκολούθουν οἱ σαλπιγκταί, καὶ κατόπιν αὐτῶν ἡ φάλαγξ τὸ στῖφος εἰς ἓξ πλατύνασα. τούτοις παρείπετό τις ἑκατόνταρχος ἐξ ἔθους τὴν τάξιν ἐπισκοπούμενος. τὸ δ’ οἰκετικὸν ἑκάστου τάγματος ἅπαν τοῖς πεζοῖς εἵπετο, τὰς ἀποσκευὰς τῶν στρατιωτῶν ἐπὶ τοῖς ὀρεῦσιν καὶ τοῖς ὑποζυγίοις ἄγοντες· κατόπιν δὲ πάντων [τῶν ταγμάτων] ὁ μίσθιος ὄχλος, οἷς οὐραγοὶ πρὸς ἀσφάλειαν ἠκολούθουν πεζοί τε καὶ ὁπλῖται καὶ τῶν ἱππέων συχνοί.", "st": "3.6.2"}, {"sp": "N", "t": "Οὕτως ὁδεύσας Οὐεσπασιανὸς μετὰ τῆς δυνάμεως εἰς τοὺς ὅρους ἀφικνεῖται τῆς Γαλιλαίας, ἔνθα καταστρατοπεδευσάμενος ὡρμημένους εἰς πόλεμον τοὺς στρατιώτας κατεῖχεν, ἐπιδεικνύμενος τὴν στρατιὰν εἰς κατάπληξιν τοῖς πολεμίοις καὶ μετανοίας καιρὸν διδούς, εἰ πρὸ μάχης μεταβάλοιντο· ἅμα δὲ καὶ πρὸς πολιορκίαν τῶν ἐρυμάτων ἐξηρτύετο. μετάνοιαν μὲν οὖν τῆς ἀποστάσεως ὀφθεὶς ὁ στρατηγὸς πολλοῖς ἐνειργάσατο, κατάπληξιν δὲ πᾶσιν· οἱ μὲν γὰρ περὶ τὸν Ἰώσηπον ἐστρατοπεδευκότες οὐκ ἄπωθεν τῆς Σεπφώρεως παρὰ πόλιν Γαρὶν καλουμένην ἐπεὶ πλησιάζοντα τὸν πόλεμον ἤκουσαν ὅσον τε οὔπω τοὺς Ῥωμαίους συμμίξοντας σφίσιν, οὐ μόνον πρὸ μάχης, ἀλλὰ καὶ πρὶν ἰδεῖν τοὺς ἐχθροὺς διασκίδνανται φυγῇ. καταλείπεται δ’ ὁ Ἰώσηπος μετ’ ὀλίγων, καὶ κατιδὼν ὡς οὔτε δέχεσθαι τοὺς πολεμίους ἀρκετὴν ἔχει δύναμιν καὶ πεπτώκοι τὰ φρονήματα τῶν Ἰουδαίων ἄσμενοί τ’ ἄν, εἰ πιστεύοιντο, χωροῖεν οἱ πλείους ἐπὶ σπονδάς, ἐδεδίει μὲν ἤδη περὶ παντὸς τοῦ πολέμου, τότε δ’ ὡς πορρωτάτω χωρίζεσθαι τῶν κινδύνων ἔκρινεν. ἀναλαβὼν δὲ τοὺς συμμείναντας εἰς Τιβεριάδα καταφεύγει.", "st": "3.6.3"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ τῇ πόλει τῶν Γαδάρων ἐπελθὼν αἱρεῖ τε κατὰ πρώτην ἔφοδον αὐτὴν μαχίμου πλήθους ἔρημον καταλαβών, καὶ παρελθὼν εἴσω πάντας ἡβηδὸν ἀναιρεῖ μηδεμιᾶς τῶν Ῥωμαίων ἡλικίας ἔλεον ποιουμένων μίσει πρὸς τὸ ἔθνος καὶ μνήμῃ τῆς κατὰ τὸν Κέστιον αὐτῶν παρανομίας. ἐμπίμπρησιν δὲ οὐ μόνον αὐτὴν τὴν πόλιν, ἀλλὰ καὶ τὰς πέριξ κώμας πάσας τε καὶ πολίχνας, ἃς μὲν παντελῶς ἐκλελειμμένας, ἔστιν δ’ ἃς αὐτὸς ἐξανδραποδιζόμενος.", "st": "3.7.1"}, {"sp": "N", "t": "Ὁ δ’ Ἰώσηπος ἣν πρὸς ἀσφάλειαν εἵλετο πόλιν αὐτὸς ἐνέπλησεν δέους καταφυγών. οἱ δὲ ἀπὸ τῆς Τιβεριάδος οὐκ ἄν, εἰ μὴ πρὸς τὸ πᾶν ἀπεγνώκει τὸν πόλεμον, τραπῆναί ποτε αὐτὸν ᾤοντο. καὶ κατὰ τοῦτό γε οὐ διημάρτανον αὐτοῦ τῆς γνώμης· ἑώρα μὲν γάρ, ποῖ ῥέψει τὰ Ἰουδαίων τέλους, καὶ μίαν αὐτῶν ᾔδει σωτηρίαν, εἰ μεταβάλοιντο. αὐτὸς δὲ καίπερ συγγνωσθήσεσθαι παρὰ Ῥωμαίοις προσδοκῶν, ὅμως τεθνάναι μᾶλλον εἵλετο πολλάκις ἢ καταπροδοὺς τὴν πατρίδα καὶ τὴν ἐμπιστευθεῖσαν αὐτῷ στρατηγίαν ὑβρίσας εὐτυχεῖν παρ’ οἷς πολεμήσων ἐπέμφθη. γράφειν οὖν τοῖς ἐν τέλει τῶν Ἱεροσολύμων διέγνω μετὰ ἀκριβείας τὰ πράγματα, ὡς μήτ’ ἐπὶ μεῖζον ἐξάρας τὴν τῶν πολεμίων ἰσχὺν αὖθις εἰς δειλίαν κακίζοιτο μήτε ἐνδεέστερον ἀπαγγείλας κἂν μετανοήσαντας ἴσως θρασύνοιεν, ἵνα τε ἢ σπονδὰς αἱρούμενοι ταχέως ἀντιγράψωσιν ἢ πολεμεῖν ἐγνωκότες πρὸς Ῥωμαίους ἀξιόμαχον αὐτῷ πέμψωσι δύναμιν. ὁ μὲν οὖν ταῦτ’ ἐπιστείλας πέμπει διὰ τάχους ἐπὶ Ἱεροσολύμων τοὺς τὰ γράμματα κομίζοντας.", "st": "3.7.2"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ ὡρμημένος ἐξαιρεῖν τὴν Ἰωταπάταν, πέπυστο γὰρ εἰς αὐτὴν πλείστους τῶν πολεμίων συμπεφευγέναι καὶ ἄλλως ὁρμητήριον ἰσχυρὸν οὖσαν αὐτῶν, πέμπει πεζούς τε καὶ ἱππεῖς τοὺς προεξομαλιοῦντας τὴν ὁδὸν ὀρεινὴν ὑπάρχουσαν καὶ πετρώδη, δύσβατον δὲ καὶ πεζοῖς, ἱππεῦσιν δ’ ἀμήχανον. οἱ μὲν οὖν τέσσαρσιν ἡμέραις ἐξειργάσαντο καὶ πλατεῖαν ἤνοιξαν τῇ στρατιᾷ λεωφόρον· τῇ πέμπτῃ δ’ ὁ Ἰώσηπος, αὕτη δ’ ἦν Ἀρτεμισίου μηνὸς μία καὶ εἰκάς, φθάνει παρελθὼν εἰς τὴν Ἰωταπάταν ἐκ τῆς Τιβεριάδος καὶ πεπτωκότα τοῖς Ἰουδαίοις ἐγείρει τὰ φρονήματα. Οὐεσπασιανῷ δέ τις εὐαγγελίζεται τὴν μετάβασιν τοῦ ἀνδρὸς αὐτόμολος καὶ κατήπειγεν ἐπὶ τὴν πόλιν ὡς μετ’ ἐκείνης αἱρήσοντα πᾶσαν Ἰουδαίαν, εἰ λάβοι τὸν Ἰώσηπον ὑποχείριον. ὁ δ’ ἁρπάσας ὥσπερ μέγιστον εὐτύχημα τὴν ἀγγελίαν, καὶ προνοίᾳ θεοῦ τὸν συνετώτατον εἶναι δοκοῦντα τῶν πολεμίων οἰόμενος εἰς εἱρκτὴν αὐθαίρετον παρελθεῖν, εὐθέως μὲν σὺν χιλίοις ἱππεῦσιν πέμπει Πλάκιδον καὶ δεκαδάρχην Αἰβούτιον, ἄνδρα τῶν ἐπισήμων κατὰ χεῖρα καὶ σύνεσιν, περικατασχεῖν κελεύσας τὴν πόλιν, ὡς μὴ λάθοι διαδρὰς ὁ Ἰώσηπος.", "st": "3.7.3"}, {"sp": "N", "t": "Αὐτὸς δὲ μετὰ μίαν ἡμέραν ἀναλαβὼν πᾶσαν τὴν δύναμιν εἵπετο καὶ μέχρι δείλης ὁδεύσας πρὸς τὴν Ἰωταπάταν ἀφικνεῖται. ἀναλαβὼν δὲ τὴν στρατιὰν εἰς τὸ προσάρκτιον αὐτῆς μέρος ἔν τινι λόφῳ στρατοπεδεύεται διέχοντι σταδίους ἑπτὰ τῆς πόλεως, πειρώμενος ὡς μάλιστα τοῖς πολεμίοις εὐσύνοπτος εἶναι πρὸς ἔκπληξιν· ἣ καὶ παραχρῆμα τοσαύτη τοὺς Ἰουδαίους κατέσχεν, ὡς μηδένα τοῦ τείχους τολμῆσαι προελθεῖν. Ῥωμαῖοι δ’ εὐθὺς μὲν ἀπώκνησαν προσβαλεῖν δι’ ὅλης ὡδευκότες ἡμέρας, διπλῇ δὲ τῇ φάλαγγι κυκλοῦνται τὴν πόλιν καὶ τρίτην ἔξωθεν περιιστᾶσιν τὴν ἵππον, πάσας ἀποφράσσοντες αὐτοῖς τὰς ἐξόδους. τοῦτ’ ἐν ἀπογνώσει σωτηρίας παρώξυνε τοὺς Ἰουδαίους πρὸς τόλμαν· οὐδὲν γὰρ ἀνάγκης ἐν πολέμῳ μαχιμώτερον.", "st": "3.7.4"}, {"sp": "N", "t": "Γενομένης δὲ μεθ’ ἡμέραν προσβολῆς τὸ μὲν πρῶτον Ἰουδαῖοι κατὰ χώραν μένοντες ἀντεῖχον ἀντικρὺ τῶν Ῥωμαίων ἐστρατοπεδευκότες πρὸ τοῦ τείχους· ὡς δὲ Οὐεσπασιανὸς τούτοις μὲν τοὺς τοξότας καὶ σφενδονήτας καὶ πᾶν τὸ τῶν ἑκηβόλων πλῆθος ἐπιστήσας ἐπέτρεψεν βάλλειν, αὐτὸς δὲ μετὰ τῶν πεζῶν εἰς τὸ πρόσαντες ἀνώθει καθ’ ὃ τὸ τεῖχος ἦν εὐάλωτον, δείσας ὁ Ἰώσηπος περὶ τῇ πόλει προπηδᾷ καὶ σὺν αὐτῷ πᾶν τὸ τῶν Ἰουδαίων πλῆθος. συμπεσόντες δὲ τοῖς Ῥωμαίοις ἀθρόοι τοῦ μὲν τείχους ἀνέστειλαν αὐτούς, πολλὰ δ’ ἐπεδείκνυντο χειρῶν ἔργα καὶ τόλμης. οὐκ ἔλασσόν γε μὴν ὧν ἔδρων ἀντέπασχον· ὅσον γὰρ αὐτοὺς ἡ τῆς σωτηρίας ἀπόγνωσις, τοσοῦτο τοὺς Ῥωμαίους αἰδὼς παρεκρότει, καὶ τοὺς μὲν ἐμπειρία μετ’ ἀλκῆς, τοὺς δὲ θράσος ὥπλιζε τῷ θυμῷ στρατηγουμένους. παραταξάμενοι δὲ δι’ ὅλης ἡμέρας νυκτὶ διαλύονται, τρώσαντες μὲν πλείστους Ῥωμαίων, δεκατρεῖς δ’ ἀνελόντες· αὐτῶν δ’ ἔπεσον μὲν δεκαεπτά, τραυματίαι δ’ ἐγένοντο ἑξακόσιοι.", "st": "3.7.5"}, {"sp": "N", "t": "Τῇ δ’ ὑστεραίᾳ πάλιν προσβάλλουσι τοῖς Ῥωμαίοις ἐπεξελθόντες καὶ πολὺ καρτερώτερον ἀντιπαρετάξαντο, θαρραλεώτεροι μὲν ἐκ τοῦ παρὰ λόγον ἀντισχεῖν τῇ προτέρᾳ γεγενημένοι, χρώμενοι δὲ καὶ τοῖς Ῥωμαίοις μαχιμωτέροις· ὑπὸ γὰρ αἰδοῦς εἰς ὀργὴν ἐξεκαίοντο τὸ μὴ ταχέως νικᾶν ἧτταν ἡγούμενοι. καὶ μέχρι πέμπτης ἡμέρας προσβολαὶ μὲν ἐγίνοντο τῶν Ῥωμαίων ἀδιάλειπτοι, ἐκδρομαὶ δὲ τῶν Ἰωταπατηνῶν καὶ τειχομαχίαι καρτερώτεραι, καὶ οὔτε Ἰουδαῖοι τὴν τῶν πολεμίων ἰσχὺν κατωρρώδουν οὔτε Ῥωμαῖοι πρὸς τὸ τῆς πόλεως δυσάλωτον ἀπέκαμνον.", "st": "3.7.6"}, {"sp": "N", "t": "Ἔστιν δ’ Ἰωταπάτα πλὴν ὀλίγου πᾶσα κρημνός, ἐκ μὲν τῶν ἄλλων μερῶν πάντοθεν φάραγξιν ἀπείροις ἀπότομος, ὡς τῶν κατιδεῖν πειρωμένων τὰς ὄψεις προεξασθενεῖν τοῦ βάθους, ἀπὸ βορέου δὲ προσιτὴ μόνον, καθ’ ὃ λήγοντι τῷ ὄρει πλαγίῳ προσέκτισται. καὶ τοῦτο δ’ ὁ Ἰώσηπος ἐμπεριειλήφει τειχίζων τὴν πόλιν, ὡς ἀκατάληπτον εἶναι πολεμίοις τὴν ὑπὲρ αὐτῆς ἀκρώρειαν. κυκλόθεν δ’ ἄλλοις ὄρεσιν καλυπτομένη, πρὶν εἰσαφίκοιτό τις εἰς αὐτήν, παντελῶς ἀόρατος ἦν. εἶχε μὲν οὖν οὕτως ὀχυρότητος Ἰωταπάτη·", "st": "3.7.7"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ τῇ τε φύσει τοῦ χωρίου καὶ ταῖς τόλμαις τῶν Ἰουδαίων ἀντιφιλονεικῶν ἔγνω καρτερώτερον ἅπτεσθαι τῆς πολιορκίας, καὶ προσκαλεσάμενος τοὺς ὑπ’ αὐτὸν ἡγεμόνας ἐβουλεύετο περὶ τῆς προσβολῆς. δόξαν δὲ χῶσαι τὸ προσιτὸν τοῦ τείχους ἐπὶ συγκομιδὴν ὕλης ἐκπέμπει πᾶν τὸ στράτευμα, καὶ κοπέντων τῶν περὶ τὴν πόλιν ὀρῶν συναλισθείσης τε ἅμα τοῖς ξύλοις ἀπείρου χερμάδος, οἱ μὲν πρὸς ἀλεωρὰν τῶν ὕπερθεν ἀφιεμένων βελῶν γέρρα διατείναντες ὑπὲρ χαρακωμάτων ἔχουν ὑπ’ αὐτοῖς οὐδὲν ἢ μικρὰ βλαπτόμενοι ταῖς ἀπὸ τοῦ τείχους βολαῖς· οἱ δὲ τοὺς πλησίον ὄχθους ἀνασπῶντες γῆν αὐτοῖς ἀδιαλείπτως ἔφερον, καὶ τριχῆ διῃρημένων ἀργὸς ἦν οὐδείς. οἱ δὲ Ἰουδαῖοι πέτρας τε μεγάλας ἀπὸ τῶν τειχῶν τοῖς σκεπάσμασιν αὐτῶν ἐπηφίεσαν καὶ πᾶν εἶδος βελῶν· ἦν δὲ καὶ μὴ διικνουμένων πολὺς ὁ ψόφος καὶ φοβερὸς ἐμπόδιον τοῖς ἐργαζομένοις.", "st": "3.7.8"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ ἐν κύκλῳ τὰς ἀφετηρίους μηχανὰς ἐπιστήσας, τὰ πάντα δ’ ἦν ἑκατὸν ἑξήκοντα ὄργανα, βάλλειν ἐκέλευσεν τοὺς ἐπὶ τοῦ τείχους. ὁμοῦ δὲ οἵ τε καταπέλται τὰς λόγχας ἀνερροίζουν καὶ ταλαντιαῖοι λίθοι μέγεθος ἐκ τῶν πετροβόλων ἐβάλλοντο πῦρ τε καὶ πλῆθος ἀθρόων οἰστῶν, ἅπερ οὐ μόνον τὸ τεῖχος ἀνεπίβατον τοῖς Ἰουδαίοις ἐποίησεν, ἀλλὰ καὶ τὴν ἐντὸς ὅσης ἐφικνεῖτο χώρας· καὶ γὰρ καὶ τὸ τῶν Ἀράβων τοξοτῶν πλῆθος ἀκοντισταί τε καὶ σφενδονῆται πάντες ἅμα τοῖς μηχανήμασιν ἔβαλλον. οὐ μὴν εἰργόμενοι τῆς καθύπερθεν ἀμύνης ἠρέμουν· ἐκτρέχοντες γὰρ λῃστρικώτερον κατὰ λόχους περιέσπων τε τῶν ἐργαζομένων τὰς σκέπας καὶ τοὺς γυμνουμένους ἔπαιον, καὶ καθ’ ὃ παρείκοιεν ἐκεῖνοι διερρίπτουν τε τὸ χῶμα καὶ τὰ χαρακώματα σὺν τοῖς γέρροις ἐνεπίμπρασαν, μέχρι συνεὶς Οὐεσπασιανὸς τὴν διαίρεσιν τῶν ἔργων αἰτίαν εἶναι τῆς βλάβης, τὰ γὰρ διαστήματα τοῖς Ἰουδαίοις προσβολῆς παρεῖχεν τόπον, ἑνοῖ τὰ σκεπάσματα, καὶ συναφθείσης ἅμα αὐτοῖς τῆς δυνάμεως ἀνείρχθησαν αἱ τῶν Ἰουδαίων παραδύσεις.", "st": "3.7.9"}, {"sp": "N", "t": "Ἐγειρομένου δὲ τοῦ χώματος ἤδη καὶ ταῖς ἐπάλξεσιν ὅσον οὔπω πλησιάζοντος δεινὸν ὁ Ἰώσηπος νομίσας, εἰ μηδὲν ἀντιμηχανήσαιτο τῇ πόλει σωτήριον, συναθροίζει τέκτονας καὶ τὸ τεῖχος ἐκέλευσεν ὑψοῦν. τῶν δ’ ἀδύνατον εἶναι φαμένων οἰκοδομεῖν τοσούτοις βέλεσι βαλλομένους, σκέπην αὐτοῖς ἐπινοεῖ τοιάνδε· δρυφάκτους πήξασθαι κελεύσας ἐμπετάσαι τε βύρσας νεοδόρους βοῶν, ὡς ἀναδέχοιντο μὲν τοὺς ἀπὸ τῶν πετροβόλων λίθους κολπούμεναι, περιολισθάνοι δὲ ἀπ’ αὐτῶν καὶ τὰ λοιπὰ βέλη καὶ τὸ πῦρ ὑπὸ τῆς ἰκμάδος εἴργοιτο, προανίστησιν τῶν τεκτόνων. ὑφ’ οἷς ἀσφαλῶς ἐργαζόμενοι δι’ ἡμέρας τε καὶ νυκτὸς τὸ τεῖχος ἤγειραν εἰς εἴκοσι πήχεις τὸ ὕψος, καὶ συχνοὺς μὲν πύργους ἐνῳκοδόμησαν αὐτῷ, καρτερὰν δὲ ἔπαλξιν ἐφηρμόσαντο. τοῦτο τοῖς Ῥωμαίοις ἤδη τῆς πόλεως ἐντὸς οἰομένοις εἶναι πολλὴν ἐποίησεν ἀθυμίαν, καὶ πρός τε τὴν ἐπίνοιαν τοῦ Ἰωσήπου καὶ τὸ παράστημα τῶν ἐπὶ τῆς πόλεως κατεπλάγησαν.", "st": "3.7.10"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ καὶ πρὸς τὸ πανοῦργον τοῦ στρατηγήματος καὶ πρὸς τὰς τόλμας παρωξύνετο τῶν Ἰωταπατηνῶν· πάλιν γὰρ ἀναθαρσήσαντες ἐπὶ τῷ τειχισμῷ τοῖς Ῥωμαίοις ἐπεξέθεον, καὶ καθ’ ἡμέραν ἐγίνοντο συμπλοκαὶ κατὰ λόχους ἐπίνοιά τε λῃστρικὴ πᾶσα καὶ τῶν προστυχόντων ἁρπαγαὶ καὶ τῶν ἄλλων ἔργων πυρπολήσεις, ἕως Οὐεσπασιανὸς ἀναπαύσας τὴν στρατιὰν μάχης διέγνω προσκαθεζόμενος σπάνει τῶν ἐπιτηδείων αἱρεῖν τὴν πόλιν· ἢ γὰρ ἀναγκαζομένους ταῖς ἀπορίαις ἱκετεύσειν αὐτὸν ἢ μέχρι παντὸς ἀπαυθαδισαμένους διαφθαρήσεσθαι λιμῷ. πολύ τε ῥᾴοσιν αὐτοῖς ἠξίου χρήσεσθαι κατὰ τὴν μάχην, εἰ διαλιπὼν αὖθις ἐκτετρυχωμένοις ἐπιπέσοι. φρουρεῖν δὴ πάσας αὐτῶν ἐκέλευσεν τὰς ἐξόδους.", "st": "3.7.11"}, {"sp": "N", "t": "Τοῖς δὲ σίτου μὲν πλῆθος ἦν ἔνδον καὶ τῶν ἄλλων πλὴν ἁλὸς ἁπάντων, ἔνδεια δὲ ὕδατος ὡς ἂν πηγῆς μὲν οὐκ οὔσης κατὰ τὴν πόλιν, τῷ δ’ ὀμβρίῳ διαρκουμένων τῶν ἐν αὐτῇ· σπάνιον δ’ εἴ ποτε τὸ κλίμα θέρους ὕεται. καὶ κατὰ ταύτην τὴν ὥραν πολιορκουμένων ἀθυμία δεινὴ πρὸς τὴν τοῦ δίψους ἐπίνοιαν ἦν, ἀσχαλλόντων ἤδη ὡς καθάπαν ἐπιλελοιπότος ὕδατος· ὁ γὰρ Ἰώσηπος τήν τε πόλιν ὁρῶν τῶν ἄλλων ἐπιτηδείων εὔπορον καὶ τὰ φρονήματα γενναῖα τῶν ἀνδρῶν, βουλόμενός τε παρ’ ἐλπίδα τοῖς Ῥωμαίοις ἐκτεῖναι τὴν πολιορκίαν, μέτρῳ τὸ ποτὸν αὐτοῖς διένειμεν εὐθέως. οἱ δὲ τὸ ταμιεύεσθαι χαλεπώτερον ἐνδείας ὑπελάμβανον, καὶ τὸ μὴ αὐτεξούσιον αὐτῶν πλέον ἐκίνει τὴν ὄρεξιν, καὶ καθάπερ εἰς ἔσχατον ἤδη δίψους προήκοντες ἀπέκαμνον. διακείμενοι δὲ οὕτως οὐκ ἐλάνθανον τοὺς Ῥωμαίους· ἀπὸ γὰρ τοῦ κατάντους ἑώρων αὐτοὺς ὑπὲρ τὸ τεῖχος ἐφ’ ἕνα συρρέοντας τόπον καὶ μετρουμένους τὸ ὕδωρ, ἐφ’ ὃν καὶ τοῖς ὀξυβελέσιν ἐξικνούμενοι πολλοὺς ἀνῄρουν.", "st": "3.7.12"}, {"sp": "N", "t": "Καὶ Οὐεσπασιανὸς μὲν οὐκ εἰς μακρὰν τῶν ἐκδοχείων κενωθέντων ἤλπιζεν ὑπὸ τῆς ἀνάγκης αὐτῷ παραδοθήσεσθαι τὴν πόλιν· ὁ δὲ Ἰώσηπος κλάσαι τὴν ἐλπίδα ταύτην αὐτῷ προαιρούμενος ἐμβρέξαι κελεύει πλείστους τὰ ἱμάτια καὶ κατακρεμάσαι περὶ τὰς ἐπάλξεις, ὥστε περιρρεῖσθαι πᾶν ἐξαπίνης τὸ τεῖχος. πρὸς τοῦτ’ ἀθυμία τῶν Ῥωμαίων καὶ κατάπληξις ἦν θεασαμένων εἰς χλεύην τοσοῦτον παραναλίσκοντας ὕδατος οὓς οὐδὲ ποτὸν ἔχειν ὑπελάμβανον, ὥστε καὶ τὸν στρατηγὸν ἀπογνόντα τὴν δι’ ἐνδείας ἅλωσιν τρέπεσθαι πάλιν πρὸς ὅπλα καὶ βίαν. ὃ δὴ τοῖς Ἰουδαίοις δι’ ἐπιθυμίας ἦν· ἀπεγνωκότες γὰρ ἑαυτοὺς καὶ τὴν πόλιν πρὸ λιμοῦ καὶ δίψης τὸν ἐν πολέμῳ θάνατον ᾑροῦντο.", "st": "3.7.13"}, {"sp": "N", "t": "Ὁ μέντοι γε Ἰώσηπος πρὸς τῷδε τῷ στρατηγήματι καὶ ἕτερον ἐπενόησεν εἰς περιουσίαν αὐτῷ· διά τινος χαράδρας δυσβάτου καὶ διὰ τοῦθ’ ὑπὸ τῶν φυλάκων ἀμελουμένης κατὰ τὰ πρὸς δύσιν μέρη τῆς φάραγγος ἐκπέμπων τινὰς γράμματά τε πρὸς οὓς ἠβούλετο τῶν ἔξω Ἰουδαίων διεπέμψατο καὶ παρ’ αὐτῶν ἐλάμβανεν, παντός τε ἐπιτηδείου τῶν ἀνὰ τὴν πόλιν ἐπιλελοιπότων εὐπόρησεν, ἕρπειν τὰ πολλὰ παρὰ τὰς φυλακὰς κελεύσας τοῖς ἐξιοῦσιν καὶ τὰ νῶτα καλύπτειν νάκεσιν, ὡς εἰ καὶ κατίδοι τις αὐτοὺς νύκτωρ, φαντασίαν παρέχοιεν κυνῶν, μέχρι συναισθόμενοι τὴν ἐπίνοιαν οἱ φρουροὶ περιίσχουσιν τὴν χαράδραν.", "st": "3.7.14"}, {"sp": "N", "t": "Καὶ τόθ’ ὁ Ἰώσηπος μὲν τὴν πόλιν οὐκ εἰς μακρὰν ὁρῶν ἀνθέξειν, ἐν ἀπόρῳ δὲ τὴν ἑαυτῶν σωτηρίαν εἰ μένοι, δρασμὸν ἅμα τοῖς δυνατοῖς ἐβουλεύετο. συναισθόμενοι δὲ τὸ πλῆθος καὶ περιχυθὲν αὐτῷ κατηντιβόλουν μὴ σφᾶς περιιδεῖν ἐπ’ αὐτῷ μόνῳ κειμένους· εἶναι γὰρ τῇ πόλει καὶ σωτηρίας μὲν ἐλπὶς παραμένων, παντὸς ἀγωνισομένου δι’ αὐτὸν προθύμως, κἂν ἁλῶσιν δέ, παραμυθίαν. πρέπειν δ’ αὐτῷ μήτε φυγεῖν τοὺς ἐχθροὺς μήτ’ ἐγκαταλιπεῖν τοὺς φίλους μήτ’ ἀποπηδᾶν ὥσπερ χειμαζομένης νεώς, εἰς ἣν ἐν γαλήνῃ παρῆλθεν· ἐπιβαπτίσειν γὰρ αὐτοῖς τὴν πόλιν μηδενὸς ἔτι τοῖς πολεμίοις τολμῶντος ἀνθίστασθαι δι’ ὃν ἂν θαρσοῖεν οἰχομένου.", "st": "3.7.15"}, {"sp": "N", "t": "Ὁ δὲ Ἰώσηπος τὸ κατ’ αὐτὸν ἀσφαλὲς ὑποστελλόμενος ὑπὲρ αὐτῶν ἔφασκεν ποιεῖσθαι τὴν ἔξοδον· μένων μὲν γὰρ οὔτ’ ἂν ὠφελῆσαί τι μέγα σωζομένους, κἂν ἁλίσκωνται, συναπολεῖσθαι περιττῶς, ἐκδὺς δὲ τῆς πολιορκίας ἔξωθεν αὐτοὺς ὠφελήσειν μέγιστα· τούς τε γὰρ ἐκ τῆς χώρας Γαλιλαίους συναθροίσειν ᾗ τάχος καὶ Ῥωμαίους ἑτέρῳ πολέμῳ τῆς πόλεως αὐτῶν ἀντιπερισπάσειν. οὐχ ὁρᾶν δέ, τί παρακαθεζόμενος αὐτοῖς χρήσιμος εἴη νῦν, πλὴν εἰ μὴ Ῥωμαίους παροξύνων μᾶλλον ἐπὶ τὴν πολιορκίαν, οὓς περὶ πλείστου ποιεῖσθαι λαβεῖν αὐτόν· εἰ δ’ ἐκδράντα πύθοιντο, πολὺ τῆς ἐπὶ τὴν πόλιν ὁρμῆς ἀνήσειν. οὐκ ἔπειθεν δὲ τούτοις, ἀλλὰ μᾶλλον ἐξέκαυσεν τὸ πλῆθος αὐτοῦ περιέχεσθαι· παιδία γοῦν καὶ γέροντες καὶ γύναια μετὰ νηπίων ὀδυρόμενα προσέπιπτον αὐτῷ καὶ τοῖς ποσὶν ἐμπλεκόμενοι πάντες εἴχοντο, καὶ μετὰ κωκυτῶν κοινωνὸν σφίσι τῆς τύχης μένειν ἱκέτευον, οὐ φθόνῳ τῆς ἐκείνου σωτηρίας, ἔμοιγε δοκεῖν, ἀλλ’ ἐλπίδι τῆς ἑαυτῶν· οὐδὲν γὰρ ἠξίουν πείσεσθαι δεινὸν Ἰωσήπου μένοντος.", "st": "3.7.16"}, {"sp": "N", "t": "Ὁ δὲ πειθομένῳ μὲν ἱκετηρίαν ταῦτα νομίσας, βιαζομένῳ δὲ φρουράν, πολὺ δ’ αὐτοῦ τῆς εἰς τὴν ἀπόλειψιν ὁρμῆς καὶ ὁ τῶν ὀδυρομένων ἔκλασεν οἶκτος, μένειν τε ἔγνω, καὶ τὴν κοινὴν τῆς πόλεως ἀπόγνωσιν ὁπλισάμενος, νῦν καιρός, εἰπών, ἄρχεσθαι μάχης, ὅτ’ ἐλπὶς οὐκ ἔστι σωτηρίας· καλὸν εὔκλειαν ἀντικαταλλαξάμενον τοῦ βίου καὶ δράσαντά τι γενναῖον εἰς μνήμην ὀψιγενῶν πεσεῖν, ἐπ’ ἔργα τρέπεται. καὶ προελθὼν μετὰ τῶν μαχιμωτάτων διεσκίδνα τε τοὺς φρουροὺς καὶ μέχρι τοῦ στρατοπέδου τῶν Ῥωμαίων κατέτρεχεν, καὶ τὰς μὲν ἐπὶ τῶν χωμάτων δέρρεις, αἷς ὑπεσκήνουν, διέσπα, τοῖς δὲ ἔργοις ἐνέβαλλεν πῦρ. τῇ τε ἑξῆς ὁμοίως καὶ τῇ τρίτῃ καὶ ἐπὶ συχνὰς ἡμέρας καὶ νύκτας πολεμῶν οὐκ ἔκαμνεν.", "st": "3.7.17"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ τῶν [τε] Ῥωμαίων κακουμένων ταῖς ἐκδρομαῖς, τρέπεσθαί τε γὰρ ὑπὸ Ἰουδαίων ᾐδοῦντο καὶ τραπέντων ἐπιδιώκειν βάρει τῶν ὅπλων ἦσαν βραδεῖς, οἵ τε Ἰουδαῖοι πρίν τι παθεῖν ἀεὶ δρῶντες ἀνέφευγον εἰς τὴν πόλιν, τοῖς μὲν ὁπλίταις τὰς ὁρμὰς αὐτῶν ἐκκλίνειν ἐκέλευσεν καὶ μὴ συμπλέκεσθαι θανατῶσιν ἀνθρώποις· οὐδὲν γὰρ ἀλκιμώτερον εἶναι τῆς ἀπογνώσεως, περισβέννυσθαι δὲ αὐτῶν τὰς ὁρμὰς σκοπῶν ἀπορουμένας ὥσπερ ὕλης τὸ πῦρ· προσήκειν γε μὴν καὶ Ῥωμαίοις μετὰ ἀσφαλείας καὶ τὸ νικᾶν, ὡς ἂν οὐκ ἐξ ἀνάγκης πολεμοῦσιν, ἀλλὰ προσκτωμένοις. τοῖς δὲ τῶν Ἀράβων τοξόταις καὶ τοῖς ἀπὸ τῆς Συρίας σφενδονήταις καὶ λιθοβόλοις τὰ πολλὰ τοὺς Ἰουδαίους ἀνέστελλεν· ἠρέμει δὲ οὐδὲ τῶν ἀφετηρίων ὀργάνων τὸ πλῆθος. οἱ δὲ τούτοις μὲν εἶκον κακούμενοι, τῶν δὲ πόρρω βαλλομένων ἐνδοτέρω γινόμενοι προσέκειντο τοῖς Ῥωμαίοις χαλεποὶ καὶ ψυχῆς καὶ σώματος ἀφειδοῦντες ἐμάχοντο, ἐκ διαδοχῆς ἑκάτεροι τὸ κεκμηκὸς ἑαυτῶν ἀναλαμβάνοντες.", "st": "3.7.18"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ ἡγούμενος τῷ μήκει τοῦ χρόνου καὶ ταῖς ἐκδρομαῖς ἀντιπολιορκεῖσθαι, τῶν χωμάτων ἤδη τοῖς τείχεσι πελαζόντων προσάγειν ἔγνω τὸν κριόν. ὁ δ’ ἐστὶν ὑπερμεγέθης δοκὸς ἱστῷ νηὸς παραπλήσιος· ἐστόμωται δὲ παχεῖ σιδήρῳ κατ’ ἄκρον εἰς κριοῦ προτομήν, ἀφ’ οὗ καὶ καλεῖται, τετυπωμένῳ. καταιωρεῖται δὲ κάλοις μέσος ὥσπερ ἀπὸ πλάστιγγος ἑτέρας δοκοῦ, σταυροῖς ἑκατέρωθεν ἑδραίοις ὑπεστηριγμένης. ἀνωθούμενος δὲ ὑπὸ πλήθους ἀνδρῶν εἰς τὸ κατόπιν, τῶν αὐτῶν ἀθρόως πάλιν εἰς τοὔμπροσθεν ἐπιβρισάντων τύπτει τὰ τείχη τῷ προανέχοντι σιδήρῳ. καὶ οὐδεὶς οὕτως καρτερὸς πύργος ἢ περίβολος πλατύς, ὃς κἂν τὰς πρώτας πληγὰς ἐνέγκῃ κατίσχυσεν τῆς ἐπιμονῆς. ἐπὶ ταύτην τὴν πεῖραν ὁ στρατηγὸς τῶν Ῥωμαίων μετέβαινεν βίᾳ τὴν πόλιν ἑλεῖν σπεύδων, ὡς τὸ προσκαθέζεσθαι βλαβερὸν ἦν Ἰουδαίων οὐκ ἠρεμούντων. οἱ μὲν οὖν τούς τε καταπέλτας καὶ τὰ λοιπὰ τῶν ἀφετηρίων, ὡς ἐξικνοῖτο τῶν ἐπὶ τοῦ τείχους κωλύειν πειρωμένων, ἔγγιον προσαγαγόντες ἔβαλλον· ὁμοίως δὲ συνήγγιζον οἱ τοξόται καὶ σφενδονῆται. διὰ δὲ ταῦτα μηδενὸς τῶν περιβόλων ἐπιβῆναι τολμῶντος προσῆγον ἕτεροι τὸν κριὸν γέρροις τε διηνεκέσι καὶ καθύπερθεν πεφραγμένον δέρρει πρός τε αὐτῶν καὶ τοῦ μηχανήματος ἀσφάλειαν. καὶ κατὰ τὴν πρώτην πληγὴν διεσείσθη μὲν τὸ τεῖχος, κραυγὴ δὲ μεγίστη παρὰ τῶν ἔνδον ἤρθη καθάπερ ἑαλωκότων ἤδη.", "st": "3.7.19"}, {"sp": "N", "t": "Πολλάκις δὲ εἰς τὸν αὐτὸν παίοντας τόπον ὁ Ἰώσηπος ὁρῶν ὅσον οὔπω καταρριφθησόμενον τὸ τεῖχος, σοφίζεται κατ’ ὀλίγον τὴν βίαν τοῦ μηχανήματος. σάκκους ἀχύρων πληρώσαντας ἐκέλευσεν καθιμᾶν καθ’ ὃ φερόμενον ἀεὶ τὸν κριὸν ὁρῷεν, ὡς πλάζοιτό τε ἡ ἐμβολή, καὶ δεχόμενοι τὰς πληγὰς ἐκκενοῖεν τῇ χαυνότητι. τοῦτο πλείστην διατριβὴν παρέσχεν τοῖς Ῥωμαίοις, καθ’ ὃ μὲν τρέποιεν τὴν μηχανὴν ἀντιπαραγόντων τοὺς σάκκους τῶν ὕπερθεν, ὑποβαλλόντων δὲ ταῖς ἐμβολαῖς, ὡς μηδὲν κατ’ ἀντιτυπίαν βλάπτεσθαι τὸ τεῖχος· ἕως ἀντεπινοήσαντες κοντοὺς οἱ Ῥωμαῖοι μακροὺς καὶ δρέπανα δήσαντες ἐπ’ ἄκρων τοὺς σάκους ἀπέτεμνον. ἐνεργοῦς δὲ οὕτω τῆς ἑλεπόλεως γενομένης καὶ τοῦ τείχους, νεοπαγὲς γὰρ ἦν, ἐνδιδόντος ἤδη, τὸ λοιπὸν ἐπὶ τὴν ἐκ πυρὸς ἄμυναν οἱ περὶ τὸν Ἰώσηπον ὥρμησαν. ἁψάμενοι δὲ ὅσον αὔης εἶχον ὕλης τριχόθεν ἐπεκθέουσιν, καὶ τά τε μηχανήματα καὶ τὰ γέρρα καὶ τὰ χώματα τῶν Ῥωμαίων ὑπεπίμπρασαν. οἱ δὲ κακῶς ἐπεβοήθουν πρός τε τὴν τόλμαν αὐτῶν καταπεπληγότες καὶ ὑπὸ τῆς φλογὸς τὰς ἀμύνας φθανόμενοι· ξηρᾶς γὰρ ὕλης, πρὸς δὲ ἀσφάλτου τε καὶ πίσσης, ἔτι δὲ θείου διίπτατο τὸ πῦρ ἐπινοίας τάχιον, καὶ τὰ πολλῷ καμάτῳ πεπονημένα τοῖς Ῥωμαίοις ἐπὶ μιᾶς ὥρας ἐνέμετο.", "st": "3.7.20"}, {"sp": "N", "t": "Ἔνθα καὶ ἀνήρ τις ἐξεφάνη Ἰουδαίων λόγου καὶ μνήμης ἄξιος· Σαμίου μὲν παῖς ἦν, Ἐλεάζαρος δὲ ἐκαλεῖτο, Σαβὰ δὲ πατρὶς αὐτῷ τῆς Γαλιλαίας· ὑπερμεγέθη δὲ πέτραν ἀράμενος ἀφίησιν ἀπὸ τοῦ τείχους ἐπὶ τὴν ἑλέπολιν μετὰ τοσαύτης βίας, ὥστε ἀπορρῆξαι τὴν κεφαλὴν τοῦ μηχανήματος, ἣν καὶ καταπηδήσας ἐκ μέσων αἴρεται τῶν πολεμίων καὶ μετὰ πολλῆς ἀδείας ἐπὶ τὸ τεῖχος ἔφερεν. σκοπὸς δὲ πᾶσιν τοῖς ἐχθροῖς γενόμενος καὶ γυμνῷ τῷ σώματι τὰς πληγὰς δεξάμενος πέντε μὲν διαπείρεται βέλεσιν, πρὸς οὐδὲν δὲ τούτων ἐπιστραφείς, ὅτε τὸ τεῖχος ἀνέβη καὶ περίοπτος πᾶσιν τῆς εὐτολμίας ἔστη, τότε ἰλυσπώμενος ὑπὸ τῶν τραυμάτων μετὰ τοῦ κριοῦ κατέπεσεν. ἄριστοι μετ’ αὐτὸν ἐφάνησαν ἀδελφοὶ δύο Νετείρας καὶ Φίλιππος, ἀπὸ Ῥούμας κώμης, Γαλιλαῖοι καὶ αὐτοί, οἳ προπηδῶσι μὲν εἰς τοὺς ἀπὸ τοῦ δεκάτου τάγματος, τοσούτῳ δὲ ῥοίζῳ καὶ βίᾳ τοῖς Ῥωμαίοις συνέπεσον, ὡς διαρρῆξαί τε τὰς τάξεις καὶ τρέψασθαι καθ’ οὓς ἐφορμήσειαν ἅπαντας.", "st": "3.7.21"}, {"sp": "N", "t": "Μετὰ τούτους ὅ τε Ἰώσηπος καὶ τὸ λοιπὸν πλῆθος ἀράμενοι πῦρ πάλιν τὰ μηχανήματα καὶ τὰς ὑποδύσεις ἅμα τοῖς ἔργοις ὑφῆψαν τοῦ τε πέμπτου καὶ τοῦ δεκάτου τραπέντος τάγματος, οἱ λοιποὶ δὲ φθάσαντες καὶ τὰ ὄργανα καὶ πᾶσαν ὕλην κατέχωσαν. περὶ δὲ δείλην πάλιν ἀναστήσαντες προσῆγον τὸν κριὸν ᾗ προπεπονήκει τυπτόμενον τὸ τεῖχος. ἔνθα τις τῶν ἀμυνομένων ἀπ’ αὐτοῦ βάλλει τὸν Οὐεσπασιανὸν βέλει κατὰ τὸν ταρσὸν τοῦ ποδὸς καὶ τιτρώσκει μὲν ἐπιπολαίως προεκλύσαντος τὸ βληθὲν τοῦ διαστήματος, μέγιστον δὲ θόρυβον ἐνεποίησεν τοῖς Ῥωμαίοις· πρὸς γὰρ τὸ αἷμα ταραχθέντων τῶν πλησίον φήμη διὰ παντὸς ἐπῄει τοῦ στρατοῦ, καὶ τῆς πολιορκίας οἱ πλείους ἀφέμενοι μετ’ ἐκπλήξεως καὶ δέους ἐπὶ τὸν στρατηγὸν συνέθεον. πρὸ δὲ πάντων Τίτος δείσας περὶ τῷ πατρὶ παρῆν, ὡς τὸ πλῆθος καὶ τῇ πρὸς τὸν ἡγούμενον εὐνοίᾳ καὶ τῇ τοῦ παιδὸς ἀγωνίᾳ συγχυθῆναι. ῥᾷστα μέντοι τόν τε υἱὸν ὁ πατὴρ δεδιότα καὶ τὴν στρατιὰν ἔπαυσεν τοῦ θορύβου· τῶν γὰρ ἀλγηδόνων ἐπάνω γενόμενος καὶ πᾶσιν τοῖς ἐπτοημένοις δι’ αὐτὸν ὀφθῆναι σπουδάσας χαλεπώτερον Ἰουδαίοις ἐπῆρεν τὸν πόλεμον· ἕκαστος γὰρ ὡς τιμωρὸς τοῦ στρατηγοῦ προκινδυνεύειν ἤθελεν, καὶ βοῇ παρακροτοῦντες ἀλλήλους ἐπὶ τὸ τεῖχος ὥρμων.", "st": "3.7.22"}, {"sp": "N", "t": "Οἱ δὲ περὶ τὸν Ἰώσηπον καίπερ ἐπ’ ἀλλήλοις πίπτοντες ὑπὸ τῶν καταπελτικῶν καὶ τῶν πετροβόλων, ὅμως οὐκ ἀπετρέποντο τοῦ τείχους, ἀλλὰ πυρὶ καὶ σιδήρῳ καὶ πέτροις τοὺς ἐπὶ τὰ γέρρα τὸν κριὸν ἐπιβρίθοντας ἔβαλλον. καὶ ἤνυον μὲν οὐδὲν ἢ μικρόν, αὐτοὶ δὲ ἀδιαλείπτως ἔπιπτον ὑπὸ μὴ βλεπομένων καθορώμενοι· αὐτοί τε γὰρ ὑπὸ τῆς σφετέρας περιλαμπόμενοι φλογὸς σκοπὸς ἦσαν τοῖς πολεμίοις εὐσύνοπτος ὥσπερ ἐν ἡμέρᾳ, καὶ τῶν ὀργάνων πόρρωθεν μὴ βλεπομένων δυσφύλακτον ἦν τὸ βαλλόμενον. ἥ τε οὖν τῶν ὀξυβελῶν καὶ καταπελτῶν βία πολλοὺς ἅμα διήλαυνεν, καὶ τῶν ὑπὸ τῆς μηχανῆς ἀφιεμένων πετρῶν ὁ ῥοῖζος ἐπάλξεις τε ἀπέσυρεν καὶ γωνίας ἀπέθρυπτε πύργων. ἀνδρῶν μὲν γὰρ † οὕτως ἰσχυρὸν στῖφος, ὃ μὴ μέχρις ἐσχάτης στρώννυται φάλαγγος βίᾳ τε καὶ μεγέθει τοῦ λίθου. μάθοι δ’ ἄν τις τὴν τοῦ μηχανήματος ἀλκὴν ἐκ τῶν ἐπὶ τῆσδε τῆς νυκτὸς γενομένων· πληγεὶς γάρ τις ἀπ’ αὐτοῦ τῶν περὶ τὸν Ἰώσηπον ἑστώτων ἀνὰ τὸ τεῖχος ἀπαράσσεται τὴν κεφαλὴν ὑπὸ τῆς πέτρας, καὶ τὸ κρανίον ἀπὸ τριῶν ἐσφενδονήθη σταδίων. γυναικός τε μεθ’ ἡμέραν ἐγκύμονος πληγείσης τὴν γαστέρα, προῄει δὲ νέον ἐξ οἰκίας, ἐξέσεισεν ἐφ’ ἡμιστάδιον τὸ βρέφος· τοσαύτη ἦν ἡ τοῦ λιθοβόλου βία. τῶν οὖν ὀργάνων φοβερώτερος ὁ ῥοῖζος, τῶν δὲ βαλλομένων ἦν [ὁ] ψόφος. ἐπάλληλοι δὲ ἐκτύπουν οἱ νεκροὶ κατὰ τοῦ τείχους ῥιπτόμενοι, καὶ δεινὴ μὲν ἔνδοθεν κραυγὴ γυναικῶν ἠγείρετο, συνήχουν δ’ ἔξωθεν οἰμωγαὶ φονευομένων. αἵματι δ’ ἐρρεῖτο πᾶς ὁ πρὸ τῆς μάχης περίβολος, καὶ προσβατὸν ὑπὸ πτωμάτων τὸ τεῖχος ἐγίνετο. φοβερωτέραν δὲ ἐποίουν τὴν βοὴν περιηχοῦντα τὰ ὄρη, καὶ οὐδὲν ἐπ’ ἐκείνης τῆς νυκτὸς οὔτε εἰς ἀκοῆς οὔτε εἰς ὄψεως κατάπληξιν ἀπελείπετο. πλεῖστοι μέν γε τῶν ἐπὶ τῆς Ἰωταπάτης ἀγωνιζόμενοι γενναίως ἔπεσον, πλεῖστοι δ’ ἐγένοντο τραυματίαι, καὶ μόλις περὶ τὴν ἑωθινὴν φυλακὴν ἐνδίδωσι τοῖς μηχανήμασι τὸ τεῖχος ἀδιαλείπτως τυπτόμενον· οἱ δὲ φραξάμενοι τοῖς σώμασι καὶ τοῖς ὅπλοις τὸ καταρριφθὲν ἀντωχύρωσαν πρὶν βληθῆναι τὰς ἐπιβατηρίους ὑπὸ τῶν Ῥωμαίων μηχανάς.", "st": "3.7.23"}, {"sp": "N", "t": "Ὑπὸ δὲ τὴν ἕω Οὐεσπασιανὸς ἐπὶ τὴν κατάληψιν τῆς πόλεως συνῆγεν τὴν στρατιὰν ὀλίγον ἀπὸ τοῦ νυκτερινοῦ πόνου διαναπαύσας. βουλόμενος δ’ ἀπὸ τῶν καταρριφθέντων περισπάσαι τοὺς εἴργοντας τοὺς μὲν γενναιοτάτους τῶν ἱππέων ἀποβήσας [τῶν ἵππων] τριχῇ διέταξεν κατὰ τὰ πεπτωκότα τοῦ τείχους, πάντοθεν πεφραγμένους τοῖς ὅπλοις καὶ τοὺς κοντοὺς προΐσχοντας, ὡς ὁπότε τὰς ἐπιβατηρίους βάλλοιεν μηχανὰς κατάρχοιντο τῆς εἰσόδου· κατόπιν δὲ αὐτῶν ἔταξεν τοῦ πεζοῦ τὸ ἀκμαιότατον, τὸ δὲ λοιπὸν ἱππικὸν ἀντιπαρεξέτεινεν τῷ τείχει κατὰ πᾶσαν τὴν ὀρεινὴν πρὸς τὸ μηδένα τῶν ἀναφευγόντων ἐκ τῆς ἁλώσεως διαλαθεῖν. κατόπιν δὲ τούτων περιέστησεν τοὺς τοξότας ἔχειν κελεύσας ἕτοιμα τὰ βέλη πρὸς ἄφεσιν, ὁμοίως δὲ καὶ σφενδονήτας καὶ τοὺς ἐπὶ τῶν μηχανημάτων, ἑτέρους δὲ κλίμακας ἀραμένους προσφέρειν ἐπάνω τοῖς ἀκεραίοις τείχεσιν, ἵν’ οἱ μὲν τούτους κωλύειν πειρώμενοι καταλίποιεν τὴν ἐπὶ τοῖς καταρριφθεῖσιν φυλακήν, οἱ λοιποὶ δὲ ὑπ’ ἀθρόων βιαζόμενοι τῶν βελῶν εἴξωσιν τῆς εἰσόδου.", "st": "3.7.24"}, {"sp": "N", "t": "Ἰώσηπος δὲ συνιεὶς τὴν ἐπίνοιαν ἐπὶ μὲν τοῦ μένοντος τείχους σὺν τοῖς κεκμηκόσιν ἵστησι τοὺς γηραιοὺς ὡς μηδὲν ταύτῃ βλαβησομένους, εἰς δὲ τὰ παρερρωγότα τοῦ τείχους τοὺς δυνατωτάτους καὶ πρὸ πάντων ἀνὰ ἓξ ἄνδρας, μεθ’ ὧν καὶ αὐτὸς εἰς τὸ προκινδυνεύειν ἐκληρώσατο. ἐκέλευσέν τε πρὸς μὲν τὸν ἀλαλαγμὸν τῶν ταγμάτων ἀποφράξαι τὰς ἀκοάς, ὡς ἂν μὴ καταπλαγεῖεν, πρὸς δὲ τὸ πλῆθος τῶν βελῶν συνοκλάσαντας καλύψασθαι καθύπερθεν τοῖς θυρεοῖς ὑποχωρῆσαί τε πρὸς ὀλίγον, ἕως τὰς φαρέτρας κενώσωσιν οἱ τοξόται. βαλλόντων δὲ τὰς ἐπιβατηρίους μηχανὰς αὐτοὺς προπηδᾶν καὶ διὰ τῶν ἰδίων ὀργάνων ἀπαντᾶν τοῖς πολεμίοις, ἀγωνίζεσθαί τε ἕκαστον οὐχ ὡς ὑπὲρ σωθησομένης, ἀλλ’ ὡς ὑπὲρ ἀπολωλυίας ἤδη τῆς πατρίδος ἀμυνόμενον, λαμβάνειν τε πρὸ ὀφθαλμῶν σφαγησομένους γέροντας καὶ τέκνα καὶ γυναῖκας ἀναιρεθησομένας ὑπὸ τῶν ἐχθρῶν ὅσον οὐδέπω, καὶ τὸν ἐπὶ ταῖς μελλούσαις συμφοραῖς θυμὸν προαλίσαντας ἐναφεῖναι τοῖς δράσουσιν αὐτάς.", "st": "3.7.25"}, {"sp": "N", "t": "Ἔταξεν μὲν οὖν οὕτως ἑκάτερον· τὸ δ’ ἀργὸν ἀπὸ τῆς πόλεως· πλῆθος, γύναια καὶ παῖδες, ὡς ἐθεάσαντο τριπλῇ μὲν φάλαγγι τὴν πόλιν ἐζωσμένην, οὐδὲν γὰρ εἰς τὴν μάχην μετακεκίνητο τῶν πάλαι φυλακῶν, πρὸς δὲ τοῖς βεβλημένοις τείχεσιν τοὺς πολεμίους ξιφήρεις καὶ τὴν καθύπερθεν ὀρεινὴν λαμπομένην ὅπλοις, τά τε βέλη τοῖς τοξόταις ἐπανέχοντα τῶν Ἀράβων, ὕστατόν τινα κωκυτὸν ἁλώσεως συνήχησαν ὡς οὐκ ἀπειλουμένων ἔτι τῶν κακῶν ἀλλ’ ἤδη παρόντων. ὁ δὲ Ἰώσηπος τὰς μὲν γυναῖκας, ὡς μὴ θηλύνοιεν οἴκτῳ τὰς ὁρμὰς τῶν σφετέρων, κατακλείει ταῖς οἰκίαις μετ’ ἀπειλῆς ἡσυχάζειν κελεύσας· αὐτὸς δὲ ἐπὶ τῶν ἐρειφθέντων ᾗ ἔλαχεν παρῄει. τοῖς μὲν οὖν καθ’ ἕτερα προσφέρουσι τὰς κλίμακας οὐ προσεῖχεν, ἀπεκαραδόκει δὲ τὴν ὁρμὴν τῶν βελῶν.", "st": "3.7.26"}, {"sp": "N", "t": "Ὁμοῦ δ’ οἵ τε σαλπικταὶ τῶν ταγμάτων ἁπάντων συνήχησαν καὶ δεινὸν ἐπηλάλαξεν ἡ στρατιά, καὶ πάντοθεν ἀφιεμένων ἀπὸ συνθήματος τῶν βελῶν τὸ φῶς ὑπετέμνετο. μεμνημένοι γε μὴν τῶν τοῦ Ἰωσήπου προσταγμάτων οἱ σὺν αὐτῷ τάς τε ἀκοὰς πρὸς τὴν βοὴν καὶ τὰ σώματα πρὸς τὰς ἀφέσεις ἐφράξαντο, καὶ βαλλόντων τὰς μηχανὰς ἐπεξέδραμον δι’ αὐτῶν πρὶν ἐπιβῆναι τοὺς βαλόντας, συμπλεκόμενοί τε τοῖς ἀνιοῦσιν παντοῖα καὶ χειρῶν ἔργα καὶ ψυχῆς ἐναπεδείκνυντο, πειρώμενοι παρὰ τὰς ἐσχάτας συμφορὰς μὴ χείρους φαίνεσθαι τῶν ἐν ἀκινδύνῳ τῷ κατὰ σφᾶς ἀνδριζομένων· ὥστε οὐ πρότερον ἀπερρήγνυντο τῶν Ῥωμαίων πρὶν ἢ πεσεῖν ἢ διαφθεῖραι. ὡς δ’ οἱ μὲν ἔκαμνον διηνεκῶς ἀμυνόμενοι καὶ τοὺς προμάχους ἀμείβειν οὐκ ἔχοντες, τὸ κεκμηκὸς δὲ τῶν Ῥωμαίων ἀκραιφνεῖς διεδέχοντο καὶ ταχέως ἀντὶ τῶν ἀποβιασθέντων ἐπέβαινον ἕτεροι, παρακελευσάμενοί τε ἀλλήλοις καὶ πλευρὰν μὲν ἑνώσαντες, τοῖς δὲ θυρεοῖς καθύπερθεν φραξάμενοι στῖφος ἄρρηκτον ἐγένοντο καὶ καθάπερ ἑνὶ σώματι πάσῃ τῇ φάλαγγι τοὺς Ἰουδαίους ἀνωθοῦντες ἤδη τοῦ τείχους ἐπέβαινον.", "st": "3.7.27"}, {"sp": "N", "t": "Ὁ δὲ Ἰώσηπος ἐν ταῖς ἀμηχανίαις σύμβουλον λαβὼν τὴν ἀνάγκην, ἡ δέ ἐστιν δεινὴ πρὸς ἐπίνοιαν, ὅταν αὐτὴν ἀπόγνωσις ἐρεθίζῃ, ζέον ἔλαιον ἐκέλευσεν καταχέειν τῶν συνησπικότων. οἱ δ’ ὡς παρεσκευασμένον ἔχοντες μετὰ τάχους πολλοὶ καὶ πολὺ πάντοθεν τῶν Ῥωμαίων κατέχεον συνεπαφιέντες καὶ τὰ ἀγγεῖα βρασσόμενα τῇ θέρμῃ. τοῦτο καιομένων τῶν Ῥωμαίων διεσκέδασεν τὴν τάξιν, καὶ μετὰ δεινῶν ἀλγηδόνων ἀπεκυλινδοῦντο τοῦ τείχους· ῥᾷστα μὲν γὰρ τὸ ἔλαιον ἀπὸ κορυφῆς μέχρι ποδῶν ὑπὸ τὰς πανοπλίας διέρρει τοῦ σώματος ὅλου καὶ τὴν σάρκα φλογὸς οὐδὲν ἔλασσον ἐπεβόσκετο, θερμαινόμενόν τε φύσει ταχέως καὶ ψυχόμενον βραδέως διὰ τὴν πιότητα. τοῖς δὲ θώραξιν καὶ τοῖς κράνεσιν ἐνδεδεμένων ἀπαλλαγὴ τῆς καύσεως οὐκ ἦν, πηδῶντες δὲ καὶ συνειλούμενοι ταῖς ἀλγηδόσιν ἀπὸ τῶν γεφυρωμάτων ἔπιπτον· οἱ δὲ τραπέντες εἰς τοὺς σφετέρους πρόσω βιαζομένους εὐχείρωτοι τοῖς κατόπιν τιτρώσκουσιν ἦσαν.", "st": "3.7.28"}, {"sp": "N", "t": "Ἐπέλιπεν δὲ οὔτε Ῥωμαίους ἐν ταῖς κακοπραγίαις ἰσχὺς οὔτε τοὺς Ἰουδαίους σύνεσις, ἀλλ’ οἱ μὲν καίπερ οἰκτρὰ πάσχοντας ὁρῶντες τοὺς καταχυθέντας ὅμως εἰς τοὺς καταχέοντας ἐφέροντο τὸν πρὸ αὐτοῦ κακίζων ἕκαστος ὡς ἐμπόδιον ὄντα τῆς ῥώμης· οἱ δὲ Ἰουδαῖοι δόλῳ δευτέρῳ τὰς προσβάσεις αὐτῶν ἐπέσφαλλον τῆλιν ἑφθὴν ὑποχέοντες ταῖς σανίσιν, ἧς ἐπολισθάνοντες ὑπεσύροντο; καὶ οὔτε τῶν τρεπομένων οὔτε τῶν προσβαινόντων τις ὀρθὸς ἔμενεν, ἀλλ’ οἱ μὲν ἐπ’ αὐτῶν ὑπτιαζόμενοι τῶν ἐπιβατηρίων μηχανῶν συνεπατοῦντο, πολλοὶ δὲ ἐπὶ τὸ χῶμα κατέπιπτον. ἐπαίοντο δ’ ὑπὸ τῶν Ἰουδαίων οἱ πεσόντες· ἐσφαλμένων γὰρ τῶν Ῥωμαίων οὗτοι τῆς κατὰ χεῖρα συμπλοκῆς ἐλευθερωθέντες εἰς τὰς βολὰς εὐσχόλουν. πολλὰ δὲ κακουμένους ἐν τῇ προσβολῇ τοὺς στρατιώτας ὁ στρατηγὸς περὶ δείλην ἀνεκάλει. ἔπεσον δὲ τούτων μὲν οὐκ ὀλίγοι καὶ πλείους ἐτρώθησαν, τῶν δ’ ἀπὸ τῆς Ἰωταπάτης ἀπέθανον μὲν ἓξ ἄνδρες, τραυματίαι δ’ ὑπὲρ τριακοσίους ἀνεκομίσθησαν. εἰκάδι μὲν Δαισίου μηνὸς ἡ παράταξις ἦν.", "st": "3.7.29"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ ἐπὶ τοῖς συμβεβηκόσι τὴν στρατιὰν παραμυθούμενος, ὡς θυμουμένους ἑώρα καὶ οὐ προτροπῆς ἀλλ’ ἔργων δεομένους, προσυψῶσαι μὲν τὰ χώματα, πύργους δὲ τρεῖς πεντήκοντα ποδῶν τὸ ὕψος ἕκαστον κατασκευάσαι κελεύσας πάντοθεν σιδήρῳ κεκαλυμμένους, ὡς ἑδραῖοί τε εἶεν ὑπὸ βρίθους καὶ δυσάλωτοι πυρί, τῶν χωμάτων ἐπέστησεν, συνεπιβήσας αὐτοῖς ἀκοντιστάς τε καὶ τοξότας καὶ τῶν ἀφετηρίων ὀργάνων τὰ κουφότερα, πρὸς δὲ τοὺς ῥωμαλεωτάτους σφενδονήτας· οἳ μὴ καθορώμενοι διὰ τὸ ὕψος καὶ τὰ θωράκια τῶν πύργων εἰς καθορωμένους τοὺς ἐπὶ τοῦ τείχους ἔβαλλον. οἱ δὲ μήτε κατὰ κόρσης φερομένων τῶν βελῶν ἐκκλίνειν ῥᾳδίως δυνάμενοι μήτε τοὺς ἀφανεῖς ἀμύνεσθαι, καὶ τὸ μὲν ὕψος τῶν πύργων δυσέφικτον ὁρῶντες ἐκ χειρὸς βέλει, πυρὶ δὲ τὸν περὶ αὐτοῖς σίδηρον ἀνάλωτον, ἔφευγον ἀπὸ τοῦ τείχους καὶ προσβάλλειν πειρωμένοις ἐπεξέθεον. καὶ οἱ μὲν ἐπὶ τῆς Ἰωταπάτης ἀντεῖχον οὕτως, ἀναιρούμενοί τε καθ’ ἡμέραν πολλοὶ καὶ μηδὲν ἀντικακοῦν τοὺς πολεμίους, ὅτι μὴ μετὰ κινδύνων ἀνείργειν ἔχοντες.", "st": "3.7.30"}, {"sp": "N", "t": "Κατὰ δὲ τὰς αὐτὰς ἡμέρας Οὐεσπασιανὸς ἐπί τινα τῶν τῆς Ἰωταπάτης ἀστυγειτόνων πόλιν, Ἴαφα καλεῖται, νεωτερίζουσαν καὶ τῶν Ἰωταπατηνῶν παρὰ δόξαν ἀντεχόντων ἐπαιρομένην, Τραϊανὸν ὄντα τοῦ δεκάτου τάγματος ἡγεμόνα ἐκπέμπει παραδοὺς αὐτῷ χιλίους μὲν ἱππεῖς πεζοὺς δὲ δισχιλίους. ὁ δὲ τὴν μὲν πόλιν δυσάλωτον καταλαβών, πρὸς γὰρ τῷ φύσει καρτερὰ τυγχάνειν οὖσα καὶ διπλῷ περιβόλῳ τετείχιστο, προαπηντηκότας δὲ τοὺς ἐξ αὐτῆς ἑτοίμους εἰς μάχην ἰδὼν συμβάλλει καὶ πρὸς ὀλίγον ἀντισχόντας ἐδίωκεν. συμφυγόντων δὲ εἰς τὸ πρῶτον τεῖχος οἱ Ῥωμαῖοι κατὰ πόδας προσκείμενοι συνεισέπεσον. ὁρμήσαντας δὲ πάλιν εἰς τὸ δεύτερον τεῖχος ἀποκλείουσιν τῆς πόλεως οἱ σφέτεροι δείσαντες μὴ συνεισβάλωσιν οἱ πολέμιοι. θεὸς δ’ ἦν ἄρα ὁ Ῥωμαίοις τὰ Γαλιλαίων πάθη χαριζόμενος, ὃς καὶ τότε τὸν τῆς πόλεως λαὸν αὔτανδρον χερσὶν οἰκείαις ἐκκλεισθέντα πρὸς ἀπώλειαν ἔκδοτον φονῶσιν ἐχθροῖς παρέστησεν. ἐμπίπτοντες γὰρ ἀθρόοι ταῖς πύλαις καὶ πολλὰ τοὺς ἐπ’ αὐτῶν ὀνομαστὶ καλοῦντες ἐν μέσαις ἀπεσφάττοντο ταῖς ἱκεσίαις. καὶ τὸ μὲν πρῶτον αὐτοῖς τεῖχος οἱ πολέμιοι, τὸ δεύτερον δ’ ἔκλεισαν οἱ σφέτεροι, μέσοι δὲ τοῖν δυοῖν κατειλούμενοι περιβόλων βύζην, πολλοὶ μὲν τοῖς ἀλλήλων, πολλοὶ δὲ τοῖς ἰδίοις περιεπείροντο ξίφεσιν, ἄπειροι δὲ ὑπὸ Ῥωμαίων ἔπιπτον οὐδὲ ὅσον εἰς ἄμυναν ἀναθαρροῦντες· πρὸς γὰρ τῷ καταπεπλῆχθαι τοὺς πολεμίους τὰς ψυχὰς αὐτῶν ἔκλασεν ἡ τῶν οἰκείων προδοσία. πέρας ἔθνησκον οὐ Ῥωμαίοις ἀλλὰ τοῖς ἰδίοις καταρώμενοι, μέχρι πάντες ἀπώλοντο μύριοι καὶ δισχίλιοι τὸν ἀριθμὸν ὄντες. κενὴν δὲ μαχίμων λογιζόμενος εἶναι τὴν πόλιν ὁ Τραϊανός, εἰ δὲ καί τινες ἔνδον εἶεν, οἰόμενος μηδὲν αὐτοὺς τολμήσειν ὑπὸ δέους, ἀνετίθει τῷ στρατηγῷ τὴν ἅλωσιν, καὶ στείλας ἀγγέλους πρὸς Οὐεσπασιανὸν ᾐτεῖτο πέμψαι τὸν υἱὸν αὐτῷ Τίτον ἐπιθήσοντα τῇ νίκῃ τέλος. ὁ δὲ συμβαλὼν ὑπολείπεσθαί τινα πόνον μετὰ στρατιᾶς τὸν υἱὸν ἐπιπέμπει πεντακοσίων μὲν ἱππέων χιλίων δὲ πεζῶν. ὁ δὲ πρὸς τὴν πόλιν ἐλθὼν διὰ τάχους καὶ διατάξας τὴν στρατιὰν ἐπὶ μὲν τοῦ λαιοῦ κέρως τὸν Τραϊανὸν ἵστησιν, αὐτὸς δὲ τὸ δεξιὸν ἔχων ἐξηγεῖτο πρὸς τὴν πολιορκίαν. τῶν δὲ στρατιωτῶν κλίμακας πάντοθεν τῷ τείχει προσφερόντων πρὸς ὀλίγον οἱ Γαλιλαῖοι καθύπερθεν ἀμυνόμενοι λείπουσιν τὸν περίβολον, ἐπιπηδήσαντες δὲ οἱ περὶ τὸν Τίτον τῆς μὲν πόλεως ἐκράτησαν ταχέως, πρὸς δὲ τοὺς ἔνδον αὐτοῖς συστραφέντας καρτερὰ μάχη συρρήγνυται· καὶ γὰρ ἐν τοῖς στενωποῖς οἱ δυνατοὶ προσέπιπτον καὶ ἀπὸ τῶν οἰκιῶν αἱ γυναῖκες ἔβαλλον πᾶν τὸ προστυχὸν αὐταῖς. καὶ μέχρι μὲν ἓξ ὡρῶν ἀντεῖχον μαχόμενοι, δαπανηθέντων δὲ τῶν μαχίμων τὸ λοιπὸν πλῆθος ἔν τε τοῖς ὑπαίθροις καὶ κατὰ τὰς οἰκίας ἀπεσφάττοντο νέοι τε ὁμοῦ καὶ γέροντες· οὐδὲν γὰρ ἄρρεν ὑπελείφθη δίχα νηπίων, ἃ μετὰ γυναικῶν ἐξηνδραποδίσαντο. τῶν μὲν οὖν ἀναιρεθέντων ἀνά τε τὴν πόλιν κἀπὶ τῆς προτέρας παρατάξεως ἀριθμὸς μύριοι πρὸς τοῖς πεντακισχιλίοις ἦν, τὰ δ’ αἰχμάλωτα δισχίλια ἑκατὸν καὶ τριάκοντα. τοῦτο συνέβη τὸ πάθος Γαλιλαίοις πέμπτῃ καὶ εἰκάδι Δαισίου μηνός.", "st": "3.7.31"}, {"sp": "N", "t": "Ἔμειναν δὲ οὐδὲ Σαμαρεῖς ἀπείρατοι συμφορῶν· ἀθροισθέντες γὰρ ἐπὶ τὸ Γαριζεὶν καλούμενον ὄρος, ὅπερ αὐτοῖς ἐστιν ἅγιον, κατὰ χώραν μὲν ἔμενον, πολέμου δ’ εἶχεν ἀπειλὴν ἥ τε σύνοδος αὐτῶν καὶ τὰ φρονήματα. καὶ οὐδὲ τοῖς γειτνιῶσι κακοῖς ἐσωφρονίζοντο, πρὸς δὲ τὰς Ῥωμαίων εὐπραγίας ἐν ἀλογίστῳ τὴν κατὰ σφᾶς ἀσθένειαν ᾤδουν καὶ μετέωροι πρὸς ταραχὴν ὑπῆρχον. ἐδόκει δὲ Οὐεσπασιανῷ φθάσαι τὸ κίνημα καὶ τὰς ὁρμὰς αὐτῶν ὑποτέμνεσθαι· καὶ γὰρ φρουραῖς ἡ Σαμαρεῖτις ὅλη διείληπτο τό τε πλῆθος τῶν ἐληλυθότων καὶ ἡ σύνταξις ἦν φοβερά. Κερεάλιον οὖν ἔπαρχον ὄντα τοῦ πέμπτου τάγματος μετὰ ἑξακοσίων ἱππέων καὶ πεζῶν τρισχιλίων πέμπει. τούτῳ προσβαίνειν μὲν τὸ ὄρος καὶ συνάπτειν μάχην οὐκ ἀσφαλὲς ἔδοξεν πολλῶν καθύπερθεν τῶν πολεμίων ὄντων, κυκλωσάμενος δὲ τῇ δυνάμει πᾶσαν τὴν ὑπόρειον δι’ ὅλης αὐτοὺς ἐφρούρει τῆς ἡμέρας. συνέβη δὲ ὕδατος ἀπορουμένων τῶν Σαμαρέων ἐκφλεγῆναι τότε καὶ καῦμα δεινόν, ὥρα δ’ ἦν θέρους καὶ τῶν ἐπιτηδείων τὸ πλῆθος ἀπαράσκευον, ὡς τοὺς μὲν αὐθημερὸν ὑπὸ τοῦ δίψους ἀποθανεῖν, πολλοὺς δὲ τῆς τοιαύτης ἀπωλείας τὸ δουλεύειν προαιρουμένους Ῥωμαίοις προσφυγεῖν. ἐξ ὧν συνεὶς ὁ Κερεάλιος καὶ τοὺς ἔτι συμμένοντας ὑπὸ τῶν δεινῶν κατεαγότας ἐπαναβαίνει τῷ ὄρει, καὶ τὴν δύναμιν ἐν κύκλῳ περιστήσας τοῖς πολεμίοις τὸ μὲν πρῶτον ἐπὶ δεξιὰς προυκαλεῖτο καὶ σώζεσθαι παρεκάλει διαβεβαιούμενος ἀσφάλειαν τὰ ὅπλα ῥίψασιν· ὡς δ’ οὐκ ἔπειθεν, προσπεσὼν ἀπέκτεινεν πάντας, χιλίους ἑξακοσίους ἐπὶ μυρίοις ὄντας· ἑβδόμῃ καὶ εἰκάδι Δαισίου μηνὸς ἐπράχθη. καὶ τοιαύταις μὲν συμφοραῖς Σαμαρεῖται ἐχρήσαντο.", "st": "3.7.32"}, {"sp": "N", "t": "Τῶν δ’ ἀνὰ τὰ Ἰωτάπατα καρτερούντων καὶ παρ’ ἐλπίδα τοῖς δεινοῖς ἀντεχόντων τεσσαρακοστῇ μὲν ἡμέρᾳ καὶ ἑβδόμῃ τὰ χώματα τῶν Ῥωμαίων ὑπερήρθη τὸ τεῖχος, αὐτομολεῖ δέ τις πρὸς τὸν Οὐεσπασιανὸν τῆς αὐτῆς ἡμέρας τήν τε ὀλιγότητα τῶν ἐπὶ τῆς πόλεως ἐξαγγέλλων καὶ τὴν ἀσθένειαν, καὶ ὡς ἀγρυπνίᾳ διηνεκεῖ καὶ μάχαις ἐπαλλήλοις δεδαπανημένοι δυνατοὶ μὲν εἶεν οὐδὲ βιαζομένους ἔτι φέρειν, καὶ δόλῳ δ’ ἂν ἁλοῖεν, εἴ τις ἐπιθοῖτο· περὶ γὰρ τὴν ἐσχάτην φυλακήν, καθ’ ἣν ἄνεσίν τε τῶν δεινῶν ἐδόκουν ἔχειν καὶ καθάπτεται μάλιστα κεκοπωμένων ἑωθινὸς ὕπνος, καταδαρθάνειν ἔφασκεν τοὺς φύλακας συνεβούλευέν τε κατὰ ταύτην τὴν ὥραν ἐπελθεῖν. τῷ δ’ ἦν μὲν δι’ ὑπονοίας ὁ αὐτόμολος τό τε πρὸς ἀλλήλους πιστὸν εἰδότι τῶν Ἰουδαίων καὶ τὴν πρὸς τὰς κολάσεις ὑπεροψίαν, ἐπειδὴ καὶ πρότερον ληφθείς τις τῶν ἀπὸ τῆς Ἰωταπάτης πρὸς πᾶσαν αἰκίαν βασάνων ἀντέσχεν καὶ μηδὲν διὰ πυρὸς ἐξερευνῶσι τοῖς πολεμίοις περὶ τῶν ἔνδον εἰπὼν ἀνεσταυρώθη τοῦ θανάτου καταμειδιῶν· τά γε μὴν εἰκότα πιστὸν ἐποίει τὸν προδότην, καὶ τάχα μὲν ἀληθεύειν ἐκεῖνον, μηδὲν δ’ αὐτὸς ἐξ ἐνέδρας πείσεσθαι μέγα προσδοκῶν, τὸν μὲν φυλάσσειν ἐκέλευσεν, ἐπὶ δὲ τὴν κατάληψιν τῆς πόλεως παρεσκεύαζε τὴν στρατιάν.", "st": "3.7.33"}, {"sp": "N", "t": "Κατὰ δὲ τὴν μηνυθεῖσαν ὥραν ᾔεσαν ἡσυχῆ πρὸς τὸ τεῖχος. καὶ πρῶτος ἐπιβαίνει Τίτος σὺν ἑνὶ τῶν χιλιάρχων Δομετίῳ Σαβίνῳ τῶν ἀπὸ τοῦ πέμπτου καὶ δεκάτου τάγματος ὀλίγους ἄγων· ἀποσφάξαντες δὲ τοὺς φύλακας εἰσίασιν εἰς τὴν πόλιν, μεθ’ οὓς Σέκστος τις Καλουάριος χιλίαρχος καὶ Πλάκιδος τοὺς ὑπὸ σφίσι τεταγμένους εἰσῆγον. κατειλημμένης δὲ τῆς ἄκρας καὶ τῶν πολεμίων ἐν μέσῳ στρεφομένων, ἤδη δὲ καὶ ἡμέρας οὔσης, ὅμως οὔπω τῆς ἁλώσεως τοῖς κρατουμένοις αἴσθησις ἦν· καμάτῳ τε γὰρ οἱ πολλοὶ καὶ ὕπνῳ διαλέλυντο, καὶ τῶν διανισταμένων ὁμίχλη τὰς ὄψεις ἀπήμβλυνεν πολλὴ κατὰ τύχην τότε τῇ πόλει περιχυθεῖσα, μέχρι πάσης τῆς στρατιᾶς εἰσπεσούσης πρὸς μόνην τὴν τῶν κακῶν αἴσθησιν ἐξανέστησαν καὶ τὴν ἅλωσιν ἐπίστευον ἀναιρούμενοι. Ῥωμαίους δὲ κατὰ μνήμην ὧν ἐκ τῆς πολιορκίας ἔπαθον οὔτε φειδὼ εἰσῄει τινὸς οὔτ’ ἔλεος, ἀλλ’ εἰς τὸ κάταντες ἀπὸ τῆς ἄκρας τὸν λεὼ συνωθοῦντες ἐφόνευον. ἔνθα καὶ τοὺς ἔτι μάχεσθαι δυναμένους ἡ δυσχωρία τὴν ἄμυναν ἀφείλετο· θλιβόμενοι γὰρ ἐν τοῖς στενωποῖς καὶ κατὰ τοῦ πρανοῦς ὑπολισθάνοντες ῥέοντι κατ’ ἄκρας ἐκαλύπτοντο τῷ πολέμῳ. τοῦτο πολλοὺς καὶ τῶν περὶ τὸν Ἰώσηπον ἐπιλέκτων ἐπ’ αὐτοχειρίαν παρώξυνεν· κατιδόντες γάρ, ὡς οὐδένα τῶν Ῥωμαίων ἀνελεῖν δύνανται, τό γε πεσεῖν αὐτοὺς ὑπὸ Ῥωμαίων προέλαβον καὶ συναθροισθέντες ἐπὶ τὰ καταλήγοντα τῆς πόλεως σφᾶς αὐτοὺς ἀνεῖλον.", "st": "3.7.34"}, {"sp": "N", "t": "Ὅσοι γε μὴν ὑπὸ πρώτην τῆς καταλήψεως αἴσθησιν τῶν φυλάκων διαφυγεῖν ἔφθασαν ἀναβάντες εἴς τινα τῶν προσαρκτίων πύργων μέχρι μέν τινος ἀπημύναντο, περισχεθέντες δὲ πλήθει τῶν πολεμίων ὀψὲ παρεῖσαν τὰς δεξιὰς καὶ τοῖς ἐφεστῶσιν τὴν σφαγὴν εὔθυμοι παρέσχον. ἀναίμακτον δ’ ἂν ἦν αὐχῆσαι Ῥωμαίοις τὸ τέλος τῆς πολιορκίας, εἰ μὴ κατὰ τὴν ἅλωσιν εἷς ἔπεσέν τις· ἑκατοντάρχης ἦν Ἀντώνιος, θνήσκει δ’ ἐξ ἐνέδρας. τῶν γὰρ εἰς τὰ σπήλαιά τις συμπεφευγότων, πολλοὶ δ’ οὗτοι πλῆθος ἦσαν, ἱκετεύει τὸν Ἀντώνιον ὀρέξαι δεξιὰν αὐτῷ πίστιν τε σωτηρίας καὶ βοήθειαν πρὸς ἄνοδον· ὁ δ’ ἀφυλάκτως ὤρεγε τὴν χεῖρα, καὶ φθάσας αὐτὸν ἐκεῖνος νύττει κάτωθεν ὑπὸ τὸν βουβῶνα δόρατι καὶ παραχρῆμα διεργάζεται.", "st": "3.7.35"}, {"sp": "N", "t": "Κατ’ ἐκείνην μὲν οὖν τὴν ἡμέραν τὸ φανερὸν πλῆθος ἀνεῖλον οἱ Ῥωμαῖοι, ταῖς δ’ ἐπιούσαις ἀνερευνώμενοι τὰς καταδύσεις τοὺς ἐν τοῖς ὑπονόμοις καὶ τοῖς σπηλαίοις ἐπεξῄεσαν καὶ διὰ πάσης ἐχώρουν ἡλικίας πλὴν νηπίων καὶ γυναικῶν. καὶ τὰ μὲν αἰχμάλωτα χίλια πρὸς τοῖς διακοσίοις συνήχθη, νεκροὶ δὲ κατὰ τὴν ἅλωσιν καὶ τὰς πρότερον μάχας συνηριθμήθησαν τετρακισμύριοι. Οὐεσπασιανὸς δὲ τήν τε πόλιν κατασκάψαι κελεύει καὶ τὰ φρούρια πάντα προσεμπίπρησιν αὐτῆς. Ἰωτάπατα μὲν οὖν οὕτως ἑάλω τρεισκαιδεκάτῳ τῆς Νέρωνος ἡγεμονίας ἔτει Πανέμου νουμηνίᾳ.", "st": "3.7.36"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ τὸν Ἰώσηπον ἀναζητοῦντες κατά τε ὀργὴν σφετέραν καὶ σφόδρα τοῦ στρατηγοῦ φιλοτιμουμένου, μεγίστη γὰρ ἦν μοῖρα τοῦ πολέμου ληφθείς, τούς τε νεκροὺς διηρεύνων καὶ τοὺς ἀποκρύφους. ὁ δὲ τῆς πόλεως ἁλισκομένης δαιμονίῳ τινὶ συνεργίᾳ χρησάμενος μέσον μὲν ἑαυτὸν ἐκκλέπτει τῶν πολεμίων, καθάλλεται δὲ εἴς τινα βαθὺν λάκκον, ᾧ πλατὺ σπήλαιον διέζευκτο κατὰ πλευρὰν τοῖς ἄνωθεν ἀόρατον. ἔνθα τεσσαράκοντα μὲν τῶν ἐπισήμων ἄνδρας καταλαμβάνει λανθάνοντας, παρασκευὴν δ’ ἐπιτηδείων οὐκ ὀλίγαις ἡμέραις διαρκεῖν δυναμένην. μεθ’ ἡμέραν μὲν οὖν ὑπεστέλλετο τῶν πολεμίων πάντα διειληφότων, νυκτὸς δ’ ἀνιὼν ἐζήτει δρασμοῦ διάδυσιν καὶ τὰς φυλακὰς κατεσκέπτετο. φρουρουμένων δὲ πανταχόθεν πάντων δι’ αὐτὸν ὡς λαθεῖν οὐκ ἦν, αὖθις εἰς τὸ σπήλαιον κατῄει. δύο μὲν οὖν ἡμέραις διαλανθάνει, τῇ δὲ τρίτῃ γυναικὸς ἁλούσης τῶν ἅμα αὐτοῖς μηνύεται, καὶ Οὐεσπασιανὸς αὐτίκα μετὰ σπουδῆς πέμπει δύο χιλιάρχους Παυλῖνον καὶ Γαλλικανόν, δεξιάς τε τῷ Ἰωσήπῳ δοῦναι κελεύσας καὶ προτρεψομένους ἀνελθεῖν.", "st": "3.8.1"}, {"sp": "N", "t": "Ἀφικόμενοι γοῦν παρεκάλουν οὗτοι τὸν ἄνδρα καὶ πίστεις περὶ σωτηρίας ἐδίδοσαν, οὐ μὴν ἔπειθον· ἐκ γὰρ ὧν εἰκὸς ἦν τοσαῦτα δράσαντα παθεῖν, οὐκ ἐκ τοῦ φύσει τῶν παρακαλούντων ἡμέρου τὰς ὑποψίας συνέλεγεν ἐδεδίει τε ὡς ἐπὶ τιμωρίαν προκαλουμένους, ἕως Οὐεσπασιανὸς τρίτον ἐπιπέμπει χιλίαρχον Νικάνορα γνώριμον τῷ Ἰωσήπῳ καὶ συνήθη πάλαι. παρελθὼν δ’ οὗτος τό τε φύσει Ῥωμαίων χρηστὸν πρὸς οὓς ἂν ἅπαξ ἕλωσι διεξῄει, καὶ ὡς δι’ ἀρετὴν αὐτὸς θαυμάζοιτο μᾶλλον ἢ μισοῖτο πρὸς τῶν ἡγεμόνων, σπουδάζειν τε τὸν στρατηγὸν οὐκ ἐπὶ τιμωρίαν ἀναγαγεῖν αὐτόν, εἶναι γὰρ ταύτην καὶ παρὰ μὴ προϊόντος λαβεῖν, ἀλλὰ σῶσαι προαιρούμενον ἄνδρα γενναῖον. προσετίθει δ’ ὡς οὔτ’ ἂν Οὐεσπασιανὸς ἐνεδρεύων φίλον ἔπεμπεν, ἵνα τοῦ κακίστου πράγματος προστήσηται τὸ κάλλιστον, ἀπιστίας φιλίαν, οὐδ’ ἂν αὐτὸς ἀπατήσων ἄνδρα φίλον ὑπήκουσεν ἐλθεῖν.", "st": "3.8.2"}, {"sp": "N", "t": "Ἐνδοιάζοντος δὲ τοῦ Ἰωσήπου καὶ πρὸς τὸν Νικάνορα τὸ μὲν στρατιωτικὸν ὑπ’ ὀργῆς ἐκκαίειν τὸ σπήλαιον ὥρμητο, κατεῖχεν δ’ αὐτοὺς ὁ πολέμαρχος ζωγρῆσαι τὸν ἄνδρα φιλοτιμούμενος. ὡς δ’ ὅ τε Νικάνωρ προσέκειτο λιπαρῶν καὶ τὰς ἀπειλὰς τοῦ πολεμίου πλήθους ὁ Ἰώσηπος ἔμαθεν, ἀνάμνησις αὐτὸν τῶν διὰ νυκτὸς ὀνείρων εἰσέρχεται, δι’ ὧν ὁ θεὸς τάς τε μελλούσας αὐτῷ συμφορὰς προεσήμαινεν Ἰουδαίων καὶ τὰ περὶ τοὺς Ῥωμαίων βασιλεῖς ἐσόμενα. ἦν δὲ καὶ περὶ κρίσεις ὀνείρων ἱκανὸς συμβαλεῖν τὰ ἀμφιβόλως ὑπὸ τοῦ θείου λεγόμενα, τῶν γε μὴν ἱερῶν βίβλων οὐκ ἠγνόει τὰς προφητείας ὡς ἂν αὐτός τε ὢν ἱερεὺς καὶ ἱερέων ἔγγονος· ὧν ἐπὶ τῆς τότε ὥρας ἔνθους γενόμενος καὶ τὰ φρικώδη τῶν προσφάτων ὀνείρων σπάσας φαντάσματα προσφέρει τῷ θεῷ λεληθυῖαν εὐχήν, κἀπειδὴ τὸ Ἰουδαίων, ἔφη, φῦλον ὀκλάσαι δοκεῖ σοι τῷ κτίσαντι, μετέβη δὲ πρὸς Ῥωμαίους ἡ τύχη πᾶσα, καὶ τὴν ἐμὴν ψυχὴν ἐπελέξω τὰ μέλλοντα εἰπεῖν, δίδωμι μὲν Ῥωμαίοις τὰς χεῖρας ἑκὼν καὶ ζῶ, μαρτύρομαι δὲ ὡς οὐ προδότης, ἀλλὰ σὸς εἶμι διάκονος.", "st": "3.8.3"}, {"sp": "N", "t": "Ταῦτ’ εἰπὼν ἐνεδίδου τῷ Νικάνορι. καὶ τῶν Ἰουδαίων οἱ συγκαταφυγόντες ὡς τὸν Ἰώσηπον συνίεσαν εἴκοντα τοῖς παρακαλοῦσιν, ἀθρόοι περιστάντες, ἦ μεγάλα γ’ ἂν στενάξειαν, ἐβόων, οἱ πάτριοι νόμοι, οὓς κατέφησεν θεὸς Ἰουδαίοις ὁ κτίσας ψυχὰς θανάτου καταφρονούσας. φιλοζωεῖς, ὦ Ἰώσηπε, καὶ φῶς ὑπομένεις ὁρᾶν δοῦλον; ὡς ταχέως ἐπελάθου σαυτοῦ. πόσους ὑπὲρ ἐλευθερίας ἀποθνήσκειν ἔπεισας. ψευδῆ μὲν ἄρα δόξαν ἀνδρείας, ψευδῆ δὲ καὶ συνέσεως εἶχες, εἴ γε σωτηρίαν μὲν ἔχειν ἐλπίζεις παρ’ οἷς οὕτως ἐπολέμησας, σώζεσθαι δὲ ὑπ’ ἐκείνων, κἂν ᾖ βέβαιον, θέλεις. ἀλλ’ εἰ καὶ σοὶ λήθην σεαυτοῦ κατέχεεν ἡ Ῥωμαίων τύχη, προνοητέον ἡμῖν τοῦ πατρίου κλέους. χρήσομέν σοι δεξιὰν καὶ ξίφος· σὺ δ’ ἂν μὲν ἑκὼν θνήσκῃς, Ἰουδαίων στρατηγός, ἂν δ’ ἄκων, προδότης τεθνήξῃ. ταῦθ’ ἅμα λέγοντες ἐπανετείναντο τὰ ξίφη καὶ διηπείλουν ἀναιρήσειν αὐτόν, εἰ τοῖς Ῥωμαίοις ἐνδιδοίη.", "st": "3.8.4"}, {"sp": "N", "t": "Δείσας δὲ τὴν ἔφοδον ὁ Ἰώσηπος καὶ προδοσίαν ἡγούμενος εἶναι τῶν τοῦ θεοῦ προσταγμάτων, εἰ προαποθάνοι τῆς διαγγελίας, ἤρχετο πρὸς αὐτοὺς φιλοσοφεῖν ἐπὶ τῆς ἀνάγκης· τί γὰρ τοσοῦτον, ἔφη, σφῶν αὐτῶν, ἑταῖροι, φονῶμεν; ἢ τί τὰ φίλτατα διαστασιάζομεν, σῶμα καὶ ψυχήν; ἠλλάχθαι τις ἐμέ φησιν. ἀλλ’ οἴδασιν Ῥωμαῖοι τοῦτό γε. καλὸν ἐν πολέμῳ θνήσκειν, ἀλλὰ πολέμου νόμῳ, τουτέστιν ὑπὸ τῶν κρατούντων. εἰ μὲν οὖν τὸν Ῥωμαίων ἀποστρέφομαι σίδηρον, ἄξιος ἀληθῶς εἰμι τοὐμοῦ ξίφους καὶ χειρὸς τῆς ἐμῆς· εἰ δ’ ἐκείνους εἰσέρχεται φειδὼ πολεμίου, πόσῳ δικαιότερον ἂν ἡμᾶς ἡμῶν αὐτῶν εἰσέλθοι; καὶ γὰρ ἠλίθιον ταῦτα δρᾶν σφᾶς αὐτούς, περὶ ὧν πρὸς ἐκείνους διιστάμεθα. καλὸν γὰρ ὑπὲρ τῆς ἐλευθερίας ἀποθνήσκειν· φημὶ κἀγώ, μαχομένους μέντοι, καὶ ὑπὸ τῶν ἀφαιρουμένων αὐτήν. νῦν δ’ οὔτ’ εἰς μάχην ἀντιάζουσιν ἡμῖν οὔτ’ ἀναιροῦσιν ἡμᾶς· δειλὸς δὲ ὁμοίως ὅ τε μὴ βουλόμενος θνήσκειν ὅταν δέῃ καὶ ὁ βουλόμενος, ὅταν μὴ δέῃ. τί δὲ καὶ δεδοικότες πρὸς Ῥωμαίους οὐκ ἄνιμεν; ἆρ’ οὐχὶ θάνατον; εἶθ’ ὃν δεδοίκαμεν ἐκ τῶν ἐχθρῶν ὑποπτευόμενον ἑαυτοῖς βέβαιον ἐπιστήσομεν; ἀλλὰ δουλείαν, ἐρεῖ τις. πάνυ γοῦν νῦν ἐσμὲν ἐλεύθεροι. γενναῖον γὰρ ἀνελεῖν ἑαυτόν, φήσει τις. οὐ μὲν οὖν, ἀλλ’ ἀγενέστατον, ὡς ἔγωγε καὶ κυβερνήτην ἡγοῦμαι δειλότατον, ὅστις χειμῶνα δεδοικὼς πρὸ τῆς θυέλλης ἐβάπτισεν ἑκὼν τὸ σκάφος. ἀλλὰ μὴν ἡ αὐτοχειρία καὶ τῆς κοινῆς ἁπάντων ζῴων φύσεως ἀλλότριον καὶ πρὸς τὸν κτίσαντα θεὸν ἡμᾶς ἐστιν ἀσέβεια. τῶν μέν γε ζῴων οὐδέν ἐστιν ὃ θνήσκει μετὰ προνοίας ἢ δι’ αὐτοῦ· φύσεως γὰρ νόμος ἰσχυρὸς ἐν ἅπασιν τὸ ζῆν ἐθέλειν· διὰ τοῦτο καὶ τοὺς φανερῶς ἀφαιρουμένους ἡμᾶς τούτου πολεμίους ἡγούμεθα καὶ τοὺς ἐξ ἐνέδρας τιμωρούμεθα. τὸν δὲ θεὸν οὐκ οἴεσθε ἀγανακτεῖν, ὅταν ἄνθρωπος αὐτοῦ τὸ δῶρον ὑβρίζῃ; καὶ γὰρ εἰλήφαμεν παρ’ ἐκείνου τὸ εἶναι καὶ τὸ μηκέτι εἶναι πάλιν ἐκείνῳ δίδομεν. τὰ μέν γε σώματα θνητὰ πᾶσιν καὶ ἐκ φθαρτῆς ὕλης δεδημιούργηται, ψυχὴ δὲ ἀθάνατος ἀεὶ καὶ θεοῦ μοῖρα τοῖς σώμασιν ἐνοικίζεται· εἶτ’ ἐὰν μὲν ἀφανίσῃ τις ἀνθρώπου παρακαταθήκην ἢ διαθῆται κακῶς, πονηρὸς εἶναι δοκεῖ καὶ ἄπιστος, εἰ δέ τις τοῦ σφετέρου σώματος ἐκβάλλει τὴν παρακαταθήκην τοῦ θεοῦ, λεληθέναι δοκεῖ τὸν ἀδικούμενον; καὶ κολάζειν μὲν τοὺς ἀποδράντας οἰκέτας δίκαιον νενόμισται κἂν πονηροὺς καταλείπωσι δεσπότας, αὐτοὶ δὲ κάλλιστον δεσπότην ἀποδιδράσκοντες τὸν θεὸν οὐ δοκοῦμεν ἀσεβεῖν; ἆρ’ οὐκ ἴστε ὅτι τῶν μὲν ἐξιόντων τοῦ βίου κατὰ τὸν τῆς φύσεως νόμον καὶ τὸ ληφθὲν παρὰ τοῦ θεοῦ χρέος ἐκτινύντων, ὅταν ὁ δοὺς κομίσασθαι θέλῃ, κλέος μὲν αἰώνιον, οἶκοι δὲ καὶ γενεαὶ βέβαιοι, καθαραὶ δὲ καὶ ἐπήκοοι μένουσιν αἱ ψυχαί, χῶρον οὐράνιον λαχοῦσαι τὸν ἁγιώτατον, ἔνθεν ἐκ περιτροπῆς αἰώνων ἁγνοῖς πάλιν ἀντενοικίζονται σώμασιν· ὅσοις δὲ καθ’ ἑαυτῶν ἐμάνησαν αἱ χεῖρες, τούτων ᾅδης μὲν δέχεται τὰς ψυχὰς σκοτεινότερος, ὁ δὲ τούτων πατὴρ θεὸς εἰς ἐγγόνους τιμωρεῖται τοὺς τῶν πατέρων ὑβριστάς. διὰ τοῦτο μεμίσηται παρὰ θεῷ τοῦτο καὶ παρὰ τῷ σοφωτάτῳ κολάζεται νομοθέτῃ· τοὺς γοῦν ἀναιροῦντας ἑαυτοὺς παρὰ μὲν ἡμῖν μέχρις ἡλίου δύσεως ἀτάφους ἐκρίπτειν ἔκριναν καίτοι καὶ πολεμίους θάπτειν θεμιτὸν ἡγούμενοι, παρ’ ἑτέροις δὲ καὶ τὰς δεξιὰς τῶν τοιούτων νεκρῶν ἀποκόπτειν ἐκέλευσαν, αἷς ἐστρατεύσαντο καθ’ ἑαυτῶν, ἡγούμενοι καθάπερ τὸ σῶμα τῆς ψυχῆς ἀλλότριον, οὕτως καὶ τὴν χεῖρα τοῦ σώματος. καλὸν οὖν, ἑταῖροι, δίκαια φρονεῖν καὶ μὴ ταῖς ἀνθρωπίναις συμφοραῖς προσθεῖναι τὴν εἰς τὸν κτίσαντα ἡμᾶς δυσσέβειαν. εἰ σώζεσθαι δοκεῖ, σωζώμεθα· καὶ γὰρ οὐκ ἄδοξος ἡ σωτηρία παρ’ οἷς διὰ τοσούτων ἔργων ἐπεδειξάμεθα τὰς ἀρετάς· εἰ τεθνάναι, καλὸν ὑπὸ τῶν ἑλόντων. οὐ μεταβήσομαι δ’ ἐγὼ εἰς τὴν τῶν πολεμίων τάξιν, ἵν’ ἐμαυτοῦ προδότης γένωμαι· καὶ γὰρ ἂν εἴην πολὺ τῶν αὐτομολούντων πρὸς τοὺς πολεμίους ἠλιθιώτερος, εἴ γ’ ἐκεῖνοι μὲν ἐπὶ σωτηρίᾳ τοῦτο πράττουσιν, ἐγὼ δὲ ἐπὶ ἀπωλείᾳ, καί γε τῇ ἐμαυτοῦ. τὴν μέντοι Ῥωμαίων ἐνέδραν εὔχομαι· μετὰ γὰρ δεξιὰν ἀναιρούμενος ὑπ’ αὐτῶν εὔθυμος τεθνήξομαι, τὴν τῶν ψευσαμένων ἀπιστίαν νίκης μείζονα ἀποφέρων παραμυθίαν.", "st": "3.8.5"}, {"sp": "N", "t": "Ὁ μὲν οὖν Ἰώσηπος πολλὰ τοιαῦτα πρὸς ἀποτροπὴν τῆς αὐτοχειρίας ἔλεγεν· οἱ δὲ πεφραγμένας ἀπογνώσει τὰς ἀκοὰς ἔχοντες ὡς ἂν πάλαι καθοσιώσαντες ἑαυτοὺς τῷ θανάτῳ παρωξύνοντο πρὸς αὐτόν, καὶ προστρέχων ἄλλος ἄλλοθεν ξιφήρεις ἐκάκιζόν τε εἰς ἀνανδρίαν καὶ ὡς ἕκαστος αὐτίκα πλήξων δῆλος ἦν. ὁ δὲ τὸν μὲν ὀνομαστὶ καλῶν, τῷ δὲ στρατηγικώτερον ἐμβλέπων, τοῦ δὲ δρασσόμενος τῆς δεξιᾶς, ὃν δὲ δεήσει δυσωπῶν, καὶ ποικίλοις διαιρούμενος πάθεσιν ἐπὶ τῆς ἀνάγκης εἶργεν ἀπὸ τῆς σφαγῆς πάντων τὸν σίδηρον, ὥσπερ τὰ κυκλωθέντα τῶν θηρίων ἀεὶ πρὸς τὸν καθαπτόμενον ἀντιστρεφόμενος. τῶν δὲ καὶ παρὰ τὰς ἐσχάτας συμφορὰς ἔτι τὸν στρατηγὸν αἰδουμένων παρελύοντο μὲν αἱ δεξιαί, περιωλίσθανεν δὲ τὰ ξίφη, καὶ πολλοὶ τὰς ῥομφαίας ἐπιφέροντες αὐτομάτως παρεῖσαν.", "st": "3.8.6"}, {"sp": "N", "t": "Ὁ δ’ ἐν ταῖς ἀμηχανίαις οὐκ ἠπόρησεν ἐπινοίας, ἀλλὰ πιστεύων τῷ κηδεμόνι θεῷ τὴν σωτηρίαν παραβάλλεται, κἀπεὶ δέδοκται τὸ θνήσκειν, ἔφη, φέρε κλήρῳ τὰς ἀλλήλων σφαγὰς ἐπιτρέψωμεν, ὁ λαχὼν δ’ ὑπὸ τοῦ μετ’ αὐτὸν πιπτέτω, καὶ διοδεύσει πάντων οὕτως ἡ τύχη, μηδ’ ἐπὶ τῆς ἰδίας κείσθω δεξιᾶς ἕκαστος· ἄδικον γὰρ οἰχομένων τινὰ τῶν ἄλλων μετανοήσαντα σωθῆναι. πιστὸς ἔδοξεν ταῦτα εἰπὼν καὶ συνεκληροῦτο πείσας. ἑτοίμην δ’ ὁ λαχὼν τῷ μεθ’ αὑτὸν παρεῖχεν τὴν σφαγὴν ὡς αὐτίκα τεθνηξομένου καὶ τοῦ στρατηγοῦ· ζωῆς γὰρ ἡδίω τὸν μετὰ [τοῦ] Ἰωσήπου θάνατον ἡγοῦντο. καταλείπεται δ’ οὗτος εἴτε ὑπὸ τύχης χρὴ λέγειν, εἴτε ὑπὸ θεοῦ προνοίας σὺν ἑτέρῳ, καὶ σπουδάζων μήθ’ ὑπὸ τοῦ κλήρου καταδικασθῆναι μήτε, εἰ τελευταῖος λείποιτο, μιᾶναι τὴν δεξιὰν ὁμοφύλῳ φόνῳ πείθει κἀκεῖνον ἐπὶ πίστει ζῆν.", "st": "3.8.7"}, {"sp": "N", "t": "Ὁ μὲν οὖν οὕτως τόν τε Ῥωμαίων καὶ τὸν οἰκείων διαφυγὼν πόλεμον ἐπὶ Οὐεσπασιανὸν ἤγετο ὑπὸ [τοῦ] Νικάνορος. οἱ δὲ Ῥωμαῖοι πάντες ἐπὶ θέαν αὐτοῦ συνέτρεχον, καὶ τοῦ πλήθους συνθλιβομένου περὶ τῷ στρατηγῷ θόρυβος ἦν ποικίλος, τῶν μὲν γεγηθότων ἐπὶ τῷ ληφθέντι, τῶν δ’ ἀπειλούντων, τῶν δ’ ἐγγύθεν ἰδεῖν βιαζομένων. καὶ οἱ μὲν πόρρωθεν κολάζειν ἐβόων τὸν πολέμιον, τῶν δὲ πλησίον ἀνάμνησις αὐτοῦ τῶν ἔργων εἰσῄει καὶ πρὸς τὴν μεταβολὴν θάμβος, τῶν τε ἡγεμόνων οὐδεὶς ἦν, ὃς εἰ καὶ πρότερον ὠργίζετο, τότε πρὸς τὴν ὄψιν οὐκ ἐνέδωκεν αὐτοῦ. μάλιστα δὲ τὸν Τίτον ἐξαιρέτως τό τε καρτερικὸν ἐν ταῖς συμφοραῖς ᾕρει τοῦ Ἰωσήπου καὶ πρὸς τὴν ἡλικίαν ἔλεος, ἀναμιμνησκομένῳ τε τὸν πάλαι μαχόμενον καὶ τὸν ἐν χερσὶν ἐχθρῶν ἄρτι κείμενον ὁρῶντι παρῆν [δὲ] νοεῖν, ὅσον δύναται τύχη, καὶ ὡς ὀξεῖα μὲν πολέμου ῥοπή, τῶν δ’ ἀνθρωπίνων οὐδὲν βέβαιον· παρὸ καὶ τότε συνδιέθηκεν μὲν πλείστους ἑαυτῷ καὶ πρὸς οἶκτον τοῦ Ἰωσήπου, πλείστη δ’ αὐτῷ καὶ παρὰ τῷ πατρὶ μοῖρα σωτηρίας ἐγένετο. ὁ μέντοι Οὐεσπασιανὸς φρουρεῖν αὐτὸν μετὰ πάσης ἀσφαλείας προσέταττεν ὡς ἀναπέμψων αὐτίκα Νέρωνι.", "st": "3.8.8"}, {"sp": "N", "t": "Τοῦτο ἀκούσας ὁ Ἰώσηπος μόνῳ τι διαλεχθῆναι θέλειν ἔλεγεν αὐτῷ. μεταστησαμένου δ’ ἐκείνου πλὴν τοῦ παιδὸς Τίτου καὶ δυοῖν φίλων τοὺς ἄλλους ἅπαντας σὺ μέν, ἔφη, Οὐεσπασιανέ, νομίζεις αἰχμάλωτον αὐτὸ μόνον εἰληφέναι Ἰώσηπον, ἐγὼ δὲ ἄγγελος ἥκω σοι μειζόνων. μὴ γὰρ ὑπὸ θεοῦ προπεμπόμενος ᾔδειν τὸν Ἰουδαίων νόμον, καὶ πῶς στρατηγοῖς ἀποθνήσκειν πρέπει. Νέρωνί με πέμπεις· τί γάρ; οἱ μετὰ Νέρωνα μέχρι σοῦ διάδοχοι μενοῦσιν. σὺ Καῖσαρ, Οὐεσπασιανέ, καὶ αὐτοκράτωρ, σὺ καὶ παῖς ὁ σὸς οὗτος. δέσμει δέ με νῦν ἀσφαλέστερον, καὶ τήρει σεαυτῷ· δεσπότης μὲν γὰρ οὐ μόνον ἐμοῦ σὺ Καῖσαρ, ἀλλὰ καὶ γῆς καὶ θαλάττης καὶ παντὸς ἀνθρώπων γένους, ἐγὼ δὲ ἐπὶ τιμωρίαν δέομαι φρουρᾶς μείζονος, εἰ κατασχεδιάζω καὶ θεοῦ. ταῦτ’ εἰπόντος παραχρῆμα μὲν Οὐεσπασιανὸς ἀπιστεῖν ἐδόκει καὶ τὸν Ἰώσηπον ὑπελάμβανεν ταῦτα περὶ σωτηρίας πανουργεῖν, κατὰ μικρὸν δὲ εἰς πίστιν ὑπήγετο τοῦ θεοῦ διεγείροντος αὐτὸν εἰς τὴν ἡγεμονίαν ἤδη καὶ τὰ σκῆπτρα δι’ ἑτέρων σημείων προδεικνύντος. ἀτρεκῆ δὲ τὸν Ἰώσηπον καὶ ἐν ἄλλοις κατελάμβανεν· τῶν γὰρ τοῖς ἀπορρήτοις παρατυχόντων φίλων ὁ ἕτερος θαυμάζειν ἔφη πῶς οὔτε τοῖς ἐπὶ τῶν Ἰωταπάτων περὶ ἁλώσεως, οὔθ’ ἑαυτῷ προμαντεύσαιτο αἰχμαλωσίαν, εἰ μὴ ταῦτα λῆρος εἴη διακρουομένου τὰς ἐπ’ αὐτὸν ὀργάς. ὁ δὲ Ἰώσηπος καὶ τοῖς Ἰωταπατηνοῖς ὅτι μετὰ τεσσαρακοστὴν ἑβδόμην ἡμέραν ἁλώσονται προειπεῖν ἔφη, καὶ ὅτι πρὸς Ῥωμαίων αὐτὸς ζωγρηθήσεται. ταῦτα παρὰ τῶν αἰχμαλώτων κατ’ ἰδίαν ὁ Οὐεσπασιανὸς ἐκπυθόμενος ὡς εὕρισκεν ἀληθῆ, οὕτω πιστεύειν περὶ τῶν κατ’ αὐτὸν ἦρκτο. φρουρᾶς μὲν οὖν καὶ δεσμῶν οὐκ ἀνίει τὸν Ἰώσηπον, ἐδωρεῖτο δ’ ἐσθῆτι καὶ τοῖς ἄλλοις κειμηλίοις φιλοφρονούμενός τε καὶ περιέπων διετέλει τὰ πολλὰ Τίτου τῇ τιμῇ συνεργοῦντος.", "st": "3.8.9"}, {"sp": "N", "t": "Τετάρτῃ δὲ Πανέμου μηνὸς ἀναζεύξας εἰς Πτολεμαΐδα κἀκεῖθεν εἰς τὴν παράλιον ἀφικνεῖται Καισάρειαν, μεγίστην τῆς τε Ἰουδαίας πόλιν καὶ τὸ πλέον ὑφ’ Ἑλλήνων οἰκουμένην. ἐδέχοντο δὲ καὶ τὴν στρατιὰν καὶ τὸν στρατηγὸν μετὰ πάσης εὐφημίας καὶ φιλοφροσύνης οἱ ἐπιχώριοι, καὶ κατ’ εὔνοιαν μὲν τὴν πρὸς Ῥωμαίους, τὸ δὲ πλέον ἔχθει τῶν κατεστραμμένων· διὸ καὶ τὸν Ἰώσηπον ἀθρόοι καταβοῶντες ἠξίουν κολάζειν. Οὐεσπασιανὸς δὲ τὴν περὶ τούτου δέησιν ὡς ὑπ’ ἀκρίτου γινομένην πλήθους ἐξέλυσεν ἡσυχίᾳ· τῶν δὲ ταγμάτων τὰ μὲν δύο χειμερίσοντα ἐκάθισεν ἐπὶ τῆς Καισαρείας ἐπιτήδειον ὁρῶν τὴν πόλιν, τὸ δέκατον δὲ καὶ πέμπτον εἰς Σκυθόπολιν, ὡς μὴ θλίβοι παντὶ τῷ στρατῷ τὴν Καισάρειαν. ἀλεεινὴ δ’ ἦν κἀκείνη χειμῶνος ὥρᾳ καθ’ ὅσον πνιγώδης θέρους ὑπὸ καυμάτων, πεδιὰς οὖσα καὶ παράλιος.", "st": "3.9.1"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ συναθροισθέντες οἵ τε κατὰ στάσιν ἐκπίπτοντες τῶν πόλεων καὶ οἱ διαφυγόντες ἐκ τῶν κατεστραμμένων, πλῆθος οὐκ ὀλίγον, ἀνακτίζουσιν Ἰόππην ὁρμητήριον σφίσιν, ἐρημωθεῖσαν ὑπὸ Κεστίου πρότερον, καὶ τῆς χώρας ἐκπεπολεμωμένης ἀνειργόμενοι μεταβαίνειν ἔγνωσαν εἰς τὴν θάλασσαν. πηξάμενοί τε πειρατικὰ σκάφη πλεῖστα τόν τε Συρίας καὶ Φοινίκης καὶ τὸν ἐπ’ Αἰγύπτου πόρον ἐλῄστευον, ἄπλωτά τε πᾶσιν ἐποίουν τὰ τῇδε πελάγη. Οὐεσπασιανὸς δὲ ὡς ἔγνω τὴν σύνταξιν αὐτῶν, πέμπει πεζούς τε καὶ ἱππεῖς ἐπὶ τὴν Ἰόππην, οἳ νύκτωρ ὡς ἀφύλακτον εἰσέρχονται τὴν πόλιν. οἱ δ’ ἐν αὐτῇ προῄσθοντο μὲν τὴν εἰσβολὴν καὶ καταδείσαντες τοῦ μὲν εἴργειν τοὺς Ῥωμαίους ἀπετρέποντο, συμφυγόντες δὲ εἰς τὰς ναῦς ἐξωτέρω βέλους διενυκτέρευσαν.", "st": "3.9.2"}, {"sp": "N", "t": "Ἀλιμένου δ’ οὔσης φύσει τῆς Ἰόππης, αἰγιαλῷ γὰρ ἐπιλήγει τραχεῖ καὶ τὸ μὲν ἄλλο πᾶν ὀρθίῳ, βραχὺ δὲ συννεύοντι κατὰ τὰς κεραίας ἑκατέρωθεν· αἱ δέ εἰσιν κρημνοὶ βαθεῖς καὶ προύχουσαι σπιλάδες εἰς τὸ πέλαγος, ἔνθα καὶ τῶν Ἀνδρομέδας δεσμῶν ἔτι δεικνύμενοι τύποι πιστοῦνται τὴν ἀρχαιότητα τοῦ μύθου, τύπτων δὲ τὸν αἰγιαλὸν ἐναντίος βορέας καὶ πρὸς ταῖς δεχομέναις πέτραις ὑψηλὸν ἀναπέμπων τὸ κῦμα σφαλερώτερον ἐρημίας τὸν ὅρμον ἀπεργάζεται· κατὰ τοῦτον σαλεύουσιν τοῖς ἀπὸ τῆς Ἰόππης ὑπὸ τὴν ἕω πνεῦμα βίαιον ἐπιπίπτει· μελαμβόριον ὑπὸ τῶν ταύτῃ πλοϊζομένων καλεῖται· καὶ τὰς μὲν ἀλλήλαις τῶν νεῶν αὐτόθι συνήραξεν, τὰς δὲ πρὸς ταῖς πέτραις, πολλὰς δὲ πρὸς ἀντίον κῦμα βιαζομένας εἰς τὸ πέλαγος, τόν τε γὰρ αἰγιαλὸν ὄντα πετρώδη καὶ τοὺς ἐπ’ αὐτοῦ πολεμίους ἐδεδοίκεσαν, μετέωρος ὑπεραρθεὶς ὁ κλύδων ἐβάπτιζεν. ἦν δ’ οὔτε φυγῆς τόπος οὔτε μένουσιν σωτηρία, βίᾳ μὲν ἀνέμου τῆς θαλάσσης ἐξωθουμένοις, Ῥωμαίων δὲ τῆς πόλεως. καὶ πολλὴ μὲν οἰμωγὴ συρρηγνυμένων ἐγίνετο τῶν σκαφῶν, πολὺς δ’ ἀγνυμένων ὁ ψόφος. καὶ τοῦ πλήθους οἱ μὲν ὑπὸ τῶν κυμάτων καλυπτόμενοι διεφθείροντο, πολλοὶ δὲ τοῖς ναυαγίοις ἐμπλεκόμενοι· τινὲς δὲ ὡς κουφοτέρῳ τὴν θάλατταν ἔφθανον τῷ σιδήρῳ σφᾶς αὐτοὺς ἀναιροῦντες. τό γε μὴν πλεῖστον ὑπὸ τῶν κυμάτων ἐκφερόμενον περιεξαίνετο ταῖς ἀπορρῶξιν, ὡς αἱμαχθῆναι μὲν ἐπὶ πλεῖστον τὸ πέλαγος, πληρωθῆναι δὲ νεκρῶν τὴν παράλιον· καὶ γὰρ τοὺς ἐπὶ τὸν αἰγιαλὸν ἐκφερομένους ἐφεστῶτες οἱ Ῥωμαῖοι διέφθειρον. ἀριθμὸς δὲ τῶν ἐκβρασθέντων σωμάτων τετρακισχίλιοι πρὸς τοῖς διακοσίοις ἦν. Ῥωμαῖοι δὲ λαβόντες ἀμαχητὶ τὴν πόλιν κατασκάπτουσιν.", "st": "3.9.3"}, {"sp": "N", "t": "Ἰόππη μὲν οὖν ἐν ὀλίγῳ χρόνῳ δεύτερον ὑπὸ Ῥωμαίοις ἑάλω. Οὐεσπασιανὸς δὲ ὡς μὴ πάλιν οἱ πειραταὶ συναλισθεῖεν εἰς αὐτήν, στρατόπεδόν τε ἐπὶ τῆς ἀκροπόλεως ἐγείρει καὶ τὸ ἱππικὸν ἐν αὐτῷ καταλείπει μετὰ πεζῶν ὀλίγων, ἵν’ οὗτοι μὲν κατὰ χώραν μένοντες φρουρῶσι τὸ στρατόπεδον, οἱ δ’ ἱππεῖς προνομεύωσι τὴν πέριξ καὶ τὰς περιοίκους κώμας τε καὶ πολίχνας ἐξαιρῶσιν τῆς Ἰόππης. οἱ μὲν οὖν κατὰ τὰ προσταχθέντα τὴν χώραν κατατρέχοντες καθ’ ἡμέραν ἔτεμνόν τε καὶ ἠρήμουν ἅπασαν.", "st": "3.9.4"}, {"sp": "N", "t": "Ὡς δὲ εἰς τὰ Ἱεροσόλυμα τὸ κατὰ τὴν Ἰωταπάτην πάθος ἠγγέλη, τὸ μὲν πρῶτον ἠπίστουν οἱ πολλοὶ καὶ διὰ τὸ μέγεθος τῆς συμφορᾶς καὶ διὰ τὸ μηδένα τῶν λεγομένων αὐτόπτην παρεῖναι· διεσώθη γὰρ οὐδὲ ἄγγελος, ἀλλ’ αὐτοματὶ διεκήρυσσεν φήμη τὴν ἅλωσιν οἰκεία φύσει τῶν σκυθρωποτέρων. κατ’ ὀλίγον δὲ διὰ τῶν προσχώρων ὥδευε τἀληθὲς καὶ παρὰ πᾶσιν ἀμφιβολίας ἦν ἤδη βεβαιότερον, προσεσχεδιάζετό γε μὴν τοῖς πεπραγμένοις καὶ τὰ μὴ γενόμενα· τεθνεὼς γὰρ ἐπὶ τῆς ἁλώσεως καὶ ὁ Ἰώσηπος ἠγγέλλετο. τοῦτο μεγίστου τὰ Ἱεροσόλυμα πένθους ἐπλήρωσεν· κατὰ μέν γε οἴκους καὶ κατὰ συγγενείας οἷς προσήκων ἕκαστος ἦν τῶν ἀπολωλότων ἐθρηνεῖτο, τὸ δ’ ἐπὶ τῷ στρατηγῷ πένθος ἐδημεύθη, καὶ οἱ μὲν ξένους, οἱ δὲ συγγενεῖς, οἱ δὲ φίλους ἐθρήνουν, τὸν Ἰώσηπον δὲ πάντες, ὡς ἐπὶ τριακοστὴν μὲν ἡμέραν μὴ διαλιπεῖν τὰς ὀλοφύρσεις ἐν τῇ πόλει, πλείστους δὲ μισθοῦσθαι τοὺς αὐλητάς, οἳ θρήνων αὐτοῖς ἐξῆρχον.", "st": "3.9.5"}, {"sp": "N", "t": "Ὡς δὲ τἀληθῆ διεκαλύπτετο τῷ χρόνῳ καὶ τὰ μὲν κατὰ τὴν Ἰωταπάτην ὥσπερ εἶχεν, ἐσχεδιασμένον δὲ τὸ κατὰ τὸν Ἰώσηπον πάθος εὑρίσκετο, ζῆν δ’ αὐτὸν ἔγνωσαν καὶ παρὰ Ῥωμαίοις ὄντα καὶ πρὸς τῶν ἡγεμόνων πλέον ἢ κατ’ αἰχμαλώτου τύχην περιέπεσθαι, τοσοῦτον ὀργῆς ἐπὶ ζῶντος ὅσον εὐνοίας ἐπὶ τεθνάναι δοκοῦντος πρότερον ἀνελάμβανον. καὶ παρ’ οἷς μὲν εἰς ἀνανδρίαν, παρ’ οἷς δὲ εἰς προδοσίαν ἐκακίζετο, πλήρης τε ἀγανακτήσεως ἦν καὶ τῶν κατ’ αὐτοῦ βλασφημιῶν ἡ πόλις. παρωξύνοντο δὲ ταῖς πληγαῖς καὶ προσεξεκαίοντο ταῖς κακοπραγίαις· τό γε μὴν πταίειν, ὃ γίνεται τοῖς εὖ φρονοῦσιν ἀσφαλείας καὶ τῶν ὁμοίων φυλακῆς αἴτιον, ἐκείνοις κέντρον ἑτέρων ἐγίνετο συμφορῶν· καὶ τὸ τέλος ἀεὶ τῶν κακῶν αὖθις ἀρχή· μᾶλλον γοῦν ὥρμων ἐπὶ τοὺς Ῥωμαίους ὡς καὶ Ἰώσηπον ἐν αὐτοῖς ἀμυνούμενοι. τοὺς μὲν οὖν ἐπὶ τῶν Ἱεροσολύμων τοιοῦτοι θόρυβοι κατεῖχον.", "st": "3.9.6"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ καθ’ ἱστορίαν τῆς Ἀγρίππα βασιλείας, ἐνῆγεν γὰρ βασιλεὺς αὐτόν, ἅμα καὶ δεξιώσασθαι τὸν ἡγεμόνα σὺν τῇ στρατιᾷ τῷ κατὰ τὸν οἶκον ὄλβῳ προαιρούμενος καὶ καταστεῖλαι δι’ αὐτῶν τὰ νοσοῦντα τῆς ἀρχῆς, ἄρας ἀπὸ τῆς παράλου Καισαρείας εἰς τὴν Φιλίππου καλουμένην μεταβαίνει Καισάρειαν. ἔνθα μέχρι μὲν ἡμερῶν εἴκοσι τὴν στρατιὰν διαναπαύων καὶ αὐτὸς ἐν εὐωχίαις ἦν, ἀποδιδοὺς τῷ θεῷ χαριστήρια τῶν κατωρθωμένων. ὡς δ’ αὐτῷ Τιβεριὰς μὲν νεωτερίζειν, ἀφεστάναι δὲ ἠγγέλλοντο Ταριχέαι, μοῖρα δὲ τῆς Ἀγρίππα βασιλείας ἦσαν ἀμφότεραι, πανταχόθεν τοὺς Ἰουδαίους καταστρέφεσθαι διεγνωκὼς τὴν ἐπὶ τούτους στρατείαν εὔκαιρον ἡγεῖτο καὶ δι’ Ἀγρίππαν, ὡς εἰς ξενίας ἀμοιβὴν σωφρονίσων αὐτῷ τὰς πόλεις. πέμπει δὴ τὸν υἱὸν Τίτον εἰς Καισάρειαν μετάξοντα τὴν ἐκεῖθεν στρατιὰν εἰς Σκυθόπολιν· ἡ δ’ ἐστὶν μεγίστη τῆς δεκαπόλεως καὶ γείτων τῆς Τιβεριάδος. ἔνθα καὶ αὐτὸς παραγενόμενος ἐκδέχεται τὸν υἱὸν καὶ μετὰ τριῶν ταγμάτων προελθὼν στρατοπεδεύεται μὲν ἀπὸ τριάκοντα τῆς Τιβεριάδος σταδίων κατά τινα σταθμὸν εὐσύνοπτον τοῖς νεωτερίζουσιν· Ἔνναβρις ὀνομάζεται. πέμπει δὲ δεκαδάρχην Οὐαλεριανὸν σὺν ἱππεῦσιν πεντήκοντα διαλεχθησόμενον εἰρηνικὰ τοῖς κατὰ τὴν πόλιν καὶ προτρεψόμενον ἐπὶ πίστεις· ἀκηκόει γάρ, ὡς ἐπιθυμοίη μὲν εἰρήνης ὁ δῆμος, καταστασιάζοιτο δ’ ὑπό τινων πολεμεῖν βιαζομένων. προσελάσας δὲ Οὐαλεριανὸς ἐπεὶ πλησίον ἦν τοῦ τείχους, αὐτός τε καταβαίνει καὶ τοὺς σὺν αὐτῷ τῶν ἱππέων ἀπέβησεν, ὡς μὴ δοκοῖεν ἀκροβολιζόμενοι παρεῖναι. καὶ πρὶν εἰς λόγους ἐλθεῖν ἐπεκθέουσιν αὐτῷ τῶν στασιαστῶν οἱ δυνατώτατοι μεθ’ ὅπλων. ἐξηγεῖτο δ’ αὐτῶν Ἰησοῦς τις ὄνομα παῖς Τοῦφα τοῦ λῃστρικοῦ στίφους ὁ κορυφαιότατος. Οὐαλεριανὸς δὲ οὔτε παρὰ τὰς ἐντολὰς τοῦ στρατηγοῦ συμβαλεῖν ἀσφαλὲς ἡγούμενος, εἰ καὶ τὸ νικᾶν εἴη βέβαιον, καὶ σφαλερὸν τὸ μάχεσθαι πολλοῖς μετ’ ὀλίγων ἀπαρασκευάστοις τε πρὸς ἑτοίμους, καὶ ἄλλως ἐκπλαγεὶς τὴν ἀδόκητον τῶν Ἰουδαίων τόλμαν, φεύγει πεζός, ἕτεροί τε ὁμοίως πέντε τοὺς ἵππους ἀπέλιπον, οὓς οἱ περὶ τὸν Ἰησοῦν ἀπήγαγον εἰς τὴν πόλιν γεγηθότες ὡς μάχῃ ληφθέντας οὐκ ἐνέδρᾳ.", "st": "3.9.7"}, {"sp": "N", "t": "Τοῦτο καταδείσαντες οἱ γηραιοὶ τοῦ δήμου καὶ προύχειν δοκοῦντες φεύγουσι μὲν εἰς τὸ τῶν Ῥωμαίων στρατόπεδον, ἐπαγόμενοι δὲ τὸν βασιλέα προσπίπτουσιν ἱκέται Οὐεσπασιανῷ, μὴ σφᾶς περιιδεῖν δεόμενοι, μηδὲ τὴν ὀλίγων ἀπόνοιαν ἡγήσασθαι τῆς πόλεως ὅλης· φείσασθαι δὲ τοῦ δήμου Ῥωμαίοις φίλα φρονοῦντος ἀεί, καὶ τοὺς αἰτίους τιμωρήσασθαι τῆς ἀποστάσεως, ὑφ’ ὧν αὐτοὶ φρουρηθῆναι μέχρι νῦν ἐπὶ δεξιὰς ἐπειγόμενοι πάλαι. ταύταις ἐνεδίδου ταῖς ἱκεσίαις ὁ στρατηγὸς καίτοι διὰ τὴν ἁρπαγὴν τῶν ἵππων ἐφ’ ὅλην ὠργισμένος τὴν πόλιν· καὶ γὰρ ἀγωνιῶντα περὶ αὐτῆς τὸν Ἀγρίππαν ἑώρα. λαβόντων δὲ τούτων τῷ δήμῳ δεξιὰς οἱ περὶ τὸν Ἰησοῦν οὐκέτι ἀσφαλὲς ἡγούμενοι μένειν ἐπὶ τῆς Τιβεριάδος εἰς Ταριχέας ἀποδιδράσκουσιν. καὶ μεθ’ ἡμέραν Οὐεσπασιανὸς σὺν ἱππεῦσιν προπέμπει πρὸς τὴν ἀκρώρειαν Τραϊανὸν ἀποπειραθῆναι τοῦ πλήθους, εἰ πάντες εἰρηνικὰ φρονοῖεν. ὡς δ’ ἔγνω τὸν δῆμον ὁμοφρονοῦντα τοῖς ἱκέταις, ἀναλαβὼν τὴν δύναμιν ᾔει πρὸς τὴν πόλιν. οἱ δὲ τάς τε πύλας ἀνοίγουσιν αὐτῷ καὶ μετ’ εὐφημιῶν ὑπήντων σωτῆρα καὶ εὐεργέτην ἀνακαλοῦντες. τῆς δὲ στρατιᾶς τριβομένης περὶ τὴν τῶν εἰσόδων στενότητα παραρρῆξαι τοῦ κατὰ μεσημβρίαν τείχους Οὐεσπασιανὸς κελεύσας πλατύνει τὴν εἰσβολὴν αὐτοῖς. ἁρπαγῆς μέντοι καὶ ὕβρεως ἀπέχεσθαι παρήγγειλεν τῷ βασιλεῖ χαριζόμενος, τῶν τε τειχῶν διὰ τοῦτον ἐφείσατο συμμενεῖν πρὸς τὸ λοιπὸν ἐγγυωμένου τοὺς ἐν αὐτοῖς, καὶ πολλὰ κεκακωμένην τὴν πόλιν ἐκ τῆς στάσεως ἀνελάμβανεν.", "st": "3.9.8"}, {"sp": "N", "t": "Ἔπειτα προελθὼν αὐτῆς τε μεταξὺ καὶ Ταριχεῶν στρατοπεδεύεται, τειχίζει τε τὴν παρεμβολὴν ὀχυρωτέραν ὑφορώμενος ἐκεῖ πολέμου τριβὴν αὐτῷ γενησομένην· συνέρρει γὰρ εἰς τὰς Ταριχέας πᾶν τὸ νεωτερίζον, τῇ τε τῆς πόλεως ὀχυρότητι καὶ τῇ λίμνῃ πεποιθότες, ἣ καλεῖται Γεννησὰρ πρὸς τῶν ἐπιχωρίων. ἡ μὲν γὰρ πόλις, ὥσπερ ἡ Τιβεριὰς ὑπόρειος οὖσα, καθὰ μὴ τῇ λίμνῃ προσεκλύζετο πάντοθεν ὑπὸ τοῦ Ἰωσήπου τετείχιστο καρτερῶς, ἔλασσον μέντοι τῆς Τιβεριάδος· τὸν μὲν γὰρ ἐκεῖ περίβολον ἐν ἀρχῇ τῆς ἀποστάσεως δαψιλείᾳ χρημάτων καὶ δυνάμεως ἐκρατύνατο, Ταριχέαι δ’ αὐτοῦ τὰ λείψανα τῆς φιλοτιμίας μετέλαβον. σκάφη δ’ ἦν αὐτοῖς ἐπὶ τῆς λίμνης παρεσκευασμένα πολλὰ πρός τε τὸ συμφεύγειν ἐπὶ γῆς ἡττωμένους, κἂν εἰ δέοι, διαναυμαχεῖν ἐξηρτυμένα. περιβαλλομένων δὲ τῶν Ῥωμαίων τὸ στρατόπεδον οἱ περὶ τὸν Ἰησοῦν οὔτε πρὸς τὸ πλῆθος οὔτε πρὸς τὴν εὐταξίαν τῶν πολεμίων ὑποδείσαντες προθέουσιν, καὶ πρὸς τὴν πρώτην ἔφοδον τῶν τειχοποιῶν σκεδασθέντων ὀλίγα τῆς δομήσεως σπαράξαντες, ὡς ἑώρων τοὺς ὁπλίτας ἀθροιζομένους, πρίν τι παθεῖν εἰς τοὺς σφετέρους ἀνέφευγον· ἐπιδιώξαντες δὲ Ῥωμαῖοι συνελαύνουσιν αὐτοὺς εἰς τὰ σκάφη. καὶ οἱ μὲν ἀναχθέντες εἰς ὅσον ἐξικνεῖσθαι τῶν Ῥωμαίων βάλλοντες δύναιντο τάς τε ἀγκύρας ἔβαλλον καὶ πυκνώσαντες ὥσπερ φάλαγγα τὰς ναῦς ἐπαλλήλους τοῖς ἐπὶ γῆς πολεμίοις διεναυμάχουν· Οὐεσπασιανὸς δὲ τὸ πολὺ πλῆθος αὐτῶν ἠθροισμένον ἀκούων ἐν τῷ πρὸ τῆς πόλεως πεδίῳ πέμπει τὸν υἱὸν σὺν ἱππεῦσιν ἑξακοσίοις ἐπιλέκτοις.", "st": "3.10.1"}, {"sp": "N", "t": "Ὁ δ’ ὑπέρογκον εὑρὼν τὴν τῶν πολεμίων πληθὺν πρὸς μὲν τὸν πατέρα πέμπει πλείονος δυνάμεως αὐτῷ δεῖν λέγων. αὐτὸς δὲ τοὺς μὲν πλείους τῶν ἱππέων ὡρμημένους ὁρῶν καὶ πρὶν ἀφικέσθαι βοήθειαν, ἔστιν δ’ οὓς ἡσυχῆ πρὸς τὸ πλῆθος τῶν Ἰουδαίων καταπεπληγότας, ἐν ἐπηκόῳ στὰς ἔλεξεν ὧδε· ἄνδρες, ἔφη, Ῥωμαῖοι, καλὸν γὰρ ἐν ἀρχῇ τῶν λόγων ὑπομνῆσαι τοῦ γένους ὑμᾶς, ἵν’ εἰδῆτε, τίνες ὄντες πρὸς τίνας μάχεσθαι μέλλομεν. τὰς μέν γε ἡμετέρας χεῖρας οὐδὲν εἰς τοῦτο τῶν ἐπὶ τῆς οἰκουμένης διαπέφευγεν, Ἰουδαῖοι δέ, ἵν’ εἴπωμεν καὶ ὑπὲρ αὐτῶν, μέχρι νῦν οὐ κοπιῶσιν ἡττώμενοι. καὶ δεινὸν ἐκείνων ἑστώτων ἐν ταῖς κακοπραγίαις ἡμᾶς τοῖς εὐτυχήμασιν ἐγκάμνειν. προθυμίας μὲν εἰς τὸ φανερὸν ὑμᾶς εὖ ἔχοντας χαίρω βλέπων, δέδοικα δὲ μή τινι τῶν πολεμίων τὸ πλῆθος κατάπληξιν λεληθυῖαν ἐνεργάσηται. λογισάσθω δὴ πάλιν οἷος πρὸς οἵους παρατάξεται, καὶ διότι Ἰουδαῖοι μέν, εἰ καὶ σφόδρα τολμηταὶ καὶ θανάτου καταφρονοῦντες, ἀλλ’ ἀσύντακτοί τε καὶ πολέμων ἄπειροι καὶ ὄχλος ἂν ἄλλως, οὐ στρατιὰ λέγοιντο· τὰ δὲ τῆς ἡμετέρας ἐμπειρίας καὶ τάξεως τί δεῖ καὶ λέγειν; ἐπὶ τοῦτο μέντοι γε μόνοι καὶ κατ’ εἰρήνην ἀσκούμεθα τοῖς ὅπλοις, ἵν’ ἐν πολέμῳ μὴ πρὸς τὸ ἀντίπαλον ἀριθμῶμεν ἑαυτούς. ἐπεὶ τίς ὄνησις τῆς διηνεκοῦς στρατείας, ἂν ἴσοι πρὸς ἀστρατεύτους ἀντιτασσώμεθα; λογίζεσθε δέ, ὅτι καὶ πρὸς γυμνῆτας ὁπλῖται καὶ ἱππεῖς πρὸς πεζοὺς καὶ στρατηγούμενοι πρὸς ἀστρατηγήτους διαγωνίζεσθε, καὶ ὡς ὑμᾶς μὲν ταῦτα πολλαπλασίους ποιεῖ τὰ πλεονεκτήματα, πολὺ δὲ τοῦ τῶν πολεμίων ἀριθμοῦ [παραιρεῖται τὰ ἐλαττώματα]. κατορθοῖ δὲ τοὺς πολέμους οὐ πλῆθος ἀνθρώπων, κἂν ᾖ μάχιμον, ἀνδρεία δέ, κἂν ἐν ὀλίγοις· οἱ μέν γε καὶ τάξασθαι ῥᾴδιοι καὶ προσαμύνειν ἑαυτοῖς, αἱ δ’ ὑπέρογκοι δυνάμεις ὑφ’ ἑαυτῶν βλάπτονται πλέον ἢ τῶν πολεμίων. Ἰουδαίων μὲν οὖν τόλμα καὶ θράσος ἡγεῖται καὶ ἀπόνοια, πάθη κατὰ μὲν τὰς εὐπραγίας εὔτονα, σβεννύμενα δὲ ἐν ἐλαχίστοις σφάλμασιν· ἡμῶν δ’ ἀρετὴ καὶ εὐπείθεια καὶ τὸ γενναῖον, ὃ κἀν τοῖς ἄλλοις εὐτυχήμασιν ἀκμάζει κἀν τοῖς πταίσμασιν οὐ μέχρι τέλους σφάλλεται. καὶ ὑπὲρ μειζόνων δὲ ἢ Ἰουδαῖοι διαγωνιεῖσθε· καὶ γὰρ εἰ περὶ ἐλευθερίας καὶ πατρίδων ἐκείνοις ὁ πόλεμος κινδυνεύεται, τί μεῖζον ἡμῖν εὐδοξίας καὶ τοῦ μὴ δοκεῖν μετὰ τὴν τῆς οἰκουμένης ἡγεμονίαν ἐν ἀντιπάλῳ τὰ Ἰουδαίων τίθεσθαι; σκεπτέον δ’ ὅτι καὶ παθεῖν μὲν οὐδὲν ἀνήκεστον ἡμῖν φόβος· πολλοὶ γὰρ οἱ βοηθήσοντες καὶ πλησίον· ἁρπάσαι δὲ τὴν νίκην δυνάμεθα, καὶ χρὴ τοὺς ὑπὸ τοῦ πατρὸς πεμπομένους ἡμῖν συμμάχους φθάνειν, ἵν’ ἀκοινώνητόν τε ᾖ τὸ κατόρθωμα καὶ μεῖζον. νομίζω δ’ ἔγωγε ἐπὶ τῆσδε τῆς ὥρας καὶ τὸν πατέρα τὸν ἐμὸν κρίνεσθαι κἀμὲ καὶ ὑμᾶς, εἰ τῶν μὲν προκατωρθωμένων ἄξιος ἐκεῖνος, ἐγὼ δ’ ἐκείνου παῖς, στρατιῶται δ’ ὑμεῖς ἐμοῦ· καὶ γὰρ ἐκείνῳ τὸ νικᾶν ἔθος, κἀγὼ πρὸς αὐτὸν ὑποστρέφειν οὐκ ἂν ὑπομείναιμι λειφθείς. ὑμεῖς δὲ πῶς οὐκ ἂν αἰσχύνοισθε προκινδυνεύοντος ἡγεμόνος ἡττώμενοι; προκινδυνεύσω γάρ, εὖ ἴστε, καὶ πρῶτος εἰς τοὺς πολεμίους ἐμβαλῶ. μὴ λείπεσθε δ’ ὑμεῖς ἐμοῦ πεπεισμένοι τὴν ἐμὴν ὁρμὴν παρακροτεῖσθαι θεῷ συμμάχῳ, καὶ προγινώσκετε σαφῶς, ὅτι τῆς ἔξω μάχης πλέον τι κατορθώσομεν.", "st": "3.10.2"}, {"sp": "N", "t": "Ταῦτα τοῦ Τίτου διεξιόντος προθυμία δαιμόνιος ἐμπίπτει τοῖς ἀνδράσιν, καὶ προσγενομένου πρὶν συμβαλεῖν Τραϊανοῦ μετὰ τετρακοσίων ἱππέων ἤσχαλλον ὡς μειουμένης τῆς νίκης αὐτοῖς διὰ τὴν κοινωνίαν. ἔπεμψεν δὲ Οὐεσπασιανὸς καὶ Ἀντώνιον Σίλωνα σὺν δισχιλίοις τοξόταις κελεύσας καταλαβόντας τὸ ἀντικρὺ τῆς πόλεως ὄρος τοὺς ἐπὶ τοῦ τείχους ἀνείργειν. καὶ οἱ μὲν ὡς προσετέτακτο τοὺς ταύτῃ πειρωμένους ἐκβοηθεῖν περιέσχον, ὁ δὲ Τίτος πρῶτος τὸν ἵππον ἤλαυνεν εἰς τοὺς πολεμίους καὶ σὺν κραυγῇ μετ’ αὐτὸν οἱ λοιποὶ παρεκτείναντες ἑαυτοὺς εἰς ὅσον ἐπεῖχον οἱ πολέμιοι τὸ πεδίον· παρὸ καὶ πολὺ πλείους ἔδοξαν. οἱ δὲ Ἰουδαῖοι καίτοι τήν τε ὁρμὴν καὶ τὴν εὐταξίαν αὐτῶν καταπλαγέντες πρὸς ὀλίγον μὲν ἀντέσχον ταῖς ἐμβολαῖς, νυσσόμενοι δὲ τοῖς κοντοῖς καὶ τῷ ῥοίζῳ τῶν ἱππέων ἀνατρεπόμενοι συνεπατοῦντο. πολλῶν δὲ πανταχοῦ φονευομένων διασκίδνανται καὶ πρὸς τὴν πόλιν ὡς ἕκαστος εἶχεν τάχους ἔφευγον. Τίτος δὲ τοὺς μὲν κατόπιν προσκείμενος ἀνῄρει, τῶν δὲ διεκπαίων ἀθρόων, οὓς δὲ φθάνων κατὰ στόμα διήλαυνεν, πολλοὺς δὲ συνηλοία περὶ ἀλλήλοις πεσόντας ἐμπηδῶν, πᾶσιν δὲ τὰς πρὸς τὸ τεῖχος φυγὰς ὑπετέμνετο καὶ πρὸς τὸ πεδίον ἀπέστρεφεν, ἕως τῷ πλήθει βιασάμενοι καὶ διεκπεσόντες εἰς τὴν πόλιν συνέφευγον.", "st": "3.10.3"}, {"sp": "N", "t": "Ἐκδέχεται δὲ αὐτοὺς πάλιν στάσις ἔσω χαλεπή· τοῖς μὲν γὰρ ἐπιχωρίοις διά τε τὰς κτήσεις καὶ τὴν πόλιν οὐκ ἐδόκει πολεμεῖν ἀπ’ ἀρχῆς καὶ τότε διὰ τὴν ἧτταν πλέον· ὁ δ’ ἔπηλυς πολὺς ὢν πλεῖον ἐβιάζετο, καὶ διωργισμένων ἐπ’ ἀλλήλοις κραυγή τε ἦν καὶ θόρυβος ὡς ὅσον οὔπω φερομένων εἰς ὅπλα. κατακούσας δὲ τῆς ταραχῆς Τίτος, οὐ γὰρ ἦν ἄπωθεν τοῦ τείχους, οὗτος ἦν ὁ καιρός, ἐκβοᾷ, καὶ τί, συστρατιῶται, μέλλομεν ἐκδιδόντος ἡμῖν Ἰουδαίους θεοῦ; δέξασθε τὴν νίκην. οὐκ ἀκούετε βοῆς; στασιάζουσιν οἱ τὰς χεῖρας ἡμῶν διεκφυγόντες. ἔχομεν τὴν πόλιν, ἐὰν ταχύνωμεν· δεῖ δὲ πόνου πρὸς τῷ τάχει καὶ λήματος· οὐδὲν γὰρ τῶν μεγάλων φιλεῖ δίχα κινδύνου κατορθοῦσθαι. φθάνειν δ’ οὐ μόνον χρὴ τὴν τῶν πολεμίων ὁμόνοιαν, οὓς ἀνάγκη διαλλάξει ταχέως, ἀλλὰ καὶ τὴν τῶν ἡμετέρων βοήθειαν, ἵνα πρὸς τῷ νικῆσαι τοσοῦτον πλῆθος ὀλίγοι καὶ τὴν πόλιν ἕλωμεν μόνοι.", "st": "3.10.4"}, {"sp": "N", "t": "Ταῦθ’ ἅμα λέγων ἐπὶ τὸν ἵππον ἀνεπήδα καὶ καθηγεῖται πρὸς τὴν λίμνην, δι’ ἧς ἐλάσας πρῶτος εἰς τὴν πόλιν εἰσέρχεται καὶ μετ’ αὐτὸν οἱ λοιποί. δέος δὲ πρὸς τὴν τόλμαν αὐτοῦ τοῖς ἐπὶ τῶν τειχῶν ἐνέπεσεν, καὶ μάχεσθαι μὲν ἢ διακωλύειν οὐδεὶς ὑπέμεινεν, λιπόντες δὲ τὴν φρουρὰν οἱ μὲν περὶ τὸν Ἰησοῦν διὰ τῆς χώρας ἔφευγον, οἱ δ’ ἐπὶ τὴν λίμνην καταθέοντες ὑπαντιάζουσιν τοῖς πολεμίοις περιέπιπτον· ἐκτείνοντο δ’ οἱ μὲν ἐπιβαίνοντες τῶν σκαφῶν, οἱ δὲ τοῖς ἀναχθεῖσιν προσπίπτειν πειρώμενοι. πολὺς δὲ τῶν κατὰ τὴν πόλιν ἦν φόνος, τῶν μὲν ἐπηλύδων ὅσοι μὴ διαφυγεῖν ἔφθασαν ἀντιτασσομένων, ἀμαχητὶ δὲ τῶν ἐπιχωρίων· κατὰ γὰρ ἐλπίδα δεξιᾶς καὶ τὸ συνειδὸς τοῦ μὴ βεβουλεῦσθαι πολεμεῖν μάχης ἀπετρέποντο, μέχρι Τίτος τοὺς μὲν αἰτίους ἀνελών, οἰκτείρας δὲ τοὺς ἐπιχωρίους ἀνεπαύσατο φόνου. καὶ οἱ μὲν εἰς τὴν λίμνην καταφυγόντες ἐπεὶ τὴν πόλιν εἶδον ἑαλωκυῖαν, ὡς πορρωτάτω τῶν πολεμίων ἀνήχθησαν·", "st": "3.10.5"}, {"sp": "N", "t": "Τίτος δ’ ἐκπέμψας τινὰ τῶν ἱππέων εὐαγγελίζεται τῷ πατρὶ τὸ ἔργον. ὁ δ’, ὡς εἰκός, ὑπερησθεὶς τῇ τε τοῦ παιδὸς ἀρετῇ καὶ τῷ κατορθώματι, μεγίστη γὰρ ἐδόκει καθῃρῆσθαι μοῖρα τοῦ πολέμου, τότε μὲν ἐλθὼν περισχόντας τὴν πόλιν φρουρεῖν ἐκέλευσεν, ὡς μὴ διαλάθοι τις ἐξ αὐτῆς, καὶ κτείνειν προσέταξεν τῇ δ’ ὑστεραίᾳ πρὸς τὴν λίμνην καταβὰς σχεδίας ἐκέλευσεν πήσσειν ἐπὶ τοὺς καταπεφευγότας· αἱ δ’ ἐγίνοντο ταχέως ἀφθονίᾳ τε ὕλης καὶ πλήθει τεχνιτῶν.", "st": "3.10.6"}, {"sp": "N", "t": "Ἡ δὲ λίμνη Γεννησὰρ μὲν ἀπὸ τῆς προσεχοῦς χώρας καλεῖται, σταδίων δ’ εὖρος οὖσα τεσσαράκοντα καὶ πρὸς τούτοις ἑτέρων ἑκατὸν τὸ μῆκος γλυκεῖά τε ὅμως ἐστὶ καὶ ποτιμωτάτη· καὶ γὰρ τῆς ἑλώδους παχύτητος ἔχει τὸ νᾶμα λεπτότερον καθαρά τ’ ἐστὶν πάντοθεν αἰγιαλοῖς ἐπιλήγουσα καὶ ψάμμῳ, πρὸς δὲ εὔκρατος ἀρύσασθαι, ποταμοῦ μὲν ἢ κρήνης προσηνεστέρα, ψυχροτέρα δὲ ἢ κατὰ λίμνης διάχυσιν ἀεὶ μένουσα. τὸ μὲν γὰρ ὕδωρ οὐκ ἀπᾴδει χιόνος ἐξαιθριασθέν, ὅπερ θέρους νυκτὸς ποιεῖν ἔθος τοῖς ἐπιχωρίοις, γένη δὲ ἰχθύων ἐν αὐτῇ διάφορα πρὸς τοὺς ἀλλαχοῦ γεῦσίν τε καὶ ἰδέαν. μέση δ’ ὑπὸ τοῦ Ἰορδάνου τέμνεται. καὶ δοκεῖ μὲν Ἰορδάνου πηγὴ τὸ Πάνειον, φέρεται δ’ ὑπὸ γῆν εἰς τοῦτο κρυπτῶς ἐκ τῆς καλουμένης Φιάλης· ἡ δ’ ἐστὶν ἀνιόντων εἰς τὴν Τραχωνῖτιν ἀπὸ σταδίων ἑκατὸν εἴκοσι Καισαρείας τῆς ὁδοῦ κατὰ τὸ δεξιὸν μέρος οὐκ ἄπωθεν. ἐκ μὲν οὖν τῆς περιφερείας ἐτύμως Φιάλη καλεῖται τροχοειδὴς οὖσα λίμνη, μένει δ’ ἐπὶ χείλους αὐτῆς ἀεὶ τὸ ὕδωρ μήθ’ ὑπονοστοῦν μήθ’ ὑπερχεόμενον. ἀγνοούμενος δὲ τέως ὁ Ἰορδάνης ἐντεῦθεν ἄρχεσθαι διὰ τοῦ τετραρχήσαντος Τραχωνιτῶν ἠλέγχθη Φιλίππου· βαλὼν γὰρ οὗτος εἰς τὴν Φιάλην ἄχυρα κατὰ τὸ Πάνειον, ἔνθεν ἐδόκουν οἱ παλαιοὶ γεννᾶσθαι τὸν ποταμόν, εὗρεν ἀνενεχθέντα. τοῦ μὲν οὖν Πανείου τὸ φυσικὸν κάλλος ὑπὸ τῆς βασιλικῆς προσεξήσκηται πολυτελείας τῷ Ἀγρίππα πλούτῳ κεκοσμημένον· ἀρχόμενος δὲ φανεροῦ ῥεύματος ὁ Ἰορδάνης ἀπὸ τοῦδε τοῦ ἄντρου κόπτει μὲν τὰ τῆς Σεμεχωνίτιδος λίμνης ἕλη καὶ τέλματα, διαμείψας δ’ ἑτέρους ἑκατὸν εἴκοσι σταδίους μετὰ πόλιν Ἰουλιάδα διεκπαίει τὴν Γεννησὰρ μέσην, ἔπειτα πολλὴν ἀναμετρούμενος ἐρημίαν εἰς τὴν Ἀσφαλτῖτιν ἔξεισι λίμνην.", "st": "3.10.7"}, {"sp": "N", "t": "Παρατείνει δὲ τὴν Γεννησὰρ ὁμώνυμος χώρα θαυμαστὴ φύσιν τε καὶ κάλλος· οὔτε γὰρ αὐτή τι φυτὸν ἀρνεῖται διὰ τὴν πιότητα, καὶ πᾶν πεφυτεύκασιν οἱ νεμόμενοι, τοῦ δ’ ἀέρος τὸ εὔκρατον ἁρμόζει καὶ τοῖς διαφόροις. καρύαι μέν γε φυτῶν τὸ χειμεριώτατον ἄπειροι τεθήλασιν ἔνθα φοίνικες, οἳ καύματι τρέφονται, συκαῖ δὲ καὶ ἐλαῖαι πλησίον τούτων, αἷς μαλθακώτερος ἀὴρ ἀποδέδεικται. φιλοτιμίαν ἄν τις εἴποι τῆς φύσεως βιασαμένης εἰς ἓν συναγαγεῖν τὰ μάχιμα καὶ τῶν ὡρῶν ἀγαθὴν ἔριν ἑκάστης ὥσπερ ἀντιποιουμένης τοῦ χωρίου· καὶ γὰρ οὐ μόνον τρέφει παρὰ δόξαν τὰς διαφόρους ὀπώρας ἀλλὰ καὶ διαφυλάσσει. τὰ μέν γε βασιλικώτατα σταφυλήν τε καὶ σῦκον δέκα μησὶν ἀδιαλείπτως χορηγεῖ, τοὺς δὲ λοιποὺς καρποὺς δι’ ἔτους ὅλου περιγηράσκοντας ἑαυτοῖς· πρὸς γὰρ τῇ τῶν ἀέρων εὐκρασίᾳ καὶ πηγῇ διάρδεται γονιμωτάτῃ, Καφαρναοὺμ αὐτὴν οἱ ἐπιχώριοι καλοῦσιν. ταύτην φλέβα τινὲς τοῦ Νείλου ἔδοξαν, ἐπεὶ γεννᾷ τῷ κατὰ τὴν Ἀλεξανδρέων λίμνην κορακίνῳ παραπλήσιον. μῆκος δὲ τοῦ χωρίου παρατείνει κατὰ τὸν αἰγιαλὸν τῆς ὁμωνύμου λίμνης ἐπὶ σταδίους τριάκοντα, καὶ εὖρος εἴκοσι. ταῦτα μὲν οὕτως φύσεως ἔχει.", "st": "3.10.8"}, {"sp": "N", "t": "Οὐεσπασιανὸς δέ, ἐπεὶ παρεσκευάσθησαν αἱ σχεδίαι, τῆς δυνάμεως ἐπιβήσας ὅσον ᾤετο τοῖς κατὰ τὴν λίμνην ἀνταρκέσειν ἐπανήγετο. τοῖς δὲ συνελαυνομένοις οὔτ’ ἐπὶ γῆν διαφεύγειν ἦν ἐκπεπολεμωμένων πάντων οὔτ’ ἐξ ἴσου διαναυμαχεῖν· τά τε γὰρ σκάφη μικρὰ ὄντα καὶ λῃστρικὰ πρὸς τὰς σχεδίας ἦν ἀσθενῆ, καὶ καθ’ ἕκαστον ἐμπλέοντες ὀλίγοι πρὸς ἀθρόους ἐφεστῶτας τοὺς Ῥωμαίους ἐγγίζειν ἐδεδοίκεισαν. ὅμως δ’ οὖν ἐκπεριπλέοντες τὰς σχεδίας, ἔστιν δ’ ὅπου καὶ πλησιάζοντες, πόρρωθεν τοὺς Ῥωμαίους ἔβαλλον λίθοις καὶ παραξύοντες ἐγγύθεν ἔπαιον. ἐκακοῦντο δ’ αὐτοὶ πλέον κατ’ ἀμφότερα· ταῖς τε γὰρ χερμάσιν οὐδὲν δρῶντες ὅτι μὴ κτύπον ἐπάλληλον, εἰς γὰρ πεφραγμένους ἔβαλλον, ἐφικτοὶ τοῖς Ῥωμαίων ἐγίνοντο βέλεσιν, καὶ πλησιάζειν τολμῶντες πρὶν δρᾶσαί τι παθεῖν ἔφθανον καὶ σὺν αὐτοῖς ἐβαπτίζοντο τοῖς σκάφεσιν. τῶν δὲ διεκπαίειν πειρωμένων πολλοὺς μὲν ἐφικνούμενοι κοντοῖς διέπειρον, οὓς δὲ ξιφήρεις ἐπιπηδῶντες εἰς τὰ σκάφη, τινὰς δὲ συντρεχούσαις ταῖς σχεδίαις ἐναποληφθέντας μέσους εἷλον ἅμα ταῖς ἁλιάσιν. τῶν δὲ βαπτισθέντων τοὺς ἀνανεύοντας ἢ βέλος ἔφθανεν ἢ σχεδία κατελάμβανεν, καὶ προσβαίνειν ὑπ’ ἀμηχανίας εἰς τοὺς ἐχθροὺς πειρωμένων ἢ κεφαλὰς ἢ χεῖρας ἀπέκοπτον οἱ Ῥωμαῖοι. πολλή τε ἦν αὐτῶν καὶ ποικίλη φθορὰ πανταχοῦ, μέχρι τραπέντες εἰς γῆν ἐξεώσθησαν οἱ λοιποὶ κεκυκλωμένων αὐτοῖς τῶν ἁλιάδων. ἐκχεόμενοι δὲ πολλοὶ μὲν ἐν αὐτῇ κατηκοντίζοντο τῇ λίμνῃ, πολλοὺς δ’ ἐκπηδήσαντας οἱ Ῥωμαῖοι διέφθειραν ἐπὶ γῆς. ἦν δ’ ἰδεῖν κεκερασμένην μὲν αἵματι, πεπληρωμένην δὲ νεκρῶν τὴν λίμνην ἅπασαν· διεσώθη γὰρ οὐδείς. δεινὴ δὲ ταῖς ἑξῆς ἡμέραις περιεῖχε τὴν χώραν ὀδμή τε καὶ ὄψις· οἱ μὲν γὰρ αἰγιαλοὶ ναυαγίων ἅμα καὶ διοιδούντων ἔγεμον σωμάτων, ἐκκαιόμενοι δὲ καὶ μυδῶντες οἱ νεκροὶ τὸν ἀέρα διέφθειρον, ὡς μὴ μόνον οἰκτρὸν Ἰουδαίοις γενέσθαι τὸ πάθος, ἀλλὰ καὶ διὰ μίσους τοῖς δράσασιν ἐλθεῖν. τοῦτο μὲν ἐκείνης τῆς ναυμαχίας τὸ τέλος, ἀπέθανον δὲ σὺν τοῖς ἐπὶ τῆς πόλεως πρότερον πεσοῦσιν ἑξακισχίλιοι ἑπτακόσιοι.", "st": "3.10.9"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ μετὰ τὴν μάχην καθίζει μὲν ἐπὶ βήματος ἐν Ταριχέαις, διακρίνων δ’ ἀπὸ τῶν ἐπιχωρίων τὸν ἔπηλυν λεώ, κατάρξαι γὰρ οὗτος ἐδόκει πολέμου, μετὰ τῶν ἡγεμόνων εἰ χρὴ καὶ τούτους σώζειν ἐσκέπτετο. φαμένων δὲ τούτων βλαβερὰν ἔσεσθαι τὴν ἄφεσιν αὐτῶν, οὐ γὰρ ἠρεμήσειν ἀπολυθέντας ἀνθρώπους ἐστερημένους μὲν τῶν πατρίδων, βιάζεσθαι δὲ καὶ πρὸς οὓς ἂν καταφύγωσιν πολεμεῖν δυναμένους, Οὐεσπασιανὸς ὡς μὲν οὔτ’ ἄξιοι σωτηρίας εἶεν καὶ διαφεύξονται κατὰ τῶν ἀφέντων ἐγίνωσκεν, τὸν δὲ τρόπον αὐτῶν τῆς ἀναιρέσεως διενοεῖτο. καὶ γὰρ αὐτόθι κτείνων ἐκπολεμώσειν ὑφωρᾶτο τοὺς ἐπιχωρίους, οὐ γὰρ ἀνέξεσθαι φονευομένων ἱκετῶν τοσούτων παρ’ αὐτοῖς, καὶ μετὰ πίστεις ἐπιθέσθαι προελθοῦσιν οὐχ ὑπέμενεν. ἐξενίκων δ’ οἱ φίλοι μηδὲν κατὰ Ἰουδαίων ἀσεβὲς εἶναι λέγοντες καὶ χρῆναι τὸ συμφέρον αἱρεῖσθαι πρὸ τοῦ πρέποντος, ὅταν ᾖ μὴ δυνατὸν ἄμφω. κατανεύσας οὖν αὐτοῖς ἄδειαν ἀμφίβολον ἐπέτρεψεν ἐξιέναι διὰ μόνης τῆς ἐπὶ Τιβεριάδα φερούσης ὁδοῦ. τῶν δὲ ταχέως πιστευσάντων οἷς ἤθελον καὶ μετὰ φανερῶν ἐν ἀσφαλεῖ τῶν χρημάτων ᾗπερ ἐπετράπη χωρούντων, διαλαμβάνουσιν μὲν οἱ Ῥωμαῖοι τὴν μέχρι Τιβεριάδος πᾶσαν, ὡς μή τις ἀποκλίνειεν, συγκλείουσι δ’ αὐτοὺς εἰς τὴν πόλιν. καὶ Οὐεσπασιανὸς ἐπελθὼν ἵστησι πάντας ἐν τῷ σταδίῳ, καὶ γηραιοὺς μὲν ἅμα τοῖς ἀχρήστοις διακοσίους ἐπὶ χιλίοις ὄντας ἀνελεῖν ἐκέλευσεν, τῶν δὲ νέων ἐπιλέξας τοὺς ἰσχυροτάτους ἑξακισχιλίους ἔπεμψεν εἰς τὸν ἰσθμὸν Νέρωνι, καὶ τὸ λοιπὸν πλῆθος εἰς τρισμυρίους καὶ τετρακοσίους ὄντας πιπράσκει χωρὶς τῶν Ἀγρίππᾳ χαρισθέντων· τοὺς γὰρ ἐκ τῆς τούτου βασιλείας ἐπέτρεψεν αὐτῷ ποιεῖν εἴ τι βούλοιτο· πιπράσκει δὲ καὶ τούτους ὁ βασιλεύς. ὁ μέντοι γε ἄλλος ὄχλος Τραχωνῖται καὶ Γαυλανῖται καὶ Ἱππηνοὶ καὶ ἐκ τῆς Γαδαρίτιδος τὸ πλέον ὡς στασιασταὶ καὶ φυγάδες καὶ οἷς τὰ τῆς εἰρήνης ὀνείδη τὸν πόλεμον προυξένει ἑάλωσαν δὲ Γορπιαίου μηνὸς ὀγδόῃ.", "st": "3.10.10"}, {"sp": "HDR", "t": "Βιβλίον Δʹ", "st": "4"}, {"sp": "N", "t": "Ὅσοι δὲ μετὰ τὴν Ἰωταπάτων ἅλωσιν Γαλιλαῖοι Ῥωμαίων ἀφεστήκεσαν, οὗτοι τῶν ἐν Ταριχέαις ἡττηθέντων προσεχώρουν, καὶ παρέλαβον πάντα Ῥωμαῖοι τὰ φρούρια καὶ τὰς πόλεις πλὴν Γισχάλων καὶ τῶν τὸ Ἰταβύριον ὄρος κατειληφότων. συνέστη δὲ τούτοις καὶ Γάμαλα πόλις Ταριχεῶν ἄντικρυς ὑπὲρ τὴν λίμνην κειμένη. τῆς δ’ Ἀγρίππα λήξεως αὕτη τε ἦν καὶ Σωγάνη καὶ Σελεύκεια, καὶ αἱ μὲν [ἐκ] τῆς Γαυλανίτιδος ἀμφότεραι· τοῦ γὰρ ἄνω καλουμένου Γαυλανᾶ μέρος ἦν ἡ Σωγάνη, τοῦ κάτω δ’ ἡ Γάμαλα· Σελεύκεια δὲ πρὸς τῇ Σεμεχωνιτῶν λίμνῃ. ταύτῃ τριάκοντα μὲν εὖρος, ἑξήκοντα δὲ μῆκος στάδιοι· διατείνει δ’ αὐτῆς τὰ ἕλη μέχρι Δάφνης χωρίου τά τε ἄλλα τρυφεροῦ καὶ πηγὰς ἔχοντος, αἳ τρέφουσαι τὸν μικρὸν καλούμενον Ἰόρδανον ὑπὸ τὸν τῆς χρυσῆς βοὸς νεὼ προπέμπουσι τῷ μεγάλῳ. τοὺς μὲν οὖν ἐπὶ Σωγάνην καὶ Σελεύκειαν ὑπὸ τὴν ἀρχὴν τῆς ἀποστάσεως δεξιαῖς Ἀγρίππας προσηγάγετο, Γάμαλα δ’ οὐ προσεχώρει πεποιθυῖα τῇ δυσχωρίᾳ πλέον τῶν Ἰωταπάτων. τραχὺς γὰρ αὐχὴν ἀφ’ ὑψηλοῦ κατατείνων ὄρους μέσον ἐπαίρει τένοντα, μηκύνεται δὲ ἐκ τῆς ὑπεροχῆς εἰς τοὔμπροσθεν ἐκκλίνων ὅσον κατόπιν, ὡς εἰκάζεσθαι καμήλῳ τὸ σχῆμα, παρ’ ἣν ὠνόμασται τὸ τρανὸν τῆς κλήσεως οὐκ ἐξακριβούντων τῶν ἐπιχωρίων. κατὰ πλευρὰ μὲν δὴ καὶ πρόσωπον εἰς φάραγγας ἀβάτους περισχίζεται, τὸ κατ’ οὐρὰν δὲ ὀλίγον ἀναφεύγει τῆς δυσχωρίας, ὅθεν ἀπήρτηται τοῦ ὄρους· καὶ τοῦτο δ’ ἐπικαρσίᾳ παρακόψαντες τάφρῳ δύσβατον οἱ ἐπιχώριοι κατεσκεύασαν. πρὸς ὀρθίῳ δὲ τῇ λαγόνι δεδομημέναι πεπύκνωντο δεινῶς ἐπ’ ἀλλήλαις αἱ οἰκίαι, κρημνιζομένῃ τε ἡ πόλις ἐοικυῖα κατέτρεχεν εἰς ἑαυτὴν ἀπὸ τῆς ὀξύτητος. καὶ πρὸς μεσημβρίαν μὲν ἔκλινεν, ὁ νότιος δ’ αὐτῆς ὄχθος εἰς ἄπειρον ὕψος ἀνατείνων ἄκρα τῆς πόλεως ἦν, ἀτείχιστος δὲ ὑπὲρ αὐτὴν κρημνὸς εἰς τὴν βαθυτάτην κατατείνων φάραγγα· πηγὴ δ’ ἐντὸς τοῦ τείχους, ἐφ’ ἣν τὸ ἄστυ κατέληγεν.", "st": "4.1.1"}, {"sp": "N", "t": "Οὕτως οὖσαν φύσει δυσμήχανον τὴν πόλιν τειχίζων ὁ Ἰώσηπος ἐποίησεν ὀχυρωτέραν ὑπονόμοις τε καὶ διώρυξιν. οἱ δ’ ἐν αὐτῇ φύσει μὲν τοῦ χωρίου θαρραλεώτεροι τῶν κατὰ τὴν Ἰωταπάτην ἦσαν, πολὺ δ’ ἐλάττους μάχιμοι, καὶ τῷ τόπῳ πεποιθότες οὐδὲ πλείονας ὑπελάμβανον πεπλήρωτο γὰρ ἡ πόλις διὰ τὴν ὀχυρότητα συμφυγόντων· παρὸ καὶ τοῖς ὑπ’ Ἀγρίππα προπεμφθεῖσιν ἐπὶ τὴν πολιορκίαν ἀντεῖχεν ἐπὶ μῆνας ἑπτά.", "st": "4.1.2"}, {"sp": "N", "t": "Οὐεσπασιανὸς δ’ ἄρας ἀπὸ τῆς Ἀμμαθοῦς, ἔνθα πρὸ τῆς Τιβεριάδος ἐστρατοπεδεύκει· μεθερμηνευομένη δ’ Ἀμμαθοῦς θερμὰ λέγοιτ’ ἄν, ἔστι γὰρ ἐν αὐτῇ πηγὴ θερμῶν ὑδάτων πρὸς ἄκεσιν ἐπιτηδείων· ἀφικνεῖται πρὸς τὴν Γάμαλαν. καὶ πᾶσαν μὲν κυκλώσασθαι φυλακῇ τὴν πόλιν οὐχ οἷός τε ἦν οὕτως διακειμένην, πρὸς δὲ τοῖς δυνατοῖς φρουροὺς καθίστησι καὶ τὸ ὑπερκείμενον ὄρος καταλαμβάνεται. τειχισαμένων δὲ ὥσπερ ἔθος τῶν ταγμάτων ὑπὲρ αὐτοῦ στρατόπεδα χωμάτων ἤρχετο κατ’ οὐράν, καὶ τὸ μὲν κατ’ ἀνατολὰς αὐτῷ μέρος, ᾗπερ ὁ ἀνωτάτω τῆς πόλεως πύργος ἦν, ἐφ’ οὗ τὸ πέμπτον καὶ δέκατον τάγμα, καὶ τὸ πέμπτον μὲν κατὰ μέσην ἐξειργάζετο τὴν πόλιν, τὰς δὲ διώρυγας ἀνεπλήρου καὶ τὰς φάραγγας τὸ δέκατον. κἀν τούτῳ προσελθόντα τοῖς τείχεσιν Ἀγρίππαν τὸν βασιλέα καὶ περὶ παραδόσεως τοῖς ἐφεστῶσι πειρώμενον διαλέγεσθαι βάλλει τις τῶν σφενδονητῶν κατὰ τὸν δεξιὸν ἀγκῶνα λίθῳ. καὶ ὁ μὲν ὑπὸ τῶν οἰκείων θᾶττον περιεσχέθη, Ῥωμαίους δὲ ἐπήγειρεν εἰς τὴν πολιορκίαν ὀργή τε περὶ τοῦ βασιλέως καὶ περὶ σφῶν αὐτῶν δέος· οὐ γὰρ ἀπολείψειν ὠμότητος ὑπερβολὴν κατ’ ἀλλοφύλων καὶ πολεμίων τοὺς πρὸς ὁμόφυλον καὶ τῶν συμφερόντων αὐτοῖς σύμβουλον οὕτως ἀγριωθέντας.", "st": "4.1.3"}, {"sp": "N", "t": "Συντελεσθέντων οὖν τῶν χωμάτων θᾶττον πλήθει χειρῶν καὶ τῶν πραττομένων ἔθει προσῆγον τὰς μηχανάς. οἱ δὲ περὶ τὸν Χάρητα καὶ Ἰώσηπον, οὗτοι γὰρ ἦσαν τῶν κατὰ τὴν πόλιν δυνατώτατοι, καίπερ καταπεπληγότας τοὺς ὁπλίτας τάττουσιν, ἐπειδὴ μέχρι πολλοῦ πρὸς τὴν πολιορκίαν ἀνθέξειν οὐχ ὑπελάμβανον ὕδατι καὶ τοῖς ἄλλοις ἐπιτηδείοις μὴ διαρκούμενοι. παρακροτήσαντες δ’ ὅμως ἐξήγαγον ἐπὶ τὸ τεῖχος, καὶ πρὸς ὀλίγον μὲν ἀπημύναντο τοὺς προσάγοντας τὰς μηχανάς, βαλλόμενοι δὲ τοῖς καταπελτικοῖς καὶ τοῖς πετροβόλοις ἀνεχώρουν εἰς τὴν πόλιν. καὶ προσάγοντες οἱ Ῥωμαῖοι τριχόθεν τοὺς κριοὺς διασείουσι μὲν τὸ τεῖχος, ὑπὲρ δὲ τῶν ἐρειφθέντων εἰσχεόμενοι μετὰ πολλοῦ σαλπίγγων ἤχου καὶ κτύπου τῶν ὅπλων αὐτοί τ’ ἐπαλαλάζοντες συνερρήγνυντο τοῖς κατὰ τὴν πόλιν. οἱ δὲ τέως μὲν κατὰ τὰς πρώτας εἰσόδους ἐνιστάμενοι προσωτέρω χωρεῖν ἐκώλυον καὶ καρτερῶς τοὺς Ῥωμαίους ἀνεῖργον· βιαζόμενοι δὲ ὑπὸ πολλῶν καὶ πάντοθεν τρέπονται πρὸς τὰ ὑψηλὰ τῆς πόλεως καὶ προσκειμένοις τοῖς πολεμίοις ἐξ ὑποστροφῆς ἐπιπεσόντες συνώθουν εἰς τὸ κάταντες καὶ τῇ στενότητι καὶ δυσχωρίᾳ θλιβομένους ἀνῄρουν. οἱ δὲ μήτε τοὺς κατὰ κορυφὴν ἀμύνασθαι δυνάμενοι μήτε διεκπαίειν τῶν σφετέρων πρόσω βιαζομένων ἐπὶ τὰς οἰκίας τῶν πολεμίων, πρόσγειοι γὰρ ἦσαν, ἀνέφευγον. αἱ δὲ ταχέως κατηρείποντο πληρούμεναι καὶ τὸ βάρος μὴ στέγουσαι, κατέσειε δὲ πολλὰς μία τῶν ὑπ’ αὐτῆς πεσοῦσα καὶ πάλιν ἐκεῖναι τὰς ὑπ’ αὐτάς. τοῦτο πλείστους διέφθειρε τῶν Ῥωμαίων· ὑπὸ γὰρ ἀμηχανίας καίτοι συνιζανούσας ὁρῶντες ἐπεπήδων ταῖς στέγαις, καὶ πολλοὶ μὲν κατεχώννυντο τοῖς ἐρειπίοις, πολλοὶ δ’ ὑποφεύγοντες μέρη τοῦ σώματος κατελαμβάνοντο, πλείστους δὲ ὁ κονιορτὸς ἄγχων ἀνῄρει. συνεργίαν θεοῦ τοῦτο Γαμαλεῖς ὑπελάμβανον καὶ τῆς κατὰ σφᾶς ἀμελοῦντες βλάβης ἐπέκειντο, πρός τε τὰ στέγη τοὺς πολεμίους ἀνωθοῦντες καί τοι κατολισθάνοντας ἐν ὀξέσι τοῖς στενωποῖς καὶ ἀεὶ τοὺς πίπτοντας ὕπερθεν βάλλοντες ἔκτεινον. καὶ τὰ μὲν ἐρείπια χερμάδων πλέα ἦν αὐτοῖς, σίδηρον δὲ παρεῖχον οἱ τῶν πολεμίων νεκροί· παρασπῶντες γὰρ τὰ τῶν πεσόντων ξίφη κατὰ τῶν δυσθανατούντων ἐχρῶντο. πολλοὶ δ’ ἀπὸ πιπτόντων ἤδη τῶν δωμάτων σφᾶς αὐτοὺς βάλλοντες ἔθνησκον. ἦν δ’ οὐδὲ τραπέντων ἡ φυγὴ ῥᾴδιος· κατὰ γὰρ ἄγνοιαν τῶν ὁδῶν καὶ παχύτητα τοῦ κονιορτοῦ μηδὲ ἀλλήλους ἐπιγινώσκοντες ἀνειλοῦντο καὶ περὶ σφᾶς ἔπιπτον.", "st": "4.1.4"}, {"sp": "N", "t": "Οἱ μὲν οὖν μόλις εὑρίσκοντες τὰς ἐξόδους ἀνεχώρησαν ἐκ τῆς πόλεως· Οὐεσπασιανὸς δ’ ἀεὶ προσμένων τοῖς πονουμένοις, δεινὸν γάρ τι πάθος αὐτὸν εἰσῄει κατερειπομένην ὁρῶντα περὶ τῷ στρατῷ τὴν πόλιν, ἐν λήθῃ τοῦ κατ’ αὐτὸν ἀσφαλοῦς γενόμενος λανθάνει κατὰ μικρὸν ἀνωτάτω τῆς πόλεως προελθών, ἔνθα μέσοις ἐγκαταλείπεται τοῖς κινδύνοις μετ’ ὀλίγων παντελῶς· οὐδὲ γὰρ ὁ παῖς αὐτῷ Τίτος τότε συμπαρῆν τηνικαῦτα πρὸς Μουκιανὸν εἰς Συρίαν ἀπεσταλμένος. τραπῆναι μὲν οὖν οὔτε ἀσφαλὲς οὔτε πρέπον ἡγήσατο, μνησθεὶς δὲ τῶν ἀπὸ νεότητος αὐτῷ πεπονημένων καὶ τῆς ἰδίας ἀρετῆς, ὥσπερ ἔνθους γενόμενος, συνασπίζει μὲν τοὺς ἅμ’ αὐτῷ τά τε σώματα καὶ τὰς πανοπλίας, ὑφίσταται δὲ κατὰ κορυφὴν ἐπιρρέοντα τὸν πόλεμον καὶ οὔτε ἀνδρῶν πλῆθος οὔτε βελῶν ὑποπτήξας ἐπέμενε, μέχρι δαιμόνιον τὸ παράστημα τῆς ψυχῆς συννοήσαντες οἱ πολέμιοι ταῖς ὁρμαῖς ἐνέδοσαν. ἀτονώτερον δὲ προσκειμένων αὐτὸς ὑπὸ πόδα ἀνεχώρει νῶτα μὴ δεικνὺς ἕως ἔξω τοῦ τείχους ἐγένετο. πλεῖστοι μὲν οὖν Ῥωμαίων κατὰ ταύτην ἔπεσον τὴν μάχην, ἐν οἷς ὁ δεκαδάρχης Αἰβούτιος, ἀνὴρ οὐ μόνον ἐφ’ ἧς ἔπεσε παρατάξεως, ἀλλὰ πανταχοῦ καὶ πρότερον γενναιότατος φανεὶς καὶ πλεῖστα κακὰ Ἰουδαίους ἐργασάμενος. ἑκατοντάρχης δέ τις, Γάλλος ὀνόματι, μετὰ στρατιωτῶν δέκα περισχεθεὶς ἐν τῇ ταραχῇ κατέδυ μὲν εἴς τινος οἰκίαν, τῶν δ’ ἐν αὐτῇ διαλαλούντων παρὰ δεῖπνον ὅσα κατὰ τῶν Ῥωμαίων ἢ περὶ σφῶν ὁ δῆμος ἐβουλεύετο κατακροασάμενος, ἦν δὲ αὐτός τε καὶ οἱ σὺν αὐτῷ Σύροι, νύκτωρ ἐπανίσταται καὶ πάντας ἀποσφάξας μετὰ τῶν στρατιωτῶν εἰς τοὺς Ῥωμαίους διασώζεται.", "st": "4.1.5"}, {"sp": "N", "t": "Οὐεσπασιανὸς δ’ ἀθυμοῦσαν τὴν στρατιὰν ἀνοίᾳ πταισμάτων καὶ διότι τέως οὐδαμοῦ τηλικαύτῃ συμφορᾷ κέχρηντο, τό γε μὴν πλέον αἰδουμένους ἐπὶ τῷ τὸν στρατηγὸν μόνον τοῖς κινδύνοις ἐγκαταλιπεῖν παρεμυθεῖτο, περὶ μὲν τοῦ καθ’ αὑτὸν ὑποστελλόμενος, ὡς μηδὲ τὴν ἀρχὴν μέμφεσθαι δοκοίη, δεῖν δὲ τὰ κοινὰ λέγων ἀνδρείως φέρειν τὴν τοῦ πολέμου φύσιν ἐννοοῦντας, ὡς οὐδαμοῦ τὸ νικᾶν ἀναιμωτὶ περιγίνεται, δαπανᾷ δ’ ἡ τύχη τι καὶ παρίσταται. τοσαύτας μέντοι μυριάδας Ἰουδαίων ἀνελόντας αὐτοὺς ὀλίγην τῷ δαίμονι δεδωκέναι συμβολήν. εἶναι δ’ ὥσπερ ἀπειροκάλων τὸ λίαν ἐπαίρεσθαι ταῖς εὐπραγίαις, οὕτως ἀνάνδρων τὸ καταπτήσσειν ἐν τοῖς πταίσμασιν· ὀξεῖα γὰρ ἐν ἀμφοτέροις ἡ μεταβολή, κἀκεῖνος ἄριστος ὁ κἀν τοῖς εὐτυχήμασιν νήφων, ἵνα μένῃ καὶ δι’ εὐθυμίας ἀναπαλαίων τὰ σφάλματα. τὰ μέντοι συμβεβηκότα νῦν οὔτε μαλακισθέντων ὑμῶν οὔτε παρὰ τὴν τῶν Ἰουδαίων ἀρετὴν γέγονεν, ἀλλὰ κἀκείνοις τοῦ πλεονεκτῆσαι καὶ τοῦ διαμαρτεῖν ἡμῖν αἴτιον ἡ δυσχωρία. καθ’ ἣν ἄν τις ὑμῶν μέμψαιτο τῆς ὁρμῆς τὸ ἀταμίευτον· ἀναφυγόντων γὰρ ἐπὶ τὰ ὑψηλὰ τῶν πολεμίων αὑτοὺς ὑποστέλλειν ἐχρῆν, καὶ μὴ κατὰ κορυφὴν ἱσταμένοις τοῖς κινδύνοις ἕπεσθαι, κρατοῦντας δὲ τῆς κάτω πόλεως κατ’ ὀλίγον προκαλεῖσθαι τοὺς ἀναφεύγοντας εἰς ἀσφαλῆ καὶ ἑδραίαν μάχην. νυνὶ δὲ ἀκρατῶς ἐπὶ τὴν νίκην ἐπειγόμενοι τῆς ἀσφαλείας ἠμελήσατε. τὸ δ’ ἀπερίσκεπτον ἐν πολέμῳ καὶ τῆς ὁρμῆς μανιῶδες οὐ πρὸς Ῥωμαίων, οἳ πάντα ἐμπειρίᾳ καὶ τάξει κατορθοῦμεν, ἀλλὰ βαρβαρικόν, καὶ ᾧ μάλιστα Ἰουδαῖοι κρατοῦνται. χρὴ τοίνυν ἐπὶ τὴν αὑτῶν ἀρετὴν ἀναδραμεῖν καὶ θυμοῦσθαι μᾶλλον ἢ προσαθυμεῖν τῷ παρ’ ἀξίαν πταίσματι. τὴν δ’ ἀρίστην ἕκαστος ἐκ τῆς ἰδίας χειρὸς ἐπιζητείτω παραμυθίαν· οὕτω γὰρ τοῖς τε ἀπολωλόσι τιμωρήσεσθε καὶ τοὺς ἀνελόντας ἀμυνεῖσθε. πειράσομαι δ’ ἐγώ, καθάπερ νῦν, ἐπὶ πάσης μάχης προάγειν τε ὑμῶν εἰς τοὺς πολεμίους καὶ τελευταῖος ἀποχωρεῖν.", "st": "4.1.6"}, {"sp": "N", "t": "Ὁ μὲν οὖν τοιαῦτα λέγων τὴν στρατιὰν ἀνελάμβανεν, τοῖς δὲ Γαμαλεῦσιν πρὸς ὀλίγον μὲν θαρρῆσαι τῷ κατορθώματι παρέστη παραλόγως τε συμβάντι καὶ μεγάλως, λογιζόμενοι δ’ ὕστερον ἀφῃρῆσθαι σφᾶς αὐτοὺς καὶ δεξιᾶς ἐλπίδας τό τε μὴ δύνασθαι διαφεύγειν ἐννοοῦντες, ἤδη γὰρ ἐπέλιπε τὰ ἐπιτήδεια, δεινῶς ἠθύμουν καὶ ταῖς ψυχαῖς ἀναπεπτώκεσαν. οὐ μὴν εἰς τὸ δυνατὸν ἠμέλουν σωτηρίας, ἀλλὰ καὶ τὰ παραρρηχθέντα τοῦ τείχους οἱ γενναιότατοι καὶ τὰ μένοντα περισχόντες ἐφύλασσον οἱ λοιποί. τῶν δὲ Ῥωμαίων ἐπιρρωννύντων τὰ χώματα καὶ πάλιν πειρωμένων προσβολῆς οἱ πολλοὶ διεδίδρασκον ἐκ τῆς πόλεως κατά τε δυσβάτων φαράγγων, ᾗπερ οὐκ ἔκειντο φυλακαί, καὶ διὰ τῶν ὑπονόμων. ὅσοι γε μὴν δέει τοῦ ληφθῆναι παρέμενον, [ἐν] ἐνδείᾳ διεφθείροντο· πανταχόθεν γὰρ τροφὴ τοῖς μάχεσθαι δυναμένοις συνηθροίζετο.", "st": "4.1.7"}, {"sp": "N", "t": "Καὶ οἱ μὲν ἐν τοιούτοις πάθεσι διεκαρτέρουν, Οὐεσπασιανὸς δὲ πάρεργον ἐποιεῖτο τῆς πολιορκίας τοὺς τὸ Ἰταβύριον κατειληφότας ὄρος, ὅ ἐστι τοῦ μεγάλου πεδίου καὶ Σκυθοπόλεως μέσον· οὗ τὸ μὲν ὕψος ἐπὶ τριάκοντα σταδίους ἀνίσχει, μόλις προσβατὸν κατὰ τὸ προσάρκτιον κλίμα, πεδίον δ’ ἐστὶν ἡ κορυφὴ σταδίων ἓξ καὶ εἴκοσι, πᾶν τετειχισμένον. ἤγειρε δὲ τοσοῦτον ὄντα τὸν περίβολον ὁ Ἰώσηπος ἐν τεσσαράκοντα ἡμέραις τῇ τε ἄλλῃ χορηγούμενος ὕλῃ κάτωθεν καὶ ὕδατι· καὶ γὰρ τοῖς ἐποίκοις μόνον ἦν ὄμβριον. πολλοῦ οὖν πλήθους ἐπὶ τοῦτο συνειλεγμένου Οὐεσπασιανὸς Πλάκιδον σὺν ἱππεῦσιν ἑξακοσίοις πέμπει. τούτῳ τὸ μὲν προσβαίνειν ἀμήχανον ἦν, ἐλπίδι δὲ δεξιῶν καὶ παρακλήσεως πρὸς εἰρήνην τοὺς πολλοὺς προεκαλεῖτο. κατῄεσαν δὲ ἀντεπιβουλεύοντες· ὅ τε γὰρ Πλάκιδος ὡμίλει πρᾳότερον σπουδάζων αὐτοὺς ἐν τῷ πεδίῳ λαβεῖν, κἀκεῖνοι κατῄεσαν ὡς πειθόμενοι δῆθεν, ἵνα ἀφυλάκτῳ προσπέσωσιν. ἐνίκα μέντοι τὸ Πλακίδου πανοῦργον· ἀρξαμένων γὰρ τῶν Ἰουδαίων μάχης φυγὴν ὑπεκρίνετο καὶ διώκοντας ἑλκύσας ἐπὶ πολὺ τοῦ πεδίου τοὺς ἱππεῖς ἐπιστρέφει, τρεψάμενος δὲ πλείστους μὲν αὐτῶν ἀναιρεῖ, τὸ δὲ λοιπὸν πλῆθος ὑποτεμόμενος εἴργει τῆς ἀνόδου. καὶ οἱ μὲν τὸ Ἰταβύριον καταλιπόντες ἐπὶ Ἱεροσολύμων ἔφευγον, οἱ δὲ ἐπιχώριοι πίστεις λαβόντες, ἐπιλελοίπει δ’ αὐτοὺς ὕδωρ, τό τε ὄρος καὶ σφᾶς αὐτοὺς Πλακίδῳ παρέδοσαν.", "st": "4.1.8"}, {"sp": "N", "t": "Τῶν δ’ ἐπὶ τῆς Γαμάλας οἱ παραβολώτεροι μὲν φεύγοντες διελάνθανον, οἱ δ’ ἀσθενεῖς διεφθείροντο λιμῷ· τὸ μάχιμον δ’ ἀντεῖχεν τῇ πολιορκίᾳ, μέχρι δευτέρᾳ καὶ εἰκάδι μηνὸς Ὑπερβερεταίου τρεῖς τῶν ἀπὸ τοῦ πέμπτου καὶ δεκάτου τάγματος στρατιῶται περὶ τὴν ἑωθινὴν φυλακὴν ὑποδύντες τὸν προύχοντα κατὰ τούτους πύργον ὑπορύσσουσιν ἡσυχῆ. τοῖς δ’ ὑπὲρ αὐτοῦ φύλαξιν οὔτε προσιόντων αἴσθησις, νὺξ γὰρ ἦν, οὔτε προσελθόντων ἐγένετο. οἱ δὲ στρατιῶται φειδόμενοι τοῦ ψόφου καὶ πέντε τοὺς κραταιοτάτους ἐκκυλίσαντες λίθους ὑποπηδῶσι. κατηρείπετο δὲ ὁ πύργος ἐξαίφνης μετὰ μεγίστου ψόφου, καὶ συγκατακρημνίζονται μὲν οἱ φύλακες αὐτῷ, θορυβηθέντες δὲ οἱ κατὰ τὰς ἄλλας φυλακὰς ἔφευγον· καὶ πολλοὺς διεκπαίειν τολμῶντας οἱ Ῥωμαῖοι διέφθειραν, ἐν οἷς καὶ Ἰώσηπόν τις ὑπὲρ τὸ παρερρηγμένον τοῦ τείχους ἐκδιδράσκοντα βαλὼν ἀναιρεῖ. τῶν δ’ ἀνὰ τὴν πόλιν διασεισθέντων ὑπὸ τοῦ ψόφου διαδρομή τε ἦν καὶ πτόα πολλὴ καθάπερ εἰσπεπαικότων πάντων τῶν πολεμίων. ἔνθα καὶ Χάρης κατακείμενος καὶ νοσηλευόμενος ἐκλείπει πολλοῦ δέους συνεργήσαντος εἰς θάνατον τῇ νόσῳ. Ῥωμαῖοί γε μὴν μεμνημένοι τοῦ προτέρου πταίσματος οὐκ εἰσέβαλλον ἕως τρίτῃ καὶ εἰκάδι τοῦ προειρημένου μηνός.", "st": "4.1.9"}, {"sp": "N", "t": "Τίτος δέ, ἤδη γὰρ παρῆν, ὀργῇ τῆς πληγῆς ἣν παρ’ αὐτὸν ἐπλήγησαν ἀπόντα Ῥωμαῖοι, τῶν ἱππέων ἐπιλέξας διακοσίους, πρὸς οἷς πεζοὺς, εἰσέρχεται τὴν πόλιν ἡσυχῆ. καὶ παρελθόντος οἱ μὲν φύλακες αἰσθόμενοι μετὰ βοῆς ἐχώρουν ἐπὶ τὰ ὅπλα, δήλης δὲ τῆς εἰσβολῆς ταχέως καὶ τοῖς εἴσω γενομένης, οἱ μὲν ἁρπάζοντες τὰ τέκνα καὶ γυναῖκας ἐπισυρόμενοι πρὸς τὴν ἄκραν ἀνέφευγον μετὰ κωκυτοῦ καὶ βοῆς, οἱ δὲ τὸν Τίτον ὑπαντιάζοντες ἀδιαλείπτως ἔπιπτον· ὅσοι δὲ ἀπεκωλύθησαν ἐπὶ τὴν κορυφὴν ἀναδραμεῖν ὑπ’ ἀμηχανίας εἰς τὰς τῶν Ῥωμαίων φρουρὰς ἐξέπιπτον. ἄπειρος δ’ ἦν πανταχοῦ φονευομένων ὁ στόνος, καὶ τὸ αἷμα πᾶσαν ἐπέκλυζε τὴν πόλιν κατὰ πρανοῦς χεόμενον. πρὸς δὲ τοὺς ἀναφεύγοντας εἰς τὴν ἄκραν ἐπεβοήθει Οὐεσπασιανὸς πᾶσαν εἰσαγαγὼν τὴν δύναμιν. ἦν δ’ ἥ τε κορυφὴ πάντοθεν πετρώδης καὶ δύσβατος, εἰς ἄπειρον ὕψος ἐπηρμένη, καὶ πανταχόθεν † τοῦ βάθους κατέγεμεν περιειλημμένη κρημνοῖς κατέτεμνόν τε. ἐνταῦθα τοὺς προσβαίνοντας οἱ Ἰουδαῖοι τοῖς τε ἄλλοις βέλεσι καὶ πέτρας κατακυλινδοῦντες ἐκάκουν· αὐτοὶ δὲ δι’ ὕψος ἦσαν δυσέφικτοι βέλει. γίνεται δὲ πρὸς ἀπώλειαν αὐτῶν ἄντικρυς θύελλα δαιμόνιος, ἣ τὰ μὲν Ῥωμαίων ἔφερεν εἰς αὐτοὺς βέλη, τὰ δὲ αὐτῶν ἀνέστρεφεν καὶ πλάγια παρέσυρεν. οὔτε δὲ τοῖς ὑποκρήμνοις ἐφίστασθαι διὰ τὴν βίαν ἐδύναντο τοῦ πνεύματος μηδὲν ἑδραῖον ἔχοντες, οὔτε τοὺς προσβαίνοντας καθορᾶν. ἐπαναβαίνουσι δὲ Ῥωμαῖοι, καὶ περισχόντες οὓς μὲν ἀμυνομένους ἔφθανον, οὓς δὲ χεῖρας προΐσχοντας· ἐτόνου δὲ τὸν θυμὸν αὐτοῖς ἐπὶ πάντας ἡ μνήμη τῶν ἐπὶ τῆς πρώτης εἰσβολῆς ἀπολωλότων. ἀπογινώσκοντες δὲ τὴν σωτηρίαν πανταχόθεν οἱ πολλοὶ περισχόμενοι τέκνα καὶ γυναῖκας αὑτούς τε κατεκρήμνιζον εἰς τὴν φάραγγα· βαθυτάτη δ’ αὕτη κατὰ τὴν ἄκραν ὑπορώρυκτο. συνέβη δὲ τὴν Ῥωμαίων ὀργὴν τῆς εἰς ἑαυτοὺς ἀπονοίας τῶν ἁλόντων πρᾳοτέραν φανῆναι· τετρακισχίλιοι μέν γε ὑπὸ τούτων ἐσφάγησαν, οἱ δὲ ῥίψαντες ἑαυτοὺς ὑπὲρ πεντακισχιλίους εὑρέθησαν. διεσώθη δὲ πλὴν δύο γυναικῶν οὐδείς· τῆς Φιλίππου δὲ ἦσαν ἀδελφῆς θυγατέρες αὗται, αὐτὸς δὲ ὁ Φίλιππος Ἰακίμου τινὸς ἀνδρὸς ἐπισήμου, τετραρχήσαντος Ἀγρίππᾳ τῷ βασιλεῖ. διεσώθησαν δὲ τὰς παρὰ τὴν ἅλωσιν ὀργὰς Ῥωμαίων λαθοῦσαι· τότε γὰρ οὐδὲ νηπίων ἐφείδοντο, πολλὰ δ’ ἑκάστοτε ἁρπάζοντες ἐσφενδόνων ἀπὸ τῆς ἄκρας. Γάμαλα μὲν οὕτως ἑάλω τρίτῃ καὶ εἰκάδι μηνὸς Ὑπερβερεταίου τῆς ἀποστάσεως ἀρξαμένης Γορπιαίου μηνὸς τετάρτῃ καὶ εἰκάδι.", "st": "4.1.10"}, {"sp": "N", "t": "Μόνη δὲ Γίσχαλα πολίχνη τῆς Γαλιλαίας ἀχείρωτος κατελείπετο, τοῦ μὲν πλήθους εἰρηνικὰ φρονοῦντος, καὶ γὰρ ἦσαν τὸ πλέον γεωργοὶ καὶ ταῖς ἀπὸ τῶν καρπῶν ἐλπίσιν ἀεὶ προσανέχοντες, παρεισεφθαρμένου δ’ αὐτοῖς οὐκ ὀλίγου λῃστρικοῦ τάγματος, ᾧ τινες καὶ τοῦ πολιτικοῦ συνενόσουν. ἐνῆγε δὲ τούτους εἰς τὴν ἀπόστασιν καὶ συνεκρότει Ληΐου τινὸς υἱὸς Ἰωάννης, γόης ἀνὴρ καὶ ποικιλώτατος τὸ ἦθος, πρόχειρος μὲν ἐλπίσαι μεγάλα, δεινὸς δὲ τῶν ἐλπισθέντων περιγενέσθαι παντί τε ὢν δῆλος ἀγαπᾶν τὸν πόλεμον εἰς δυναστείας ἐπίθεσιν. ὑπὸ τούτῳ τὸ στασιῶδες ἐν τοῖς Γισχάλοις ἐτέτακτο, δι’ οὓς τυχὸν καὶ πρεσβευσάμενον περὶ παραδόσεως τὸ δημοτικὸν ἐν πολέμου μοίρᾳ τὴν Ῥωμαίων ἔφοδον ἐξεδέχετο. Οὐεσπασιανὸς δὲ ἐπὶ μὲν τούτους Τίτον ἐκπέμπει σὺν χιλίοις ἱππεῦσιν, τὸ δέκατον δὲ τάγμα ἀπαίρει εἰς Σκυθόπολιν. αὐτὸς δὲ σὺν δυσὶ τοῖς λοιποῖς ἐπανῆλθεν εἰς Καισάρειαν, τοῦ τε συνεχοῦς καμάτου διδοὺς ἀνάπαυσιν αὐτοῖς καὶ δι’ εὐθηνίαν τῶν πόλεων τά τε σώματα καὶ τὸ πρόθυμον ὑποθρέψειν οἰόμενος ἐπὶ τοὺς μέλλοντας ἀγῶνας· οὐ γὰρ ὀλίγον αὐτῷ πόνον ἑώρα περὶ τοῖς Ἱεροσολύμοις λειπόμενον, ἅτε δὴ βασιλείου μὲν οὔσης τῆς πόλεως καὶ προανεχούσης ὅλου τοῦ ἔθνους, συρρεόντων δὲ εἰς αὐτὴν τῶν ἐκ τοῦ πολέμου διαδιδρασκόντων. τό γε μὴν φύσει τε ὀχυρὸν αὐτῆς καὶ διὰ κατασκευὴν τειχῶν ἀγωνίαν οὐ τὴν τυχοῦσαν ἐνεποίει· τὰ δὲ φρονήματα τῶν ἀνδρῶν καὶ τὰς τόλμας δυσμεταχειρίστους καὶ δίχα τειχῶν ὑπελάμβανεν. διὸ δὴ τοὺς στρατιώτας καθάπερ ἀθλητὰς προήσκει τῶν ἀγώνων.", "st": "4.2.1"}, {"sp": "N", "t": "Τίτῳ δὲ προσιππασαμένῳ τοῖς Γισχάλοις εὐπετὲς μὲν ἦν ἐξ ἐφόδου τὴν πόλιν ἑλεῖν, εἰδὼς δέ, εἰ βίᾳ ληφθείη, διαφθαρησόμενον ὑπὸ τῶν στρατιωτῶν ἀνέδην τὸ πλῆθος, ἦν δ’ αὐτῷ κόρος ἤδη φόνων καὶ δι’ οἴκτου τὸ πλέον ἀκρίτως συναπολλύμενον τοῖς αἰτίοις, ἐβούλετο μᾶλλον ὁμολογίαις παραστήσασθαι τὴν πόλιν. καὶ δὴ τοῦ τείχους ἀνδρῶν καταγέμοντος, οἳ τὸ πλέον ἦσαν ἐκ τοῦ διεφθαρμένου τάγματος, θαυμάζειν ἔφη πρὸς αὐτούς, τίνι πεποιθότες πάσης ἑαλωκυίας πόλεως μόνοι τὰ Ῥωμαίων ὅπλα μένουσιν, ἑωρακότες μὲν ὀχυρωτέρας πολλῷ πόλεις ὑπὸ μίαν προσβολὴν κατεστραμμένας, ἐν ἀσφαλείᾳ δὲ τῶν ἰδίων κτημάτων ἀπολαύοντας ὅσοι ταῖς Ῥωμαίων δεξιαῖς ἐπίστευσαν, ἃς καὶ νῦν προτείνειν αὐτοῖς μηδὲν μνησικακῶν τῆς αὐθαδείας. εἶναι γὰρ συγγνωστὸν ἐλευθερίας ἐλπίδα, μηκέτι μέντοι τὴν ἐν τοῖς ἀδυνάτοις ἐπιμονήν· εἰ γὰρ οὐ πεισθήσονται λόγοις φιλανθρώποις καὶ δεξιαῖς πίστεως, πειράσειν αὐτοὺς ἀφειδῆ τὰ ὅπλα, καὶ ὅσον οὐδέπω † γνωσθήσεσθαι πιεζόμενον τοῖς Ῥωμαίων μηχανήμασιν τὸ τεῖχος, ᾧ πεποιθότες ἐπιδείκνυνται μόνοι Γαλιλαίων, ὅτι εἰσὶν αὐθάδεις αἰχμάλωτοι.", "st": "4.2.2"}, {"sp": "N", "t": "Πρὸς ταῦτα τῶν μὲν δημοτικῶν οὐ μόνον οὐκ ἀποκρίνεσθαί τινι μετῆν, ἀλλ’ οὐδ’ ἐπὶ τὸ τεῖχος ἀναβῆναι· προδιείληπτο γὰρ ἅπαν τοῖς λῃστρικοῖς, καὶ φύλακες τῶν πυλῶν ἦσαν, ὡς μή τινες ἢ προέλθοιεν ἐπὶ τὰς σπονδὰς ἢ δέξαιντό τινας τῶν ἱππέων εἰς τὴν πόλιν· ὁ δ’ Ἰωάννης αὐτός τε ἀγαπᾶν ἔφη τὰς προκλήσεις καὶ τοὺς ἀπειθοῦντας ἢ πείσειν ἢ συναναγκάσειν· δεῖν μέντοι τὴν ἡμέραν αὐτὸν ἐκείνην, ἑβδομὰς γὰρ ἦν, χαρίσασθαι τῷ Ἰουδαίων νόμῳ, καθ’ ἣν ὥσπερ ὅπλα κινεῖν αὐτοῖς, οὕτω καὶ τὸ συντίθεσθαι περὶ εἰρήνης ἀθέμιτον. οὐκ ἀγνοεῖν δὲ οὐδὲ Ῥωμαίους, ὡς ἀργὴ πάντων αὐτοῖς ἐστιν ἡ τῆς ἑβδομάδος περίοδος, ἔν τε τῷ παραβαίνειν αὐτὴν οὐχ ἧττον ἀσεβεῖν τῶν βιασθέντων τὸν βιασάμενον. φέρειν δ’ ἐκείνῳ μὲν οὐδεμίαν βλάβην τὰ τῆς ὑπερθέσεως· τί γὰρ ἄν τις ἐν νυκτὶ βουλεύσαιτο δρασμοῦ πλέον ἐξὸν περιστρατοπεδεύσαντα παραφυλάξαι; μέγα δὲ κέρδος αὐτοῖς τὸ μηδὲν παραβῆναι τῶν πατρίων ἐθῶν. πρέπει δὲ τῷ παρὰ προσδοκίαν εἰρήνην χαριζομένῳ τοῖς σωζομένοις τηρεῖν καὶ τοὺς νόμους. τοιούτοις ἐσοφίζετο τὸν Τίτον, οὐ τοσοῦτον τῆς ἑβδομάδος στοχαζόμενος, ὅσον τῆς αὑτοῦ σωτηρίας· ἐδεδοίκει δὲ ἐγκαταληφθῆναι παραχρῆμα τῆς πόλεως ἁλούσης ἐν νυκτὶ καὶ φυγῇ τὰς ἐλπίδας ἔχων τοῦ βίου. θεοῦ δ’ ἦν ἔργον ἄρα τοῦ σώζοντος τὸν Ἰωάννην ἐπὶ τὸν τῶν Ἱεροσολύμων ὄλεθρον τὸ μὴ μόνον πεισθῆναι Τίτον τῇ σκήψει τῆς ὑπερθέσεως, ἀλλὰ καὶ τῆς πόλεως πορρωτέρω στρατοπεδεύσασθαι πρὸς Κυδασοῖς· μεσόγειος δέ ἐστι Τυρίων κώμη καρτερά, διὰ μίσους ἀεὶ καὶ πολέμου Γαλιλαίοις, ἔχουσα πλῆθός τε οἰκητόρων καὶ τὴν ὀχυρότητα τῆς πρὸς τὸ ἔθνος διαφορᾶς ἐφόδια.", "st": "4.2.3"}, {"sp": "N", "t": "Νυκτὸς δ’ ὁ Ἰωάννης ὡς οὐδεμίαν περὶ τῇ πόλει Ῥωμαίων ἑώρα φυλακήν, τὸν καιρὸν ἁρπασάμενος οὐ μόνον τοὺς περὶ αὐτὸν ὁπλίτας ἀλλὰ καὶ τῶν ἀργοτέρων συχνοὺς ἅμα ταῖς γενεαῖς ἀναλαβὼν ἐπὶ Ἱεροσολύμων ἔφευγε. μέχρι μὲν οὖν εἴκοσι σταδίων οἷόν τε ἦν συνεξαγαγεῖν γυναικῶν καὶ παιδίων ὄχλον ἀνθρώπῳ κατασπερχομένῳ τοῖς ὑπὲρ αἰχμαλωσίας καὶ τοῦ ζῆν φόβοις, περαιτέρω δὲ προκόπτοντος ἀπελείποντο, καὶ δειναὶ τῶν ἐωμένων ἦσαν ὀλοφύρσεις· ὅσον γὰρ ἕκαστος τῶν οἰκείων ἐγίνετο πορρωτέρω, τοσοῦτον ἐγγὺς ὑπελάμβανεν εἶναι τῶν πολεμίων, παρεῖναί τε ἤδη τοὺς αἰχμαλωτισομένους δοκοῦντες ἐπτόηντο, καὶ πρὸς τὸν ἀλλήλων ἐκ τοῦ δρόμου ψόφον ἐπεστρέφοντο καθάπερ ἤδη παρόντων οὓς ἔφευγον· ἀνοδίαις τ’ ἐνέπιπτον οἱ πολλοί, καὶ περὶ τὴν λεωφόρον ἡ τῶν φθανόντων ἔρις συνέτριβεν τοὺς πολλούς. οἰκτρὸς δὲ γυναικῶν καὶ παιδίων ὄλεθρος ἦν, καί τινες πρὸς ἀνακλήσεις ἀνδρῶν τε καὶ συγγενῶν ἐθάρσησαν μετὰ κωκυτῶν ἱκετεύουσαι περιμένειν. ἀλλ’ ἐνίκα τὸ Ἰωάννου παρακέλευσμα σώζειν ἑαυτοὺς ἐμβοῶντος καὶ καταφεύγειν ἔνθα καὶ περὶ τῶν ἀπολειπομένων ἀμυνοῦνται Ῥωμαίους ἂν ἁρπαγῶσι. τὸ μὲν οὖν τῶν διαδιδρασκόντων πλῆθος ὡς ἕκαστος ἰσχύος εἶχεν ἢ τάχους ἐσκέδαστο.", "st": "4.2.4"}, {"sp": "N", "t": "Τίτος δὲ μεθ’ ἡμέραν ἐπὶ τὰς συνθήκας πρὸς τὸ τεῖχος παρῆν. ἀνοίγει δ’ αὐτῷ τὰς πύλας ὁ δῆμος, καὶ μετὰ τῶν γενεῶν προελθόντες ἀνευφήμουν ὡς εὐεργέτην καὶ φρουρᾶς ἐλευθερώσαντα τὴν πόλιν· ἐδήλουν γὰρ ἅμα τὴν τοῦ Ἰωάννου φυγὴν καὶ παρεκάλουν φείσασθαί τε αὐτῶν καὶ παρελθόντα τοὺς ὑπολειπομένους τῶν νεωτεριζόντων κολάσαι. ὁ δὲ τὰς τοῦ δήμου δεήσεις ἐν δευτέρῳ θέμενος μοῖραν ἔπεμπε τῶν ἱππέων Ἰωάννην διώξουσαν, οἳ τὸν μὲν οὐ καταλαμβάνουσιν, ἔφθη γὰρ εἰς Ἱεροσόλυμα διαφυγών, τῶν δὲ συναπαράντων ἀποκτείνουσι μὲν εἰς ἑξακισχιλίους, γύναια δὲ καὶ παιδία τρισχιλίων ὀλίγον ἀποδέοντα περιελάσαντες ἀνήγαγον. ὁ δὲ Τίτος ἤχθετο μὲν ἐπὶ τῷ μὴ παραχρῆμα τιμωρήσασθαι τὸν Ἰωάννην τῆς ἀπάτης, ἱκανὸν δὲ ἀστοχήσαντι τῷ θυμῷ παραμύθιον ἔχων τὸ πλῆθος τῶν αἰχμαλώτων καὶ τοὺς διεφθαρμένους εἰσῄει τε ἀνευφημούμενος εἰς τὴν πόλιν, καὶ τοῖς στρατιώταις ὀλίγον τοῦ τείχους παρασπάσαι κελεύσας νόμῳ καταλήψεως ἀπειλαῖς μᾶλλον ἢ κολάσει τοὺς ταράσσοντας τὴν πόλιν ἀνέστελλε· πολλοὺς γὰρ ἂν καὶ διὰ τὰ οἰκεῖα μίση καὶ διαφορὰς ἰδίας ἐνδείξασθαι τοὺς ἀναιτίους, εἰ διακρίνοι τοὺς τιμωρίας ἀξίους· ἄμεινον δ’ εἶναι μετέωρον ἐν φόβῳ τὸν αἴτιον καταλιπεῖν ἤ τινα τῶν οὐκ ἀξίων αὐτῷ συναπολεῖν· τὸν μὲν γὰρ ἴσως καὶ σωφρονῆσαι δέει κολάσεως τὴν ἐπὶ τοῖς παρῳχηκόσι συγγνώμην αἰδούμενον, ἀδιόρθωτον δὲ τὴν ἐπὶ τοῖς παραναλωθεῖσι τιμωρίαν εἶναι. φρουρᾷ μέντοι τὴν πόλιν ἠσφαλίσατο, δι’ ἧς τούς τε νεωτερίζοντας ἐφέξειν καὶ τοὺς εἰρηνικὰ φρονοῦντας θαρραλεωτέρους καταλείψειν ἔμελλεν. Γαλιλαία μὲν οὖν οὕτως ἑάλω πᾶσα, πολλοῖς ἱδρῶσι προγυμνάσασα Ῥωμαίους ἐπὶ τὰ Ἱεροσόλυμα.", "st": "4.2.5"}, {"sp": "N", "t": "Πρὸς δὲ τὴν εἴσοδον τοῦ Ἰωάννου ὁ πᾶς δῆμος ἐξεκέχυτο, καὶ περὶ ἕκαστον τῶν συμπεφευγότων μυρίος ὅμιλος συνηθροισμένοι τὰς ἔξωθεν συμφορὰς ἀνεπυνθάνοντο. τῶν δὲ τὸ μὲν ἆσθμα θερμὸν ἔτι κοπτόμενον ἐδήλου τὴν ἀνάγκην, ἠλαζονεύοντο δὲ κἀν κακοῖς, οὐ πεφευγέναι Ῥωμαίους φάσκοντες, ἀλλ’ ἥκειν πολεμήσοντες αὐτοὺς ἐξ ἀσφαλοῦς· ἀλογίστων γὰρ εἶναι καὶ ἀχρήστων παραβόλως προκινδυνεύειν περὶ Γίσχαλα καὶ πολίχνας ἀσθενεῖς, δέον τὰ ὅπλα καὶ τὰς ἀκμὰς ταμιεύεσθαι τῇ μητροπόλει καὶ συμφυλάσσειν. ἔνθα δὴ παρεδήλουν τὴν ἅλωσιν τῶν Γισχάλων, καὶ τὴν λεγομένην εὐσχημόνως ὑποχώρησιν αὐτῶν οἱ πολλοὶ δρασμὸν ἐνενόουν. ὡς μέντοι τὰ περὶ τοὺς αἰχμαλωτισθέντας ἠκούσθη, σύγχυσις οὐ μετρία κατέσχε τὸν δῆμον, καὶ μεγάλα τῆς ἑαυτῶν ἁλώσεως συνελογίζοντο τὰ τεκμήρια. Ἰωάννης δ’ ἐπὶ μὲν τοῖς καταληφθεῖσιν ἧττον ἠρυθρία, περιιὼν δ’ ἑκάστους ἐπὶ τὸν πόλεμον ἐνῆγεν ταῖς ἐλπίσιν, τὰ μὲν Ῥωμαίων ἀσθενῆ κατασκευάζων, τὴν δ’ οἰκείαν δύναμιν ἐξαίρων, καὶ κατειρωνευόμενος τῆς τῶν ἀπείρων ἀγνοίας, ὡς οὐδ’ ἂν πτερὰ λαβόντες ὑπερβαῖέν ποτε Ῥωμαῖοι τὸ Ἱεροσολύμων τεῖχος οἱ περὶ ταῖς Γαλιλαίων κώμαις κακοπαθοῦντες καὶ πρὸς τοῖς ἐκεῖ τείχεσι κατατρίψαντες τὰς μηχανάς.", "st": "4.3.1"}, {"sp": "N", "t": "Τούτοις τὸ πολὺ τῶν νέων προσδιεφθείρετο καὶ πρὸς [μὲν] τὸν πόλεμον ἦρτο, τῶν δὲ σωφρονούντων καὶ γηραιῶν οὐκ ἦν ὅστις οὐ τὰ μέλλοντα προορώμενος ὡς ἤδη τῆς πόλεως οἰχομένης ἐπένθει. ὁ μὲν οὖν δῆμος ἦν ἐν τοιαύτῃ συγχύσει, προδιέστη δὲ τὸ κατὰ τὴν χώραν πλῆθος τῆς ἐν Ἱεροσολύμοις στάσεως. ὁ μὲν γὰρ Τίτος ἀπὸ Γισχάλων εἰς Καισάρειαν, Οὐεσπασιανὸς δὲ ἀπὸ Καισαρείας εἰς Ἰάμνειαν καὶ Ἄζωτον ἀφικόμενος παρίσταταί τε αὐτὰς καὶ φρουροὺς ἐγκαταστήσας ὑπέστρεψε πολὺ πλῆθος ἐπαγόμενος τῶν ἐπὶ δεξιᾷ προσκεχωρηκότων. ἐκινεῖτο δ’ ἐν ἑκάστῃ πόλει ταραχὴ καὶ πόλεμος ἐμφύλιος, ὅσον τε ἀπὸ Ῥωμαίων ἀνέπνεον εἰς ἀλλήλους τὰς χεῖρας ἐπέστρεφον. ἦν δὲ τῶν ἐρώντων τοῦ πολέμου πρὸς τοὺς ἐπιθυμοῦντας εἰρήνης ἔρις χαλεπή. καὶ πρῶτον μὲν ἐν οἰκίαις ἥπτετο τῶν ὁμονοούντων πάλαι τὸ φιλόνεικον, ἔπειτα ἀφηνιάζοντες ἀλλήλων οἱ φίλτατοι [λαοὶ] καὶ συνιὼν ἕκαστος πρὸς τοὺς τὰ αὐτὰ προαιρουμένους ἤδη κατὰ πλῆθος ἀντετάσσοντο. καὶ στάσις μὲν ἦν πανταχοῦ, τὸ νεωτερίζον δὲ καὶ τῶν ὅπλων ἐπιθυμοῦν ἐπεκράτει νεότητι καὶ τόλμῃ γηραιῶν καὶ σωφρόνων. ἐτράποντο δὲ πρῶτον μὲν εἰς ἁρπαγὰς ἕκαστοι τῶν ἐπιχωρίων, ἔπειτα συντασσόμενοι κατὰ λόχους ἐπὶ λῃστείαν τῶν κατὰ τὴν χώραν, ὡς ὠμότητος καὶ παρανομίας ἕνεκεν αὐτοῖς μηδὲν Ῥωμαίων τοὺς ὁμοφύλους διαφέρειν καὶ πολὺ τοῖς πορθουμένοις κουφοτέραν δοκεῖν τὴν ὑπὸ Ῥωμαίοις ἅλωσιν.", "st": "4.3.2"}, {"sp": "N", "t": "Οἱ φρουροὶ δὲ τῶν πόλεων τὰ μὲν ὄκνῳ τοῦ κακοπαθεῖν, τὰ δὲ μίσει τοῦ ἔθνους οὐδὲν ἢ μικρὰ προσήμυνον τοῖς κακουμένοις, μέχρι κόρῳ τῶν κατὰ τὴν χώραν ἁρπαγῶν ἀθροισθέντες οἱ τῶν πανταχοῦ συνταγμάτων ἀρχιλῃσταὶ καὶ γενόμενοι πονηρίας στῖφος εἰς τὰ Ἱεροσόλυμα παρεισφθείρονται, πόλιν ἀστρατήγητον καὶ πατρίῳ μὲν ἔθει πᾶν ἀπαρατηρήτως δεχομένην τὸ ὁμόφυλον, τότε δ’ οἰομένων ἁπάντων τοὺς ἐπιχεομένους πάντας ἀπ’ εὐνοίας ἥκειν συμμάχους. ὃ δὴ καὶ δίχα τῆς στάσεως ὕστερον ἐβάπτισεν τὴν πόλιν· πλήθει γὰρ ἀχρήστῳ καὶ ἀργῷ προεξαναλώθη τὰ τοῖς μαχίμοις διαρκεῖν δυνάμενα, καὶ πρὸς τῷ πολέμῳ στάσιν τε ἑαυτοῖς καὶ λιμὸν ἐπικατεσκεύασαν.", "st": "4.3.3"}, {"sp": "N", "t": "Ἄλλοι τε ἀπὸ τῆς χώρας λῃσταὶ παρελθόντες εἰς τὴν πόλιν καὶ τοὺς ἔνδον προσλαβόντες χαλεπωτέρους οὐδὲν ἔτι τῶν δεινῶν παρίεσαν· οἵ γε οὐ μόνον ἁρπαγαῖς καὶ λωποδυσίαις τὴν τόλμαν ἐμέτρουν, ἀλλὰ καὶ μέχρι φόνων ἐχώρουν, οὐ νυκτὸς ἢ λαθραίως ἢ ἐπὶ τοὺς τυχόντας, ἀλλὰ φανερῶς καὶ μεθ’ ἡμέραν καὶ τῶν ἐπισημοτάτων καταρχόμενοι. πρῶτον μὲν γὰρ Ἀντίπαν, ἄνδρα τοῦ βασιλικοῦ γένους καὶ τῶν κατὰ τὴν πόλιν δυνατωτάτων, ὡς καὶ τοὺς δημοσίους θησαυροὺς πεπιστεῦσθαι, συλλαβόντες εἷρξαν· ἐπὶ τούτῳ Ληουίαν τινὰ τῶν ἐπισήμων καὶ Συφὰν υἱὸν Ἀρεγέτου, βασιλικὸν δ’ ἦν καὶ τούτων τὸ γένος, πρὸς δὲ τοὺς κατὰ τὴν χώραν προύχειν δοκοῦντας. δεινὴ δὲ κατάπληξις εἶχε τὸν δῆμον, καὶ καθάπερ κατειλημμένης τῆς πόλεως πολέμῳ τὴν καθ’ αὑτὸν ἕκαστος σωτηρίαν ἠγάπα.", "st": "4.3.4"}, {"sp": "N", "t": "Τοῖς δ’ οὐκ ἀπέχρη τὰ δεσμὰ τῶν συνειλημμένων, οὐδὲ ἀσφαλὲς ᾤοντο τὸ μέχρι πολλοῦ δυνατοὺς ἄνδρας οὕτω φυλάσσειν· ἱκανοὺς μὲν γὰρ εἶναι καὶ τοὺς οἴκους αὐτῶν πρὸς ἄμυναν οὐκ ὀλιγάνδρους ὄντας, οὐ μὴν ἀλλὰ καὶ τὸν δῆμον ἐπαναστήσεσθαι τάχα κινηθέντα πρὸς τὴν παρανομίαν. δόξαν οὖν ἀναιρεῖν αὐτοὺς Ἰωάννην τινὰ πέμπουσιν τὸν ἐξ αὐτῶν εἰς φόνους προχειρότατον· Δορκάδος οὗτος ἐκαλεῖτο παῖς κατὰ τὴν ἐπιχώριον γλῶσσαν· ᾧ δέκα συνελθόντες εἰς τὴν εἱρκτὴν ξιφήρεις ἀποσφάττουσιν τοὺς συνειλημμένους. παρανομήματι δ’ ἐν τηλικούτῳ μεγάλως ἀπεψεύδοντο καὶ προφάσεις [ἀνέπλαττον]· διαλεχθῆναι γὰρ αὐτοὺς Ῥωμαίοις περὶ παραδόσεως τῶν Ἱεροσολύμων, καὶ προδότας ἀνῃρηκέναι τῆς κοινῆς ἐλευθερίας ἔφασκον, καθόλου τ’ ἐπηλαζονεύοντο τοῖς τολμήμασιν ὡς εὐεργέται καὶ σωτῆρες τῆς πόλεως γεγενημένοι.", "st": "4.3.5"}, {"sp": "N", "t": "Συνέβη δὲ εἰς τοσοῦτον τὸν μὲν δῆμον ταπεινότητος καὶ δέους, ἐκείνους δὲ ἀπονοίας προελθεῖν, ὡς ἐπ’ αὐτοῖς εἶναι καὶ τὰς χειροτονίας τῶν ἀρχιερέων. ἄκυρα γοῦν τὰ γένη ποιήσαντες, ἐξ ὧν κατὰ διαδοχὰς οἱ ἀρχιερεῖς ἀπεδείκνυντο, καθίστασαν ἀσήμους καὶ ἀγενεῖς, ἵν’ ἔχοιεν συνεργοὺς τῶν ἀσεβημάτων· τοῖς γὰρ παρ’ ἀξίαν ἐπιτυχοῦσι τῆς ἀνωτάτω τιμῆς ὑπακούειν ἦν ἀνάγκη τοῖς παρασχοῦσι. συνέκρουον δὲ καὶ τοὺς ἐν τέλει ποικίλαις ἐπινοίαις καὶ λογοποιίαις, καιρὸν ἑαυτοῖς ἐν ταῖς πρὸς ἀλλήλους τῶν κωλυόντων φιλονεικίαις ποιούμενοι, μέχρι τῶν εἰς ἀνθρώπους ὑπερεμπλησθέντες ἀδικημάτων ἐπὶ τὸ θεῖον μετήνεγκαν τὴν ὕβριν καὶ μεμιασμένοις τοῖς ποσὶ παρῄεσαν εἰς τὸ ἅγιον.", "st": "4.3.6"}, {"sp": "N", "t": "Ἐπανισταμένου τε αὐτοῖς ἤδη τοῦ πλήθους, ἐνῆγε γὰρ ὁ γεραίτατος τῶν ἀρχιερέων Ἄνανος, ἀνὴρ σωφρονέστατος καὶ τάχα ἂν διασώσας τὴν πόλιν, εἰ τὰς τῶν ἐπιβούλων χεῖρας ἐξέφυγεν, οἱ δὲ τὸν νεὼν τοῦ θεοῦ φρούριον αὑτοῖς καὶ τῶν ἀπὸ τοῦ δήμου ταραχῶν ποιοῦνται καταφυγήν, καὶ τυραννεῖον ἦν αὐτοῖς τὸ ἅγιον. παρεκίρνατο δὲ τοῖς δεινοῖς εἰρωνεία, τὸ τῶν ἐνεργουμένων ἀλγεινότερον· ἀποπειρώμενοι γὰρ τῆς τοῦ δήμου καταπλήξεως καὶ τὴν αὑτῶν δοκιμάζοντες ἰσχὺν κληρωτοὺς ἐπεχείρησαν ποιεῖν τοὺς ἀρχιερεῖς οὔσης, ὡς ἔφαμεν, κατὰ γένος αὐτῶν τῆς διαδοχῆς. ἦν δὲ πρόσχημα μὲν τῆς ἐπιβουλῆς ἔθος ἀρχαῖον, ἐπειδὴ καὶ πάλαι κληρωτὴν ἔφασαν εἶναι τὴν ἀρχιερωσύνην, τὸ δὲ ἀληθὲς τοῦ βεβαιοτέρου [νόμου] κατάλυσις καὶ τέχνη πρὸς δυναστείαν τὰς ἀρχὰς δι’ αὑτῶν καθισταμένοις.", "st": "4.3.7"}, {"sp": "N", "t": "Καὶ δὴ μεταπεμψάμενοι μίαν τῶν ἀρχιερατικῶν φυλήν, Ἐνιάχιν καλεῖται, διεκλήρουν ἀρχιερέα, λαγχάνει δ’ ἀπὸ τύχης ὁ μάλιστα διαδείξας αὐτῶν τὴν παρανομίαν, Φαννί τις ὄνομα, υἱὸς Σαμουήλου κώμης Ἀφθίας, ἀνὴρ οὐ μόνον οὐκ ἐξ ἀρχιερέων, ἀλλ’ οὐδ’ ἐπιστάμενος σαφῶς τί ποτ’ ἦν ἀρχιερωσύνη δι’ ἀγροικίαν. ἀπὸ γοῦν τῆς χώρας αὐτὸν ἄκοντα σύραντες ὥσπερ ἐπὶ σκηνῆς ἀλλοτρίῳ κατεκόσμουν προσωπείῳ τήν τ’ ἐσθῆτα περιτιθέντες τὴν ἱερὰν καὶ τὸ τί δεῖ ποιεῖν ἐπὶ καιροῦ διδάσκοντες. χλεύη δ’ ἦν ἐκείνοις καὶ παιδιὰ τὸ τηλικοῦτον ἀσέβημα, τοῖς δ’ ἄλλοις ἱερεῦσιν ἐπιθεωμένοις πόρρωθεν παιζόμενον τὸν νόμον δακρύειν ἐπῄει καὶ κατέστενον τὴν τῶν ἱερῶν τιμῶν κατάλυσιν.", "st": "4.3.8"}, {"sp": "N", "t": "Ταύτην τὴν τόλμαν αὐτῶν οὐκ ἤνεγκεν ὁ δῆμος, ἀλλ’ ὥσπερ ἐπὶ τυραννίδος κατάλυσιν ὥρμηντο πάντες· καὶ γὰρ οἱ προύχειν αὐτῶν δοκοῦντες, Γωρίων τε υἱὸς Ἰωσήπου καὶ ὁ Γαμαλιήλου Συμεών, παρεκρότουν ἔν τε ταῖς ἐκκλησίαις ἀθρόους καὶ κατ’ ἰδίαν περιιόντες ἕκαστον ἤδη ποτὲ τίσασθαι τοὺς λυμεῶνας τῆς ἐλευθερίας καὶ καθᾶραι τῶν μιαιφόνων τὸ ἅγιον, οἵ τε δοκιμώτατοι τῶν ἀρχιερέων, Γαμάλα μὲν υἱὸς Ἰησοῦς Ἀνάνου δὲ Ἄνανος, πολλὰ τὸν δῆμον εἰς νωθείαν κατονειδίζοντες ἐν ταῖς συνόδοις ἐπήγειρον τοῖς ζηλωταῖς· τοῦτο γὰρ αὑτοὺς ἐκάλεσαν ὡς ἐπ’ ἀγαθοῖς ἐπιτηδεύμασιν ἀλλ’ οὐχὶ ζηλώσαντες τὰ κάκιστα τῶν ἔργων [καὶ] ὑπερβαλλόμενοι.", "st": "4.3.9"}, {"sp": "N", "t": "Καὶ δὴ συνελθόντος τοῦ πλήθους εἰς ἐκκλησίαν καὶ πάντων ἀγανακτούντων μὲν ἐπὶ τῇ καταλήψει τῶν ἁγίων ταῖς τε ἁρπαγαῖς καὶ τοῖς πεφονευμένοις, οὔπω δὲ πρὸς τὴν ἄμυναν ὡρμημένων τῷ δυσεπιχειρήτους, ὅπερ ἦν, τοὺς ζηλωτὰς ὑπολαμβάνειν, καταστὰς ἐν μέσοις ὁ Ἄνανος καὶ πολλάκις εἰς τὸν ναὸν ἀπιδὼν ἐμπλήσας τε τοὺς ὀφθαλμοὺς δακρύων ἦ καλόν γε, εἶπεν, ἦν ἐμοὶ τεθνάναι πρὶν ἐπιδεῖν τὸν οἶκον τοῦ θεοῦ τοσούτοις ἄγεσι καταγέμοντα καὶ τὰς ἀβάτους καὶ ἁγίας χώρας ποσὶ μιαιφόνων στενοχωρουμένας. ἀλλὰ περικείμενος τὴν ἀρχιερατικὴν ἐσθῆτα καὶ τὸ τιμιώτατον καλούμενος τῶν σεβασμίων ὀνομάτων, ζῶ καὶ φιλοψυχῶ, μηδ’ ὑπὲρ τοὐμοῦ γήρως ὑπομένων εὐκλεῆ θάνατον † εἰ δεῖ μὴ μόνος εἰμὶ καὶ καθάπερ ἐν ἐρημίᾳ τὴν ἐμαυτοῦ ψυχὴν ἐπιδώσω μόνην ὑπὲρ τοῦ θεοῦ. τί γὰρ καὶ δεῖ ζῆν ἐν δήμῳ συμφορῶν ἀναισθητοῦντι καὶ παρ’ οἷς ἀπόλωλεν ἡ τῶν ἐν χερσὶ παθῶν ἀντίληψις; ἁρπαζόμενοι γοῦν ἀνέχεσθε καὶ τυπτόμενοι σιωπᾶτε, καὶ τοῖς φονευομένοις οὐδ’ ἐπιστένει τις ἀναφανδόν. ὢ τῆς πικρᾶς τυραννίδος. τί [δὲ] μέμφομαι τοὺς τυράννους; μὴ γὰρ οὐκ ἐτράφησαν ὑφ’ ὑμῶν καὶ τῆς ὑμετέρας ἀνεξικακίας; μὴ γὰρ οὐχ ὑμεῖς περιιδόντες τοὺς πρώτους συνισταμένους, ἔτι δ’ ἦσαν ὀλίγοι, πλείους ἐποιήσατε τῇ σιωπῇ καὶ καθοπλιζομένων ἠρεμοῦντες καθ’ ἑαυτῶν ἐπεστρέψατε τὰ ὅπλα, δέον τὰς πρώτας αὐτῶν ἐπικόπτειν ὁρμάς, ὅτε λοιδορίαις καθήπτοντο τῶν συγγενῶν, ὑμεῖς δὲ ἀμελήσαντες ἐφ’ ἁρπαγὰς παρωξύνατε τοὺς ἀλιτηρίους, καὶ πορθουμένων οἴκων λόγος ἦν οὐδείς· τοιγαροῦν αὐτοὺς ἥρπαζον τοὺς δεσπότας, καὶ συρομένοις διὰ μέσης τῆς πόλεως οὐδεὶς ἐπήμυνεν. οἱ δὲ καὶ δεσμοῖς ᾐκίσαντο τοὺς ὑφ’ ὑμῶν προδοθέντας, ἐῶ λέγειν πόσους καὶ ποδαπούς· ἀλλ’ ἀκαταιτιάτοις ἀκρίτοις οὐδεὶς ἐβοήθησε τοῖς δεδεμένοις. ἀκόλουθον ἦν ἐπιδεῖν τοὺς αὐτοὺς φονευομένους. ἐπείδομεν καὶ τοῦτο καθάπερ ἐξ ἀγέλης ζῴων ἀλόγων ἑλκομένου τοῦ κρατιστεύοντος ἀεὶ θύματος, οὐδὲ φωνήν τις ἀφῆκεν οὐχ ὅπως ἐκίνησε τὴν δεξιάν. φέρετε δὴ [τοίνυν], φέρετε πατούμενα βλέποντες τὰ ἅγια καὶ πάντας ὑποθέντες αὐτοὶ τοῖς ἀνοσίοις τοὺς τῶν τολμημάτων βαθμοὺς μὴ βαρύνεσθε τὴν ὑπεροχήν· καὶ γὰρ νῦν πάντως ἂν ἐπὶ μεῖζον προύκοψαν, εἴ τι τῶν ἁγίων καταλῦσαι μεῖζον εἶχον. κεκράτηται μὲν οὖν τὸ ὀχυρώτατον τῆς πόλεως· λεγέσθω γὰρ νῦν τὸ ἱερὸν ὡς ἄκρα τις ἢ φρούριον· ἔχοντες δ’ ἐπιτετειχισμένην τυραννίδα τοσαύτην καὶ τοὺς ἐχθροὺς ὑπὲρ κορυφὴν βλέποντες, τί βουλεύεσθε καὶ τίσι τὰς γνώμας προσθάλπετε; Ῥωμαίους ἄρα περιμενεῖτε, ἵν’ ἡμῶν βοηθήσωσι τοῖς ἁγίοις; ἔχει μὲν οὕτως τὰ πράγματα τῇ πόλει, καὶ πρὸς τοσοῦτον ἥκομεν συμφορῶν, ἵνα ἡμᾶς ἐλεήσωσι καὶ πολέμιοι. οὐκ ἐξαναστήσεσθε, ὦ τλημονέστατοι, καὶ πρὸς τὰς πληγὰς ἐπιστραφέντες, ὃ κἀπὶ τῶν θηρίων ἔστιν ἰδεῖν, τοὺς τύπτοντας ἀμυνεῖσθε; οὐκ ἀναμνήσεσθε τῶν ἰδίων ἕκαστος συμφορῶν οὐδὲ ἃ πεπόνθατε πρὸ ὀφθαλμῶν θέμενοι τὰς ψυχὰς ἐπ’ αὐτοὺς θήξετε πρὸς τὴν ἄμυναν; ἀπόλωλεν ἄρα παρ’ ὑμῖν τὸ τιμιώτατον τῶν παθῶν καὶ φυσικώτατον, ἐλευθερίας ἐπιθυμία, φιλόδουλοι δὲ καὶ φιλοδέσποτοι γεγόναμεν ὥσπερ ἐκ προγόνων τὸ ὑποτάσσεσθαι παραλαβόντες. ἀλλ’ ἐκεῖνοί γε πολλοὺς καὶ μεγάλους ὑπὲρ τῆς αὐτονομίας πολέμους διήνεγκαν καὶ οὔτε τῆς Αἰγυπτίων οὔτε τῆς Μήδων δυναστείας ἡττήθησαν ὑπὲρ τοῦ μὴ ποιεῖν τὸ κελευόμενον. καὶ τί δεῖ τὰ τῶν προγόνων λέγειν; ἀλλ’ ὁ νῦν πρὸς Ῥωμαίους πόλεμος, ἐῶ διελέγχειν πότερον λυσιτελὴς ὢν καὶ σύμφορος ἢ τοὐναντίον, τίνα δ’ οὖν ἔχει πρόφασιν; οὐ τὴν ἐλευθερίαν; εἶτα τοὺς τῆς οἰκουμένης δεσπότας μὴ φέροντες τῶν ὁμοφύλων τυράννων ἀνεξόμεθα; καίτοι τὸ μὲν τοῖς ἔξωθεν ὑπακούειν ἀνενέγκαι τις ἂν εἰς τὴν ἅπαξ ἡττήσασαν τύχην, τὸ δὲ τοῖς οἰκείοις εἴκειν πονηροῖς ἀγεννῶν ἐστι καὶ προαιρουμένων. ἐπειδὴ δὲ ἅπαξ ἐμνήσθην Ῥωμαίων, οὐκ ἀποκρύψομαι πρὸς ὑμᾶς εἰπεῖν ὃ μεταξὺ τῶν λόγων ἐμπεσὸν ἐπέστρεψε τὴν διάνοιαν, ὅτι κἂν ἁλῶμεν ὑπ’ ἐκείνοις, ἀπείη δὲ ἡ πεῖρα τοῦ λόγου, χαλεπώτερον οὐδὲν παθεῖν ἔχομεν ὧν ἡμᾶς διατεθείκασιν οὗτοι. πῶς δὲ οὐ δακρύων ἄξιον ἐκείνων μὲν ἐν τῷ ἱερῷ καὶ ἀναθήματα βλέπειν, τῶν δὲ ὁμοφύλων τὰ σκῦλα σεσυληκότων καὶ ἀνελόντων τὴν τῆς μητροπόλεως εὐγένειαν, καὶ πεφονευμένους ἄνδρας ὧν ἀπέσχοντο ἂν κἀκεῖνοι κρατήσαντες; καὶ Ῥωμαίους μὲν μηδέποτε ὑπερβῆναι τὸν ὅρον τῶν βεβήλων μηδὲ παραβῆναί τι τῶν ἱερῶν ἐθῶν, πεφρικέναι δὲ πόρρωθεν ὁρῶντας τοὺς τῶν ἁγίων περιβόλους, γενηθέντας δέ τινας ἐν τῇδε τῇ χώρᾳ καὶ τραφέντας ὑπὸ τοῖς ἡμετέροις ἔθεσι καὶ Ἰουδαίους καλουμένους ἐμπεριπατεῖν μέσοις τοῖς ἁγίοις θερμὰς ἔτι τὰς χεῖρας ἐξ ὁμοφύλων ἔχοντας φόνων; εἶτά τις δέδοικεν τὸν ἔξωθεν πόλεμον καὶ τοὺς ἐν συγκρίσει πολλῷ τῶν οἰκείων ἡμῖν μετριωτέρους; καὶ γὰρ ἄν, εἰ ἐτύμους δεῖ τοῖς πράγμασι τὰς κλήσεις ἐφαρμόζειν, τάχα ἂν εὕροι τις Ῥωμαίους μὲν ἡμῖν βεβαιωτὰς τῶν νόμων, πολεμίους δὲ τοὺς ἔνδον. ἀλλ’ ὅτι μὲν ἐξώλεις οἱ ἐπίβουλοι τῆς ἐλευθερίας, καὶ πρὸς ἃ δεδράκασιν οὐκ ἄν τις ἐπινοήσειεν δίκην ἀξίαν κατ’ αὐτῶν, οἶμαι πάντας ἥκειν πεπεισμένους οἴκοθεν καὶ πρὸ τῶν ἐμῶν λόγων παρωξύνθαι τοῖς ἔργοις ἐπ’ αὐτούς, ἃ πεπόνθατε. καταπλήσσονται δ’ ἴσως οἱ πολλοὶ τό τε πλῆθος αὐτῶν καὶ τὴν τόλμαν, ἔτι δὲ καὶ τὴν ἐκ τοῦ τόπου πλεονεξίαν. ταῦτα δ’ ὥσπερ συνέστη διὰ τὴν ὑμετέραν ἀμέλειαν, καὶ νῦν αὐξηθήσεται πλέον ὑπερθεμένων· καὶ γὰρ τὸ πλῆθος αὐτοῖς ἐπιτρέφεται καθ’ ἡμέραν παντὸς πονηροῦ πρὸς τοὺς ὁμοίους αὐτομολοῦντος, καὶ τὴν τόλμαν ἐξάπτει μέχρι νῦν μηδὲν ἐμπόδιον, τῷ τε τόπῳ καθύπερθεν ὄντες χρήσαιντο καὶ μετὰ παρασκευῆς, ἂν ἡμεῖς χρόνον δῶμεν. πιστεύσατε δὲ ὡς, ἐὰν προσβαίνωμεν ἐπ’ αὐτούς, ἔσονται τῇ συνειδήσει ταπεινότεροι, καὶ τὸ πλεονέκτημα τοῦ ὕψους ὁ λογισμὸς ἀπολεῖ. τάχα τὸ θεῖον ὑβρισμένον ἀναστρέψει κατ’ αὐτῶν τὰ βαλλόμενα, καὶ τοῖς σφετέροις διαφθαρήσονται βέλεσιν οἱ δυσσεβεῖς. μόνον ὀφθῶμεν αὐτοῖς, καὶ καταλέλυνται. καλὸν δέ, κἂν προσῇ τις κίνδυνος, ἀποθνήσκειν πρὸς τοῖς ἱεροῖς πυλῶσι καὶ τὴν ψυχὴν εἰ καὶ μὴ πρὸ παίδων ἢ γυναικῶν, ἀλλ’ ὑπὲρ τοῦ θεοῦ καὶ τῶν ἁγίων προέσθαι. προστήσομαι δ’ ἐγὼ γνώμῃ τε καὶ χειρί, καὶ οὔτε ἐπίνοιά τις ὑμῖν λείψει πρὸς ἀσφάλειαν ἐξ ἡμῶν οὔτε τοῦ σώματος ὄψεσθε φειδόμενον.", "st": "4.3.10"}, {"sp": "N", "t": "Τούτοις ὁ Ἄνανος παρακροτεῖ τὸ πλῆθος ἐπὶ τοὺς ζηλωτάς, οὐκ ἀγνοῶν μὲν ὡς εἶεν ἤδη δυσκατάλυτοι πλήθει τε καὶ νεότητι καὶ παραστήματι ψυχῆς, τὸ πλέον δὲ συνειδήσει τῶν εἰργασμένων· οὐ γὰρ ἐνδώσειν αὐτοὺς εἰς ἐσχάτην συγγνώμην ἐφ’ οἷς ἔδρασαν ἐλπίσαντας· ὅμως δὲ πᾶν ὁτιοῦν παθεῖν προῃρεῖτο μᾶλλον ἢ περιιδεῖν ἐν τοιαύτῃ τὰ πράγματα συγχύσει. τὸ δὲ πλῆθος ἄγειν αὐτοὺς ἐβόα καθ’ ὧν παρεκάλει, καὶ προκινδυνεύειν ἕκαστος ἦν ἑτοιμότατος.", "st": "4.3.11"}, {"sp": "N", "t": "Ἐν ὅσῳ δὲ ὁ Ἄνανος κατέλεγέ τε καὶ συνέτασσε τοὺς ἐπιτηδείους πρὸς μάχην, οἱ ζηλωταὶ πυνθανόμενοι τὴν ἐπιχείρησιν, παρῆσαν γὰρ οἱ ἀγγέλλοντες αὐτοῖς πάντα τὰ παρὰ τοῦ δήμου, παροξύνονται κἀκ τοῦ ἱεροῦ προπηδῶντες ἀθρόοι τε καὶ κατὰ λόχους οὐδενὸς ἐφείδοντο τῶν προστυγχανόντων. ἀθροίζεται δὲ ὑπ’ Ἀνάνου ταχέως τὸ δημοτικόν, πλήθει μὲν ὑπερέχον, ὅπλοις δὲ καὶ τῷ μὴ συγκεκροτῆσθαι λειπόμενον τῶν ζηλωτῶν. τὸ πρόθυμον δὲ παρ’ ἑκατέροις ἀνεπλήρου τὰ λείποντα, τῶν μὲν ἀπὸ τῆς πόλεως ἀνειληφότων ὀργὴν ἰσχυροτέραν τῶν ὅπλων, τῶν δὲ ἀπὸ τοῦ ἱεροῦ τόλμαν παντὸς πλήθους ὑπερέχουσαν· καὶ οἱ μὲν ἀοίκητον ὑπολαμβάνοντες αὑτοῖς τὴν πόλιν εἰ μὴ τοὺς λῃστὰς ἐκκόψειαν αὐτῆς, οἱ ζηλωταὶ δὲ εἰ μὴ κρατοῖεν οὐκ ἔστιν ἧστινος ὑστερήσειν τιμωρίας, συνερρήγνυντο στρατηγούμενοι τοῖς πάθεσι, τὸ μὲν πρῶτον κατὰ τὴν πόλιν καὶ πρὸ τοῦ ἱεροῦ λίθοις βάλλοντες ἀλλήλους καὶ πόρρωθεν διακοντιζόμενοι, κατὰ δὲ τὰς τροπὰς οἱ κρατοῦντες ἐχρῶντο τοῖς ξίφεσι· καὶ πολὺς ἦν ἑκατέρων φόνος, τραυματίαι τε ἐγίνοντο συχνοί. καὶ τοὺς μὲν ἀπὸ τοῦ δήμου διεκόμιζον εἰς τὰς οἰκίας οἱ προσήκοντες, ὁ δὲ βληθεὶς τῶν ζηλωτῶν εἰς τὸ ἱερὸν ἀνῄει καθαιμάσσων τὸ θεῖον ἔδαφος· καὶ μόνον ἄν τις εἴποι τὸ ἐκείνων αἷμα μιᾶναι τὰ ἅγια. κατὰ μὲν οὖν τὰς συμβολὰς ἐκτρέχοντες ἀεὶ περιῆσαν οἱ λῃστρικοί, τεθυμωμένοι δὲ οἱ δημοτικοὶ καὶ πλείους ἀεὶ γινόμενοι, κακίζοντες τοὺς ἐνδιδόντας καὶ μὴ διδόντες τοῖς τρεπομένοις ἀναχώρησιν οἱ κατόπιν βιαζόμενοι, πᾶν μὲν ἐπιστρέφουσι τὸ σφέτερον εἰς τοὺς ὑπεναντίους· κἀκείνων μηκέτ’ ἀντεχόντων τῇ βίᾳ, κατὰ μικρὸν δ’ ἀναχωρούντων εἰς τὸ ἱερὸν συνεισπίπτουσιν οἱ περὶ τὸν Ἄνανον. τοῖς δὲ κατάπληξις ἐμπίπτει στερομένοις τοῦ πρώτου περιβόλου, καὶ καταφυγόντες εἰς τὸ ἐνδοτέρω ταχέως ἀποκλείουσι τὰς πύλας. τῷ δ’ Ἀνάνῳ προσβαλεῖν μὲν οὐκ ἐδόκει τοῖς ἱεροῖς πυλῶσιν ἄλλως τε κἀκείνων βαλλόντων ἄνωθεν, ἀθέμιτον δ’ ἡγεῖτο, κἂν κρατήσῃ, μὴ προηγνευκὸς εἰσαγαγεῖν τὸ πλῆθος· διακληρώσας δ’ ἐκ πάντων εἰς ἑξακισχιλίους ὁπλίτας καθίστησιν ἐπὶ ταῖς στοαῖς φρουρούς· διεδέχοντο δὲ ἄλλοι τούτους, καὶ παντὶ μὲν ἀνάγκη παρεῖναι πρὸς τὴν φυλακὴν ἐκ περιόδου, πολλοὶ δὲ τῶν ἐν ἀξιώμασιν ἐφεθέντες ὑπὸ τῶν ἄρχειν δοκούντων μισθούμενοι πενιχροτέρους ἀνθ’ ἑαυτῶν ἐπὶ τὴν φρουρὰν ἔπεμπον.", "st": "4.3.12"}, {"sp": "N", "t": "Γίνεται δὲ τούτοις πᾶσιν ὀλέθρου παραίτιος Ἰωάννης, ὃν ἔφαμεν ἀπὸ Γισχάλων διαδρᾶναι, δολιώτατος ἀνὴρ καὶ δεινὸν ἔρωτα τυραννίδος ἐν τῇ ψυχῇ περιφέρων, ὃς πόρρωθεν ἐπεβούλευε τοῖς πράγμασιν. καὶ δὴ τότε τὰ τοῦ δήμου φρονεῖν ὑποκρινόμενος συμπεριῄει μὲν τῷ Ἀνάνῳ βουλευομένῳ σὺν τοῖς δυνατοῖς μεθ’ ἡμέραν καὶ νύκτωρ ἐπιόντι τὰς φυλακάς, διήγγελλε δὲ τὰ ἀπόρρητα τοῖς ζηλωταῖς, καὶ πᾶν σκέμμα τοῦ δήμου πρὶν καλῶς βουλευθῆναι παρὰ τοῖς ἐχθροῖς ἐγινώσκετο δι’ αὐτοῦ. μηχανώμενος δὲ τὸ μὴ δι’ ὑποψίας ἐλθεῖν ἀμέτροις ἐχρῆτο ταῖς θεραπείαις εἰς τόν τε Ἄνανον καὶ τοὺς τοῦ δήμου προεστῶτας. ἐχώρει δ’ εἰς τοὐναντίον αὐτῷ τὸ φιλότιμον· διὰ γὰρ τὰς ἀλόγους κολακείας μᾶλλον ὑπωπτεύετο, καὶ τὸ πανταχοῦ παρεῖναι μὴ καλούμενον ἔμφασιν προδοσίας τῶν ἀπορρήτων παρεῖχε. συνεώρων μὲν γὰρ αἰσθανομένους ἅπαντα τοὺς ἐχθροὺς τῶν παρ’ αὐτοῖς βουλευμάτων, πιθανώτερος δ’ οὐδεὶς ἦν Ἰωάννου πρὸς ὑποψίας τοῦ διαγγέλλειν. ἀποσκευάσασθαι μὲν οὖν αὐτὸν οὐκ ἦν ῥᾴδιον ὄντα δυνατὸν ἐκ πονηρίας καὶ ἄλλως οὐ τῶν ἀσήμων ὑπεζωσμένον τε πολλοὺς τῶν συνεδρευόντων τοῖς ὅπλοις, ἐδόκει δὲ αὐτὸν ὅρκοις πιστώσασθαι πρὸς εὔνοιαν. ὤμνυε δ’ ὁ Ἰωάννης ἑτοίμως εὐνοήσειν τε τῷ δήμῳ καὶ μήτε βουλήν τινα μήτε πρᾶξιν προδώσειν τοῖς ἐχθροῖς, συγκαταλύσειν δὲ τοὺς ἐπιτιθεμένους καὶ χειρὶ καὶ γνώμῃ. οἱ δὲ περὶ τὸν Ἄνανον πιστεύσαντες τοῖς ὅρκοις ἤδη χωρὶς ὑπονοίας εἰς τὰς συμβουλίας αὐτὸν παρελάμβανον, καὶ δὴ καὶ πρεσβευτὴν εἰσπέμπουσι πρὸς τοὺς ζηλωτὰς περὶ διαλύσεων· ἦν γὰρ αὐτοῖς σπουδὴ τὸ παρ’ αὐτοῖς μὴ μιᾶναι τὸ ἱερὸν μηδέ τινα τῶν ὁμοφύλων ἐν αὐτῷ πεσεῖν.", "st": "4.3.13"}, {"sp": "N", "t": "Ὁ δ’ ὥσπερ τοῖς ζηλωταῖς ὑπὲρ εὐνοίας ὀμόσας καὶ οὐ κατ’ αὐτῶν, παρελθὼν εἴσω καὶ καταστὰς εἰς μέσους πολλάκις μὲν ἔφη κινδυνεῦσαι δι’ αὐτούς, ἵνα μηδὲν ἀγνοήσωσι τῶν ἀπορρήτων, ὅσα κατ’ αὐτῶν οἱ περὶ τὸν Ἄνανον ἐβουλεύσαντο· νῦν δὲ τὸν μέγιστον ἀναρριπτεῖν κίνδυνον σὺν πᾶσιν αὐτοῖς, εἰ μή τις προσγένοιτο βοήθεια δαιμόνιος. οὐ γὰρ ἔτι μέλλειν Ἄνανον, ἀλλὰ πείσαντα μὲν τὸν δῆμον πεπομφέναι πρέσβεις πρὸς Οὐεσπασιανόν, ἵν’ ἐλθὼν κατὰ τάχος παραλάβῃ τὴν πόλιν, ἁγνείαν δὲ παρηγγελκέναι κατ’ αὐτῶν εἰς τὴν ἑξῆς ἡμέραν, ἵν’ ἢ κατὰ θρησκείαν εἰσελθόντες ἢ καὶ βιασάμενοι συμμίξωσιν αὐτοῖς. οὐχ ὁρᾶν δὲ μέχρι τίνος ἢ τὴν φρουρὰν οἴσουσιν ἢ παρατάξονται πρὸς τοσούτους. προσετίθει δ’ ὡς αὐτὸς εἰσπεμφθείη κατὰ θεοῦ πρόνοιαν ὡς πρεσβευτὴς περὶ διαλύσεων· τὸν γὰρ Ἄνανον ταύτας αὐτοῖς προτείνειν, ὅπως ἀνυποπτοτέροις ἐπέλθῃ. δεῖν οὖν ἢ τῷ λόγῳ τοῦ ζῆν τοὺς φρουροῦντας ἱκετεύειν ἢ πορίζεσθαί τινα παρὰ τῶν ἔξωθεν ἐπικουρίαν· τοὺς δὲ θαλπομένους ἐλπίδι συγγνώμης εἰ κρατηθεῖεν, ἐπιλελῆσθαι τῶν ἰδίων τολμημάτων ἢ νομίζειν ἅμα τῷ μετανοεῖν τοὺς δεδρακότας εὐθέως ὀφείλειν διηλλάχθαι καὶ τοὺς παθόντας. ἀλλὰ τῶν μὲν ἀδικησάντων διὰ μίσους πολλάκις γίνεσθαι καὶ τὴν μεταμέλειαν, τοῖς ἀδικηθεῖσι δὲ τὰς ὀργὰς ἐπ’ ἐξουσίας χαλεπωτέρας· ἐφεδρεύειν δέ γε ἐκείνοις φίλους καὶ συγγενεῖς τῶν ἀπολωλότων καὶ δῆμον τοσοῦτον ὑπὲρ καταλύσεως νόμων καὶ δικαστηρίων τεθυμωμένον, ὅπου κἂν ᾖ τι μέρος τὸ ἐλεοῦν, ὑπὸ πλείονος ἂν αὐτὸ τοῦ διαγανακτοῦντος ἀφανισθῆναι.", "st": "4.3.14"}, {"sp": "N", "t": "Τοιαῦτα μὲν ἐποίκιλλεν ἀθρόως δεδισσόμενος, καὶ τὴν ἔξωθεν βοήθειαν ἀναφανδὸν μὲν οὐκ ἐθάρρει λέγειν, ᾐνίσσετο δὲ τοὺς Ἰδουμαίους· ἵνα δὲ καὶ τοὺς ἡγεμόνας τῶν ζηλωτῶν ἰδίᾳ παροξύνῃ, τὸν Ἄνανον εἴς τε ὠμότητα διέβαλλε καὶ ἀπειλεῖν ἐκείνοις ἐξαιρέτως ἔλεγεν. ἦσαν δὲ Ἐλεάζαρος μὲν υἱὸς Γίωνος, ὃς δὴ καὶ πιθανώτατος ἐδόκει τῶν ἐν αὐτοῖς νοῆσαί τε τὰ δέοντα καὶ τὰ νοηθέντα πρᾶξαι, Ζαχαρίας δέ τις υἱὸς Ἀμφικάλλει, γένος ἐκ τῶν ἱερέων ἑκάτερος. οὗτοι πρὸς ταῖς κοιναῖς τὰς ἰδίας καθ’ ἑαυτῶν ἀπειλὰς ἀκούσαντες, ἔτι δ’ ὡς οἱ περὶ τὸν Ἄνανον δυναστείαν αὑτοῖς περιποιούμενοι Ῥωμαίους ἐπικαλοῖντο, καὶ γὰρ τοῦτο Ἰωάννης προσεψεύσατο, μέχρι πολλοῦ μὲν ἠποροῦντο, τί χρὴ πράττειν εἰς ὀξὺν οὕτως καιρὸν συνεωσμένους· παρεσκευάσθαι μὲν γὰρ τὸν δῆμον ἐπιχειρεῖν αὐτοῖς οὐκ εἰς μακράν, αὐτῶν δὲ τὸ σύντομον τῆς ἐπιβουλῆς ὑποτετμῆσθαι τὰς ἔξωθεν ἐπικουρίας· πάντα γὰρ ἂν φθῆναι παθεῖν πρὶν καὶ πυθέσθαι τινὰ τῶν συμμάχων. ἔδοξε δ’ ὅμως ἐπικαλεῖσθαι τοὺς Ἰδουμαίους, καὶ γράψαντες ἐπιστολὴν σύντομον, ὡς Ἄνανος μὲν προδιδοίη Ῥωμαίοις τὴν μητρόπολιν ἐξαπατήσας τὸν δῆμον, αὐτοὶ δ’ ὑπὲρ τῆς ἐλευθερίας ἀποστάντες ἐν τῷ ἱερῷ φρουροῖντο, ὀλίγος δ’ ἔτι χρόνος αὐτοῖς βραβεύοι τὴν σωτηρίαν, εἰ δὲ μὴ βοηθήσουσιν ἐκεῖνοι κατὰ τάχος, αὐτοὶ μὲν ὑπ’ Ἀνάνῳ τε καὶ τοῖς ἐχθροῖς, ἡ πόλις δ’ ὑπὸ Ῥωμαίους φθάσει γενομένη. τὰ δὲ πολλὰ τοῖς ἀγγέλοις ἐνετέλλοντο πρὸς τοὺς ἄρχοντας τῶν Ἰδουμαίων διαλέγεσθαι. προεβλήθησαν δὲ ἐπὶ τὴν ἀγγελίαν δύο τῶν δραστηρίων ἀνδρῶν εἰπεῖν τε ἱκανοὶ καὶ πεῖσαι περὶ πραγμάτων, τὸ δὲ τούτων χρησιμώτερον, ὠκύτητι ποδῶν διαφέροντες· τοὺς μὲν γὰρ Ἰδουμαίους αὐτόθεν ᾔδεισαν πεισθησομένους, ἅτε θορυβῶδες καὶ ἄτακτον ἔθνος αἰεί τε μετέωρον πρὸς τὰ κινήματα καὶ μεταβολαῖς χαῖρον, πρὸς ὀλίγην τε κολακείαν τῶν δεομένων τὰ ὅπλα κινοῦν καὶ καθάπερ εἰς ἑορτὴν εἰς τὰς παρατάξεις ἐπειγόμενον. ἔδει δὲ τάχους εἰς τὴν ἀγγελίαν· εἰς ὃ μηδὲν ἐλλείποντες προθυμίας οἱ πεμφθέντες, ἐκαλεῖτο δ’ αὐτῶν Ἀνανίας ἑκάτερος, καὶ δὴ πρὸς τοὺς ἄρχοντας τῶν Ἰδουμαίων παρῆσαν.", "st": "4.4.1"}, {"sp": "N", "t": "Οἱ δὲ πρὸς τὴν ἐπιστολὴν καὶ τὰ ῥηθέντα παρὰ τῶν ἀφιγμένων ἐκπλαγέντες, ὥσπερ ἐμμανεῖς περιέθεόν τε τὸ ἔθνος καὶ διεκήρυσσον τὴν στρατείαν. ἤθροιστο δ’ ἡ πληθὺς τάχιον τοῦ παραγγέλματος, καὶ πάντες ὡς ἐπ’ ἐλευθερίᾳ τῆς μητροπόλεως ἥρπαζον τὰ ὅπλα. συνταχθέντες δὲ εἰς δύο μυριάδας παραγίνονται πρὸς τὰ Ἱεροσόλυμα, χρώμενοι τέσσαρσιν ἡγεμόσιν Ἰωάννῃ τε καὶ Ἰακώβῳ παιδὶ Σωσᾶ, πρὸς δὲ τούτοις ἦν Σίμων υἱὸς Θακήου καὶ Φινέας Κλουσώθ.", "st": "4.4.2"}, {"sp": "N", "t": "Τὸν δὲ Ἄνανον ἡ μὲν ἔξοδος τῶν ἀγγέλων ὥσπερ καὶ τοὺς φρουροὺς ἔλαθεν, ἡ δ’ ἔφοδος τῶν Ἰδουμαίων οὐκέτι· προγνοὺς γὰρ ἀπέκλειέ τε τὰς πύλας αὐτοῖς καὶ διὰ φυλακῆς εἶχε τὰ τείχη. καθάπαν γε μὴν αὐτοὺς ἐκπολεμεῖν οὐκ ἔδοξεν, ἀλλὰ λόγοις πείθειν πρὸ τῶν ὅπλων. στὰς οὖν ἐπὶ τὸν ἄντικρυς αὐτῶν πύργον ὁ μετὰ Ἄνανον γεραίτατος τῶν ἀρχιερέων Ἰησοῦς, πολλῶν ἔφη καὶ ποικίλων τὴν πόλιν κατεσχηκότων θορύβων ἐν οὐδενὶ θαυμάσαι τὴν τύχην οὕτως, ὡς τῷ συμπράττειν τοῖς πονηροῖς καὶ τὰ παράδοξα· παρεῖναι γοῦν ὑμᾶς ἀνθρώποις ἐξωλεστάτοις μετὰ τοσαύτης προθυμίας ἐπαμυνοῦντας καθ’ ἡμῶν, μεθ’ ὅσης εἰκὸς ἦν ἐλθεῖν οὐδὲ τῆς μητροπόλεως καλούσης ἐπὶ βαρβάρους. καὶ εἰ μὲν ἑώρων τὴν σύνταξιν ὑμῶν ἐξ ὁμοίων τοῖς καλέσασιν ἀνδρῶν, οὐκ ἂν ἄλογον τὴν ὁρμὴν ὑπελάμβανον· οὐδὲν γὰρ οὕτως συνίστησι τὰς εὐνοίας ὡς τρόπων συγγένεια· νῦν δ’, εἰ μέν τις αὐτοὺς ἐξετάζοι καθ’ ἕνα, μυρίων ἕκαστος εὑρεθήσεται θανάτων ἄξιος. τὰ γὰρ θύματα καὶ καθάρματα τῆς πόλεως ὅλης, κατασωτευσάμενα τὰς ἰδίας οὐσίας καὶ προγυμνάσαντα τὴν ἀπόνοιαν ἐν ταῖς πέριξ κώμαις τε καὶ πόλεσι, τελευταῖα λεληθότως παρεισέρρευσαν εἰς τὴν ἱερὰν πόλιν, λῃσταὶ δι’ ὑπερβολὴν ἀσεβημάτων μιαίνοντες καὶ τὸ ἀβέβηλον ἔδαφος, οὓς ὁρᾶν ἔστι νῦν ἀδεεῖς ἐμμεθυσκομένους τοῖς ἁγίοις καὶ τὰ σκῦλα τῶν πεφονευμένων καταναλίσκοντας εἰς τὰς ἀπλήστους γαστέρας. τὸ δ’ ὑμέτερον πλῆθος καὶ τὸν κόσμον τῶν ὅπλων ὁρᾶν ἔστιν οἷος ἔπρεπεν καλούσης μὲν τῆς μητροπόλεως κοινῷ βουλευτηρίῳ, συμμάχους δὲ κατ’ ἀλλοφύλων. τί ἂν οὖν εἴποι τοῦτό τις ἢ τύχης ἐπήρειαν, ὅταν λογάσι πονηροῖς αὔτανδρον ἔθνος ὁρᾷ συνασπίζον [αὐτοῖς]; μέχρι πολλοῦ μὲν ἀπορῶ, τί δή ποτε καὶ τὸ κινῆσαν ὑμᾶς οὕτω ταχέως ἐγένετο· μὴ γὰρ ἂν δίχα μεγάλης αἰτίας ἀναλαβεῖν τὰς πανοπλίας ὑπὲρ λῃστῶν καὶ κατὰ δήμου συγγενοῦς· ἐπεὶ δὲ ἠκούσαμεν Ῥωμαίους καὶ προδοσίαν, ταῦτα γὰρ ὑμῶν ἐθορύβουν τινὲς ἀρτίως, καὶ τῆς μητροπόλεως ἐπ’ ἐλευθερώσει παρεῖναι, πλέον τῶν ἄλλων τολμημάτων ἐθαυμάσαμεν τοὺς ἀλιτηρίους τῆς περὶ τοῦτο ψευδοῦς ἐπινοίας· ἄνδρας γὰρ φύσει φιλελευθέρους καὶ διὰ τοῦτο μάλιστα τοῖς ἔξωθεν πολεμίοις μάχεσθαι παρεσκευασμένους οὐκ ἐνῆν ἄλλως ἐξαγριῶσαι καθ’ ἡμῶν ἢ λογοποιήσαντας προδοσίαν τῆς ποθουμένης ἐλευθερίας. ἀλλ’ ὑμᾶς γε χρὴ σκέπτεσθαι τούς τε διαβάλλοντας καὶ καθ’ ὧν, συνάγειν τε τὴν ἀλήθειαν οὐκ ἐκ τῶν ἐπιπλάστων λόγων ἀλλ’ ἐκ τῶν κοινῶν πραγμάτων. τί γὰρ δὴ καὶ παθόντες ἂν ἡμεῖς Ῥωμαίοις προσπωλοῖμεν ἑαυτοὺς νῦν, παρὸν ἢ μηδὲ ἀποστῆναι τὸ πρῶτον ἢ προσχωρῆσαι ταχέως ἀποστάντας ὄντων ἔτι τῶν πέριξ ἀπορθήτων; νῦν μὲν γὰρ οὐδὲ βουλομένοις διαλύσασθαι ῥᾴδιον, ὅτε Ῥωμαίους μὲν ὑπερόπτας πεποίηκεν ὑποχείριος ἡ Γαλιλαία, φέρει δ’ αἰσχύνην ἡμῖν θανάτου χαλεπωτέραν τὸ θεραπεύειν αὐτοὺς ὄντας ἤδη πλησίον. καὶ ἐγὼ καθ’ ἑαυτὸν μὲν ἂν εἰρήνην προτιμήσαιμι θανάτου, πολεμούμενος δ’ ἅπαξ καὶ συμβαλὼν θάνατον εὐκλεᾶ τοῦ ζῆν αἰχμάλωτος. πότερον δέ φασιν ἡμᾶς τοὺς τοῦ δήμου προεστῶτας πέμψαι κρύφα πρὸς Ῥωμαίους ἢ καὶ τὸν δῆμον κοινῇ ψηφισάμενον; εἰ μὲν ἡμᾶς, εἰπάτωσαν τοὺς πεμφθέντας φίλους, τοὺς διακονήσαντας τὴν προδοσίαν οἰκέτας. ἐφωράθη τις ἀπιών; ἀνακομιζόμενος ἑάλω; γραμμάτων γεγόνασιν ἐγκρατεῖς; πῶς δὲ τοὺς μὲν τοσούτους πολίτας ἐλάθομεν, οἷς κατὰ πᾶσαν ὥραν συναναστρεφόμεθα, τοῖς δὲ ὀλίγοις καὶ φρουρουμένοις καὶ μηδ’ εἰς τὴν πόλιν ἐκ τοῦ ἱεροῦ προελθεῖν δυναμένοις ἐγνώσθη τὰ κατὰ τὴν χώραν λαθραίως ἐνεργούμενα; νῦν δ’ ἔγνωσαν, ὅτε δεῖ δοῦναι δίκας τῶν τετολμημένων, ἕως δ’ ἦσαν ἀδεεῖς αὐτοί, προδότης ἡμῶν οὐδεὶς ὑπωπτεύετο; εἰ δ’ ἐπὶ τὸν δῆμον ἀναφέρουσι τὴν αἰτίαν, ἐν φανερῷ δήπουθεν ἐβουλεύσαντο, οὐδεὶς ἀπεστάτει τῆς ἐκκλησίας, ὥστε τάχιον ἂν τῆς μηνύσεως ἔσπευσεν ἡ φήμη πρὸς ὑμᾶς φανερωτέρα. τί δέ; οὐχὶ καὶ πρέσβεις ἔδει πέμπειν ψηφισαμένους τὰς διαλύσεις; καὶ τίς ὁ χειροτονηθείς; εἰπάτωσαν. ἀλλὰ τοῦτο μὲν δυσθανατούντων καὶ πλησίον οὔσας τὰς τιμωρίας διακρουομένων σκῆψίς ἐστιν· εἰ γὰρ δὴ καὶ προδοθῆναι τὴν πόλιν εἵμαρτο, μόνους ἂν τολμῆσαι καὶ τοῦτο τοὺς διαβάλλοντας, ὧν τοῖς τολμήμασιν ἓν μόνον [κακὸν] λείπει, προδοσία. χρὴ δὲ ὑμᾶς, ἐπειδήπερ ἅπαξ πάρεστε μετὰ τῶν ὅπλων, τὸ μὲν δικαιότατον, ἀμύνειν τῇ μητροπόλει καὶ συνεξαιρεῖν τοὺς τὰ δικαστήρια καταλύσαντας τυράννους, οἳ πατήσαντες τοὺς νόμους ἐπὶ τοῖς αὐτῶν ξίφεσι πεποίηνται τὰς κρίσεις. ἄνδρας γοῦν ἀκαταιτιάτους τῶν ἐπιφανῶν ἐκ μέσης τῆς ἀγορᾶς ἁρπάσαντες δεσμοῖς τε προῃκίσαντο καὶ μηδὲ φωνῆς μηδ’ ἱκεσίας ἀνασχόμενοι διέφθειραν. ἔξεστιν δ’ ὑμῖν παρελθοῦσιν εἴσω μὴ πολέμου νόμῳ θεάσασθαι τὰ τεκμήρια τῶν λεγομένων, οἴκους ἠρημωμένους ταῖς ἐκείνων ἁρπαγαῖς καὶ γύναια καὶ γενεὰς τῶν ἀπεσφαγμένων μελανειμονούσας, κωκυτὸν δὲ καὶ θρῆνον ἀνὰ τὴν πόλιν ὅλην· οὐδεὶς γάρ ἐστιν, ὃς οὐ γέγευται τῆς τῶν ἀνοσίων καταδρομῆς· οἵ γε ἐπὶ τοσοῦτον ἐξώκειλαν ἀπονοίας, ὥστε μὴ μόνον ἐκ τῆς χώρας καὶ τῶν ἔξωθεν πόλεων ἐπὶ τὸ πρόσωπον καὶ τὴν κεφαλὴν ὅλου τοῦ ἔθνους μετενεγκεῖν τὴν λῃστρικὴν τόλμαν, ἀλλὰ καὶ ἀπὸ τῆς πόλεως ἐπὶ τὸ ἱερόν. ὁρμητήριον γοῦν αὐτοῖς τοῦτο καὶ καταφυγὴ ταμιεῖόν τε τῶν ἐφ’ ἡμᾶς παρασκευῶν γέγονεν, ὁ δ’ ὑπὸ τῆς οἰκουμένης προσκυνούμενος χῶρος καὶ τοῖς ἀπὸ περάτων γῆς ἀλλοφύλοις ἀκοῇ τετιμημένος παρὰ τῶν γενηθέντων ἐνθάδε θηρίων καταπατεῖται· νεανιεύονταί τε ἐν ταῖς ἀπογνώσεσιν ἤδη δήμους τε δήμοις καὶ πόλεσι πόλεις συγκρούειν καὶ κατὰ τῶν σπλάγχνων τῶν ἰδίων τὸ ἔθνος στρατολογεῖν. ἀνθ’ ὧν τὸ μὲν κάλλιστον καὶ πρέπον, ὡς ἔφην, ὑμῖν συνεξαιρεῖν τοὺς ἀλιτηρίους καὶ ὑπὲρ αὐτῆς τῆς ἀπάτης ἀμυνομένους, ὅτι συμμάχους ἐτόλμησαν καλεῖν οὓς ἔδει τιμωροὺς δεδιέναι· εἰ δὲ αἰδεῖσθε τὰς τῶν τοιούτων ἐπικλήσεις, ἀλλά τοι πάρεστι θεμένοις τὰ ὅπλα καὶ παρελθοῦσιν εἰς τὴν πόλιν σχήματι συγγενῶν ἀναλαβεῖν τὸ μέσον συμμάχων τε καὶ πολεμίων ὄνομα δικαστὰς γενομένους. καίτοι λογίσασθε, πόσον κερδήσουσιν ἐφ’ ὁμολογουμένοις καὶ τηλικούτοις κρινόμενοι παρ’ ὑμῖν οἱ τοῖς ἀκαταιτιάτοις μηδὲ λόγου μεταδόντες· λαμβανέτωσαν δ’ οὖν ταύτην ἐκ τῆς ὑμετέρας ἀφίξεως τὴν χάριν. εἰ δ’ οὔτε συναγανακτεῖν ἡμῖν οὔτε κρίνεσθαι δεῖ, τρίτον ἐστὶ καταλιπεῖν ἑκατέρους καὶ μήτε ταῖς ἡμετέραις ἐπιβαίνειν συμφοραῖς μήτε τοῖς ἐπιβούλοις τῆς μητροπόλεως συνέρχεσθαι. εἰ γὰρ καὶ τὰ μάλιστα Ῥωμαίοις ὑποπτεύετε διειλέχθαι τινάς, παρατηρεῖν ἔξεστι τὰς ἐφόδους, κἄν τι τῶν διαβεβλημένων ἔργῳ διακαλύπτηται, τότε φρουρεῖν τὴν μητρόπολιν ἐλθόντας κολάζειν τε τοὺς αἰτίους πεφωραμένους· οὐ γὰρ ἂν ὑμᾶς φθάσειαν οἱ πολέμιοι τῇ πόλει προσῳκημένους. εἰ δ’ οὐδὲν ὑμῖν τούτων εὔγνωμον ἢ μέτριον δοκεῖ, μὴ θαυμάζετε τὰ κλεῖθρα τῶν πυλῶν, ἕως ἂν φέρητε τὰ ὅπλα.", "st": "4.4.3"}, {"sp": "N", "t": "Τοιαῦτα μὲν ὁ Ἰησοῦς ἔλεγε· τῶν δὲ Ἰδουμαίων οὔτε τὸ πλῆθος προσεῖχεν, ἀλλὰ τεθύμωτο μὴ τυχὸν ἑτοίμης τῆς εἰσόδου, καὶ διηγανάκτουν οἱ στρατηγοὶ πρὸς ἀπόθεσιν τῶν ὅπλων αἰχμαλωσίαν ἡγούμενοι τὸ κελευόντων τινῶν αὐτὰ ῥῖψαι. Σίμων δὲ υἱὸς Κααθὰ τῶν ἡγεμόνων εἷς, μόλις τῶν οἰκείων καταστείλας τὸν θόρυβον καὶ στὰς εἰς ἐπήκοον τοῖς ἀρχιερεῦσιν, οὐκέτι θαυμάζειν ἔφη φρουρουμένων ἐν τῷ ἱερῷ τῶν προμάχων τῆς ἐλευθερίας, εἴ γε καὶ τῷ ἔθνει κλείουσί τινες ἤδη τὴν κοινὴν πόλιν, καὶ Ῥωμαίους μὲν εἰσδέχεσθαι παρασκευάζονται τάχα καὶ στεφανώσαντες τὰς πύλας, Ἰδουμαίοις δὲ ἀπὸ τῶν πύργων διαλέγονται καὶ τὰ ὑπὲρ τῆς ἐλευθερίας ὅπλα κελεύουσι ῥῖψαι, μὴ πιστεύοντες δὲ τοῖς συγγενέσι τὴν τῆς μητροπόλεως φυλακὴν τοὺς αὐτοὺς δικαστὰς ποιοῦνται τῶν διαφόρων, καὶ κατηγοροῦντές τινων ὡς ἀποκτείνειαν ἀκρίτους, αὐτοὶ καταδικάζοιεν ὅλου τοῦ ἔθνους ἀτιμίαν· τὴν γοῦν ἅπασι τοῖς ἀλλοφύλοις ἀναπεπταμένην εἰς θρησκείαν πόλιν τοῖς οἰκείοις νῦν ἀποτετείχισθε. πάνυ γὰρ ἐπὶ σφαγὰς ἐσπεύδομεν καὶ τὸν κατὰ τῶν ὁμοφύλων πόλεμον οἱ διὰ τοῦτο ταχύναντες, ἵν’ ὑμᾶς τηρήσωμεν ἐλευθέρους. τοιαῦτα μέντοι καὶ πρὸς τῶν φρουρουμένων ἠδίκησθε, καὶ πιθανὰς οὕτως ὑποψίας οἶμαι κατ’ ἐκείνων συνελέξατε. ἔπειτα τῶν ἔνδον φρουρᾷ κρατοῦντες ὅσοι κήδονται τῶν κοινῶν πραγμάτων, καὶ τοῖς συγγενεστάτοις ἔθνεσιν ἀθρόοις ἀποκλείσαντες μὲν τὴν πόλιν ὑβριστικὰ δ’ οὕτως προστάγματα κελεύοντες, τυραννεῖσθαι λέγετε καὶ τὸ τῆς δυναστείας ὄνομα τοῖς ὑφ’ ὑμῶν τυραννουμένοις περιάπτετε. τίς ἂν ἐνέγκαι τὴν εἰρωνείαν τῶν λόγων ἀφορῶν εἰς τὴν ἐναντιότητα τῶν πραγμάτων; εἰ μὴ καὶ νῦν ὑμᾶς ἀποκλείουσιν Ἰδουμαῖοι τῆς μητροπόλεως, οὓς αὐτοὶ τῶν πατρίων ἱερῶν εἴργετε. μέμψαιτ’ ἂν εἰκότως τις τοὺς ἐν τῷ ἱερῷ πολιορκουμένους, ὅτι θαρσήσαντες τοὺς προδότας κολάζειν, οὓς ὑμεῖς ἄνδρας ἐπισήμους καὶ ἀκαταιτιάτους λέγετε διὰ τὴν κοινωνίαν, οὐκ ἀφ’ ὑμῶν ἤρξαντο καὶ τὰ καιριώτατα τῆς προδοσίας μέρη προαπέκοψαν. ἀλλ’ εἰ κἀκεῖνοι τῆς χρείας ἐγένοντο μαλακώτεροι, τηρήσομεν Ἰδουμαῖοι τὸν οἶκον τοῦ θεοῦ καὶ τῆς κοινῆς πατρίδος προπολεμήσομεν ἅμα τούς τε ἔξωθεν ἐπιόντας καὶ τοὺς ἔνδον προδιδόντας ἀμυνόμενοι πολεμίους. ἐνθάδε πρὸ τῶν τειχῶν μενοῦμεν ἐν τοῖς ὅπλοις, ἕως ἂν Ῥωμαῖοι κάμωσι προσέχοντες ὑμῖν ἢ ὑμεῖς ἐλεύθερα φρονήσαντες μεταβάλησθε.", "st": "4.4.4"}, {"sp": "N", "t": "Τούτοις τὸ μὲν τῶν Ἰδουμαίων ἐπεβόα πλῆθος, ὁ δὲ Ἰησοῦς ἀθυμῶν ἀνεχώρει τοὺς μὲν Ἰδουμαίους μηδὲν φρονοῦντας ὁρῶν μέτριον, διχόθεν δὲ τὴν πόλιν πολεμουμένην. ἦν δὲ οὐδὲ τοῖς Ἰδουμαίοις ἐν ἠρεμίᾳ τὰ φρονήματα· καὶ γὰρ τεθύμωντο πρὸς τὴν ὕβριν εἰρχθέντες τῆς πόλεως καὶ τὰ τῶν ζηλωτῶν ἰσχυρὰ δοκοῦντες ὡς οὐδὲν ἐπαμύνοντας ἑώρων, ἠποροῦντο καὶ μετενόουν πολλοὶ τὴν ἄφιξιν. ἡ δὲ αἰδὼς τοῦ τέλεον ἀπράκτους ὑποστρέφειν ἐνίκα τὴν μεταμέλειαν, ὥστε μένειν αὐτόθι πρὸ τοῦ τείχους κακῶς αὐλιζομένους· διὰ γὰρ τῆς νυκτὸς ἀμήχανος ἐκρήγνυται χειμὼν ἄνεμοί τε βίαιοι σὺν ὄμβροις λαβροτάτοις καὶ συνεχεῖς ἀστραπαὶ βρονταί τε φρικώδεις καὶ μυκήματα σειομένης τῆς γῆς ἐξαίσια. πρόδηλον δὲ ἦν ἐπ’ ἀνθρώπων ὀλέθρῳ τὸ κατάστημα τῶν ὅλων συγκεχυμένον, καὶ οὐχὶ μικροῦ τις ἂν εἰκάσαι συμπτώματος τὰ τέρατα.", "st": "4.4.5"}, {"sp": "N", "t": "Μία δὲ τοῖς Ἰδουμαίοις καὶ τοῖς ἐν τῇ πόλει παρέστη δόξα, τοῖς μὲν ὀργίζεσθαι τὸν θεὸν ἐπὶ τῇ στρατείᾳ καὶ οὐκ ἂν διαφυγεῖν ἐπενεγκόντας ὅπλα τῇ μητροπόλει, τοῖς δὲ περὶ τὸν Ἄνανον νενικηκέναι χωρὶς παρατάξεως καὶ τὸν θεὸν ὑπὲρ αὐτῶν στρατηγεῖν. κακοὶ δ’ ἦσαν ἄρα τῶν μελλόντων στοχασταὶ καὶ κατεμαντεύοντο τῶν ἐχθρῶν ἃ τοῖς ἰδίοις αὐτῶν ἐπῄει παθεῖν. οἱ μὲν γὰρ Ἰδουμαῖοι συσπειραθέντες τοῖς σώμασιν ἀλλήλους ἀντέθαλπον καὶ τοὺς θυρεοὺς ὑπὲρ κεφαλῆς συμφράξαντες ἧττον ἐκακοῦντο τοῖς ὑετοῖς, οἱ δὲ ζηλωταὶ μᾶλλον τοῦ καθ’ αὑτοὺς κινδύνου ὑπὲρ ἐκείνων ἐβασανίζοντο καὶ συνελθόντες ἐσκόπουν, εἴ τινα μηχανὴν αὐτοῖς ἀμύνης ἐπινοήσειαν. τοῖς μὲν οὖν θερμοτέροις ἐδόκει μετὰ τῶν ὅπλων βιάζεσθαι τοὺς παραφυλάσσοντας, ἔπειτα δ’ εἰσπεσόντας εἰς μέσον τῆς πόλεως ἀναφανδὸν ἀνοίγειν τοῖς συμμάχοις τὰς πύλας· τούς τε γὰρ φύλακας εἴξειν πρὸς τὸ ἀδόκητον αὐτῶν τεταραγμένους ἄλλως τε καὶ τοὺς πλείονας [αὐτῶν] ὄντας ἀνόπλους καὶ πολέμων ἀπείρους, καὶ τῶν κατὰ τὴν πόλιν δυσσύνακτον ἔσεσθαι τὸ πλῆθος κατειλημένον ὑπὸ τοῦ χειμῶνος εἰς τὰς οἰκίας. εἰ δὲ καί τις γένοιτο κίνδυνος, πρέπειν αὐτοῖς πᾶν ὁτιοῦν παθεῖν ἢ περιιδεῖν τοσοῦτον πλῆθος δι’ αὐτοὺς αἰσχρῶς ἀπολλύμενον. οἱ δὲ συνετώτεροι βιάζεσθαι μὲν ἀπεγίνωσκον ὁρῶντες οὐ μόνον τὴν αὐτῶν φρουρὰν πληθύουσαν ἀλλὰ καὶ τὸ τῆς πόλεως τεῖχος διὰ τοὺς Ἰδουμαίους ἐπιμελῶς φυλασσόμενον, ᾤοντό τε πανταχοῦ τὸν Ἄνανον παρεῖναι καὶ κατὰ πᾶσαν ὥραν ἐπισκέπτεσθαι τὰς φυλακάς· ὃ δὴ ταῖς μὲν ἄλλαις νυξὶν οὕτως εἶχεν, ἀνείθη δὲ κατ’ ἐκείνην, οὐ κατὰ τὴν Ἀνάνου ῥᾳθυμίαν, ἀλλ’ ὡς αὐτὸς ἐκεῖνος ἀπόλοιτο καὶ τὸ πλῆθος τῶν φυλάκων στρατηγούσης τῆς εἱμαρμένης, ἣ δὴ καὶ τότε τῆς νυκτὸς προκοπτούσης καὶ τοῦ χειμῶνος ἐπακμάζοντος κοιμίζει μὲν τοὺς ἐπὶ τῇ στοᾷ φρουρούς, τοῖς δὲ ζηλωταῖς ἐπίνοιαν ἐμβάλλει τῶν ἱερῶν αἴροντας πριόνων ἐκτεμεῖν τοὺς μοχλοὺς τῶν πυλῶν. συνήργησε δ’ αὐτοῖς πρὸς τὸ μὴ κατακουσθῆναι τὸν ψόφον ὅ τε τῶν ἀνέμων ἦχος καὶ τὸ τῶν βροντῶν ἐπάλληλον.", "st": "4.4.6"}, {"sp": "N", "t": "Διαλανθάνοντες δὲ ἐκ τοῦ ἱεροῦ παραγίνονται πρὸς τὸ τεῖχος καὶ τοῖς αὐτοῖς πρίοσι χρώμενοι τὴν κατὰ τοὺς Ἰδουμαίους ἀνοίγουσι πύλην. τοῖς δὲ τὸ μὲν πρῶτον ἐμπίπτει ταραχὴ τοὺς περὶ τὸν Ἄνανον ἐπιχειρεῖν οἰηθεῖσι, καὶ πᾶς ἐπὶ τοῦ ξίφους ἔσχε τὴν δεξιὰν ὡς ἀμυνούμενος· ταχέως δὲ γνωρίζοντες τοὺς ἥκοντας εἰσῄεσαν. εἰ μὲν οὖν ἐτράποντο περὶ τὴν πόλιν, οὐδὲν ἐκώλυσεν ἂν ἀπολωλέναι τὸν δῆμον αὔτανδρον· οὕτως εἶχον ὀργῆς· νῦν δὲ πρώτους τοὺς ζηλωτὰς σπεύδοντες τῆς φρουρᾶς ἐξελέσθαι, δεομένων πολλὰ καὶ τῶν εἰσδεξαμένων μὴ περιιδεῖν δι’ οὓς ἦλθον ἐν μέσοις τοῖς δεινοῖς μηδ’ αὐτοῖς χαλεπώτερον ἐπισεῖσαι τὸν κίνδυνον· τῶν μὲν γὰρ φρουρῶν ἁλόντων ῥᾴδιον αὐτοῖς εἶναι χωρεῖν ἐπὶ τὴν πόλιν, εἰ δ’ ἅπαξ ταύτην προκινήσειαν, οὐκ ἂν ἔτι ἐκείνων κρατῆσαι· πρὸς γὰρ τὴν αἴσθησιν συντάξεσθαι αὐτοὺς καὶ τὰς ἀνόδους ἀποφράξειν·", "st": "4.4.7"}, {"sp": "N", "t": "Συνεδόκει ταῦτα τοῖς Ἰδουμαίοις, καὶ διὰ τῆς πόλεως ἀνέβαινον πρὸς τὸ ἱερόν, μετέωροί τε οἱ ζηλωταὶ τὴν ἄφιξιν αὐτῶν ἐκαραδόκουν. καὶ παριόντων εἴσω καὶ αὐτοὶ θαρροῦντες προῄεσαν ἐκ τοῦ ἐνδοτέρου ἱεροῦ. μιγέντες δὲ τοῖς Ἰδουμαίοις προσέβαλλον ταῖς φυλακαῖς, καὶ τινὰς μὲν τῶν προκοιτούντων ἀπέσφαξαν κοιμωμένους, πρὸς δὲ τὴν τῶν ἐγρηγορότων βοὴν διανέστη πᾶν τὸ πλῆθος καὶ μετ’ ἐκπλήξεως ἁρπάζοντες τὰ ὅπλα πρὸς τὴν ἄμυναν ἐχώρουν. ἕως μὲν οὖν μόνους τοὺς ζηλωτὰς ἐπιχειρεῖν ὑπελάμβανον, ἐθάρρουν ὡς τῷ πλήθει περιεσόμενοι, κατιδόντες δὲ ἔξωθεν ἐπιχεομένους ἄλλους ᾔσθοντο τὴν εἰσβολὴν τῶν Ἰδουμαίων, καὶ τὸ μὲν πλέον αὐτῶν ἅμα ταῖς ψυχαῖς κατέβαλλε τὰ ὅπλα καὶ πρὸς οἰμωγαῖς ἦν, φραξάμενοι δὲ ὀλίγοι τῶν νέων γενναίως ἐδέχοντο τοὺς Ἰδουμαίους καὶ μέχρι πολλοῦ τὴν ἀργοτέραν πληθὺν ἔσκεπον. οἱ δὲ κραυγῇ διεσήμαινον τοῖς κατὰ τὴν πόλιν τὰς συμφοράς, κἀκείνων ἀμῦναι μὲν οὐδεὶς ἐτόλμησεν, ὡς ἔμαθον εἰσπεπαικότας τοὺς Ἰδουμαίους, ἀργὰ δ’ ἀντεβόων καὶ ἀντωλοφύροντο, καὶ πολὺς κωκυτὸς γυναικῶν ἠγείρετο κινδυνεύοντος ἑκάστῃ τινὸς τῶν φυλάκων. οἱ δὲ ζηλωταὶ τοῖς Ἰδουμαίοις συνεπηλάλαζον καὶ τὴν ἐκ πάντων βοὴν ὁ χειμὼν ἐποίει φοβερωτέραν. ἐφείδοντό τε οὐδενὸς Ἰδουμαῖοι φύσει τε ὠμότατοι φονεύειν ὄντες καὶ τῷ χειμῶνι κεκακωμένοι κατὰ τῶν ἀποκλεισάντων ἐχρῶντο τοῖς θυμοῖς· ἦσαν δ’ ὅμοιοι τοῖς ἱκετεύουσι καὶ τοῖς ἀμυνομένοις καὶ πολλοὺς τήν τε συγγένειαν ἀναμιμνήσκοντας καὶ δεομένους τοῦ κοινοῦ ἱεροῦ λαβεῖν αἰδῶ διήλαυνον τοῖς ξίφεσιν. ἦν δὲ φυγῆς μὲν οὐδεὶς τόπος οὐδὲ σωτηρίας ἐλπίς, συνωθούμενοι δὲ περὶ ἀλλήλους κατεκόπτοντο, καὶ τὸ πλέον ἐκβιαζόμενοι. ὡς οὐκέτ’ ἦν ὑποχωρήσεως τόπος ἐπῄεσαν δὲ οἱ φονεύοντες, ὑπ’ ἀμηχανίας κατεκρήμνιζον ἑαυτοὺς εἰς τὴν πόλιν, οἰκτρότερον ἔμοιγε δοκεῖν οὗ διέφευγον ὀλέθρου τὸν αὐθαίρετον ὑπομένοντες. ἐπεκλύσθη δὲ τὸ ἔξωθεν ἱερὸν πᾶν αἵματι, καὶ νεκροὺς ὀκτακισχιλίους πεντακοσίους ἡ ἡμέρα κατελάμβανεν.", "st": "4.5.1"}, {"sp": "N", "t": "Οὐκ ἐκορέσθησαν δὲ τούτοις οἱ θυμοὶ τῶν Ἰδουμαίων, ἀλλ’ ἐπὶ τὴν πόλιν τραπόμενοι πᾶσαν μὲν οἰκίαν διήρπαζον, ἔκτεινον δὲ τὸν περιτυχόντα. καὶ τὸ μὲν ἄλλο πλῆθος αὐτοῖς ἐδόκει παρανάλωμα, τοὺς δὲ ἀρχιερεῖς ἀνεζήτουν, καὶ κατ’ ἐκείνων ἦν τοῖς πλείστοις ἡ φορά. ταχέως δ’ ἁλόντες διεφθείροντο, καὶ τοῖς νεκροῖς αὐτῶν ἐπιστάντες τὸν μὲν Ἄνανον τῆς πρὸς τὸν δῆμον εὐνοίας. τὸν δὲ Ἰησοῦν τῶν ἀπὸ τοῦ τείχους λόγων ἐπέσκωπτον. προῆλθον δὲ εἰς τοσοῦτον ἀσεβείας ὥστε καὶ ἀτάφους ῥῖψαι, καίτοι τοσαύτην Ἰουδαίων περὶ τὰς ταφὰς πρόνοιαν ποιουμένων, ὥστε καὶ τοὺς ἐκ καταδίκης ἀνεσταυρωμένους πρὸ δύντος ἡλίου καθελεῖν τε καὶ θάπτειν. οὐκ ἂν ἁμάρτοιμι δ’ εἰπὼν ἁλώσεως ἄρξαι τῇ πόλει τὸν Ἀνάνου θάνατον, καὶ ἀπ’ ἐκείνης τῆς ἡμέρας ἀνατραπῆναι τὸ τεῖχος καὶ διαφθαρῆναι τὰ πράγματα Ἰουδαίοις, ἐν ᾗ τὸν ἀρχιερέα καὶ ἡγεμόνα τῆς ἰδίας σωτηρίας αὐτῶν ἐπὶ μέσης τῆς πόλεως εἶδον ἀπεσφαγμένον. ἦν γὰρ δὴ τά τε ἄλλα σεμνὸς ἁνὴρ καὶ δικαιότατος. καὶ παρὰ τὸν ὄγκον τῆς τε εὐγενείας καὶ τῆς ἀξίας καὶ ἧς εἶχε τιμῆς ἠγαπηκὼς τὸ ἰσότιμον καὶ πρὸς τοὺς ταπεινοτάτους, φιλελεύθερός τε ἐκτόπως καὶ δημοκρατίας ἐραστής, πρό τε τῶν ἰδίων λυσιτελῶν τὸ κοινῇ συμφέρον ἀεὶ τιθέμενος καὶ περὶ παντὸς ποιούμενος τὴν εἰρήνην· ἄμαχα γὰρ ᾔδει τὰ Ῥωμαίων· προσκοπούμενος δ’ ὑπ’ ἀνάγκης καὶ τὰ κατὰ τὸν πόλεμον, ὅπως, εἰ μὴ διαλύσαιντο Ἰουδαῖοι, δεξιῶς διαφέροιντο. καθόλου δ’ εἰπεῖν, ζῶντος Ἀνάνου πάντως ἂν διελύθησαν· δεινὸς γὰρ ἦν εἰπεῖν τε καὶ πεῖσαι τὸν δῆμον, ἤδη δὲ ἐχειροῦτο καὶ τοὺς ἐμποδίζοντας· ἢ πολεμοῦντες πλείστην ἂν τριβὴν Ῥωμαίοις παρέσχον ὑπὸ τοιούτῳ στρατηγῷ. παρέζευκτο δ’ αὐτῷ καὶ ὁ Ἰησοῦς, αὐτοῦ μὲν λειπόμενος κατὰ σύγκρισιν, προύχων δὲ τῶν ἄλλων. ἀλλ’ οἶμαι κατακρίνας ὁ θεὸς ὡς μεμιασμένης τῆς πόλεως ἀπώλειαν καὶ πυρὶ βουλόμενος ἐκκαθαρθῆναι τὰ ἅγια τοὺς ἀντεχομένους αὐτῶν καὶ φιλοστοργοῦντας περιέκοπτεν. οἱ δὲ πρὸ ὀλίγου τὴν ἱερὰν ἐσθῆτα περικείμενοι καὶ τῆς κοσμικῆς θρησκείας κατάρχοντες προσκυνούμενοί τε τοῖς ἐκ τῆς οἰκουμένης παραβάλλουσιν εἰς τὴν πόλιν, ἐρριμμένοι γυμνοὶ βορὰ κυνῶν καὶ θηρίων ἐβλέποντο. αὐτὴν ἐπ’ ἐκείνοις στενάξαι τοῖς ἀνδράσι δοκῶ τὴν ἀρετήν, ὀλοφυρομένην ὅτι τοσοῦτον ἥττητο τῆς κακίας. ἀλλὰ [γὰρ] τὸ μὲν Ἀνάνου καὶ Ἰησοῦ τέλος τοιοῦτον ἀπέβη.", "st": "4.5.2"}, {"sp": "N", "t": "Μετὰ δ’ ἐκείνους οἵ τε ζηλωταὶ καὶ τῶν Ἰδουμαίων τὸ πλῆθος τὸν λαὸν ὥσπερ ἀνοσίων ζῴων ἀγέλην ἐπιόντες ἔσφαζον. καὶ τὸ μὲν εἰκαῖον ἐφ’ οὗ καταληφθείη τόπου διεφθείρετο, τοὺς δὲ εὐγενεῖς καὶ νέους συλλαμβάνοντες εἰς εἱρκτὴν κατέκλειον δεδεμένους, κατ’ ἐλπίδα τοῦ προσθήσεσθαί τινας αὐτοῖς τὴν ἀναίρεσιν ὑπερτιθέμενοι. προσέσχε δ’ οὐδείς, ἀλλὰ πάντες τοῦ τάξασθαι μετὰ τῶν πονηρῶν κατὰ τῆς πατρίδος προείλοντο τὸν θάνατον. δεινὰς δὲ τῆς ἀρνήσεως αἰκίας ὑπέμενον μαστιγούμενοί τε καὶ στρεβλούμενοι, μετὰ δὲ τὸ μηκέτ’ ἀρκεῖν τὸ σῶμα ταῖς βασάνοις μόλις ἠξιοῦντο τοῦ ξίφους. οἱ συλληφθέντες δὲ μεθ’ ἡμέραν ἀνῃροῦντο νύκτωρ, καὶ τοὺς νεκροὺς ἐκφοροῦντες ἔρριπτον, ὡς ἑτέροις εἴη δεσμώταις τόπος. ἦν δὲ τοσαύτη τοῦ δήμου κατάπληξις, ὡς μηδένα τολμῆσαι μήτε κλαίειν φανερῶς τὸν προσήκοντα νεκρὸν μήτε θάπτειν, ἀλλὰ λαθραῖα μὲν ἦν αὐτῶν κατακεκλεισμένων τὰ δάκρυα καὶ μετὰ περισκέψεως, μή τις ἐπακούσῃ τῶν ἐχθρῶν, ἔστενον· ἴσα γὰρ τοῖς πενθουμένοις ὁ πενθήσας εὐθὺς ἔπασχε· νύκτωρ δὲ κόνιν αἴροντες χεροῖν ὀλίγην ἐπερρίπτουν τοῖς σώμασι, καὶ μεθ’ ἡμέραν εἴ τις παράβολος. μύριοι καὶ δισχίλιοι τῶν εὐγενῶν νέων οὕτως διεφθάρησαν.", "st": "4.5.3"}, {"sp": "N", "t": "Οἱ δὲ ἤδη διαμεμισηκότες τὸ φονεύειν ἀνέδην εἰρωνεύοντο δικαστήρια καὶ κρίσεις. καὶ δή τινα τῶν ἐπιφανεστάτων ἀποκτείνειν προθέμενοι Ζαχαρίαν υἱὸν Βάρεις· παρώξυνε δὲ αὐτοὺς τὸ λίαν τἀνδρὸς μισοπόνηρον καὶ φιλελεύθερον, ἦν δὲ καὶ πλούσιος, ὥστε μὴ μόνον ἐλπίζειν τὴν ἁρπαγὴν τῆς οὐσίας, ἀλλὰ καὶ προσαποσκευάσεσθαι δυνατὸν ἄνθρωπον εἰς τὴν αὐτῶν κατάλυσιν· συγκαλοῦσι μὲν ἐξ ἐπιτάγματος ἑβδομήκοντα τῶν ἐν τέλει δημοτῶν εἰς τὸ ἱερόν, περιθέντες δ’ αὐτοῖς ὥσπερ ἐπὶ σκηνῆς σχῆμα δικαστῶν ἔρημον ἐξουσίας τοῦ Ζαχαρίου κατηγόρουν, ὡς ἐνδιδοίη τὰ πράγματα Ῥωμαίοις καὶ περὶ προδοσίας διαπέμψαιτο πρὸς Οὐεσπασιανόν. ἦν δὲ οὔτ’ ἔλεγχός τις τῶν κατηγορουμένων οὔτε τεκμήριον, ἀλλ’ αὐτοὶ πεπεῖσθαι καλῶς ἔφασαν καὶ τοῦτ’ εἶναι πίστιν τῆς ἀληθείας ἠξίουν. ὅ γε μὴν Ζαχαρίας συνιδὼν μηδεμίαν αὐτῷ καταλειπομένην σωτηρίας ἐλπίδα, κεκλῆσθαι γὰρ κατ’ ἐνέδραν εἰς εἱρκτήν, οὐκ ἐπὶ δικαστήριον, ἐποιήσατο τὴν τοῦ ζῆν ἀπόγνωσιν οὐκ ἀπαρρησίαστον, ἀλλὰ καταστὰς τὸ μὲν πιθανὸν τῶν κατηγορημένων διεχλεύασε καὶ διὰ βραχέων ἀπελύσατο τὰς ἐπιφερομένας αἰτίας. ἔπειτα δὲ τὸν λόγον εἰς τοὺς κατηγόρους ἀποστρέψας ἑξῆς πάσας αὐτῶν διεξῄει τὰς παρανομίας καὶ πολλὰ περὶ τῆς συγχύσεως κατωλοφύρατο τῶν πραγμάτων. οἱ ζηλωταὶ δ’ ἐθορύβουν καὶ μόλις τῶν ξιφῶν ἀπεκράτουν, τὸ σχῆμα καὶ τὴν εἰρωνείαν τοῦ δικαστηρίου μέχρι τέλους παῖξαι προαιρούμενοι, καὶ ἄλλως πειράσαι θέλοντες τοὺς δικαστάς, εἰ παρὰ τὸν αὐτῶν κίνδυνον μνησθήσονται τοῦ δικαίου. φέρουσι δὲ οἱ ἑβδομήκοντα τῷ κρινομένῳ τὰς ψήφους ἅπαντες καὶ σὺν αὐτῷ προείλοντο τεθνάναι μᾶλλον ἢ τῆς ἀναιρέσεως αὐτοῦ λαβεῖν τὴν ἐπιγραφήν. ἤρθη δὲ βοὴ τῶν ζηλωτῶν πρὸς τὴν ἀπόλυσιν, καὶ πάντων μὲν ἦν ἀγανάκτησις ἐπὶ τοῖς δικασταῖς ὡς μὴ συνιεῖσι τὴν εἰρωνείαν τῆς δοθείσης αὐτοῖς ἐξουσίας, δύο δὲ τολμηρότατοι προσπεσόντες ἐν μέσῳ τῷ ἱερῷ διαφθείρουσι τὸν Ζαχαρίαν καὶ πεσόντι ἐπιχλευάσαντες ἔφασαν καὶ παρ’ ἡμῶν τὴν ψῆφον ἔχεις καὶ βεβαιοτέραν ἀπόλυσιν ῥίπτουσί τε αὐτὸν [εὐθέως] ἀπὸ τοῦ ἱεροῦ κατὰ τῆς ὑποκειμένης φάραγγος. τοὺς δὲ δικαστὰς πρὸς ὕβριν ἀπεστραμμένοις τοῖς ξίφεσι τύπτοντες ἐξέωσαν τοῦ περιβόλου, δι’ ἓν τοῦτο φεισάμενοι τῆς σφαγῆς αὐτῶν, ἵνα σκεδασθέντες ἀνὰ τὴν πόλιν ἄγγελοι πᾶσι τῆς δουλείας γένωνται.", "st": "4.5.4"}, {"sp": "N", "t": "Τοῖς δὲ Ἰδουμαίοις ἤδη τῆς παρουσίας μετέμελε καὶ προσίστατο τὰ πραττόμενα. συναγαγὼν δὲ αὐτούς τις ἀπὸ τῶν ζηλωτῶν κατ’ ἰδίαν ἐλθὼν ἐνεδείκνυτο τὰ συμπαρανομηθέντα τοῖς καλέσασι καὶ τὸ κατὰ τῆς μητροπόλεως διεξῄει· παρατάσσεσθαι μὲν γὰρ ὡς ὑπὸ τῶν ἀρχιερέων προδιδομένης Ῥωμαίοις τῆς μητροπόλεως, εὑρηκέναι δὲ προδοσίας μὲν τεκμήριον οὐδέν, τοὺς δ’ ἐκείνην ὑποκρινομένους φυλάττεσθαι καὶ πολέμου καὶ τυραννίδος ἔργα τολμῶντας. προσήκειν μὲν οὖν αὐτοῖς διακωλύειν ἀπ’ ἀρχῆς· ἐπειδὴ δὲ ἅπαξ εἰς κοινωνίαν ἐμφυλίου φόνου προέπεσον, ὅρον γοῦν ἐπιθεῖναι τοῖς ἁμαρτήμασι καὶ μὴ παραμένειν χορηγοῦντας ἰσχὺν τοῖς καταλύουσι τὰ πάτρια. καὶ γὰρ εἴ τινες χαλεπαίνουσι τὸ κλεισθῆναι τὰς πύλας καὶ μὴ δοθῆναι μετὰ τῶν ὅπλων αὐτοῖς ἑτοίμην τὴν εἴσοδον, ἀλλὰ τοὺς εἴρξαντας τετιμωρῆσθαι· καὶ τεθνάναι μὲν Ἄνανον, διεφθάρθαι δὲ ἐπὶ μιᾶς νυκτὸς ὀλίγου δεῖν πάντα τὸν δῆμον· ἐφ’ οἷς τῶν μὲν οἰκείων πολλοὺς αἰσθάνεσθαι μετανοοῦντας, τῶν ἐπικαλεσαμένων δὲ ὁρᾶν ἄμετρον τὴν ὠμότητα μηδὲ δι’ οὓς ἐσώθησαν αἰδουμένων· ἐν ὄμμασι γοῦν τῶν συμμάχων τὰ αἴσχιστα τολμᾶν, καὶ τὰς ἐκείνων παρανομίας Ἰδουμαίοις προσάπτεσθαι, μέχρις ἂν μήτε κωλύῃ τις μήτε χωρίζηται τῶν δρωμένων. δεῖν οὖν, ἐπειδὴ διαβολὴ μὲν πέφηνε τὰ τῆς προδοσίας, ἔφοδος δὲ Ῥωμαίων οὐδεμία προσδοκᾶται, δυναστεία δ’ ἐπιτετείχισται τῇ πόλει δυσκατάλυτος, αὐτοὺς ἀναχωρεῖν ἐπ’ οἴκου καὶ τῷ μὴ κοινωνεῖν τοῖς φαύλοις ἁπάντων ἀπολογήσασθαι πέρι, ὧν φενακισθέντες μετάσχοιεν.", "st": "4.5.5"}, {"sp": "N", "t": "Τούτοις πεισθέντες οἱ Ἰδουμαῖοι πρῶτον μὲν λύουσι τοὺς ἐν τοῖς δεσμωτηρίοις περὶ δισχιλίους δημότας, οἳ παραχρῆμα φυγόντες ἐκ τῆς πόλεως ἀφικνοῦνται πρὸς Σίμωνα, περὶ οὗ μικρὸν ὕστερον ἐροῦμεν· ἔπειτα ἐκ τῶν Ἱεροσολύμων ἀνεχώρησαν ἐπ’ οἴκου. καὶ συνέβη τὸν χωρισμὸν αὐτῶν γενέσθαι παράδοξον ἀμφοτέροις· ὅ τε γὰρ δῆμος ἀγνοῶν τὴν μετάνοιαν ἀνεθάρσησε πρὸς ὀλίγον ὡς ἐχθρῶν κεκουφισμένος, οἵ τε ζηλωταὶ μᾶλλον ἐπανέστησαν, οὐχ ὡς ὑπὸ συμμάχων καταλειφθέντες, ἀλλ’ ἀπηλλαγμένοι τῶν δυσωπούντων καὶ διατρεπόντων παρανομεῖν. οὐκέτι γοῦν μέλλησις ἢ σκέψις ἦν τῶν ἀδικημάτων, ἀλλ’ ὀξυτάταις μὲν ἐχρῶντο ταῖς ἐπινοίαις εἰς ἕκαστα, τὰ δοχθέντα δὲ τάχιον καὶ τῆς ἐπινοίας ἐνήργουν. μάλιστα δ’ ἐπ’ ἀνδρείαν τε καὶ εὐγένειαν ἐφόνων, τὴν μὲν φθόνῳ λυμαινόμενοι, τὸ δὲ γενναῖον δέει· μόνην γὰρ αὐτῶν ἀσφάλειαν ὑπελάμβανον τὸ μηδένα τῶν δυνατῶν καταλιπεῖν. ἀνῃρέθη γοῦν σὺν πολλοῖς ἑτέροις καὶ Γουρίων, ἀξιώματι μὲν καὶ γένει προύχων, δημοκρατικὸς δὲ καὶ φρονήματος ἐλευθερίου μεστός, εἰ καί τις ἕτερος Ἰουδαίων· ἀπώλεσε δὲ αὐτὸν ἡ παρρησία μάλιστα πρὸς τοῖς ἄλλοις πλεονεκτήμασιν. οὐδ’ ὁ Περαΐτης Νίγερ αὐτῶν τὰς χεῖρας διέφυγεν, ἀνὴρ ἄριστος ἐν τοῖς πρὸς Ῥωμαίους πολέμοις γενόμενος· ὃς καὶ βοῶν πολλάκις τάς τε ὠτειλὰς ἐπιδεικνὺς διὰ μέσης ἐσύρετο τῆς πόλεως. ἐπεὶ δὲ ἔξω τῶν πυλῶν ἦκτο, τὴν σωτηρίαν ἀπογνοὺς περὶ ταφῆς ἱκέτευεν· οἱ δὲ προαπειλήσαντες ἧς ἐπεθύμει μάλιστα γῆς μὴ μεταδώσειν αὐτῷ, τὸν φόνον ἐνήργουν. ἀναιρούμενος δὲ ὁ Νίγερ τιμωροὺς Ῥωμαίους αὐτοῖς ἐπηράσατο λιμόν τε καὶ λοιμὸν ἐπὶ τῷ πολέμῳ καὶ πρὸς ἅπασι τὰς ἀλλήλων χεῖρας· ἃ δὴ πάντα κατὰ τῶν ἀσεβῶν ἐκύρωσεν ὁ θεός, καὶ τὸ δικαιότατον, ὅτι γεύσασθαι τῆς ἀλλήλων ἀπονοίας ἔμελλον οὐκ εἰς μακρὰν στασιάσαντες. Νίγερ μὲν οὖν ἀνῃρημένος τοὺς περὶ τῆς καταλύσεως αὐτῶν φόβους ἐπεκούφισε, τοῦ λαοῦ δὲ μέρος οὐδὲν ἦν, ᾧ μὴ πρὸς ἀπώλειαν ἐπενοεῖτο πρόφασις. τὸ μὲν γὰρ αὐτῶν διενεχθέν τινι πάλαι διέφθαρτο, τὸ δὲ μὴ προσκροῦσαν κατ’ εἰρήνην ἐπικαίρους ἐλάμβανε τὰς αἰτίας· καὶ ὁ μὲν μηδ’ ὅλως αὐτοῖς προσιὼν ὡς ὑπερήφανος, ὁ προσιὼν δὲ μετὰ παρρησίας ὡς καταφρονῶν, ὁ θεραπεύων δ’ ὡς ἐπίβουλος ὑπωπτεύετο. μία δὲ ἦν τῶν τε μεγίστων καὶ μετριωτάτων ἐγκλημάτων τιμωρία θάνατος· καὶ διέφυγεν οὐδείς, εἰ μὴ σφόδρα τις ἦν ταπεινὸς ἢ δι’ ἀγένειαν ἢ διὰ τύχην.", "st": "4.6.1"}, {"sp": "N", "t": "Ῥωμαίων δὲ οἱ μὲν ἄλλοι πάντες ἡγεμόνες ἕρμαιον ἡγούμενοι τὴν στάσιν τῶν πολεμίων ὥρμηντο πρὸς τὴν πόλιν καὶ τὸν Οὐεσπασιανὸν ἤπειγον ὡς ἂν ὄντα κύριον τῶν ὅλων, φάμενοι πρόνοιαν θεοῦ σύμμαχον σφίσι τῷ τετράφθαι τοὺς ἐχθροὺς κατ’ ἀλλήλων· εἶναι μέντοι τὴν ῥοπὴν ὀξεῖαν, καὶ ταχέως Ἰουδαίους ὁμονοήσειν [ἡμῖν] ἢ κοπιάσαντας ἐν τοῖς ἐμφυλίοις κακοῖς ἢ μετανοήσαντας. Οὐεσπασιανὸς δὲ πλεῖστον αὐτοὺς ἔφη τοῦ δέοντος ἁμαρτάνειν, ὥσπερ ἐν θεάτρῳ χειρῶν τε καὶ ὅπλων ἐπίδειξιν ποιήσασθαι γλιχομένους οὐκ ἀκίνδυνον, ἀλλὰ μὴ τὸ συμφέρον καὶ τἀσφαλὲς σκοποῦντας. εἰ μὲν γὰρ εὐθέως ὁρμήσειεν ἐπὶ τὴν πόλιν, αἴτιος ὁμονοίας ἔσεσθαι τοῖς πολεμίοις καὶ τὴν ἰσχὺν αὐτῶν ἀκμάζουσαν ἐφ’ ἑαυτὸν ἐπιστρέψειν· εἰ δὲ περιμείνειεν, ὀλιγωτέροις χρήσεσθαι δαπανηθεῖσιν ἐν τῇ στάσει. στρατηγεῖν μὲν γὰρ ἄμεινον αὐτοῦ τὸν θεὸν ἀπονητὶ Ῥωμαίοις παραδιδόντα Ἰουδαίους καὶ τὴν νίκην ἀκινδύνως τῇ στρατιᾷ χαριζόμενον· ὥστε χρῆναι διαφθειρομένων χερσὶν οἰκείαις τῶν ἐχθρῶν καὶ τῷ μεγίστῳ κακῷ στάσει χρωμένων θεατὰς μᾶλλον αὐτοὺς ἀποκαθῆσθαι τῶν κινδύνων ἢ θανατῶσιν ἀνθρώποις καὶ λελυσσηκόσιν κατ’ ἀλλήλων χεῖρα μίσγειν. εἰ δέ τις οἴεται τὴν δόξαν τῆς νίκης ἑωλοτέραν ἔσεσθαι δίχα μάχης, γνώτω τοῦ διὰ τῶν ὅπλων σφαλεροῦ τὸ μετὰ ἡσυχίας κατόρθωμα λυσιτελέστερον· καὶ γὰρ οὐχ ἧττον εὐκλεεῖς οἴεσθαι χρὴ τῶν κατὰ χεῖρα λαμπρῶν τοὺς ἐγκρατείᾳ καὶ συνέσει τὰ ἴσα πράξαντας. ἅμα μέντοι μειουμένων τῶν πολεμίων καὶ τὴν αὑτοῦ στρατιὰν ἀναληφθεῖσαν ἐκ τῶν συνεχῶν πόνων ἐρρωμενέστερον ἄξειν. ἄλλως τε καὶ τῶν στοχαζομένων τῆς περὶ τὴν νίκην λαμπρότητος οὐ τοῦτον εἶναι τὸν καιρόν· οὐ γὰρ περὶ κατασκευὴν ὅπλων ἢ τειχῶν οὐδὲ περὶ συλλογὴν ἐπικούρων Ἰουδαίους ἀσχολεῖσθαι, καὶ τὴν ὑπέρθεσιν ἔσεσθαι κατὰ τῶν διδόντων, ἀλλ’ ἐμφυλίῳ πολέμῳ καὶ διχονοίᾳ τραχηλιζομένους καθ’ ἡμέραν οἰκτρότερα πάσχειν ὧν ἂν ἐπελθόντες αὐτοὶ διαθεῖεν αὐτοὺς ἁλόντας. εἴτ’ οὖν τἀσφαλές τις σκοποίη, χρῆναι τοὺς ὑφ’ ἑαυτῶν ἀναλισκομένους ἐᾶν, εἴτε τὸ εὐκλεέστερον τοῦ κατορθώματος, οὐ δεῖν τοῖς οἴκοι νοσοῦσιν ἐπιχειρεῖν· ῥηθήσεσθαι γὰρ εὐλόγως οὐκ αὐτῶν τὴν νίκην ἀλλὰ τῆς στάσεως.", "st": "4.6.2"}, {"sp": "N", "t": "Ταῦτα Οὐεσπασιανῷ λέγοντι συνῄνουν οἱ ἡγεμόνες, καὶ παραχρῆμα τὸ στρατηγικὸν τῆς γνώμης ἀνεφαίνετο· πολλοὶ γοῦν καθ’ ἡμέραν ηὐτομόλουν τοὺς ζηλωτὰς διαδιδράσκοντες. χαλεπὴ δ’ ἦν ἡ φυγὴ φρουραῖς διειληφότων τὰς διεξόδους πάσας καὶ τὸν ὁπωσοῦν ἐν αὐταῖς ἁλισκόμενον ὡς πρὸς Ῥωμαίους ἀπιόντα διαχρωμένων. ὅ γε μὴν χρήματα δοὺς ἐξηφίετο καὶ μόνος ἦν ὁ μὴ διδοὺς προδότης, ὥστε κατελείπετο τῶν εὐπόρων τὴν φυγὴν ὠνουμένων μόνους ἐναποσφάττεσθαι τοὺς πένητας. νεκροὶ δὲ κατὰ τὰς λεωφόρους πάσας ἐσωρεύοντο παμπληθεῖς, καὶ πολλοὶ τῶν ὁρμωμένων αὐτομολεῖν πάλιν τὴν ἔνδον ἀπώλειαν ᾑροῦντο· τὸν γὰρ ἐπὶ τῆς πατρίδος θάνατον ἐλπὶς ταφῆς ἐποίει δοκεῖν μετριώτερον. οἱ δὲ εἰς τοσοῦτον ὠμότητος ἐξώκειλαν, ὡς μήτε τοῖς ἔνδον ἀναιρουμένοις μήτε τοῖς ἀνὰ τὰς ὁδοὺς μεταδοῦναι γῆς, ἀλλὰ καθάπερ συνθήκας πεποιημένοι τοῖς τῆς πατρίδος συγκαταλῦσαι καὶ τοὺς τῆς φύσεως νόμους ἅμα τε τοῖς εἰς ἀνθρώπους ἀδικήμασιν συμμιᾶναι καὶ τὸ θεῖον, ὑφ’ ἡλίῳ τοὺς νεκροὺς μυδῶντας ἀπέλειπον. τοῖς δὲ θάπτουσί τινα τῶν προσηκόντων ὃ καὶ τοῖς αὐτομολοῦσιν ἐπιτίμιον θάνατος ἦν, καὶ δεῖσθαι παραχρῆμα ταφῆς ἔδει τὸν ἑτέρῳ χαριζόμενον. καθόλου τε εἰπεῖν, οὐδὲν οὕτως ἀπολώλει χρηστὸν πάθος ἐν ταῖς τότε συμφοραῖς ὡς ἔλεος· ἃ γὰρ ἐχρῆν οἰκτείρειν, ταῦτα παρώξυνε τοὺς ἀλιτηρίους, καὶ ἀπὸ μὲν τῶν ζώντων ἐπὶ τοὺς ἀνῃρημένους, ἀπὸ δὲ τῶν νεκρῶν ἐπὶ τοὺς ζῶντας τὰς ὀργὰς μετέφερον· καὶ δι’ ὑπερβολὴν δέους ὁ περιὼν τοὺς προληφθέντας ὡς ἀναπαυσαμένους ἐμακάριζεν οἵ τε ἐν τοῖς δεσμωτηρίοις αἰκιζόμενοι κατὰ σύγκρισιν καὶ τοὺς ἀτάφους ἀπέφαινον εὐδαίμονας. κατεπατεῖτο μὲν οὖν πᾶς αὐτοῖς θεσμὸς ἀνθρώπων, ἐγελᾶτο δὲ τὰ θεῖα, καὶ τοὺς τῶν προφητῶν χρησμοὺς ὥσπερ ἀγυρτικὰς λογοποιίας ἐχλεύαζον. πολλὰ δ’ οὗτοι περὶ ἀρετῆς καὶ κακίας προεθέσπισαν, ἃ παραβάντες οἱ ζηλωταὶ καὶ τὴν κατὰ τῆς πατρίδος προφητείαν τέλους ἠξίωσαν. ἦν γὰρ δή τις παλαιὸς λόγος ἀνδρῶν † ἔνθα τότε τὴν πόλιν ἁλώσεσθαι καὶ καταφλέξεσθαι τὸ ἁγιώτατον νόμῳ πολέμου, στάσις ἐὰν κατασκήψῃ καὶ χεῖρες οἰκεῖαι προμιάνωσι τὸ τοῦ θεοῦ τέμενος· οἷς οὐκ ἀπιστήσαντες οἱ ζηλωταὶ διακόνους αὑτοὺς ἐπέδοσαν.", "st": "4.6.3"}, {"sp": "N", "t": "Ἤδη δὲ Ἰωάννῃ τυραννιῶντι τὸ πρὸς τοὺς ὁμοίους ἰσότιμον ἠδοξεῖτο, καὶ κατ’ ὀλίγους προσποιούμενος τῶν πονηροτέρων ἀφηνίαζε τοῦ συντάγματος. ἀεὶ δὲ τοῖς μὲν τῶν ἄλλων δόγμασιν ἀπειθῶν, τὰ δὲ αὑτοῦ προστάσσων δεσποτικώτερον, δῆλος ἦν μοναρχίας ἀντιποιούμενος. εἶκον δ’ αὐτῷ τινὲς μὲν δέει, τινὲς δὲ κατ’ εὔνοιαν, δεινὸς γὰρ ἦν ἀπάτῃ καὶ λόγῳ προσαγαγέσθαι, πολλοὶ δὲ πρὸς ἀσφαλείας ἡγούμενοι τῆς αὑτῶν τὰς αἰτίας ἤδη τῶν τολμωμένων ἐφ’ ἕνα καὶ μὴ πολλοὺς ἀναφέρεσθαι. τό γε μὴν δραστήριον αὐτοῦ κατά τε χεῖρα καὶ κατὰ γνώμην δορυφόρους εἶχεν οὐκ ὀλίγους. πολλὴ δὲ μοῖρα τῶν ἀντικαθισταμένων ἀπελείπετο, παρ’ οἷς ἴσχυε μὲν καὶ φθόνος δεινὸν ἡγουμένων ὑποτετάχθαι τὸ πρὶν ἰσοτίμῳ, τὸ πλέον δ’ εὐλάβεια τῆς μοναρχίας ἀπέτρεπεν· οὔτε γὰρ καταλύσειν ῥᾳδίως ἤλπιζον αὐτὸν ἅπαξ κρατήσαντα, καὶ καθ’ αὑτῶν πρόφασιν ἕξειν τὸ τὴν ἀρχὴν ἀντιπρᾶξαι· προῃρεῖτο δ’ οὖν πολεμῶν ἕκαστος ὁτιοῦν παθεῖν ἢ δουλεύσας ἑκουσίως ἐν ἀνδραπόδου μοίρᾳ παραπολέσθαι. διαιρεῖται μὲν οὖν ἡ στάσις ἐκ τούτων, καὶ τοῖς ἐναντιωθεῖσιν Ἰωάννης ἀντεβασίλευσεν. ἀλλὰ τὰ μὲν πρὸς ἀλλήλους αὐτοῖς διὰ φυλακῆς ἦν, καὶ οὐδὲν ἢ μικρὸν εἴ ποτε διηκροβολίζοντο τοῖς ὅπλοις, ἤριζον δὲ κατὰ τοῦ δήμου καὶ πότεροι πλείονα λείαν ἄξουσιν ἀντεφιλονείκουν. ἐπεὶ δὲ ἡ πόλις τρισὶ τοῖς μεγίστοις κακοῖς ἐχειμάζετο, πολέμῳ καὶ τυραννίδι καὶ στάσει, κατὰ σύγκρισιν μετριώτερον ἦν τοῖς δημοτικοῖς ὁ πόλεμος· ἀμέλει διαδιδράσκοντες ἐκ τῶν οἰκείων ἔφευγον πρὸς τοὺς ἀλλοφύλους καὶ παρὰ Ῥωμαίοις ἧς ἀπήλπισαν ἐν τοῖς ἰδίοις σωτηρίας ἠξιοῦντο.", "st": "4.7.1"}, {"sp": "N", "t": "Τέταρτον δὲ ἄλλο κακὸν ἐκινεῖτο πρὸς τὴν τοῦ ἔθνους κατάλυσιν. φρούριον ἦν οὐ πόρρω Ἱεροσολύμων καρτερώτατον, ὑπὸ τῶν ἀρχαίων βασιλέων εἴς τε ὑπέκθεσιν κτήσεως ἐν πολέμου ῥοπαῖς καὶ σωμάτων ἀσφάλειαν κατεσκευασμένον, ὃ ἐκαλεῖτο Μασάδα. τοῦτο κατειληφότες οἱ προσαγορευόμενοι σικάριοι τέως μὲν τὰς πλησίον χώρας κατέτρεχον οὐδὲν πλέον τῶν ἐπιτηδείων ποριζόμενοι· δέει γὰρ ἀνεστέλλοντο τῆς πλείονος ἁρπαγῆς· ὡς [δὲ] τὴν Ῥωμαίων στρατιὰν ἠρεμοῦσαν, στάσει δὲ καὶ τυραννίδι ἰδίᾳ τοὺς ἐν Ἱεροσολύμοις Ἰουδαίους ἐπύθοντο διῃρημένους, ἁδροτέρων ἥπτοντο τολμημάτων. καὶ κατὰ τὴν ἑορτὴν τῶν ἀζύμων, ἣν ἄγουσιν Ἰουδαῖοι σωτήρια ἐξ οὗ τῆς ὑπ’ Αἰγυπτίοις δουλείας ἀνεθέντες εἰς τὴν πάτριον γῆν κατῆλθον, νύκτωρ τοὺς ἐμποδὼν ὄντας διαλαθόντες πολίχνην τινὰ κατατρέχουσιν καλουμένην Ἐνγαδδί, ἐν ᾗ τὸ μὲν ἀμύνεσθαι δυνάμενον πρὶν ὅπλων ἅψασθαι καὶ συνελθεῖν φθάσαντες ἐσκέδασαν καὶ τῆς πόλεως ἐξέβαλον, τὸ δὲ φυγεῖν ἧττον ὄν, γύναιά τε καὶ παῖδας, ὑπὲρ ἑπτακοσίους ἀναιροῦσιν. ἔπειτα τούς τε οἴκους ἐξεσκευασμένοι καὶ τῶν καρπῶν τοὺς ἀκμαιοτάτους ἁρπάσαντες ἀνήνεγκαν εἰς τὴν Μασάδαν. καὶ οἱ μὲν ἐλῄζοντο πάσας τὰς περὶ τὸ φρούριον κώμας καὶ τὴν χώραν ἐπόρθουν ἅπασαν προσδιαφθειρομένων αὐτοῖς καθ’ ἡμέραν ἑκασταχόθεν οὐκ ὀλίγων· ἐκινεῖτο δὲ καὶ κατὰ τὰ ἄλλα τῆς Ἰουδαίας κλίματα τὸ τέως ἠρεμοῦν τὸ λῃστρικόν, καθάπερ δὲ ἐν σώματι τοῦ κυριωτάτου φλεγμαίνοντος πάντα τὰ μέλη συνενόσει· διὰ γοῦν τὴν ἐν τῇ μητροπόλει στάσιν καὶ ταραχὴν ἄδειαν ἔσχον οἱ κατὰ τὴν χώραν πονηροὶ τῶν ἁρπαγῶν καὶ τὰς οἰκείας ἕκαστος κώμας ἁρπάζοντες ἔπειτα εἰς τὴν ἐρημίαν ἀφίσταντο. συναθροιζόμενοί τε καὶ συνομνύμενοι κατὰ λόχους στρατιᾶς μὲν ὀλιγώτεροι πλείους δὲ λῃστηρίου προσέπιπτον ἱεροῖς καὶ πόλεσιν, καὶ κακοῦσθαι μὲν συνέβαινεν ἐφ’ οὓς ὁρμήσειαν ὡς ἐν πολέμῳ καταληφθέντας, φθάνεσθαι δὲ τὰς ἀμύνας ὡς λῃστῶν ἅμα ταῖς ἁρπαγαῖς ἀποδιδρασκόντων. οὐδὲν δὲ μέρος ἦν τῆς Ἰουδαίας, ὃ μὴ τῇ προανεχούσῃ πόλει συναπώλλυτο.", "st": "4.7.2"}, {"sp": "N", "t": "Ταῦτα Οὐεσπασιανῷ παρὰ τῶν αὐτομόλων διηγγέλλετο. καίπερ γὰρ φρουρούντων τὰς ἐξόδους τῶν στασιαστῶν ἁπάσας καὶ διαφθειρόντων τοὺς ὁπωσοῦν προσιόντας, ὅμως ἦσαν οἳ διελάνθανον καὶ καταφεύγοντες εἰς τοὺς Ῥωμαίους τὸν στρατηγὸν ἐνῆγον ἀμῦναι τῇ πόλει καὶ τὰ τοῦ δήμου περισῶσαι λείψανα· διὰ γὰρ τὴν πρὸς Ῥωμαίους εὔνοιαν ἀνῃρῆσθαί τε τοὺς πολλοὺς καὶ κινδυνεύειν τοὺς περιόντας. ὁ δὲ οἰκτείρων ἤδη τὰς συμφορὰς αὐτῶν τὸ μὲν δοκεῖν ἐκπολιορκήσων ἐφίσταται τὰ Ἱεροσόλυμα, τὸ δὲ ἀληθὲς ἀπαλλάξων πολιορκίας. ἔδει μὲν προκαταστρέψασθαι τὰ λειπόμενα καὶ μηδὲν ἔξωθεν ἐμπόδιον τῇ πολιορκίᾳ καταλιπεῖν· ἐλθὼν οὖν ἐπὶ τὰ Γάδαρα μητρόπολιν τῆς Περαίας καρτερὰν τετράδι Δύστρου μηνὸς εἴσεισιν εἰς τὴν πόλιν· καὶ γὰρ ἔτυχον οἱ δυνατοὶ λάθρα τῶν στασιωδῶν πρεσβευσάμενοι πρὸς αὐτὸν περὶ παραδόσεως πόθῳ τε εἰρήνης καὶ διὰ τὰς οὐσίας· πολλοὶ δὲ τὰ Γάδαρα κατῴκουν πλούσιοι. τούτων τὴν πρεσβείαν ἠγνοήκεσαν οἱ διάφοροι, πλησίον δὲ ἤδη ὄντος Οὐεσπασιανοῦ διεπύθοντο, καὶ κατασχεῖν μὲν αὐτοὶ τὴν πόλιν ἀπέγνωσαν δύνασθαι τῶν τε ἔνδον ἐχθρῶν πλήθει λειπόμενοι καὶ Ῥωμαίους ὁρῶντες οὐ μακρὰν τῆς πόλεως, φεύγειν δὲ κρίνοντες ἠδόξουν ἀναιμωτὶ καὶ μηδεμίαν παρὰ τῶν αἰτίων εἰσπραξάμενοι τιμωρίαν. συλλαβόντες δὴ τὸν Δόλεσον, οὗτος γὰρ ἦν οὐ μόνον ἀξιώματι καὶ γένει τῆς πόλεως πρῶτος, ἀλλ’ ἐδόκει καὶ τῆς πρεσβείας αἴτιος, κτείνουσί τε αὐτὸν καὶ δι’ ὑπερβολὴν ὀργῆς νεκρὸν αἰκισάμενοι διέδρασαν ἐκ τῆς πόλεως. ἐπιούσης δὲ ἤδη τῆς Ῥωμαϊκῆς δυνάμεως ὅ τε δῆμος τῶν Γαδαρέων μετ’ εὐφημίας τὸν Οὐεσπασιανὸν εἰσδεξάμενοι δεξιὰς παρ’ αὐτοῦ πίστεως ἔλαβον καὶ φρουρὰν ἱππέων τε καὶ πεζῶν πρὸς τὰς τῶν φυγάδων καταδρομάς· τὸ γὰρ τεῖχος αὐτοὶ πρὶν ἀξιῶσαι Ῥωμαίους καθεῖλον, ὅπως εἴη πίστις αὐτοῖς τοῦ τὴν εἰρήνην ἀγαπᾶν τὸ μηδὲ βουληθέντας δύνασθαι πολεμεῖν.", "st": "4.7.3"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ ἐπὶ μὲν τοὺς διαδράντας ἐκ τῶν Γαδάρων Πλάκιδον σὺν ἱππεῦσιν πεντακοσίοις καὶ πεζοῖς τρισχιλίοις πέμπει, αὐτὸς δὲ μετὰ τῆς ἄλλης στρατιᾶς ὑπέστρεψεν εἰς Καισάρειαν. οἱ δὲ φυγάδες ὡς αἰφνίδιον τοὺς διώκοντας ἱππεῖς ἐθεάσαντο, πρὶν εἰς χεῖρας ἐλθεῖν εἴς τινα κώμην συνειλοῦνται Βηθενναβρὶν προσαγορευομένην· ἐν ᾗ νέων πλῆθος οὐκ ὀλίγον εὑρόντες καὶ τοὺς μὲν ἑκόντας τοὺς δὲ βίᾳ καθοπλίσαντες εἰκαίως, προπηδῶσιν ἐπὶ τοὺς περὶ τὸν Πλάκιδον. οἱ δὲ πρὸς μὲν τὴν πρώτην ἐμβολὴν ὀλίγον εἶξαν ἅμα καὶ προκαλέσασθαι τεχνιτεύοντες αὐτοὺς ἀπὸ τοῦ τείχους πορρωτέρω, λαβόντες δ’ εἰς ἐπιτήδειον περιήλαυνόν τε καὶ κατηκόντιζον, καὶ τοὺς μὲν φυγάδας αὐτῶν οἱ ἱππεῖς ὑπετέμνοντο, τὰς συμπλοκὰς δὲ τὸ πεζὸν εὐτόνως διέφθειρον. οὐ μέντοι πλέον τι τόλμης ἐπιδεικνύμενοι Ἰουδαῖοι διεφθείροντο· πεπυκνωμένοις γὰρ τοῖς Ῥωμαίοις προσπίπτοντες καὶ ταῖς πανοπλίαις ὥσπερ τετειχισμένοις, αὐτοὶ μὲν οὐχ εὕρισκον βέλους παράδυσιν οὐδ’ ηὐτόνουν ῥῆξαι τὴν φάλαγγα, περιεπείροντο δὲ τοῖς ἐκείνων βέλεσι καὶ τοῖς ἀγριωτάτοις παραπλήσιοι θηρίοις ὥρμων ἐπὶ τὸν σίδηρον, διεφθείροντο δ’ οἱ μὲν κατὰ στόμα παιόμενοι τοῖς ξίφεσιν, οἱ δὲ ὑπὸ τῶν ἱππέων σκεδαννύμενοι.", "st": "4.7.4"}, {"sp": "N", "t": "Σπουδὴ γὰρ ἦν τῷ Πλακίδῳ τὰς ἐπὶ τὴν κώμην ὁρμὰς αὐτῶν διακλείειν. καὶ συνεχῶς παρελαύνων κατ’ ἐκεῖνο τὸ μέρος, ἔπειτα ἐπιστρέφων ἅμα καὶ τοῖς βέλεσι χρώμενος εὐστόχως ἀνῄρει τοὺς πλησιάζοντας καὶ δέει τοὺς πόρρωθεν ἀνέστρεφεν, μέχρι βίᾳ διεκπεσόντες οἱ γενναιότατοι πρὸς τὸ τεῖχος διέφευγον. ἀπορία δ’ εἶχε τοὺς φύλακας· οὔτε γὰρ ἀποκλεῖσαι τοὺς ἀπὸ τῶν Γαδάρων ὑπέμενον διὰ τοὺς σφετέρους καὶ δεξάμενοι συναπολεῖσθαι προσεδόκων. ὃ δὴ καὶ συνέβη· συνωσθέντων γὰρ αὐτῶν εἰς τὸ τεῖχος παρ’ ὀλίγον μὲν οἱ τῶν Ῥωμαίων ἱππεῖς συνεισέπεσον, οὐ μὴν ἀλλὰ καὶ φθασάντων ἀποκλεῖσαι τὰς πύλας προσβαλὼν ὁ Πλάκιδος καὶ μέχρι δείλης γενναίως ἀγωνισάμενος τοῦ τείχους καὶ τῶν ἐν τῇ κώμῃ ἐκράτει. τὰ μὲν οὖν ἀργὰ πλήθη διεφθείρετο, φυγὴ δὲ ἦν τῶν δυνατωτέρων, τὰς δ’ οἰκίας οἱ στρατιῶται διήρπασαν καὶ τὴν κώμην ἐνέπρησαν. οἱ δὲ διαδράντες ἐξ αὐτῆς τοὺς κατὰ τὴν χώραν συνανέστησαν, καὶ τὰς μὲν αὐτῶν συμφορὰς ἐξαίροντες ἐπὶ μεῖζον, τῶν δὲ Ῥωμαίων τὴν στρατιὰν πᾶσαν ἐπιέναι λέγοντες πάντας πανταχόθεν ἐξέσεισαν τῷ δέει, γενόμενοί τε παμπληθεῖς ἔφευγον ἐπὶ Ἱεριχοῦντος· αὕτη γὰρ ἔτι μόνη τὰς ἐλπίδας αὐτῶν ἔθαλπε τῆς σωτηρίας καρτερὰ πλήθει γε οἰκητόρων. Πλάκιδος δὲ τοῖς ἱππεῦσι καὶ ταῖς προαγούσαις εὐπραγίαις τεθαρρηκὼς εἵπετο, καὶ μέχρι μὲν Ἰορδάνου τοὺς ἀεὶ καταλαμβανομένους ἀνῄρει, συνελάσας δὲ πρὸς τὸν ποταμὸν πᾶν τὸ πλῆθος εἰργομένους ὑπὸ τοῦ ῥεύματος, τραφὲν γὰρ ὑπ’ ὄμβρων ἄβατον ἦν, ἀντικρὺ παρετάσσετο. παρώξυνε δ’ ἡ ἀνάγκη πρὸς μάχην τοὺς φυγῆς τόπον οὐκ ἔχοντας, καὶ ταῖς ὄχθαις ἐπὶ μήκιστον παρεκτείναντες σφᾶς αὐτοὺς ἐδέχοντο τὰ βέλη καὶ τὰς τῶν ἱππέων ἐμβολάς, οἳ πολλοὺς αὐτῶν παίοντες εἰς τὸ ῥεῦμα κατέβαλον. καὶ τὸ μὲν ἐν χερσὶν αὐτῶν διαφθαρὲν μύριοι πεντακισχίλιοι, τὸ δὲ βιασθὲν ἐμπηδῆσαι εἰς τὸν Ἰορδάνην πλῆθος ἑκουσίως ἄπειρον ἦν. ἑάλωσαν δὲ περὶ δισχιλίους καὶ διακοσίους λεία τε παμπληθὴς ὄνων τε καὶ προβάτων καὶ καμήλων καὶ βοῶν.", "st": "4.7.5"}, {"sp": "N", "t": "Ἰουδαίοις μὲν οὖν οὐδὲν ἐλάττων ἥδε ἡ πληγὴ προσπεσοῦσα καὶ μείζων ἔδοξεν ἑαυτῆς διὰ τὸ μὴ μόνον τὴν χώραν ἅπασαν δι’ ἧς ἔφευγον πληρωθῆναι φόνου μηδὲ νεκροῖς διαβατὸν γενέσθαι τὸν Ἰορδάνην, ἐμπλησθῆναι δὲ τῶν σωμάτων καὶ τὴν Ἀσφαλτικὴν λίμνην, εἰς ἣν παμπληθεῖς ὑπὸ τοῦ ποταμοῦ κατεσύρησαν. Πλάκιδος δὲ δεξιᾷ τύχῃ χρώμενος ὥρμησεν ἐπὶ τὰς πέριξ πολίχνας τε καὶ κώμας, καταλαμβανόμενός τε Ἄβιλα καὶ Ἰουλιάδα καὶ Βησιμὼ τάς τε μέχρι [τῆς] Ἀσφαλτίτιδος πάσας ἐγκαθίστησιν ἑκάστῃ τοὺς ἐπιτηδείους τῶν αὐτομόλων. ἔπειτα σκάφεσιν ἐπιβήσας τοὺς στρατιώτας αἱρεῖ τοὺς εἰς τὴν λίμνην καταφεύγοντας. καὶ τὰ μὲν κατὰ τὴν Περαίαν προσεχώρησεν ἢ ἑάλω πάντα μέχρι Μαχαιροῦντος.", "st": "4.7.6"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ τὸ περὶ τὴν Γαλατίαν ἀγγέλλεται κίνημα καὶ Οὐίνδιξ ἅμα τοῖς δυνατοῖς τῶν ἐπιχωρίων ἀφεστὼς Νέρωνος, περὶ ὧν ἐν ἀκριβεστέροις ἀναγέγραπται. Οὐεσπασιανὸν δ’ ἐπήγειρεν εἰς τὴν ὁρμὴν τοῦ πολέμου τὰ ἠγγελμένα προορώμενον ἤδη τοὺς μέλλοντας ἐμφυλίους πολέμους καὶ τὸν ὅλης κίνδυνον τῆς ἡγεμονίας, ἐν ᾧ προειρηνεύσας τὰ κατὰ τὴν ἀνατολὴν ἐπικουφίσειν ᾤετο τοὺς κατὰ τὴν Ἰταλίαν φόβους. ἕως μὲν οὖν ἐπεῖχεν ὁ χειμὼν τὰς ὑπηγμένας διησφαλίζετο κώμας τε καὶ πολίχνας φρουραῖς, δεκαδάρχας μὲν κώμαις ἐγκαθιστάς, ἑκατοντάρχας δὲ πόλεσι· πολλὰ δὲ ἀνῴκιζε καὶ τῶν πεπορθημένων. ὑπὸ δὲ τὴν ἀρχὴν τοῦ ἔαρος ἀναλαβὼν τὸ πλέον τῆς δυνάμεως ἤγαγεν ἀπὸ τῆς Καισαρείας ἐπὶ Ἀντιπατρίδος, ἔνθα δυσὶν ἡμέραις καταστησάμενος τὴν πόλιν τῇ τρίτῃ προῄει πορθῶν καὶ καίων τὰς πέριξ πάσας. καταστρεψάμενος δὲ τὰ περὶ τὴν Θαμνὰ τοπαρχίαν ἐπὶ Λύδδων καὶ Ἰαμνείας ἐχώρει καὶ προκεχειρωμέναις ἑκατέραις ἐγκαταστήσας οἰκήτορας τῶν προσκεχωρηκότων ἱκανοὺς εἰς Ἀμμαοῦντα ἀφικνεῖται. καταλαβόμενος δὲ τὰς ἐπὶ τὴν μητρόπολιν αὐτῶν εἰσβολὰς στρατόπεδόν τε τειχίζει καὶ τὸ πέμπτον ἐν αὐτῇ τάγμα καταλιπὼν πρόεισι μετὰ τῆς ἄλλης δυνάμεως ἐπὶ τὴν Βεθλεπτηνφῶν τοπαρχίαν. πυρὶ δὲ αὐτήν τε καὶ τὴν γειτνιῶσαν ἀνελὼν καὶ τὰ πέριξ τῆς Ἰδουμαίας φρούρια τοῖς ἐπικαίροις τόποις ἐπετείχισε· καταλαβόμενος δὲ δύο κώμας τὰς μεσαιτάτας τῆς Ἰδουμαίας, Βήταβριν καὶ Καφάρτοβαν, κτείνει μὲν ὑπὲρ μυρίους, αἰχμαλωτίζεται δὲ ὑπὲρ χιλίους, καὶ τὸ λοιπὸν πλῆθος ἐξελάσας ἐγκαθίστησιν τῆς οἰκείας δυνάμεως οὐκ ὀλίγην, οἳ κατατρέχοντες ἐπόρθουν ἅπασαν τὴν ὀρεινήν. αὐτὸς δὲ μετὰ τῆς λοιπῆς δυνάμεως ὑπέστρεψεν εἰς Ἀμμαοῦν, ὅθεν διὰ τῆς Σαμαρείτιδος καὶ παρὰ τὴν Νέαν πόλιν καλουμένην, Μαβαρθὰ δ’ ὑπὸ τῶν ἐπιχωρίων, καταβὰς εἰς Κορέαν δευτέρᾳ Δαισίου μηνὸς στρατοπεδεύεται. τῇ δ’ ἑξῆς εἰς Ἱεριχοῦντα ἀφικνεῖται, καθ’ ἣν αὐτῷ συμμίσγει Τραϊανὸς εἷς τῶν ἡγεμόνων τὴν ἐκ τῆς Περαίας ἄγων δύναμιν ἤδη τῶν ὑπὲρ τὸν Ἰορδάνην κεχειρωμένων.", "st": "4.8.1"}, {"sp": "N", "t": "Τὸ μὲν οὖν πολὺ πλῆθος ἐκ τῆς Ἱεριχοῦς φθάσαν τὴν ἔφοδον αὐτῶν εἰς τὴν ἄντικρυς Ἱεροσολύμων ὀρεινὴν διαπεφεύγει, καταλειφθὲν δὲ οὐκ ὀλίγον διαφθείρεται. τὴν δὲ πόλιν ἔρημον κατειλήφεσαν, ἥτις ἵδρυται μὲν ἐν πεδίῳ, ψιλὸν δὲ ὑπέρκειται αὐτῇ καὶ ἄκαρπον ὄρος μήκιστον· κατὰ γὰρ τὸ βόρειον κλίμα μέχρι τῆς Σκυθοπολιτῶν γῆς ἐκτείνεται, κατὰ δὲ τὸ μεσημβρινὸν μέχρι τῆς Σοδομιτῶν χώρας καὶ τῶν περάτων τῆς Ἀσφαλτίτιδος. ἔστιν δὲ ἀνώμαλόν τε πᾶν καὶ ἀοίκητον διὰ τὴν ἀγονίαν. ἀντίκειται δὲ τούτῳ τὸ περὶ τὸν Ἰορδάνην ὄρος ἀρχόμενον ἀπὸ Ἰουλιάδος καὶ τῶν βορείων κλιμάτων, παρατεῖνον δὲ εἰς μεσημβρίαν ἕως Σομόρων, ἥπερ ὁρίζει τὴν Πέτραν τῆς Ἀραβίας. ἐν τούτῳ δ’ ἐστὶ καὶ τὸ Σιδηροῦν καλούμενον ὄρος μηκυνόμενον μέχρι τῆς Μωαβίτιδος. ἡ μέση δὲ τῶν δύο ὀρέων χώρα τὸ μέγα πεδίον καλεῖται, ἀπὸ κώμης Γινναβρὶν διῆκον μέχρι τῆς Ἀσφαλτίτιδος. ἔστι δὲ αὐτοῦ μῆκος μὲν σταδίων χιλίων διακοσίων, εὖρος δ’ εἴκοσι καὶ ἑκατόν, καὶ μέσον ὑπὸ τοῦ Ἰορδάνου τέμνεται λίμνας τε ἔχει τήν τε Ἀσφαλτῖτιν καὶ τὴν Τιβεριέων φύσιν ἐναντίας· ἡ μὲν γὰρ ἁλμυρώδης καὶ ἄγονος, ἡ Τιβεριέων δὲ γλυκεῖα καὶ γόνιμος. ἐκπυροῦται δὲ ὥρᾳ θέρους τὸ πεδίον καὶ δι’ ὑπερβολὴν αὐχμοῦ περιέχει νοσώδη τὸν ἀέρα· πᾶν γὰρ ἄνυδρον πλὴν τοῦ Ἰορδάνου, παρὸ καὶ τοὺς μὲν ἐπὶ ταῖς ὄχθαις φοινικῶνας εὐθαλεστέρους καὶ πολυφορωτέρους εἶναι συμβέβηκεν, ἧττον δὲ τοὺς πόρρω κεχωρισμένους.", "st": "4.8.2"}, {"sp": "N", "t": "Παρὰ μέντοι τὴν Ἱεριχοῦν ἐστι πηγὴ δαψιλής τε καὶ πρὸς ἀρδείας λιπαρωτάτη παρὰ τὴν παλαιὰν ἀναβλύζουσα πόλιν, ἣν Ἰησοῦς ὁ Ναυῆ παῖς στρατηγὸς Ἑβραίων πρώτην εἷλε γῆς Χαναναίων δορίκτητον. ταύτην τὴν πηγὴν λόγος ἔχει κατ’ ἀρχὰς οὐ μόνον γῆς καὶ δένδρων καρποὺς ἀπαμβλύνειν, ἀλλὰ καὶ γυναικῶν γονάς, καθόλου τε πᾶσιν εἶναι νοσώδη τε καὶ φθαρτικήν, ἐξημερωθῆναι δὲ καὶ γενέσθαι τοὐναντίον ὑγιεινοτάτην τε καὶ γονιμωτάτην ὑπὸ Ἐλισσαίου τοῦ προφήτου· γνώριμος δ’ ἦν οὗτος Ἠλία καὶ διάδοχος· ὃς ἐπιξενωθεὶς τοῖς κατὰ τὴν Ἱεριχοῦν, περισσὸν δή τι φιλοφρονησαμένων αὐτὸν τῶν ἀνθρώπων αὐτούς τε ἀμείβεται καὶ τὴν χώραν αἰωνίῳ χάριτι. προελθὼν γὰρ ἐπὶ τὴν πηγὴν καὶ καταβαλὼν εἰς τὸ ῥεῦμα πλῆρες ἁλῶν ἀγγεῖον κεράμου, ἔπειτα εἰς οὐρανὸν δεξιὰν ἀνατείνας δικαίαν κἀπὶ γῆς σπονδὰς μειλικτηρίους χεόμενος, τὴν μὲν ᾐτεῖτο μαλάξαι τὸ ῥεῦμα καὶ γλυκυτέρας φλέβας ἀνοῖξαι, τὸν δὲ ἐγκεράσασθαι τῷ ῥεύματι γονιμωτέρους [τε] ἀέρας δοῦναί τε ἅμα καὶ καρπῶν εὐθηνίαν τοῖς ἐπιχωρίοις καὶ τέκνων διαδοχήν, μηδ’ ἐπιλιπεῖν αὐτοῖς τὸ τούτων γεννητικὸν ὕδωρ, ἕως μένουσι δίκαιοι. ταύταις ταῖς εὐχαῖς πολλὰ προσχειρουργήσας ἐξ ἐπιστήμης ἔτρεψε τὴν πηγήν, καὶ τὸ πρὶν ὀρφανίας αὐτοῖς καὶ λιμοῦ παραίτιον ὕδωρ ἔκτοτε εὐτεκνίας καὶ κόρου χορηγὸν κατέστη. τοσαύτην γοῦν ἐν ταῖς ἀρδείαις ἔχει δύναμιν ὡς, εἰ καὶ μόνον ἐφάψαιτο τῆς χώρας, νοστιμώτερον εἶναι τῶν μέχρι κόρου χρονιζόντων. παρὸ καὶ τῶν [μὲν] δαψιλεστέρως χρωμένων ἡ ὄνησίς ἐστιν ὀλίγη, τούτου δὲ τοῦ ὀλίγου χορηγία δαψιλής. ἄρδει γοῦν πλέονα τῶν ἄλλων ἁπάντων, καὶ πεδίον μὲν ἔπεισιν ἑβδομήκοντα σταδίων μῆκος εὖρος δ’ εἴκοσιν, ἐκτρέφει δ’ ἐν αὐτῷ παραδείσους καλλίστους τε καὶ πυκνοτάτους. τῶν δὲ φοινίκων ἐπαρδομένων γένη πολλὰ ταῖς γεύσεσι καὶ ταῖς παρηγορίαις διάφορα· τούτων οἱ πιότεροι πατούμενοι καὶ μέλι δαψιλὲς ἀνιᾶσιν οὐ πολλῷ τοῦ λοιποῦ χεῖρον. καὶ μελιττοτρόφος δὲ ἡ χώρα· φέρει δὲ καὶ ὀποβάλσαμον, ὃ δὴ τιμιώτατον τῶν τῇδε καρπῶν, κύπρον τε καὶ μυροβάλανον, ὡς οὐκ ἂν ἁμαρτεῖν τινα εἰπόντα θεῖον εἶναι τὸ χωρίον, ἐν ᾧ δαψιλῆ τὰ σπανιώτατα καὶ κάλλιστα γεννᾶται. τῶν μὲν γὰρ ἄλλων αὐτῷ καρπῶν ἕνεκεν οὐκ ἂν ῥᾳδίως τι παραβληθείη κλίμα τῆς οἰκουμένης· οὕτως τὸ καταβληθὲν πολύχουν ἀναδίδωσιν. αἴτιόν μοι δοκεῖ τὸ θερμὸν τῶν ἀέρων καὶ τὸ τῶν ὑδάτων εὔτονον, τῶν μὲν προκαλουμένων τὰ φυόμενα καὶ διαχεόντων, τῆς δὲ ἰκμάδος ῥιζούσης ἕκαστον ἰσχυρῶς καὶ χορηγούσης τὴν ἐν θέρει δύναμιν· περικαὲς δέ ἐστιν οὕτως τὸ χωρίον, ὡς μηδένα ῥᾳδίως προϊέναι. τὸ δὲ ὕδωρ πρὸ ἀνατολῆς ἀντλούμενον, ἔπειτα ἐξαιθριασθὲν γίνεται ψυχρότατον καὶ τὴν ἐναντίαν πρὸς τὸ περιέχον φύσιν λαμβάνει, χειμῶνος δὲ ἀνάπαλιν χλιαίνεται καὶ τοῖς ἐμβαίνουσι γίνεται προσηνέστατον. ἔστι δὲ καὶ τὸ περιέχον οὕτως εὔκρατον, ὡς λινοῦν ἀμφιέννυσθαι τοὺς ἐπιχωρίους νιφομένης τῆς ἄλλης Ἰουδαίας. ἀπέχει δὲ ἀπὸ Ἱεροσολύμων μὲν σταδίους ἑκατὸν πεντήκοντα, τοῦ δὲ Ἰορδάνου ἑξήκοντα, καὶ τὸ μὲν μέχρι Ἱεροσολύμων αὐτῆς ἔρημον καὶ πετρῶδες, τὸ δὲ μέχρι τοῦ Ἰορδάνου καὶ τῆς Ἀσφαλτίτιδος χθαμαλώτερον μέν, ἔρημον δὲ ὁμοίως καὶ ἄκαρπον. ἀλλὰ γὰρ τὰ μὲν περὶ Ἱεριχοῦν εὐδαιμονεστάτην οὖσαν ἀποχρώντως δεδήλωται.", "st": "4.8.3"}, {"sp": "N", "t": "Ἄξιον δὲ ἀφηγήσασθαι καὶ τὴν φύσιν τῆς Ἀσφαλτίτιδος λίμνης, ἥτις ἐστὶ μέν, ὡς ἔφην, πικρὰ καὶ ἄγονος, ὑπὸ δὲ κουφότητος καὶ τὰ βαρύτατα τῶν εἰς αὐτὴν ῥιφέντων ἀναφέρει, καταδῦναι δ’ εἰς τὸν βυθὸν οὐδὲ ἐπιτηδεύσαντα ῥᾴδιον. ἀφικόμενος γοῦν καθ’ ἱστορίαν ἐπ’ αὐτὴν Οὐεσπασιανὸς ἐκέλευσέ τινας τῶν νεῖν οὐκ ἐπισταμένων δεθέντας ὀπίσω τὰς χεῖρας ῥιφῆναι κατὰ τοῦ βυθοῦ, καὶ συνέβη πάντας ἐπινήξασθαι καθάπερ ὑπὸ πνεύματος ἄνω βιαζομένους. ἔστι δ’ ἐπὶ τούτῳ καὶ ἡ τῆς χρόας μεταβολὴ θαυμάσιος· τρὶς γὰρ ἑκάστης ἡμέρας τὴν ἐπιφάνειαν ἀλλάσσεται καὶ πρὸς τὰς ἡλιακὰς ἀκτῖνας ἀνταυγεῖ ποικίλως. τῆς μέντοι ἀσφάλτου κατὰ πολλὰ μέρη βώλους μελαίνας ἀναδίδωσιν· αἱ δ’ ἐπινήχονται τό τε σχῆμα καὶ τὸ μέγεθος ταύροις ἀκεφάλοις παραπλήσιαι. προσελαύνοντες δὲ οἱ τῆς λίμνης ἐργάται καὶ δρασσόμενοι τοῦ συνεστῶτος ἕλκουσιν εἰς τὰ σκάφη, πληρώσασι δὲ ἀποκόπτειν οὐ ῥᾴδιον, ἀλλὰ δι’ εὐτονίαν προσήρτηται τῷ μηρύματι τὸ σκάφος, ἕως ἂν ἐμμηνίῳ γυναικῶν αἵματι καὶ οὔρῳ διαλύσωσιν αὐτήν, οἷς μόνοις εἴκει. καὶ χρήσιμος δὲ οὐ μόνον εἰς ἁρμονίας νεῶν ἀλλὰ καὶ πρὸς ἄκεσιν σωμάτων· εἰς πολλὰ γοῦν τῶν φαρμάκων παραμίσγεται. ταύτης τῆς λίμνης μῆκος μὲν ὀγδοήκοντα καὶ πεντακόσιοι στάδιοι, καθὸ δὴ μέχρι Ζοάρων τῆς Ἀραβίας ἐκτείνεται, εὖρος δὲ πεντήκοντα καὶ ἑκατόν. γειτνιᾷ δ’ ἡ Σοδομῖτις αὐτῇ, πάλαι μὲν εὐδαίμων γῆ καρπῶν τε ἕνεκεν καὶ τῆς κατὰ πόλιν περιουσίας, νῦν δὲ κεκαυμένη πᾶσα. φασὶ δὲ ὡς δι’ ἀσέβειαν οἰκητόρων κεραυνοῖς καταφλεγῆναι· ἔστι γοῦν ἔτι λείψανα τοῦ θείου πυρός, καὶ πέντε μὲν πόλεων ἰδεῖν σκιάς, ἔτι δὲ κἀν τοῖς καρποῖς σποδιὰν ἀναγεννωμένην, οἳ χροιὰν μὲν ἔχουσι τῶν ἐδωδίμων ὁμοίαν, δρεψαμένων δὲ χερσὶν εἰς καπνὸν διαλύονται καὶ τέφραν. τὰ μὲν δὴ περὶ τὴν Σοδομῖτιν μυθευόμενα τοιαύτην ἔχει πίστιν ἀπὸ τῆς ὄψεως.", "st": "4.8.4"}, {"sp": "N", "t": "Ὁ δὲ Οὐεσπασιανὸς πανταχόθεν περιτειχίζων τοὺς ἐν τοῖς Ἱεροσολύμοις ἔν τε τῇ Ἱεριχοῖ καὶ ἐν Ἀδίδοις ἐγείρει στρατόπεδα καὶ φρουροὺς ἀμφοτέραις ἐγκαθίστησιν ἔκ τε τοῦ Ῥωμαϊκοῦ καὶ συμμαχικοῦ συντάγματος. πέμπει δὲ καὶ εἰς Γέρασα Λούκιον Ἄννιον παραδοὺς μοῖραν ἱππέων καὶ συχνοὺς πεζούς. ὁ μὲν οὖν ἐξ ἐφόδου τὴν πόλιν ἑλὼν ἀποκτείνει μὲν χιλίους τῶν νέων, ὅσοι μὴ διαφυγεῖν ἔφθασαν, γενεὰς δὲ ᾐχμαλωτίσατο καὶ τὰς κτήσεις διαρπάσαι τοῖς στρατιώταις ἐπέτρεψεν· ἔπειτα τὰς οἰκίας ἐμπρήσας ἐπὶ τὰς πέριξ κώμας ἐχώρει. φυγαὶ δ’ ἦσαν τῶν δυνατῶν καὶ φθοραὶ τῶν ἀσθενεστέρων, τὸ καταλειφθὲν δὲ πᾶν ἐνεπίμπρατο. καὶ διειληφότος τοῦ πολέμου τήν τε ὀρεινὴν ὅλην καὶ τὴν πεδιάδα πάσας οἱ ἐν τοῖς Ἱεροσολύμοις τὰς ἐξόδους ἀφῄρηντο· τοὺς μέν γε αὐτομολεῖν προαιρουμένους οἱ ζηλωταὶ παρεφυλάσσοντο, τοὺς δὲ οὔπω τὰ Ῥωμαίων φρονοῦντας εἶργεν ἡ στρατιὰ πανταχόθεν τὴν πόλιν περιέχουσα.", "st": "4.9.1"}, {"sp": "N", "t": "Οὐεσπασιανῷ δ’ εἰς Καισάρειαν ἐπιστρέψαντι καὶ παρασκευαζομένῳ μετὰ πάσης τῆς δυνάμεως ἐπ’ αὐτῶν τῶν Ἱεροσολύμων ἐξελαύνειν ἀγγέλλεται Νέρων ἀνῃρημένος, τρία καὶ δέκα βασιλεύσας ἔτη καὶ ἡμέρας ὀκτώ. περὶ οὗ λέγειν ὃν τρόπον εἰς τὴν ἀρχὴν ἐξύβρισεν πιστεύσας τὰ πράγματα τοῖς πονηροτάτοις, Νυμφιδίῳ καὶ Τιγελλίνῳ, τοῖς τε ἀναξίοις τῶν ἐξελευθέρων, καὶ ὡς ὑπὸ τούτων ἐπιβουλευθεὶς κατελείφθη μὲν ὑπὸ τῶν φυλάκων ἁπάντων, διαδρὰς δὲ σὺν τέτρασι τῶν πιστῶν ἀπελευθέρων ἐν τοῖς προαστείοις ἑαυτὸν ἀνεῖλεν, καὶ ὡς οἱ καταλύσαντες αὐτὸν μετ’ οὐ πολὺν χρόνον δίκας ἔδοσαν, τόν τε κατὰ τὴν Γαλατίαν πόλεμον ὡς ἐτελεύτησε, καὶ πῶς Γάλβας ἀποδειχθεὶς αὐτοκράτωρ εἰς Ῥώμην ἐπανῆλθεν ἐκ τῆς Ἱσπανίας, καὶ ὡς ὑπὸ τῶν στρατιωτῶν αἰτιαθεὶς ἐπὶ ταπεινοφροσύνῃ ἐδολοφονήθη κατὰ μέσην τὴν Ῥωμαίων ἀγορὸν ἀπεδείχθη τε αὐτοκράτωρ Ὄθων· τήν τε τούτου στρατείαν ἐπὶ τοὺς Οὐιτελλίου στρατηγοὺς καὶ κατάλυσιν, ἔπειτα τοὺς κατὰ Οὐιτέλλιον ταράχους καὶ τὴν περὶ τὸ Καπετώλιον συμβολήν, ὅπως τε Ἀντώνιος Πρῖμος καὶ Μουκιανὸς διαφθείραντες Οὐιτέλλιον καὶ τὰ Γερμανικὰ τάγματα κατέστειλαν τὸν ἐμφύλιον πόλεμον. πάντα ταῦτα διεξιέναι μὲν ἐπ’ ἀκριβὲς παρῃτησάμην, ἐπειδὴ δι’ ὄχλου πᾶσίν ἐστιν καὶ πολλοῖς Ἑλλήνων τε καὶ Ῥωμαίων ἀναγέγραπται, συναφείας δὲ ἕνεκεν τῶν πραγμάτων καὶ τοῦ μὴ διηρτῆσθαι τὴν ἱστορίαν κεφαλαιωδῶς ἕκαστον ἐπισημαίνομαι. Οὐεσπασιανὸς τοίνυν τὸ μὲν πρῶτον ἀνεβάλλετο τὴν τῶν Ἱεροσολύμων στρατείαν, καραδοκῶν πρὸς τίνα ῥέψει τὸ κρατεῖν μετὰ Νέρωνα· αὖθις δὲ Γάλβαν ἀκούσας αὐτοκράτορα, πρὶν ἐπιστεῖλαί τι περὶ τοῦ πολέμου κἀκεῖνον, οὐκ ἐπεχείρει, πέμπει δὲ πρὸς αὐτὸν καὶ τὸν υἱὸν Τίτον ἀσπασόμενόν τε καὶ ληψόμενον τὰς περὶ Ἰουδαίων ἐντολάς. διὰ δὲ τὰς αὐτὰς αἰτίας ἅμα Τίτῳ καὶ Ἀγρίππας ὁ βασιλεὺς πρὸς Γάλβαν ἔπλει. καὶ διὰ τῆς Ἀχαΐας, χειμῶνος γὰρ ἦν ὥρα, μακραῖς ναυσὶ περιπλεόντων φθάνει Γάλβας ἀναιρεθεὶς μετὰ μῆνας ἑπτὰ καὶ ἴσας ἡμέρας· ἐξ οὗ καὶ τὴν ἡγεμονίαν παρέλαβεν Ὄθων ἀντιποιούμενος τῶν πραγμάτων. ὁ μὲν οὖν Ἀγρίππας εἰς τὴν Ῥώμην ἀφικέσθαι διέγνω μηδὲν ὀρρωδήσας πρὸς τὴν μεταβολήν· Τίτος δὲ κατὰ δαιμόνιον ὁρμὴν ἀπὸ τῆς Ἑλλάδος εἰς τὴν Συρίαν ἀνέπλει καὶ κατὰ τάχος εἰς Καισάρειαν ἀφικνεῖται πρὸς τὸν πατέρα. καὶ οἱ μὲν μετέωροι περὶ τῶν ὅλων ὄντες ὡς ἂν σαλευομένης τῆς Ῥωμαίων ἡγεμονίας ὑπερεώρων τὴν ἐπὶ Ἰουδαίους στρατείαν, καὶ διὰ τὸν περὶ τῆς πατρίδος φόβον τὴν ἐπὶ τοὺς ἀλλοφύλους ὁρμὴν ἄωρον ἐνόμιζον.", "st": "4.9.2"}, {"sp": "N", "t": "Ἐπανίσταται δὲ ἄλλος τοῖς Ἱεροσολύμοις πόλεμος. υἱὸς ἦν Γιώρα Σίμων τις, Γερασηνὸς τὸ γένος, νεανίας πανουργίᾳ μὲν ἡττώμενος Ἰωάννου τοῦ προκατέχοντος ἤδη τὴν πόλιν, ἀλκῇ δὲ σώματος καὶ τόλμῃ διαφέρων, δι’ ἣν καὶ ὑπὸ Ἀνάνου τοῦ ἀρχιερέως φυγαδευθεὶς ἐξ ἧς εἶχε τοπαρχίας Ἀκραβετηνῆς πρὸς τοὺς κατειληφότας τὴν Μασάδαν λῃστὰς παραγίνεται. τὸ μὲν οὖν πρῶτον ἦν αὐτοῖς δι’ ὑποψίας· εἰς τὸ κατωτέρω γοῦν φρούριον ἐπέτρεψαν αὐτῷ παρελθεῖν ἅμα ταῖς γυναιξίν, ἃς ἄγων ἧκεν, αὐτοὶ τὸ ὑψηλότερον οἰκοῦντες· αὖθις δὲ διὰ συγγένειαν ἠθῶν καὶ ὅτι πιστὸς ἐδόκει, συμπροενόμευε γοῦν αὐτοῖς ἐξιὼν καὶ συνεπόρθει τὰ περὶ τὴν Μασάδαν. οὐ μὴν ἐπὶ τὰ μείζω παρακαλῶν ἔπεισεν· οἱ μὲν γὰρ ἐν ἔθει ὄντες τῷ φρουρίῳ, καθάπερ φωλεοῦ χωρίζεσθαι μακρὰν ἐδεδοίκεσαν, ὁ δὲ τυραννιῶν καὶ μεγάλων ἐφιέμενος ἐπειδὴ καὶ τὴν Ἀνάνου τελευτὴν ἤκουσεν, εἰς τὴν ὀρεινὴν ἀφίσταται, καὶ προκηρύξας δούλοις μὲν ἐλευθερίαν, γέρας δὲ ἐλευθέροις τοὺς πανταχόθεν πονηροὺς συνήθροιζεν.", "st": "4.9.3"}, {"sp": "N", "t": "Ὡς δ’ ἦν αὐτῷ καρτερὸν ἤδη τὸ σύνταγμα, τὰς ἀνὰ τὴν ὀρεινὴν κώμας κατέτρεχεν, ἀεὶ δὲ προσγινομένων πλειόνων ἐθάρρει καταβαίνειν εἰς τὰ χθαμαλώτερα. κἀπειδὴ πόλεσιν ἤδη φοβερὸς ἦν, πολλοὶ πρὸς τὴν ἰσχὺν καὶ τὴν εὔροιαν τῶν κατορθωμάτων ἐφθείροντο δυνατοί, καὶ οὐκέτι ἦν δούλων μόνων οὐδὲ λῃστῶν στρατός, ἀλλὰ καὶ δημοτικῶν οὐκ ὀλίγων ὡς πρὸς βασιλέα πειθαρχεῖν. κατέτρεχε δὲ τήν τε Ἀκραβετηνὴν τοπαρχίαν καὶ τὰ μέχρι τῆς μεγάλης Ἰδουμαίας· κατὰ γὰρ κώμην τινὰ καλουμένην Ἀῒν τεῖχος κατασκευάσας ὥσπερ φρουρίῳ πρὸς ἀσφάλειαν ἐχρῆτο, κατὰ δὲ τὴν φάραγγα προσαγορευομένην Φερεταὶ πολλὰ μὲν ἀνευρύνας σπήλαια, πολλὰ δ’ εὑρὼν ἕτοιμα ταμιείοις ἐχρῆτο θησαυρῶν καὶ τῆς λείας ἐκδοχείοις. ἀνετίθει δὲ καὶ τοὺς ἁρπαζομένους εἰς αὐτὰ καρπούς, οἵ τε πολλοὶ τῶν λόχων δίαιταν εἶχον ἐν ἐκείνοις· δῆλος δ’ ἦν τό τε σύνταγμα προγυμνάζων καὶ τὰς παρασκευὰς κατὰ τῶν Ἱεροσολύμων.", "st": "4.9.4"}, {"sp": "N", "t": "Ὅθεν οἱ ζηλωταὶ δείσαντες αὐτοῦ τὴν ἐπιβουλὴν καὶ προλαβεῖν βουλόμενοι τὸν κατ’ αὐτῶν τρεφόμενον ἐξίασι μετὰ τῶν ὅπλων οἱ πλείους· ὑπαντιάζει δὲ Σίμων, καὶ παραταξάμενος συχνοὺς μὲν αὐτῶν ἀναιρεῖ, συνελαύνει δὲ τοὺς λοιποὺς εἰς τὴν πόλιν. οὔπω δὲ θαρρῶν τῇ δυνάμει τοῦ μὲν τοῖς τείχεσιν προσβάλλειν ἀπετράπη, χειρώσασθαι δὲ πρότερον τὴν Ἰδουμαίαν ἐπεβάλετο· καὶ δὴ δισμυρίους ἔχων ὁπλίτας ἤλαυνεν ἐπὶ τοὺς ὅρους αὐτῆς. οἱ δὲ ἄρχοντες τῆς Ἰδουμαίας κατὰ τάχος ἀθροίσαντες ἐκ τῆς χώρας τὸ μαχιμώτατον περὶ πεντακισχιλίους καὶ δισμυρίους, τοὺς δὲ πολλοὺς ἐάσαντες φρουρεῖν τὰ σφέτερα διὰ τὰς τῶν ἐν Μασάδᾳ σικαρίων καταδρομάς, ἐδέχοντο τὸν Σίμωνα πρὸς τοῖς ὅροις. ἔνθα συμβαλὼν αὐτοῖς καὶ δι’ ὅλης πολεμήσας ἡμέρας, οὔτε νενικηκὼς οὔτε νενικημένος διεκρίθη, καὶ ὁ μὲν εἰς τὴν Ναΐν, οἱ δὲ Ἰδουμαῖοι διελύθησαν ἐπ’ οἴκου. καὶ μετ’ οὐ πολὺ Σίμων μείζονι δυνάμει πάλιν εἰς τὴν χώραν αὐτῶν ὥρμητο, στρατοπεδευσάμενος δὲ κατά τινα κώμην, Θεκουὲ καλεῖται, πρὸς τοὺς ἐν Ἡρωδείῳ φρουρούς, ὅπερ ἦν πλησίον, Ἐλεάζαρόν τινα τῶν ἑταίρων ἔπεμψε πείσοντα παραδοῦναι τὸ ἔρυμα. τοῦτον οἱ φύλακες προθύμως ἐδέξαντο τὴν αἰτίαν ἀγνοοῦντες δι’ ἣν ἥκοι, φθεγξάμενον δὲ περὶ παραδόσεως ἐδίωκον σπασάμενοι τὰ ξίφη, μέχρι φυγῆς τόπον οὐκ ἔχων ἔρριψεν ἀπὸ τοῦ τείχους ἑαυτὸν εἰς τὴν ὑποκειμένην φάραγγα. καὶ ὁ μὲν αὐτίκα τελευτᾷ, τοῖς δ’ Ἰδουμαίοις ἤδη κατορρωδοῦσι τὴν ἰσχὺν τοῦ Σίμωνος ἔδοξε πρὸ τοῦ συμβαλεῖν κατασκέψασθαι τὴν στρατιὰν τῶν πολεμίων.", "st": "4.9.5"}, {"sp": "N", "t": "Εἰς τοῦτο δὲ ὑπηρέτην αὑτὸν ἑτοίμως ἐπεδίδου Ἰάκωβος, εἷς τῶν ἡγεμόνων, προδοσίαν ἐνθυμούμενος. ὁρμήσας γοῦν ἀπὸ τῆς Ἀλούρου, κατὰ γὰρ ταύτην συνήθροιστο τὴν κώμην τότε τῶν Ἰδουμαίων τὸ στράτευμα, παραγίνεται πρὸς Σίμωνα, καὶ πρώτην αὐτῷ παραδώσειν συντίθεται τὴν αὐτοῦ πατρίδα, λαβὼν ὅρκους ὡς ἀεὶ τίμιος ὢν διατελέσει, συνεργήσειν δὲ ὑπέσχετο καὶ περὶ τῆς ὅλης Ἰδουμαίας. ἐφ’ οἷς ἑστιαθεὶς φιλοφρόνως ὑπὸ τοῦ Σίμωνος καὶ λαμπραῖς ἐπαρθεὶς ὑποσχέσεσιν, ἐπειδήπερ εἰς τοὺς σφετέρους ὑπέστρεψε, τὸ μὲν πρῶτον πολλαπλασίονα τὴν στρατιὰν ἐψεύδετο τοῦ Σίμωνος, ἔπειτα δεξιούμενος τούς τε ἡγεμόνας καὶ κατ’ ὀλίγους πᾶν τὸ πλῆθος ἐνῆγεν ὥστε δέξασθαι τὸν Σίμωνα καὶ παραδοῦναι δίχα μάχης αὐτῷ τὴν τῶν ὅλων ἀρχήν. ἅμα δὲ ταῦτα διαπραττόμενος καὶ Σίμωνα δι’ ἀγγέλων ἐκάλει σκεδάσειν ὑπισχνούμενος τοὺς Ἰδουμαίους· ὃ δὴ παρέσχεν. ὡς γὰρ ἦν ἤδη πλησίον ἡ στρατιά, πρῶτος ἀναπηδήσας ἐπὶ τὸν ἵππον μετὰ τῶν συνδιεφθαρμένων ἔφευγε. πτοία δ’ ἐμπίπτει παντὶ τῷ πλήθει, καὶ πρὶν εἰς χεῖρας ἐλθεῖν λυθέντες ἐκ τῆς τάξεως ἀνεχώρουν ἕκαστοι πρὸς τὰ ἴδια.", "st": "4.9.6"}, {"sp": "N", "t": "Σίμων δὲ παρὰ δόξαν εἰς τὴν Ἰδουμαίαν εἰσήλασεν ἀναιμωτὶ καὶ προσβαλὼν ἀδοκήτως πρώτην αἱρεῖ τὴν πολίχνην Χεβρών, ἐν ᾗ πλείστης ἐκράτησε λείας, πάμπολυν δὲ διήρπασε καρπόν. ὡς δέ φασιν οἱ ἐπιχώριοι τὴν Χεβρὼν οὐ μόνον τῶν τῇδε πόλεων ἀλλὰ καὶ τῆς ἐν Αἰγύπτῳ Μέμφεως ἀρχαιοτέραν· δισχίλια γοῦν αὐτῇ καὶ τριακόσια ἔτη συναριθμεῖται. μυθεύουσι δὲ αὐτὴν καὶ οἰκητήριον Ἀβράμου τοῦ Ἰουδαίων προγόνου γεγονέναι μετὰ τὴν ἐκ τῆς Μεσοποταμίας ἀπανάστασιν, τούς τε παῖδας αὐτοῦ λέγουσι καταβῆναι εἰς Αἴγυπτον ἔνθεν· ὧν καὶ τὰ μνημεῖα μέχρι νῦν ἐν τῇδε τῇ πολίχνῃ δείκνυται πάνυ καλῆς μαρμάρου καὶ φιλοτίμως εἰργασμένα. δείκνυται δ’ ἀπὸ σταδίων ἓξ τοῦ ἄστεος τερέβινθος μεγίστη, καὶ φασὶ τὸ δένδρον ἀπὸ τῆς κτίσεως μέχρι νῦν διαμένειν. ἔνθεν ὁ Σίμων ἐχώρει διὰ πάσης τῆς Ἰδουμαίας, οὐ μόνον κώμας καὶ πόλεις πορθῶν, λυμαινόμενος δὲ καὶ τὴν χώραν· δίχα γὰρ τῶν ὁπλιτῶν τέσσαρες αὐτῷ συνείποντο μυριάδες, ὡς μηδὲ τῶν ἐπιτηδείων ἐξαρκούντων πρὸς τὸ πλῆθος. προσῆν δὲ ταῖς χρείαις ὠμότης τε αὐτοῦ καὶ πρὸς τὸ γένος ὀργή, δι’ ἃ μᾶλλον ἐξερημοῦσθαι συνέβαινε τὴν Ἰδουμαίαν. καθάπερ δὲ ὑπὸ τῶν ἀκρίδων κατόπιν ὕλην ἔστιν ἰδεῖν ἐψιλωμένην πᾶσαν, οὕτω τὸ κατὰ νώτου τῆς Σίμωνος στρατιᾶς ἐρημία κατελείπετο· καὶ τὰ μὲν ἐμπιπρῶντες τὰ δὲ κατασκάπτοντες, πᾶν δὲ τὸ πεφυκὸς ἀνὰ τὴν χώραν ἢ συμπατοῦντες ἠφάνιζον ἢ νεμόμενοι καὶ τὴν ἐνεργὸν ὑπὸ τῆς πορείας σκληροτέραν ἐποίουν τῆς ἀκάρπου, καθόλου τε εἰπεῖν, οὐδὲ σημεῖόν τι κατελείπετο τοῖς πορθουμένοις τοῦ γεγονέναι.", "st": "4.9.7"}, {"sp": "N", "t": "Ταῦτα πάλιν τοὺς ζηλωτὰς ἐπήγειρεν, καὶ φανερῶς μὲν ἀντιπαρατάξασθαι κατέδεισαν, προλοχίσαντες δ’ ἐν ταῖς παρόδοις ἁρπάζουσι τοῦ Σίμωνος τὴν γυναῖκα καὶ τῆς περὶ αὐτὴν θεραπείας συχνούς. ἔπειτα ὡς αὐτὸν αἰχμαλωτισάμενοι τὸν Σίμωνα γεγηθότες εἰς τὴν πόλιν ὑπέστρεψαν καὶ ὅσον οὐδέπω προσεδόκων καταθέμενον τὰ ὅπλα περὶ τῆς γυναικὸς ἱκετεύσειν. τὸν δὲ οὐκ ἔλεος εἰσῆλθεν ἀλλ’ ὀργὴ περὶ τῆς ἡρπασμένης, καὶ πρὸς τὸ τεῖχος τῶν Ἱεροσολύμων ἐλθὼν καθάπερ τὰ τρωθέντα τῶν θηρίων, ἐπειδὴ τοὺς τρώσαντας οὐ κατέλαβεν, ἐφ’ οὓς εὗρε τὸν θυμὸν ἠφίει. ὅσοι γοῦν λαχανείας ἕνεκεν ἢ φρυγανισμοῦ προεληλύθεσαν ἔξω πυλῶν ἀνόπλους καὶ γέροντας συλλαμβάνων ᾐκίζετο καὶ διέφθειρεν, δι’ ὑπερβολὴν ἀγανακτήσεως μονονουχὶ καὶ νεκρῶν γευόμενος τῶν σωμάτων. πολλοὺς δὲ καὶ χειροκοπήσας εἰσέπεμπε καταπλήξασθαι τοὺς ἐχθροὺς ἅμα καὶ διαστῆσαι τὸν δῆμον ἐπιχειρῶν πρὸς τοὺς αἰτίους. ἐντέταλτο δ’ αὐτοῖς λέγειν, ὅτι Σίμων θεὸν ὄμνυσι τὸν πάντων ἔφορον, εἰ μὴ θᾶττον ἀποδώσουσιν αὐτῷ τὴν γυναῖκα, ῥήξας τὸ τεῖχος τοιαῦτα διαθήσειν πάντας τοὺς κατὰ τὴν πόλιν, μηδεμιᾶς φεισάμενος ἡλικίας μηδὲ ἀπὸ τῶν ἀναιτίων διακρίνας τοὺς αἰτίους. τούτοις οὐ μόνον ὁ δῆμος ἀλλὰ καὶ οἱ ζηλωταὶ καταπλαγέντες ἀποπέμπουσιν αὐτῷ τὴν γυναῖκα· καὶ τότε μὲν ἐκμειλιχθεὶς ὀλίγον ἀνεπαύσατο τοῦ συνεχοῦς φόνου.", "st": "4.9.8"}, {"sp": "N", "t": "Οὐ μόνον δὲ κατὰ τὴν Ἰουδαίαν στάσις ἦν καὶ πόλεμος ἐμφύλιος, ἀλλὰ κἀπὶ τῆς Ἰταλίας. ἀνῄρητο μὲν γὰρ κατὰ μέσην τὴν Ῥωμαίων ἀγορὰν Γάλβας, ἀποδεδειγμένος δὲ αὐτοκράτωρ Ὄθων ἐπολέμει Οὐιτελλίῳ βασιλειῶντι· τοῦτον γὰρ ᾕρητο τὰ κατὰ Γερμανίαν τάγματα. καὶ γενομένης συμβολῆς κατὰ Φρηγδίακον τῆς Γαλατίας πρός τε Οὐάλεντα καὶ Καικίνναν τοὺς Οὐιτελλίου στρατηγούς, τῇ πρώτῃ μὲν ἡμέρᾳ περιῆν Ὄθων, τῇ δὲ δευτέρᾳ τὸ Οὐιτελλίου στρατιωτικόν· καὶ πολλοῦ φόνου γενομένου διεχρήσατο μὲν Ὄθων αὑτὸν ἐν Βριξέλλῳ τὴν ἧτταν πυθόμενος ἡμέρας δύο καὶ τρεῖς μῆνας κρατήσας τῶν πραγμάτων, προσεχώρησε δὲ τοῖς Οὐιτελλίου στρατηγοῖς ἡ στρατιά, καὶ κατέβαινεν αὐτὸς εἰς τὴν Ῥώμην μετὰ τῆς δυνάμεως. ἐν δὲ τούτῳ καὶ Οὐεσπασιανὸς ἀναστὰς ἐκ τῆς Καισαρείας πέμπτῃ Δαισίου μηνὸς ὥρμησεν ἐπὶ τὰ μηδέπω κατεστραμμένα τῶν τῆς Ἰουδαίας χωρίων. ἀναβὰς δὲ εἰς τὴν ὀρεινὴν αἱρεῖ δύο τοπαρχίας, τήν τε Γοφνιτικὴν καὶ τὴν Ἀκραβετηνὴν καλουμένην, μεθ’ ἃς Βήθηγά τε καὶ Ἐφραὶμ πολίχνια, οἷς φρουροὺς ἐγκαταστήσας μέχρι Ἱεροσολύμων ἱππάζετο· φθορὰ δ’ ἦν πολλῶν καταλαμβανομένων καὶ συχνοὺς ᾐχμαλωτίζετο. Κερεάλιος δὲ αὐτῷ τῶν ἡγεμόνων μοῖραν ἱππέων καὶ πεζῶν ἀναλαβὼν τὴν ἄνω καλουμένην Ἰδουμαίαν ἐπόρθει, καὶ Κάφεθρα μὲν ψευδοπολίχνιον ἐξ ἐφόδου λαβὼν ἐμπίπρησιν, ἑτέραν δὲ καλουμένην Χαραβὶν προσβαλὼν ἐπολιόρκει. πάνυ δ’ ἦν ἰσχυρὸν τὸ τεῖχος, καὶ τρίψεσθαι προσδοκῶντι πλείω χρόνον αἰφνιδίως ἀνοίγουσιν οἱ ἔνδον τὰς πύλας καὶ μεθ’ ἱκετηριῶν προελθόντες ἑαυτοὺς παρέδοσαν. Κερεάλιος δὲ τούτους παραστησάμενος ἐπὶ Χεβρὼν ἑτέρας πόλεως ἀρχαιοτάτης ἐχώρει· κεῖται δ’, ὡς ἔφην, αὕτη κατὰ τὴν ὀρεινὴν οὐ πόρρω Ἱεροσολύμων· βιασάμενος δὲ τὰς εἰσόδους τὸ μὲν ἐγκαταληφθὲν πλῆθος ἡβηδὸν ἀναιρεῖ, τὸ δ’ ἄστυ καταπίμπρησι. καὶ πάντων ἤδη κεχειρωμένων πλὴν Ἡρωδείου καὶ Μασάδας καὶ Μαχαιροῦντος, ταῦτα δ’ ὑπὸ τῶν λῃστῶν κατείληπτο, σκοπὸς ἤδη τὰ Ἱεροσόλυμα προύκειτο Ῥωμαίοις.", "st": "4.9.9"}, {"sp": "N", "t": "Ὁ δὲ Σίμων ὡς ἐρρύσατο παρὰ τῶν ζηλωτῶν τὴν γυναῖκα, πάλιν ἐπὶ τὰ λείψανα τῆς Ἰδουμαίας ὑπέστρεψεν, καὶ περιελαύνων πανταχόθεν τὸ ἔθνος εἰς Ἱεροσόλυμα τοὺς πολλοὺς φεύγειν συνηνάγκασεν. εἵπετο δὲ καὶ αὐτὸς ἐπὶ τὴν πόλιν καὶ κυκλωσάμενος αὖθις τὸ τεῖχος ὅντινα λάβοι τῶν προϊόντων κατὰ τὴν χώραν ἐργατῶν διέφθειρεν. ἦν δὲ τῷ δήμῳ Σίμων μὲν ἔξωθεν Ῥωμαίων φοβερώτερος, οἱ ζηλωταὶ δ’ ἔνδον ἑκατέρων χαλεπώτεροι, κἀν τούτοις ἐπινοίᾳ κακῶν καὶ τόλμῃ τὸ σύνταγμα τῶν Γαλιλαίων διέφερεν· τόν τε γὰρ Ἰωάννην παρήγαγον εἰς ἰσχὺν οὗτοι, κἀκεῖνος αὐτοὺς ἐξ ἧς περιεποιήσατο δυναστείας ἠμείβετο πάντα ἐπιτρέπων δρᾶν ὧν ἕκαστος ἐπεθύμει. πόθοι δ’ ἦσαν ἁρπαγῆς ἀπλήρωτοι καὶ τῶν πλουσίων οἴκων ἔρευνα φόνος τε ἀνδρῶν καὶ γυναικῶν ὕβρεις ἐπαίζοντο, μεθ’ αἵματός τε τὰ συληθέντα κατέπινον καὶ μετ’ ἀδείας ἐνεθηλυπάθουν τῷ κόρῳ, κόμας συνθετιζόμενοι καὶ γυναικείας ἐσθῆτας ἀναλαμβάνοντες, καταντλούμενοι δὲ μύροις καὶ πρὸς εὐπρέπειαν ὑπογράφοντες ὀφθαλμούς. οὐ μόνον δὲ κόσμον, ἀλλὰ καὶ πάθη γυναικῶν ἐμιμοῦντο καὶ δι’ ὑπερβολὴν ἀσελγείας ἀθεμίτους. ἐπενόησαν ἔρωτας· ἐνηλινδοῦντο δ’ ὡς πορνείῳ τῇ πόλει καὶ πᾶσαν ἀκαθάρτοις ἐμίαναν ἔργοις. γυναικιζόμενοι δὲ τὰς ὄψεις ἐφόνων ταῖς δεξιαῖς θρυπτόμενοί τε τοῖς βαδίσμασιν ἐπιόντες ἐξαπίνης ἐγίνοντο πολεμισταὶ τά τε ξίφη προφέροντες ἀπὸ τῶν βεβαμμένων χλανιδίων τὸν προστυχόντα διήλαυνον. τοὺς ἀποδιδράσκοντας δὲ Ἰωάννην Σίμων φονικώτερον ἐξεδέχετο, καὶ διαφυγών τις τὸν ἐντὸς τείχους τύραννον ὑπὸ τοῦ πρὸ πυλῶν διεφθείρετο. πᾶσα δὲ φυγῆς ὁδὸς τοῖς αὐτομολεῖν πρὸς Ῥωμαίους βουλομένοις ἀπεκέκοπτο.", "st": "4.9.10"}, {"sp": "N", "t": "Διεστασιάζετο δὲ πρὸς τὸν Ἰωάννην ἡ δύναμις, καὶ πᾶν ὅσον [ἦν] Ἰδουμαίων ἐν αὐτῇ χωρισθὲν ἐπεχείρει τῷ τυράννῳ φθόνῳ τε τῆς ἰσχύος αὐτοῦ καὶ μίσει τῆς ὠμότητος. συμβαλόντες δὲ ἀναιροῦσί τε πολλοὺς τῶν ζηλωτῶν καὶ συνελαύνουσι τοὺς λοιποὺς εἰς τὴν βασιλικὴν αὐλὴν κατασκευασθεῖσαν ὑπὸ Γραπτῆς· συγγενὴς δὲ ἦν αὕτη τοῦ τῶν Ἀδιαβηνῶν βασιλέως Ἰζᾶ· συνεισπίπτουσι δὲ οἱ Ἰδουμαῖοι, κἀκεῖθεν εἰς τὸ ἱερὸν ἐξώσαντες τοὺς ζηλωτὰς ἐφ’ ἁρπαγὴν ἐτράποντο τῶν Ἰωάννου χρημάτων· κατὰ γὰρ τὴν προειρημένην αὐλὴν αὐτός τε † ὢν ἐκεῖ καὶ τὰ λάφυρα τῆς τυραννίδος κατέθετο. ἐν δὲ τούτῳ τὸ κατὰ τὴν πόλιν ἐσκεδασμένον πλῆθος τῶν ζηλωτῶν εἰς τὸ ἱερὸν πρὸς τοὺς διαπεφευγότας ἠθροίσθη, καὶ κατάγειν αὐτοὺς παρεσκευάσατο Ἰωάννης ἐπί τε τὸν δῆμον καὶ τοὺς Ἰδουμαίους. τοῖς δὲ οὐχ οὕτω τὴν ἔφοδον αὐτῶν καταδεῖσαι παρέστη μαχιμωτέροις οὖσιν ὡς τὴν ἀπόνοιαν, μὴ νύκτωρ ἐκ τοῦ ἱεροῦ παρεισδύντες αὐτούς τε διαφθείρωσι καὶ τὸ ἄστυ καταπιμπρῶσι. συνελθόντες οὖν μετὰ τῶν ἀρχιερέων ἐβουλεύοντο, τίνα χρὴ τρόπον φυλάξασθαι τὴν ἐπίθεσιν. θεὸς δὲ ἄρα τὰς γνώμας αὐτῶν εἰς κακὸν ἔτρεψε, καὶ χαλεπώτερον ἀπωλείας ἐπενόησαν τὸ πρὸς σωτηρίαν φάρμακον· ἵνα γοῦν καταλύσωσιν Ἰωάννην, ἔκριναν δέχεσθαι Σίμωνα καὶ μετὰ ἱκετηριῶν δεύτερον εἰσαγαγεῖν ἑαυτοῖς τύραννον. ἐπεραίνετο δ’ ἡ βουλή, καὶ τὸν ἀρχιερέα Ματθίαν πέμψαντες ἐδέοντο Σίμωνι εἰσελθεῖν ὃν πολλὰ ἔδεισαν· συμπαρεκάλουν δὲ οἱ ἐκ τῶν Ἱεροσολύμων τοὺς ζηλωτὰς φεύγοντες πόθῳ τῶν οἴκων καὶ τῶν κτημάτων. ὁ δ’ αὐτοῖς ὑπερηφάνως κατανεύσας τὸ δεσπόζειν εἰσέρχεται μὲν ὡς ἀπαλλάξων τῶν ζηλωτῶν τὴν πόλιν σωτὴρ ὑπὸ τοῦ δήμου καὶ κηδεμὼν εὐφημούμενος, παρελθὼν δὲ μετὰ τῆς δυνάμεως ἐσκόπει τὰ περὶ τῆς ἑαυτοῦ δυναστείας καὶ τοὺς καλέσαντας οὐχ ἧττον ἐχθροὺς ἐνόμιζεν ἢ καθ’ ὧν ἐκέκλητο.", "st": "4.9.11"}, {"sp": "N", "t": "Σίμων μὲν οὕτως ἐνιαυτῷ τρίτῳ τοῦ πολέμου Ξανθικῷ μηνὶ Ἱεροσολύμων ἐγκρατὴς γίνεται· Ἰωάννης δὲ καὶ τὸ τῶν ζηλωτῶν πλῆθος εἰργόμενοι τῶν ἐξόδων τοῦ ἱεροῦ καὶ τὰ τῆς πόλεως ἀπολωλεκότες, παραχρῆμα γὰρ τὰ ἐκείνων οἱ περὶ τὸν Σίμωνα διήρπασαν, ἐν ἀπόρῳ τὴν σωτηρίαν εἶχον. προσέβαλλε δὲ τῷ ἱερῷ Σίμων τοῦ δήμου βοηθοῦντος, κἀκεῖνοι καταστάντες ἐπὶ τῶν στοῶν καὶ τῶν ἐπάλξεων ἠμύνοντο τὰς προσβολάς. συχνοὶ δ’ ἔπιπτον τῶν περὶ Σίμωνα καὶ πολλοὶ τραυματίαι κατεφέροντο· ῥᾳδίως γὰρ ἐξ ὑπερδεξίου τὰς βολὰς οἱ ζηλωταὶ καὶ οὐκ ἀστόχους ἐποιοῦντο. πλεονεκτοῦντες δὲ τῷ τόπῳ καὶ πύργους ἔτι προσκατεσκεύασαν τέσσαρας μεγίστους, ὡς ἀφ’ ὑψηλοτέρων ποιοῖντο τὰς ἀφέσεις, τὸν μὲν κατὰ τὴν ἀνατολικὴν καὶ βόρειον γωνίαν, τὸν δὲ τοῦ ξυστοῦ καθύπερθεν, τὸν δὲ τρίτον κατὰ γωνίαν ἄλλην ἀντικρὺ τῆς κάτω πόλεως· ὁ δὲ λοιπὸς ὑπὲρ τὴν κορυφὴν κατεσκεύαστο τῶν παστοφορίων, ἔνθα τῶν ἱερέων εἷς ἐξ ἔθους ἱστάμενος ἑκάστην ἑβδομάδα εἰσιοῦσαν προεσήμαινε σάλπιγγι δείλης καὶ τελεσθεῖσαν αὖθις περὶ ἑσπέραν, ὅτε μὲν ἀνέργειαν τῷ λαῷ καταγγέλλων, ὅτε δ’ ἔργων ἔχεσθαι. διέστησαν δ’ ἐπὶ τῶν πύργων ὀξυβελεῖς τε καὶ λιθοβόλους μηχανὰς τούς τε τοξότας καὶ σφενδονήτας. ἔνθα δὴ τὰς μὲν προσβολὰς ὀκνηροτέρας ἐποιεῖτο ὁ Σίμων μαλακιζομένων αὐτῷ τῶν πλειόνων, ἀντεῖχε δ’ ὅμως περιουσίᾳ δυνάμεως· τὰ δὲ ἀπὸ τῶν ὀργάνων βέλη πορρωτέρω φερόμενα πολλοὺς τῶν μαχομένων ἀνῄρει.", "st": "4.9.12"}, {"sp": "N", "t": "Κατὰ δὲ τὸν αὐτὸν καιρὸν περιέσχε καὶ τὴν Ῥώμην πάθη χαλεπά. παρῆν μὲν γὰρ ἀπὸ Γερμανίας Οὐιτέλλιος ἅμα τῷ στρατιωτικῷ πολὺ πλῆθος ἐπισυρόμενος ἕτερον, μὴ χωρούμενος δὲ τοῖς ἀποδεδειγμένοις εἰς τοὺς στρατιώτας περιβόλοις ὅλην ἐποιήσατο τὴν Ῥώμην στρατόπεδον καὶ πᾶσαν οἰκίαν ὁπλιτῶν ἐπλήρωσεν. οἱ δὲ ἀήθεσιν ὀφθαλμοῖς τὸν Ῥωμαίων πλοῦτον θεασάμενοι καὶ περιλαμφθέντες πάντοθεν ἀργύρῳ τε καὶ χρυσῷ τὰς ἐπιθυμίας μόλις κατεῖχον, ὥστε μὴ ἐφ’ ἁρπαγὰς τρέπεσθαί τε καὶ τοὺς ἐμποδὼν γινομένους ἀναιρεῖν. καὶ τὰ μὲν κατὰ τὴν Ἰταλίαν ἐν τούτοις ἦν.", "st": "4.10.1"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ ὡς τὰ πλησίον Ἱεροσολύμων καταστρεψάμενος ὑπέστρεψεν εἰς Καισάρειαν, ἀκούει τὰς κατὰ τὴν Ῥώμην ταραχὰς καὶ Οὐιτέλλιον αὐτοκράτορα. τοῦτο αὐτὸν καίπερ ἄρχεσθαι καθάπερ ἄρχειν καλῶς ἐπιστάμενον εἰς ἀγανάκτησιν προήγαγεν, καὶ τὸν μὲν ὡς ἐρήμου καταμανέντα τῆς ἡγεμονίας ἠδόξει δεσπότην, περιαλγήσας δὲ τῷ πάθει καρτερεῖν τὴν βάσανον οὐχ οἷός τε ἦν καὶ τῆς πατρίδος πορθουμένης ἑτέροις προσευσχολεῖν πολέμοις. ἀλλ’ ὅσον ὁ θυμὸς ἤπειγεν ἐπὶ τὴν ἄμυναν, τοσοῦτον εἶργεν ἔννοια τοῦ διαστήματος· πολλὰ γὰρ φθάσαι πανουργήσασαν τὴν τύχην πρὶν αὐτὸν εἰς τὴν Ἰταλίαν περαιωθῆναι καὶ ταῦτα χειμῶνος ὥρᾳ πλέοντα· σφαδάζουσαν ἤδη κατεῖχεν τὴν ὀργήν.", "st": "4.10.2"}, {"sp": "N", "t": "Συνιόντες δὲ οἵ τε ἡγεμόνες καὶ στρατιῶται καθ’ ἑταιρίαν φανερῶς ἤδη μεταβολὴν ἐβουλεύοντο καὶ διαγανακτοῦντες ἐβόων, ὡς οἱ μὲν ἐπὶ τῆς Ῥώμης στρατιῶται τρυφῶντες καὶ μηδ’ ἀκούειν πολέμου φήμην ὑπομένοντες διαχειροτονοῦσιν οἷς βούλονται τὴν ἡγεμονίαν καὶ πρὸς ἐλπίδα λημμάτων ἀποδεικνύουσιν αὐτοκράτορας, αὐτοὶ δὲ διὰ τοσούτων κεχωρηκότες πόνων καὶ γηρῶντες ὑπὸ τοῖς κράνεσιν ἑτέροις χαρίζονται τὴν ἐξουσίαν καὶ ταῦτα τὸν ἀξιώτερον ἄρχειν παρ’ αὑτοῖς ἔχοντες. ᾧ τίνα δικαιοτέραν ποτὲ τῆς εἰς αὐτοὺς εὐνοίας ἀποδώσειν ἀμοιβήν, εἰ τὴν νῦν καταπροοῖντο; τοσούτῳ δ’ εἶναι Οὐεσπασιανὸν ἡγεμονεύειν Οὐιτελλίου δικαιότερον, ὅσῳ καὶ αὐτοὺς τῶν ἐκεῖνον ἀποδειξάντων· οὐ γὰρ δὴ μικροτέρους τῶν ἀπὸ Γερμανίας διενηνοχέναι πολέμους οὐδὲ τῶν ἐκεῖθεν καταγαγόντων τὸν τύραννον ἡττῆσθαι τοῖς ὅπλοις. ἀγῶνος δὲ ἐνδεήσειν οὐδέν· οὐ γὰρ τὴν σύγκλητον ἢ τὸν Ῥωμαίων δῆμον ἀνέξεσθαι τῆς Οὐιτελλίου λαγνείας ἀντὶ τῆς Οὐεσπασιανοῦ σωφροσύνης, οὐδ’ ἀντὶ μὲν ἡγεμόνος ἀγαθοῦ τύραννον ὠμότατον, ἄπαιδα δὲ ἀντὶ πατρὸς αἱρήσεσθαι προστάτην· μέγιστον γὰρ δὴ πρὸς ἀσφάλειαν εἰρήνης εἶναι τὰς γνησίους τῶν βασιλέων διαδοχάς. εἴτε οὖν ἐμπειρίᾳ γήρως προσήκει τὸ ἄρχειν, Οὐεσπασιανὸν αὐτοὺς ἔχειν, εἴτε νεότητος ἀλκῇ, Τίτον· κραθήσεσθαι γὰρ τῆς παρ’ ἀμφοῖν ἡλικίας τὸ ὠφέλιμον. χορηγήσειν δὲ οὐ μόνον αὐτοὶ τὴν ἰσχὺν τοῖς ἀποδειχθεῖσι τρία τάγματα καὶ τὰς παρὰ τῶν βασιλέων συμμαχίας ἔχοντες συνετηρήσαμεν τά τε πρὸς ἕω πάντα καὶ τῆς Εὐρώπης ὅσα τῶν ἀπὸ Οὐιτελλίου φόβων κεχώρισται, καὶ τοὺς ἐπὶ τῆς Ἰταλίας δὲ συμμάχους, ἀδελφὸν Οὐεσπασιανοῦ καὶ παῖδα ἕτερον, ὧν τῷ μὲν προσθήσεσθαι πολλοὺς τῶν ἐν ἀξιώματι νέων, τὸν δὲ καὶ τὴν τῆς πόλεως φυλακὴν πεπιστεῦσθαι, μέρος οὐκ ὀλίγον εἰς ἐπιβολὴν ἡγεμονίας. καθόλου τε ἂν βραδύνωσιν αὐτοί, τάχα τὴν σύγκλητον ἀποδείξειν τὸν ὑπὸ τῶν συντετηρηκότων στρατιωτῶν ἀτιμούμενον.", "st": "4.10.3"}, {"sp": "N", "t": "Τοιαῦτα κατὰ συστροφὰς οἱ στρατιῶται διελάλουν· ἔπειτα συναθροισθέντες καὶ παρακροτήσαντες ἀλλήλους ἀναγορεύουσι τὸν Οὐεσπασιανὸν αὐτοκράτορα καὶ σώζειν τὴν κινδυνεύουσαν ἡγεμονίαν παρεκάλουν. τῷ δὲ φροντὶς μὲν ἦν πάλαι περὶ τῶν ὅλων, οὔτι γε μὴν αὐτὸς ἄρχειν προῄρητο, τοῖς μὲν ἔργοις ἑαυτὸν ἄξιον ἡγούμενος, προκρίνων δὲ τῶν ἐν λαμπρότητι κινδύνων τὴν ἐν ἰδιώταις ἀσφάλειαν. ἀρνουμένῳ δὲ μᾶλλον οἱ ἡγεμόνες ἐπέκειντο καὶ περιχυθέντες οἱ στρατιῶται ξιφήρεις ἀναιρεῖν αὐτὸν ἠπείλουν, εἰ μὴ βούλοιτο ζῆν ἀξίως. πολλὰ δὲ πρὸς αὐτοὺς διατεινάμενος ἐξ ὧν διωθεῖτο τὴν ἀρχὴν τελευταῖον, ὡς οὐκ ἔπειθεν, εἴκει τοῖς ὀνομάσασι.", "st": "4.10.4"}, {"sp": "N", "t": "Προτρεπομένων δ’ αὐτὸν ἤδη Μουκιανοῦ τε καὶ τῶν ἄλλων ἡγεμόνων ὡς αὐτοκράτορα καὶ τῆς ἄλλης στρατιᾶς ἄγειν ἐπὶ πᾶν τὸ ἀντίπαλον, ὁ δὲ πρῶτον τῶν ἐπ’ Ἀλεξανδρείας εἴχετο πραγμάτων, εἰδὼς πλεῖστον τῆς ἡγεμονίας μέρος τὴν Αἴγυπτον οὖσαν διὰ τὴν τοῦ σίτου χορηγίαν, ἧς κρατήσας εἰ παρέλκοι καὶ βίᾳ καθαιρήσειν ἤλπιζεν Οὐιτέλλιον, οὐ γὰρ ἀνέξεσθαι πείνης ἐπὶ Ῥώμης τὸ πλῆθος, τὰ δύο τε ἐπὶ τῆς Ἀλεξανδρείας τάγματα προσποιήσασθαι βουλόμενος. ἐνεθυμεῖτο δὲ καὶ πρόβλημα τὴν χώραν ἔχειν τῶν ἀπὸ τῆς τύχης ἀδήλων· ἔστι γὰρ κατά τε γῆν δυσέμβολος καὶ τὰ πρὸς θαλάσσης ἀλίμενος, κατὰ μὲν ἑσπέραν προβεβλημένη τὰ ἄνυδρα τῆς Λιβύης, κατὰ δὲ μεσημβρίαν τὴν διορίζουσαν ἀπὸ Αἰθιόπων τὴν Συήνην καὶ τοὺς ἀπλώτους τοῦ ποταμοῦ καταράκτας, ἀπὸ δὲ τῆς ἀνατολῆς τὴν ἐρυθρὰν θάλασσαν ἀναχεομένην μέχρι Κοπτοῦ. βόρειον δὲ τεῖχος αὐτῇ ἥ τε μέχρι Συρίας γῆ καὶ τὸ καλούμενον Αἰγύπτιον πέλαγος, πᾶν ἄπορον ὅρμων. τετείχισται μὲν οὕτως ἡ Αἴγυπτος πάντοθεν· τὸ μεταξὺ δὲ Πηλουσίου καὶ Συήνης μῆκος αὐτῆς σταδίων δισχιλίων, ὅ τε ἀπὸ τῆς Πλινθίνης ἀνάπλους εἰς τὸ Πηλούσιον σταδίων τρισχιλίων ἑξακοσίων. ὁ δὲ Νεῖλος ἀναπλεῖται μέχρι τῆς Ἐλεφάντων καλουμένης πόλεως, ὑπὲρ ἣν εἴργουσι προσωτέρω χωρεῖν οὓς προειρήκαμεν καταράκτας. δυσπρόσιτος δὲ λιμὴν ναυσὶ καὶ κατ’ εἰρήνην Ἀλεξανδρείας· στενός τε γὰρ εἴσπλους καὶ πέτραις ὑφάλοις τὸν ἐπ’ εὐθὺ καμπτόμενος δρόμον. καὶ τὸ μὲν ἀριστερὸν αὐτοῦ μέρος πέφρακται χειροκμήτοις σκέλεσιν, ἐν δεξιᾷ δὲ ἡ προσαγορευομένη Φάρος νῆσος πρόκειται, πύργον ἔχουσα μέγιστον ἐκπυρσεύοντα τοῖς καταπλέουσιν ἐπὶ τριακοσίους σταδίους, ὡς ἐν νυκτὶ πόρρωθεν ὁρμίζοιντο πρὸς τὴν δυσχέρειαν τοῦ κατάπλου. περὶ ταύτην τὴν νῆσον καταβέβληται χειροποίητα τείχη μέγιστα, προσαρασσόμενον δὲ τούτοις τὸ πέλαγος καὶ τοῖς ἄντικρυς ἕρκεσιν ἀμφαγνυμένον ἐκτραχύνει τὸν πόρον καὶ σφαλερὰν διὰ στενοῦ τὴν εἴσοδον ἀπεργάζεται. ὁ μέντοι γε λιμὴν ἀσφαλέστατος ἔνδον καὶ τριάκοντα σταδίων τὸ μέγεθος, εἰς ὃν τά τε λείποντα τῇ χώρᾳ πρὸς εὐδαιμονίαν κατάγεται καὶ τὰ περισσεύοντα τῶν ἐπιχωρίων ἀγαθῶν εἰς πᾶσαν χωρίζεται τὴν οἰκουμένην.", "st": "4.10.5"}, {"sp": "N", "t": "Ἐφίετο μὲν οὖν εἰκότως τῶν ταύτῃ πραγμάτων Οὐεσπασιανὸς εἰς βεβαίωσιν τῆς ὅλης ἡγεμονίας, ἐπιστέλλει δ’ εὐθὺς τῷ διέποντι τὴν Αἴγυπτον καὶ τὴν Ἀλεξάνδρειαν Τιβερίῳ Ἀλεξάνδρῳ, δηλῶν τὸ τῆς στρατιᾶς πρόθυμον, καὶ ὡς αὐτὸς ὑποδὺς ἀναγκαίως τὸ βάρος τῆς ἡγεμονίας συνεργὸν αὐτὸν καὶ βοηθὸν προσλαμβάνοι. παραναγνοὺς δὲ τὴν ἐπιστολὴν Ἀλέξανδρος προθύμως τά τε τάγματα καὶ τὸ πλῆθος εἰς αὐτὸν ὥρκωσεν. ἑκάτεροι δὲ ἀσμένως ὑπήκουσαν τὴν ἀρετὴν τἀνδρὸς ἐκ τῆς ἐγγὺς στρατηγίας εἰδότες. καὶ ὁ μὲν πεπιστευμένος ἤδη τὰ περὶ τὴν ἀρχὴν προπαρεσκεύαζεν αὐτῷ καὶ τὰ πρὸς τὴν ἄφιξιν, τάχιον δ’ ἐπινοίας διήγγελλον αἱ φῆμαι τὸν ἐπὶ τῆς ἀνατολῆς αὐτοκράτορα, καὶ πᾶσα μὲν πόλις ἑώρταζεν εὐαγγέλια [δὲ] καὶ θυσίας ὑπὲρ αὐτοῦ ἐπετέλει. τὰ δὲ κατὰ Μυσίαν καὶ Παννονίαν τάγματα, μικρῷ πρόσθεν κεκινημένα πρὸς τὴν Οὐιτελλίου τόλμαν, μείζονι χαρᾷ Οὐεσπασιανῷ τὴν ἡγεμονίαν ὤμνυον. ὁ δ’ ἀναζεύξας ἀπὸ Καισαρείας εἰς Βηρυτὸν παρῆν, ἔνθα πολλαὶ μὲν ἀπὸ τῆς Συρίας αὐτῷ, πολλαὶ δὲ κἀπὸ τῶν ἄλλων ἐπαρχιῶν πρεσβεῖαι συνήντων, στεφάνους παρ’ ἑκάστης πόλεως καὶ συγχαρτικὰ προσφέρουσαι ψηφίσματα. παρῆν δὲ καὶ Μουκιανὸς ὁ τῆς ἐπαρχίας ἡγεμὼν τὸ πρόθυμον τῶν δήμων καὶ τοὺς κατὰ πόλιν ὅρκους ἀπαγγέλλων.", "st": "4.10.6"}, {"sp": "N", "t": "Προχωρούσης δὲ πανταχοῦ κατὰ νοῦν τῆς τύχης καὶ τῶν πραγμάτων συννενευκότων ἐκ τοῦ πλείστου μέρους, ἤδη παρίστατο τῷ Οὐεσπασιανῷ νοεῖν, ὡς οὐ δίχα δαιμονίου προνοίας ἅψαιτο τῆς ἀρχῆς, ἀλλὰ δικαία τις εἱμαρμένη περιαγάγοι τὸ κρατεῖν τῶν ὅλων ἐπ’ αὐτόν· ἀναμιμνήσκεται γὰρ τά τε ἄλλα σημεῖα, πολλὰ δ’ αὐτῷ γεγόνει πανταχοῦ προφαίνοντα τὴν ἡγεμονίαν, καὶ τὰς τοῦ Ἰωσήπου φωνάς, ὃς αὐτὸν ἔτι ζῶντος Νέρωνος αὐτοκράτορα προσειπεῖν ἐθάρσησεν. ἐξεπέπληκτο δὲ τὸν ἄνδρα δεσμώτην ἔτι ὄντα παρ’ αὐτῷ, καὶ προσκαλεσάμενος Μουκιανὸν ἅμα τοῖς ἄλλοις ἡγεμόσι καὶ φίλοις πρῶτον μὲν αὐτοῦ τὸ δραστήριον ἐκδιηγεῖτο καὶ ὅσα περὶ τοῖς Ἰωταπάτοις δι’ αὐτὸν ἔκαμον, ἔπειτα τὰς μαντείας, ἃς αὐτὸς μὲν ὑπώπτευσε τότε πλάσματα τοῦ δέους, ἀποδειχθῆναι δὲ ὑπὸ τοῦ χρόνου καὶ τῶν πραγμάτων θείας. αἰσχρὸν οὖν, ἔφη, τὸν προθεσπίσαντά μοι τὴν ἀρχὴν καὶ διάκονον τῆς τοῦ θεοῦ φωνῆς ἔτι αἰχμαλώτου τάξιν ἢ δεσμώτου τύχην ὑπομένειν καὶ καλέσας τὸν Ἰώσηπον λυθῆναι κελεύει. τοῖς μὲν οὖν ἡγεμόσιν ἐκ τῆς εἰς τὸν ἀλλόφυλον ἀμοιβῆς λαμπρὰ καὶ περὶ αὑτῶν ἐλπίζειν παρέστη, συνὼν δὲ τῷ πατρὶ Τίτος δίκαιον, ὦ πάτερ, ἔφη, τοῦ Ἰωσήπου καὶ τὸ ὄνειδος ἀφαιρεθῆναι σὺν τῷ σιδήρῳ· γενήσεται γὰρ ὅμοιος τῷ μὴ δεθέντι τὴν ἀρχήν, ἂν αὐτοῦ μὴ λύσωμεν ἀλλὰ κόψωμεν τὰ δεσμά. τοῦτο γὰρ ἐπὶ τῶν μὴ δεόντως δεθέντων πράττεται. συνεδόκει ταῦτα, καὶ παρελθών τις πελέκει διέκοψε τὴν ἅλυσιν. ὁ δὲ Ἰώσηπος εἰληφὼς περὶ τῶν προειρημένων γέρας τὴν ἐπιτιμίαν ἤδη καὶ περὶ τῶν μελλόντων ἀξιόπιστος ἦν.", "st": "4.10.7"}, {"sp": "N", "t": "Οὐεσπασιανὸς δὲ ταῖς πρεσβείαις χρηματίσας καὶ καταστησάμενος ἑκάστοις τὰς ἀρχὰς δικαίως καὶ διὰ τῶν ἀξίων εἰς Ἀντιόχειαν ἀφικνεῖται. καὶ βουλευόμενος, ποῖ τρέπεσθαι, προυργιαίτερα τῆς εἰς Ἀλεξάνδρειαν ὁρμῆς τὰ κατὰ τὴν Ῥώμην ἔκρινε, τὴν μὲν βέβαιον οὖσαν ὁρῶν, τὰ δ’ ὑπὸ Οὐιτελλίου ταρασσόμενα. πέμπει δὴ Μουκιανὸν εἰς τὴν Ἰταλίαν παραδοὺς ἱππέων τε καὶ πεζῶν συχνὴν δύναμιν. ὁ δὲ διὰ τὴν τοῦ χειμῶνος ἀκμὴν δείσας τὸ πλεῖν πεζῇ τὴν στρατιὰν ἦγε διὰ Καππαδοκίας καὶ Φρυγίας.", "st": "4.11.1"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ καὶ Ἀντώνιος Πρῖμος ἀναλαβὼν τὸ τρίτον τάγμα τῶν κατὰ Μυσίαν, ἔτυχεν δ’ ἡγεμονεύων αὐτόθι, Οὐιτελλίῳ παραταξόμενος ἠπείγετο. Οὐιτέλλιος δὲ αὐτῷ συναντήσοντα μετὰ πολλῆς δυνάμεως Καικίναν Ἀλιηνὸν ἐκπέμπει, μέγα θαρρῶν τἀνδρὶ διὰ τὴν ἐπ’ Ὄθωνι νίκην. ὁ δὲ ἀπὸ τῆς Ῥώμης ἐλαύνων διὰ τάχους περὶ Κρέμωνα τῆς Γαλατίας τὸν Ἀντώνιον καταλαμβάνει· μεθόριος δ’ ἐστὶν ἡ πόλις αὕτη τῆς Ἰταλίας. κατιδὼν δὲ ἐνταῦθα τὸ πλῆθος τῶν πολεμίων καὶ τὴν εὐταξίαν, συμβαλεῖν μὲν οὐκ ἐθάρρει, σφαλερὰν δὲ τὴν ἀναχώρησιν λογιζόμενος προδοσίαν ἐβουλεύετο. συναγαγὼν δὲ τοὺς ὑπ’ αὐτὸν ἑκατοντάρχας καὶ χιλιάρχους ἐνῆγεν μεταβῆναι πρὸς τὸν Ἀντώνιον, ταπεινῶν μὲν τὰ Οὐιτελλίου πράγματα, τὴν Οὐεσπασιανοῦ δ’ ἰσχὺν ἐπαίρων, καὶ παρ’ ᾧ μὲν εἶναι λέγων μόνον τῆς ἀρχῆς ὄνομα, παρ’ ᾧ δὲ τὴν δύναμιν, καὶ αὐτοὺς δὲ ἄμεινον προλαβόντας τὴν ἀνάγκην ποιῆσαι χάριν καὶ μέλλοντας ἡττᾶσθαι τοῖς ὅπλοις ταῖς γνώμαις τὸν κίνδυνον φθάσαι· Οὐεσπασιανὸν μὲν γὰρ ἱκανὸν εἶναι καὶ χωρὶς αὐτῶν προσκτήσασθαι καὶ τὰ λείποντα, Οὐιτέλλιον δ’ οὐδὲ σὺν αὐτοῖς τηρῆσαι τὰ ὄντα.", "st": "4.11.2"}, {"sp": "N", "t": "Πολλὰ τοιαῦτα λέγων ἔπεισε καὶ πρὸς τὸν Ἀντώνιον αὐτομολεῖ μετὰ τῆς δυνάμεως. τῆς δ’ αὐτῆς νυκτὸς ἐμπίπτει μετάνοια τοῖς στρατιώταις καὶ δέος τοῦ προπέμψαντος, εἰ κρείσσων γένοιτο· σπασάμενοι δὲ τὰ ξίφη τὸν Καικίναν ὥρμησαν ἀνελεῖν, κἂν ἐπράχθη τὸ ἔργον αὐτοῖς, εἰ μὴ προσπίπτοντες οἱ χιλίαρχοι καθικέτευσαν αὐτούς. οἱ δὲ τοῦ μὲν κτείνειν ἀπέσχοντο, δήσαντες δὲ τὸν προδότην οἷοί τε ἦσαν πέμπειν Οὐιτελλίῳ. ταῦτ’ ἀκούσας ὁ Πρῖμος αὐτίκα τοὺς σφετέρους ἀνίστησι καὶ μετὰ τῶν ὅπλων ἦγεν ἐπὶ τοὺς ἀποστάντας. οἱ δὲ παραταξάμενοι πρὸς ὀλίγον μὲν ἀντέσχον, αὖθις δὲ τραπέντες ἔφευγον εἰς τὴν Κρέμωνα. τοὺς δὲ ἱππεῖς ἀναλαβὼν Πρῖμος ὑποτέμνεται τὰς εἰσόδους αὐτῶν, καὶ τὸ μὲν πολὺ πλῆθος κυκλωσάμενος πρὸ τῆς πόλεως διαφθείρει, τῷ δὲ λοιπῷ συνεισπεσὼν διαρπάσαι τὸ ἄστυ τοῖς στρατιώταις ἐφῆκεν. ἔνθα δὴ πολλοὶ μὲν τῶν ξένων ἔμποροι, πολλοὶ δὲ τῶν ἐπιχωρίων ἀπώλοντο, πᾶσα δὲ καὶ ἡ Οὐιτελλίου στρατιά, μυριάδες ἀνδρῶν τρεῖς καὶ διακόσιοι· τῶν δ’ ἀπὸ τῆς Μυσίας Ἀντώνιος τετρακισχιλίους ἀποβάλλει καὶ πεντακοσίους. λύσας δὲ τὸν Καικίναν πέμπει πρὸς Οὐεσπασιανὸν ἀγγελοῦντα τὰ πεπραγμένα. καὶ ὃς ἐλθὼν ἀπεδέχθη τε ὑπ’ αὐτοῦ καὶ τὰ τῆς προδοσίας ὀνείδη ταῖς παρ’ ἐλπίδα τιμαῖς ἐπεκάλυψεν.", "st": "4.11.3"}, {"sp": "N", "t": "Ἀνεθάρσει δὲ ἤδη καὶ κατὰ τὴν Ῥώμην Σαβῖνος, ὡς πλησίον Ἀντώνιος ὢν ἀπηγγέλλετο, καὶ συναθροίσας τὰ τῶν νυκτοφυλάκων στρατιωτῶν τάγματα νύκτωρ καταλαμβάνει τὸ Καπετώλιον. μεθ’ ἡμέραν δ’ αὐτῷ πολλοὶ τῶν ἐπισήμων προσεγένοντο καὶ Δομετιανὸς ὁ τἀδελφοῦ παῖς, μεγίστη μοῖρα τῶν εἰς τὸ κρατεῖν ἐλπίδων. Οὐιτελλίῳ δὲ Πρίμου μὲν ἐλάττων φροντὶς ἦν, τεθύμωτο δ’ ἐπὶ τοὺς συναποστάντας τῷ Σαβίνῳ, καὶ διὰ τὴν ἔμφυτον ὠμότητα διψῶν αἵματος εὐγενοῦς τοῦ στρατιωτικοῦ τὴν συγκατελθοῦσαν αὐτῷ δύναμιν ἐπαφίησι τῷ Καπετωλίῳ. πολλὰ μὲν οὖν ἔκ τε ταύτης καὶ τῶν ἀπὸ τοῦ ἱεροῦ μαχομένων ἐτολμήθη, τέλος δὲ τῷ πλήθει περιόντες οἱ ἀπὸ τῆς Γερμανίας ἐκράτησαν τοῦ λόφου. καὶ Δομετιανὸς μὲν σὺν πολλοῖς τῶν ἐν τέλει Ῥωμαίων δαιμονιώτερον διασώζεται, τὸ δὲ λοιπὸν πλῆθος ἅπαν κατεκόπη, καὶ Σαβῖνος ἀναχθεὶς ἐπὶ Οὐιτέλλιον ἀναιρεῖται διαρπάσαντές τε οἱ στρατιῶται τὰ ἀναθήματα τὸν ναὸν ἐνέπρησαν. καὶ μετὰ μίαν ἡμέραν εἰσελαύνει μὲν Ἀντώνιος μετὰ τῆς δυνάμεως, ὑπήντων δ’ οἱ Οὐιτελλίου καὶ τριχῆ κατὰ τὴν πόλιν συμβαλόντες ἀπώλοντο πάντες. προέρχεται δὲ μεθύων ἐκ τοῦ βασιλείου Οὐιτέλλιος καὶ δαψιλέστερον ὥσπερ ἐν ἐσχάτοις τῆς ἀσώτου τραπέζης κεκορεσμένος. συρεὶς δὲ διὰ τοῦ πλήθους καὶ παντοδαπαῖς αἰκίαις ἐξυβρισθεὶς ἐπὶ μέσης τῆς Ῥώμης ἀποσφάττεται, μῆνας ὀκτὼ κρατήσας καὶ ἡμέρας πέντε, ὃν εἰ συνέβη πλείω βιῶσαι χρόνον, ἐπιλιπεῖν ἂν αὐτοῦ τῇ λαγνείᾳ τὴν ἡγεμονίαν οἶμαι. τῶν δ’ ἄλλων νεκρῶν ὑπὲρ πέντε μυριάδες ἠριθμήθησαν. ταῦτα μὲν τρίτῃ μηνὸς Ἀπελλαίου πέπρακτο, τῇ δ’ ὑστεραίᾳ Μουκιανὸς εἴσεισι μετὰ τῆς στρατιᾶς, καὶ τοὺς σὺν Ἀντωνίῳ παύσας τοῦ κτείνειν, ἔτι γὰρ ἐξερευνώμενοι τὰς οἰκίας πολλοὺς μὲν τῶν Οὐιτελλίου στρατιωτῶν πολλοὺς δὲ τῶν δημοτικῶν ὡς ἐκείνου ἀνῄρουν φθάνοντες τῷ θυμῷ τὴν ἀκριβῆ διάκρισιν, προαγαγὼν δὲ τὸν Δομετιανὸν συνίστησι τῷ πλήθει μέχρι τῆς τοῦ πατρὸς ἀφίξεως ἡγεμόνα. ὁ δὲ δῆμος ἀπηλλαγμένος ἤδη τῶν φόβων αὐτοκράτορα Οὐεσπασιανὸν εὐφήμει, καὶ ἅμα τήν τε τούτου βεβαίωσιν ἑώρταζε καὶ τὴν Οὐιτελλίου κατάλυσιν.", "st": "4.11.4"}, {"sp": "N", "t": "Εἰς δὲ τὴν Ἀλεξάνδρειαν ἀφιγμένῳ τῷ Οὐεσπασιανῷ τὰ ἀπὸ τῆς Ῥώμης εὐαγγέλια ἧκε καὶ πρέσβεις ἐκ πάσης τῆς ἰδίας οἰκουμένης συνηδόμενοι· μεγίστη τε οὖσα μετὰ τὴν Ῥώμην ἡ πόλις στενοτέρα τοῦ πλήθους ἠλέγχετο. κεκυρωμένης δὲ ἤδη τῆς ἀρχῆς ἁπάσης καὶ σεσωσμένων παρ’ ἐλπίδα Ῥωμαίοις τῶν πραγμάτων Οὐεσπασιανὸς ἐπὶ τὰ λείψανα τῆς Ἰουδαίας τὸν λογισμὸν ἐπέστρεφεν. αὐτὸς μέντοι γε εἰς τὴν Ῥώμην ὥρμητο λήξαντος τοῦ χειμῶνος ἀνάγεσθαι καὶ τάχος τὰ κατὰ τὴν Ἀλεξάνδρειαν διῴκει, τὸν δὲ υἱὸν Τίτον μετὰ τῆς ἐκκρίτου δυνάμεως ἀπέστειλεν ἐξαιρήσοντα τὰ Ἱεροσόλυμα. ὁ δὲ προελθὼν πεζῇ μέχρι Νικοπόλεως, εἴκοσι δὲ αὕτη διέχει τῆς Ἀλεξανδρείας σταδίους, κἀκεῖθεν ἐπιβήσας τὴν στρατιὰν μακρῶν πλοίων ἀναπλεῖ διὰ τοῦ Νείλου κατὰ τὸν Μενδήσιον νομὸν μέχρι πόλεως Θμούεως. ἐκεῖθεν δ’ ἀποβὰς ὁδεύει καὶ κατὰ πολίχνην Τάνιν αὐλίζεται. δεύτερος αὐτῷ σταθμὸς Ἡρακλέους πόλις καὶ τρίτος Πηλούσιον γίνεται. δυσὶ δ’ ἡμέραις ἐνταῦθα τὴν στρατιὰν ἀναλαβὼν τῇ τρίτῃ διέξεισι τὰς ἐμβολὰς τοῦ Πηλουσίου, καὶ προελθὼν σταθμὸν ἕνα διὰ τῆς ἐρήμου πρὸς τῷ τοῦ Κασίου Διὸς ἱερῷ στρατοπεδεύεται, τῇ δ’ ὑστεραίᾳ κατὰ τὴν Ὀστρακίνην· οὗτος ὁ σταθμὸς ἦν ἄνυδρος, ἐπεισάκτοις δὲ ὕδασιν οἱ ἐπιχώριοι χρῶνται. μετὰ ταῦτα πρὸς Ῥινοκουρούροις ἀναπαύεται, κἀκεῖθεν εἰς Ῥάφειαν προελθὼν σταθμὸν τέταρτον, ἔστι δ’ ἡ πόλις αὕτη Συρίας ἀρχή, τὸ πέμπτον ἐν Γάζῃ τίθεται στρατόπεδον, μεθ’ ἣν εἰς Ἀσκάλωνα κἀκεῖθεν εἰς Ἰάμνειαν, ἔπειτα εἰς Ἰόππην κἀξ Ἰόππης εἰς Καισάρειαν ἀφικνεῖται διεγνωκὼς αὐτόθι τὰς ἄλλας δυνάμεις ἀθροίζειν.", "st": "4.11.5"}], []);})();
